def _lemma(surface: str) -> str:
    return VERB_LEMMA.get(_key(surface), _key(surface))


def _copula_unit(reading: Reading):
    """The copula verb unit, or None — the anchor a property/membership negates. Includes the bare/perfect
    "be"/"been" ("Emile will BE …", "has BEEN …"), not just the finite is/are/was/were."""
    for u in reading.units:
        if "verb" in u.features.get("senses", []) \
                and _key(u.surface) in ("is", "are", "was", "were", "be", "been"):
            return u
    return None


def _verb_negated(verb, reading: Reading) -> bool:
    """Is `verb` negated? Both paths are scoped by BINDING, not by presence:
      - a "not"/"never" whose `negates` obligation bound to THIS verb, or
      - a "no" quantifier whose `collection` bound to this verb's SUBJECT ("no students failed" =
        the students-collection did not fail). Scoping via the bindings means "no" negates only its
        own predication, never every verb in reach (the global-flag trap the principle warns of)."""
    for u in reading.units:
        if "negation" in u.features.get("senses", []):
            if any(o.need == "negates" and o.met and o.target is verb
                   for o in u.features.get("obligations", [])):
                return True
    subject = _follow(verb, "subject")
    if subject is not None:
        for u in reading.units:
            if "quantifier" in u.features.get("senses", []) and _key(u.surface) == "no":
                if any(o.need == "collection" and o.met and o.target is subject
                       for o in u.features.get("obligations", [])):
                    return True
    return False


def _universal(verb, reading: Reading) -> bool:
    """Is `verb`'s predication universally quantified (regardless of polarity)? True iff its SUBJECT
    is the collection an all/every/no quantifier bound to — read from the bindings, like
    _verb_negated. "all students passed" and "no students passed" are both universal (the latter a
    negative universal); "some"/"the"/a number/a bare plural are NOT, so they don't instantiate."""
    subject = _follow(verb, "subject")
    if subject is None:
        return False
    for u in reading.units:
        if "quantifier" in u.features.get("senses", []) and _key(u.surface) in ("all", "every", "no"):
            if any(o.need == "collection" and o.met and o.target is subject
                   for o in u.features.get("obligations", [])):
                return True
    return False

# --- reference resolution: coreference, entities, possessives, pronoun gender ---------------

@dataclass(frozen=True)
class Referent:
    """A resolved pronoun's antecedent — the stand-in `target` for the cross-sentence `refers`
    obligation. Its `.surface` is the entity name, so trace / obligation-summary read it like a Unit."""
    surface: str


def _entity(unit) -> str:
    """The entity a subject unit denotes: a resolved pronoun's antecedent if bound, else its own key."""
    if "pronoun" in unit.features.get("senses", []):
        ref = _follow(unit, "refers")
        if ref is not None:
            return _key(ref.surface)
    return _key(unit.surface)


def _noun_entity_key(unit) -> str:
    """The COMMON-NOUN entity a unit denotes, for the subtype-partition/coordinate-noun affine family (the
    noun-entity twin of `_entity`, used when a clause has NO names at all): a QUALIFIER for a merged
    adjective-noun compound ("red balls" → "red", from the `attributes` the noun-compound merge records), a
    bare ADJECTIVE with an elided head noun ("...than BLUE" = "...than blue balls" → "blue"), or the
    SINGULAR of a plain distinct noun ("pigs"/"cows" → "pig"/"cow", DIFFERENT nouns naturally getting
    DIFFERENT keys with no qualifier needed)."""
    attrs = unit.features.get("attributes")
    if attrs:
        return _key(attrs[0])
    if "adjective" in unit.features.get("senses", []):
        return _key(unit.surface)
    return _key(unit.features.get("singular") or unit.surface)


def _name_count(rp: "Reading") -> int:
    """How many NAME units a reading holds — the discriminator between the NAMED-ENTITY affine family (which
    requires EXACTLY 2 names for a relation / 1 for an anchor) and `_affine_relation`/`_anchor_fact`'s
    COMMON-NOUN fallback (0 or 1 names for a relation, 0 for an anchor). The named systems must gate on this
    BEFORE accepting a result — otherwise a noun-entity relation the fallback silently produces (valid for
    the coordinate-noun family, but semantically WRONG here — e.g. "as many books as the number of tables...
    ARE ON TOP OF EACH TABLE" is a per-unit RATE, not a flat count the named systems' arithmetic assumes)
    would be picked up by the wrong family and mis-solve. A real confident-wrong (700 vs gold 100000)
    surfaced this: `_anchored_sum_system` had no idea its relation actually came from the noun fallback."""
    return sum(1 for u in rp.units if "name" in u.features.get("senses", []))


# Person-GROUP nouns a set-size cardinal can count ("four PLAYERS scored points") — curated, kinship included.
GROUP_PERSON_NOUNS = KINSHIP | {"player", "person", "people", "friend", "student", "child", "kid", "boy",
                                "girl", "man", "woman", "teammate", "member", "worker", "sibling"}
_ORDINAL_WORDS = {"first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth",
                  "tenth"}


def _cast_size(rps: list) -> int:
    """How many distinct entities a problem's premises reference — its CAST. Named entities count by WORD
    (a merged "Carl and Cal" unit spans multiple words — split, skipping "and", as `_residual_sum_system`
    does); when the cast is UNNAMED, distinct ORDINAL references count instead ("the FIRST player eats 78
    seeds. The SECOND eats 53. The THIRD eats 30 more…" — three entities, no name anywhere)."""
    names = {_key(w.surface) for rp in rps for u in rp.units if "name" in u.features.get("senses", [])
             for w in u.words if _key(w.surface) != "and"}
    if names:
        return len(names)
    ords = set()
    for rp in rps:
        for u in rp.units:
            if "adjective" in u.features.get("senses", []) and _key(u.surface) in _ORDINAL_WORDS:
                ords.add(_key(u.surface))
            for a in u.features.get("attributes", []):
                if _key(a) in _ORDINAL_WORDS:
                    ords.add(_key(a))
    return len(ords)


def _set_size_cardinal(rp: "Reading", cast_n: int) -> bool:
    """True iff a premise's ONLY number is a SET-SIZE cardinal: a 0-name clause whose single integer value
    quantifies a person-GROUP noun AND equals the count of distinct named entities in the whole problem
    ("In the final game of the basketball season, four PLAYERS scored points." in a Chandra/Akiko/Michiko/
    Bailey problem — the 4 counts the CAST, it is not an arithmetic datum). Such a premise is safely
    skippable by the anchored-affine family's unused-given firewall: its systems already sum/propagate over
    exactly those named entities, so the cardinal is redundant scene-setting, not a dropped quantity."""
    if cast_n < 2 or _name_count(rp) != 0:
        return False
    if any(s in u.features.get("senses", []) for u in rp.units
           for s in ("multiplier", "comparative", "interrogative", "aggregator")) \
            or any(_fraction_parts(u.surface) is not None for u in rp.units):
        return False
    vals = [u for u in rp.units if "value" in u.features.get("senses", [])
            and u.features.get("value") is not None]
    if len(vals) != 1 or vals[0].features["value"] != cast_n:
        return False
    qn = _follow(vals[0], "quantifies")
    if qn is None:
        return False
    desc = _descriptor(qn)
    return desc is not None and desc[0] in GROUP_PERSON_NOUNS


def _disc_pair(e):
    """A discourse entry as (entity, is_name) — tolerating a bare entity string (treated as a name)."""
    return e if isinstance(e, tuple) else (e, True)


def _pick_antecedent(gender, discourse: list):
    """The antecedent for a pronoun of `gender` from `discourse` (a list of (entity, is_name) most-recent
    LAST). A gendered pronoun ("he"/"she") prefers the most recent NAME of compatible gender — a PERSON,
    not a thing like "price"; "it"/"they" take the most recent compatible entity. None if empty."""
    pairs = [_disc_pair(e) for e in discourse]
    ents = [e for e, _ in pairs]
    if gender in ("masculine", "feminine"):              # he/she → a person (named), gender-compatible
        names = [e for e, is_name in pairs if is_name and NAME_GENDER.get(e) in (None, gender)]
        if names:
            return names[-1]
    compatible = [e for e in ents if gender in (None, "plural") or NAME_GENDER.get(e) in (None, gender)]
    pool = compatible or ents
    return pool[-1] if pool else None


def _resolve_possessives(reading: Reading) -> None:
    """Back-link an unresolved POSSESSIVE pronoun ("his"/"her"/"their"/"its") to the clause's SUBJECT
    when that is a NAME — "Mr. Sam shared … his two sons" → his refers to Sam (the agent is the default
    possessor). Within-sentence and discourse-free, so it runs in `analyze` and takes precedence over the
    cross-sentence resolver; when the subject isn't a name ("his brother left") it leaves it for discourse."""
    verbs = [u for u in reading.units if "verb" in u.features.get("senses", [])]
    subj = _follow(verbs[0], "subject") if len(verbs) == 1 else None
    if subj is None or "name" not in subj.features.get("senses", []):
        return
    for u in reading.units:
        if "pronoun" not in u.features.get("senses", []) \
                or _key(u.surface) not in ("his", "her", "their", "its"):
            continue
        obs = u.features.get("obligations", [])
        ref = next((o for o in obs if o.need == "refers"), None)
        if ref is None or ref.met:
            continue
        before = dict(u.features)
        u.features["obligations"] = [Obligation(o.need, target=Referent(_entity(subj)))
                                     if o is ref else o for o in obs]
        reading.record("bind", target=u, before=before, after=dict(u.features),
                       reason=f"{u.surface!r} (possessive) back-links to the agent {_entity(subj)!r}")


def _resolve_references(reading: Reading, discourse: list) -> None:
    """Discharge each pronoun's `refers` obligation against the discourse — binding it to a Referent
    and logging a reversible Decision, so coreference shows in --trace like any other binding."""
    for u in reading.units:
        if "pronoun" not in u.features.get("senses", []):
            continue
        obs = u.features.get("obligations", [])
        ref_ob = next((o for o in obs if o.need == "refers"), None)
        if ref_ob is None or ref_ob.met:
            continue
        if u.features.get("gender") == "plural":         # "they"/"them" → the GROUP of all prior
            members = list(dict.fromkeys(_disc_pair(e)[0] for e in discourse))   # distinct entities (a collective,
            if not members:                              # like a conjoined subject) → _question_subjects expands
                continue
            antecedent = " and ".join(members)
            before = dict(u.features)
            u.features["members"] = members
        else:
            antecedent = _pick_antecedent(u.features.get("gender"), discourse)
            if antecedent is None:
                continue
            before = dict(u.features)
        u.features["obligations"] = [Obligation(o.need, target=Referent(antecedent)) if o is ref_ob
                                     else o for o in obs]
        reading.record("bind", target=u, before=before, after=dict(u.features),
                       reason=f"{u.surface!r} refers to {antecedent!r}")


# A quantity verb's arithmetic polarity: a LOSS verb subtracts, everything else (gains + the "have"
# baseline) adds. Keyed by lemma; grown deliberately like the other dictionaries.
LOSS_VERBS = {"lose", "sell", "give", "spend", "eat", "use", "drop", "drink"}

# A comparative's arithmetic direction: −1 lowers the referent ("10 years YOUNGER" → −10), +1 raises it.
COMPARATIVE_SIGN = {"less": -1, "fewer": -1, "younger": -1, "shorter": -1, "lighter": -1,
                    "slower": -1, "cheaper": -1, "smaller": -1, "lower": -1, "poorer": -1}

# POSSESSION verbs a ratio's STANDARD can sit before, in lieu of an elided "that"/"which" ("as much money
# DARWIN HAS" = "...as Darwin has") — deliberately narrow (NOT any verb) so a mistagged common noun ("CDs")
# followed by an unrelated passive modifier ("the CDs SOLD at $10 each") doesn't get misread as a name-ratio.
POSSESSION_VERBS = {"has", "had", "have", "owns", "owned", "gets", "got", "receives", "received",
                    "holds", "held",
                    # CONTAINMENT is possession (#204): "each box contains 6 eggs" carries the
                    # eggs exactly as "holds" does — the fold materializes the quantity. This was
                    # the #1 unknown word corpus-wide (59 blocked problems); typing it alone
                    # (without the relation) was the wrong-on-inject class the sweep flagged.
                    "contains", "contain", "contained"}


def _verb_sign(lemma: str) -> int:
    """+1 for a gain or the 'have' baseline, -1 for a loss verb — how this quantity folds."""
    return -1 if lemma in LOSS_VERBS else 1


# Words that ask for what REMAINS — a holdings question ("how many are left / remaining") in another
# surface form. ("rest" = "the rest"; "remain"/"remains" the verb form.)
_REMAINDER = {"left", "remaining", "leftover", "remain", "remains", "rest"}


DISTRIBUTE_VERBS = {"share", "distribute", "split", "divide", "spread"}


# Every word-problem number is produced by EXECUTING a tiny arithmetic program through the AUDITED safe
# evaluator (translate.run_program: ast.parse + an operator/function whitelist, never eval/exec) — not by
# an inline Python operator. So each answer's arithmetic is a recorded, re-executable, whitelisted program.
ARITHMETIC_LOG: list = []                                # (program, result) per audited computation


def _num(x) -> str:
    """Format a number for an arithmetic program — drop the trailing .0 so the program reads cleanly."""
    return str(int(x)) if isinstance(x, float) and x == int(x) else str(x)


def _compute(expr: str):
    """Evaluate a one-line arithmetic expression through the audited safe evaluator, LOG it, and return the
    int/float. The single arithmetic seam — no answer number is computed by a bare Python operator."""
    from reasoning import translate                       # lazy: avoid an import cycle
    val = translate.run_program(f"answer = {expr}")
    ARITHMETIC_LOG.append((expr, val))
    return int(val) if val == int(val) else val


def _holdings(entity: str, measure: tuple, context: list):
    """The net holdings of `entity` for `measure` — baseline + gains − losses — or None if unknown.
    Timeless / single-state fold (order-independent); the time-aware variant is `_holdings_at`. Quantities
    with an UNKNOWN value (`amount is None`, e.g. an unresolved shared total) are skipped — folding waits
    until synthesis pins them."""
    qs = [f for f in context if isinstance(f, Quantity) and f.entity == entity
          and f.measure == measure and f.amount is not None]
    if not qs:
        return None
    return _compute(" + ".join(f"{_verb_sign(f.verb)} * {_num(f.amount)}" for f in qs))


# A STATE verb asserts the value AT a time ("has 30 on Monday" — Monday's known total); every other
# verb is a CHANGE (a delta applied to the running value). The distinction only matters once values are
# spread across an ordered timeline (`_holdings_at`); the timeless fold treats all as signed deltas.
STATE_VERBS = {"have", "be"}
GROWTH_VERBS = {"grow", "gain", "increase", "rise", "lengthen"}   # a rate of these advances a value over time

# Verbs whose RESULT is itself a measure — their nominalisation is a quantity ("earn" → "earnings"). Lets
# "how MUCH did X earn" bind `much` to the verb (the earnings) and read the measure off it, instead of a
# blanket "much → MONEY" default. All money here; a future "weigh"→weight extends the same mechanism.
RESULT_MEASURE = {v: MONEY for v in ("earn", "spend", "pay", "cost", "save", "make", "give", "get",
                                     "receive", "sell", "buy", "charge", "collect", "win", "owe", "raise")}

# --- FACT MODEL & EXTRACTION: read Quantity/Rate/Age/Distribution facts from a reading ------

def _time_order(times: list, context: list):
    """A linear (chronological) ordering of the given time nodes from the Before closure, or None if
    they are NOT totally ordered (some pair's order is unknown — we never guess an order). Insertion
    sort using `_before`."""
    ordered = []
    for t in dict.fromkeys(x for x in times if x is not None):
        placed = False
        for k, o in enumerate(ordered):
            if _before(t, o, context):                   # t earlier than o → goes before it
                ordered.insert(k, t)
                placed = True
                break
            if not _before(o, t, context):               # neither before nor after → incomparable
                return None
        if not placed:
            ordered.append(t)
    return ordered


def _time_offset(reading: Reading) -> float:
    """A relative-time reference's POSITION on the timeline, in YEARS from 'now' (the reference point):
    "next year" → +1, "last year" → −1, "in N years" → +N, "N years ago" → −N, else 0. The temporal
    model's quantified ordering — a time-tracking quantity (AGE advances 1/year) reads it to value itself
    at a shifted time: age@(now+Δ) = age@now + Δ."""
    units = reading.units
    surf = {_key(u.surface) for u in units}
    attrs = {a for u in units for a in u.features.get("attributes", [])}
    yv = next((u.features["value"] for u in units if "value" in u.features.get("senses", [])
               and _follow(u, "quantifies") is not None
               and _descriptor(_follow(u, "quantifies"))[0] == "year"), None)
    if "ago" in surf:                                    # "N years ago" (a bare "a year ago" → 1)
        return -(yv if yv is not None else 1)
    if {"from", "now"} <= surf and yv is not None:       # "N years from now" → +N (a future displacement)
        return yv
    if (surf & {"in", "after"}) and yv is not None:      # "in N years" / "after N years"
        return yv
    if "next" in attrs:                                  # "next year"
        return 1
    if "last" in attrs:                                  # "last year"
        return -1
    return 0


def _holdings_at(entity: str, measure: tuple, context: list, at_time: str):
    """Holdings of `entity`/`measure` VALID AT time node `at_time`, folded along the timeline: a STATE
    verb SETS the running value (a known total), a CHANGE verb adds its signed delta. Events strictly
    after `at_time` are excluded; a timeless event is an always-present baseline. None (decline) if an
    event's order vs `at_time` is unknown, or the applicable times aren't linearly orderable."""
    events = [f for f in context if isinstance(f, Quantity) and f.entity == entity
              and f.measure == measure and f.amount is not None]
    if not events:
        return None
    applicable = []
    for q in events:
        if q.time is None or q.time == at_time or _before(q.time, at_time, context):
            applicable.append(q)
        elif _before(at_time, q.time, context):
            continue                                     # strictly after the query time → not in effect
        else:
            return None                                  # order vs the query time unknown → can't place
    order = _time_order([q.time for q in applicable], context)
    if order is None:
        return None
    rank = {t: k for k, t in enumerate(order)}
    chronological = sorted(applicable, key=lambda q: rank.get(q.time, -1))   # stable: None first
    running = "0"                                        # build the program as we fold: a STATE RESETS the
    for q in chronological:                              # running expression, a CHANGE appends a signed term
        term = f"{_verb_sign(q.verb)} * {_num(q.amount)}"
        running = term if q.verb in STATE_VERBS else f"{running} + {term}"
    return _compute(running)


@dataclass(frozen=True)
class Quantity:
    """A counted-amount fact: "Tom has 3 apples" → Quantity("tom", ("apple", frozenset()), 3.0,
    "have"). The measure is a collection descriptor ("3 RED apples"); `verb` (the lemma) carries the
    arithmetic intent (have=baseline, buy=gain, lose=loss) used when folding. Arithmetic analogue of
    Predication."""
    entity: str
    measure: tuple
    amount: float
    verb: str = "have"
    time: str = None      # the time NODE this value is valid at (a `time` unit's `associates` binding);
                          # None = timeless / always-valid. Order between nodes lives in `Before` facts.
    derived: bool = field(default=False, compare=False)   # True when COMPUTED from a relation/comparative/
                          # multiplier (Armand = 1/3 × Amber), not stated outright. An implicit referent
                          # ("Ella worked twice as long") prefers the most-recent NON-derived baseline over
                          # a just-derived sibling. compare=False so fact equality (and tests) ignore it.
    first_period: bool = field(default=False, compare=False)   # True for a "in the FIRST <time-unit> …"
                          # override ("in the first year he only teaches 40") — year 1 differs from the
                          # rate, so a rate×duration answer becomes override + rate×(duration−1).


@dataclass(frozen=True)
class Before:
    """A temporal ORDER fact: `Before("monday", "tuesday")` means the Monday-node is earlier than the
    Tuesday-node. RELATIONAL (read off the text's after/before cues), never a calendar rank — days
    wrap. Transitive; the closure is derived by the synthesis loop, not assumed."""
    earlier: str
    later: str


@dataclass(frozen=True)
class Distribution:
    """A DISTRIBUTION relation — "<distributor> shared <measure> between/among <recipients>". Two readings,
    both resolved by the synthesis loop: (a) whole UNKNOWN, recipients NAMED, shares known → whole = Σ
    shares; (b) whole KNOWN and `equal` → each recipient gets whole ÷ `count`. Read off the obligation
    graph (share-verb + recipient group/noun + the measure). `recipients` = named members (may be empty);
    `count` = recipient count; `recipient_noun` = the share-holder type for an unnamed equal split;
    `method` = the split method bound from a manner adverb ("equal" is computable; others decline)."""
    distributor: str
    recipients: tuple
    measure: tuple
    count: int = None
    method: str = None
    recipient_noun: tuple = None


@dataclass(frozen=True)
class Frequency:
    """A how-many-times fact: "Mary jumps twice" → Frequency("mary", "jump", 2). Counts OCCURRENCES of
    an action (the verb), distinct from Quantity (a count of a noun)."""
    entity: str
    action: str
    count: float


def _frequency(reading: Reading):
    """The frequency a "<entity> <verb>s <multiplier>" statement asserts, or None — a multiplier that
    scales a verb whose subject is known. ("N times" — the frequency-noun form — comes later.)"""
    mult = next((u for u in reading.units if "multiplier" in u.features.get("senses", [])), None)
    if mult is None:
        return None
    verb = _follow(mult, "scales")
    if verb is None or "verb" not in verb.features.get("senses", []):   # scaling a quantifier instead
        return None                                                     # ("twice as many") → not a freq
    subject = _follow(verb, "subject")
    if subject is None:
        return None
    return Frequency(_entity(subject), _lemma(verb.surface), mult.features["value"])


def _relational_age_factor(reading: Reading):
    """The factor in an "as OLD as" comparison — "twice" / "<value> times" → its number, else None. (The
    multiplier scales the AGE dimension; "two times" is value-then-"times".)"""
    if not any(_key(u.surface) == "old" for u in reading.units):
        return None
    mult = next((u for u in reading.units if "multiplier" in u.features.get("senses", [])), None)
    if mult is not None:
        return mult.features["value"]
    units = reading.units
    for i, u in enumerate(units):                         # "<value> times as old" → the value is the factor
        if _key(u.surface) == "times" and i and "value" in units[i - 1].features.get("senses", []):
            return units[i - 1].features["value"]
    for i, u in enumerate(units):                         # "1/6 as old as Y" — a FRACTION/number written
        if "value" in u.features.get("senses", []) and i + 1 < len(units) \
                and _key(units[i + 1].surface) == "as" \
                and any(_key(units[j].surface) == "old" for j in range(i + 1, min(i + 4, len(units)))):
            return u.features["value"]                    # directly before "as … old" is the factor, not an age
    return None


def _possessive_age_parts(reading: Reading):
    """The (subject, standard, factor) of a POSSESSIVE relational age — "Jordyn's age is double Zrinka's
    age" / "Jerica is twice Louis' age" → subject's age = factor × standard's age. The possessive frame
    (the noun "age" owned via a name) instead of "as old as"; the multiplier mis-scales the copula, so we
    read it POSITIONALLY: the standard is the name after the multiplier that owns an "age". None if the
    frame doesn't apply. PURE-RATIO only (a comparative offset is left to other resolvers)."""
    units = reading.units
    if not any(_key(u.surface) == "age" for u in units):
        return None
    if any(_key(u.surface) == "as" for u in units):
        return None                                       # "as old as Y" is _relational_age's frame
    if any(_key(u.surface) in ("more", "less", "older", "younger", "fewer") for u in units):
        return None                                       # an offset on the factor we don't fold here
    if not any(_key(u.surface) in ("is", "are", "was", "were", "be") for u in units):
        return None                                       # "be" covers the future "X will BE k× Y's age"
    mult = next((u for u in units if "multiplier" in u.features.get("senses", [])), None)
    if mult is None:
        return None
    if "fraction" in mult.features:
        num, den = mult.features["fraction"]; k = num / den
    else:
        k = mult.features.get("value")
    if k is None:
        return None
    mi = units.index(mult)
    names = [u for u in units if "name" in u.features.get("senses", [])]
    if not names:
        return None
    # the standard Y owns an "age": EITHER "Y's age" (age within 3 AFTER the name) OR "the age of Y" (age
    # within 3 BEFORE it, past the multiplier). Both denote Y's-age as the scaled referent.
    std = next((u for i, u in enumerate(units) if i > mi and "name" in u.features.get("senses", [])
                and (any(_key(units[j].surface) == "age" for j in range(i + 1, min(i + 4, len(units))))
                     or any(_key(units[j].surface) == "age" for j in range(max(mi, i - 3), i)))), None)
    if std is None:
        return None
    cs = _copula_args(reading)[0]                         # the copula subject: a NAME, or a resolved pronoun
    subj = cs if (cs is not None and cs is not std        # ("she is one-third Tina's age" → she→Cori), else
                  and ("name" in cs.features.get("senses", [])           # the first non-standard name
                       or ("pronoun" in cs.features.get("senses", []) and _follow(cs, "refers") is not None))) \
        else next((u for u in names if u is not std), None)
    if subj is None or subj is std or _entity(subj) == _entity(std):
        return None
    return _entity(subj), _entity(std), k


def _possessive_age_statement(reading: Reading):
    """A plain POSSESSIVE age statement — "Ron's age is 43" / "Ron's age now is 43" → Quantity(ron, year,
    43). The noun 'age' owned by a name, a copula, and a value, with NO multiplier/comparative/"as" (those
    are the relational / possessive-relational frames). Without this the value stays unbound ("age" carries
    the predication and 43 quantifies nothing). Gated to exactly one name + one value → no relation to confuse."""
    units = reading.units
    if not any(_key(u.surface) == "age" for u in units):
        return None
    if any(_key(u.surface) == "as" for u in units) \
            or any("multiplier" in u.features.get("senses", []) for u in units) \
            or any(_key(u.surface) in ("more", "less", "older", "younger", "fewer") for u in units):
        return None
    if not any(_key(u.surface) in ("is", "are", "was", "were") for u in units):
        return None
    names = [u for u in units if "name" in u.features.get("senses", [])]
    vals = [u for u in units if "value" in u.features.get("senses", [])]
    if len(names) != 1 or len(vals) != 1:
        return None
    return Quantity(_entity(names[0]), ("year", frozenset()), vals[0].features["value"], "be")


def _simultaneous_ages(reading: Reading):
    """"X was A years old WHEN Y was B years old" → two age facts at a common reference time, stored as
    current ages (the constant gap is what a later "when Y turns M" projection needs; with no other anchor,
    'then' = 'now'). Each side is a plain "<name> was <value> years old" clause flanking "when"."""
    units = reading.units
    when = next((u for u in units if _key(u.surface) == "when"
                 and "conjunction" in u.features.get("senses", [])), None)
    if when is None or not any(_key(u.surface) == "old" for u in units):
        return None

    def age_of(span):
        name = next((u for u in span if "name" in u.features.get("senses", [])), None)
        val = next((u.features["value"] for u in span if "value" in u.features.get("senses", [])
                    and _follow(u, "quantifies") is not None
                    and _descriptor(_follow(u, "quantifies"))[0] == "year"), None)
        if name is None or val is None:
            return None
        return Quantity(_entity(name), ("year", frozenset()), val, "be")

    wi = units.index(when)
    left, right = age_of(units[:wi]), age_of(units[wi + 1:])
    if left is None or right is None or left.entity == right.entity:
        return None
    return [left, right]


def _relational_age(reading: Reading, context: list):
    """A RELATIONAL AGE — "X is N times as old as Y" → X's age = N × Y's age (the year-Quantity of the
    standard Y). None when Y's age isn't known yet — the solve() fixpoint then chains a multi-hop
    (Anne = 2×Emile, Emile = 6×Maude, Maude = 8 → 96)."""
    factor = _relational_age_factor(reading)
    if factor is None:
        return None
    if any(_key(u.surface) in ("more", "less", "older", "younger", "fewer") for u in reading.units):
        return None                                       # "N more than k× as old as Y" — a comparative
        # OFFSET on top of the factor that we don't fold into the age relation (we'd compute only k×Y and
        # drop the +N). DECLINE rather than commit that wrong → defers, so a nested standard stays unknown.
    subj, _ = _copula_args(reading)                       # X — the copula's subject
    if subj is None:
        return None
    standard = next((u for u in reversed(reading.units)   # Y — the LAST name ("as old as EMILE"), not X
                     if "name" in u.features.get("senses", []) and u is not subj), None)
    if standard is None:
        return None
    y_now = _holdings(_entity(standard), ("year", frozenset()), context)
    delta = _time_offset(reading)
    si = reading.units.index(standard)                    # the present-anchor ("as Y is NOW") follows the
    std_now = any(_key(u.surface) in ("now", "today")     # standard; the displacement "from NOW" precedes
                  for u in reading.units[si + 1:])         # it — so look only to the RIGHT of the standard
    if y_now is None:
        # BACKWARD (age twin of #107): Y's age unknown, but if X's (the subject's) is known, INVERT so the
        # fixpoint chains backward through age relations too. Pure-ratio (the offset case is excluded above).
        # Mutually exclusive with the forward path, which needs Y known — no double-emit.
        x_now = _holdings(_entity(subj), ("year", frozenset()), context)
        if x_now is None or not factor:
            return None                                   # Y's age unknown → defer (see _facts_from)
        if delta == 0:                                    # present: X = k·Y → Y = X / k ("Sam 12, twice Sue" → 6)
            return Quantity(_entity(standard), ("year", frozenset()),
                            _compute(f"{_num(x_now)} / {_num(factor)}"), "be")
        # SHIFTED backward: X+Δ = k·(Y+Δ) → Y_now = (X_now+Δ)/k − Δ ("After 5 yrs Ron = 4× Maurice; Ron 43"
        # → Maurice = (43+5)/4 − 5 = 7). The "as Y is NOW" anchor drops the −Δ: X+Δ = k·Y_now → Y_now =
        # (X_now+Δ)/k.
        x_future = f"({_num(x_now)} + {_num(delta)})"
        y_now_expr = f"{x_future} / {_num(factor)}" if std_now \
            else f"{x_future} / {_num(factor)} - {_num(delta)}"
        return Quantity(_entity(standard), ("year", frozenset()), _compute(y_now_expr), "be")
    if delta == 0:                                        # present-tense relation: X = k × Y_now
        return Quantity(_entity(subj), ("year", frozenset()),
                        _compute(f"{_num(factor)} * {_num(y_now)}"), "be")
    # SHIFTED relation "In Δ years, X will be k× as old as Y": BOTH are at the future point by default
    # (X+Δ = k·(Y+Δ)), so X_now = k·(Y_now+Δ) − Δ. The variant "as Y is NOW/today" anchors the standard
    # to the present (X+Δ = k·Y_now → X_now = k·Y_now − Δ) — else the Kaylee class commits a wrong.
    y_future = _num(y_now) if std_now else f"({_num(y_now)} + {_num(delta)})"
    x_now = _compute(f"{_num(factor)} * {y_future} - {_num(delta)}")
    return Quantity(_entity(subj), ("year", frozenset()), x_now, "be")


def _future_age(reading: Reading):
    """A FUTURE age stated with a time displacement: "(In N years,) E will be X years old" / "E will be X
    years old in N years" → E's age NOW = X − N. The offset and the age share the 'year' token (so
    _time_offset can't separate them); the offset is the value quantifying the "in"/"after" preposition's
    object, the age is the OTHER year-value (by 'old'). Future tense ("will") required."""
    units = reading.units
    if not any(_key(u.surface) == "old" for u in units) \
            or not any(_key(u.surface) == "will" and "auxiliary" in u.features.get("senses", []) for u in units):
        return None
    off_prep = next((u for u in units if "preposition" in u.features.get("senses", [])
                     and _key(u.surface) in ("in", "after")), None)
    off_obj = _follow(off_prep, "object") if off_prep is not None else None
    if off_obj is None or _descriptor(off_obj)[0] != "year":
        return None
    off_val = next((u.features["value"] for u in units if "value" in u.features.get("senses", [])
                    and _follow(u, "quantifies") is off_obj), None)
    age_val = next((u.features["value"] for u in units if "value" in u.features.get("senses", [])
                    and _follow(u, "quantifies") is not None and _follow(u, "quantifies") is not off_obj
                    and _descriptor(_follow(u, "quantifies"))[0] == "year"), None)
    subj = next((u for u in units if "name" in u.features.get("senses", [])), None)
    if off_val is None or age_val is None or subj is None:
        return None
    return Quantity(_entity(subj), ("year", frozenset()),
                    _compute(f"{_num(age_val)} - {_num(off_val)}"), "be")


def _comparative_age(reading: Reading, context: list):
    """A COMPARATIVE age — "X is N years older/younger than Y" → X's age = Y's age ± N. Defers (None) until
    Y's age is known (the fixpoint then resolves it). Distinct from _relational_age's MULTIPLICATIVE "N
    times as old"; this is the ADDITIVE year-offset form."""
    units = reading.units
    comp = next((u for u in units if "comparative" in u.features.get("senses", [])
                 and _key(u.surface) in ("older", "younger")), None)
    than = next((u for u in units if _key(u.surface) == "than"), None)
    y = _follow(than, "object") if than is not None else None
    val = next((u.features["value"] for u in units if "value" in u.features.get("senses", [])
                and _follow(u, "quantifies") is not None
                and _descriptor(_follow(u, "quantifies"))[0] == "year"), None)
    subj, _ = _copula_args(reading)
    if comp is None or y is None or val is None or subj is None \
            or "name" not in y.features.get("senses", []):
        return None
    y_age = _holdings(_entity(y), ("year", frozenset()), context)
    if y_age is None:
        # BACKWARD inversion — Y's age unknown, but if the SUBJECT's is known, invert the relation:
        # "Benjie is 5 older than Margo; Benjie is 6" → Margo = 6 − 5. (older: subj = std + N → std =
        # subj − N; younger flips.) Grounds the standard so the fixpoint can chain onward, mirroring
        # _relational_quantity's bidirectional grounding. Defers if the subject's age is unknown too.
        subj_age = _holdings(_entity(subj), ("year", frozenset()), context)
        if subj_age is None:
            return None
        inv = "-" if _key(comp.surface) == "older" else "+"
        return Quantity(_entity(y), ("year", frozenset()),
                        _compute(f"{_num(subj_age)} {inv} {_num(val)}"), "be")
    op = "+" if _key(comp.surface) == "older" else "-"
    return Quantity(_entity(subj), ("year", frozenset()),
                    _compute(f"{_num(y_age)} {op} {_num(val)}"), "be")


def _relational_quantity(reading: Reading, context: list):
    """A DERIVED quantity — "Mary has twice as many" → `factor × referent`, the referent being the most
    recent prior Quantity (resolved like coreference, but for a quantity). The referent supplies the
    measure; the multiplier supplies the factor. None if there's no multiplier-on-a-quantifier or no
    referent to scale."""
    mult = next((u for u in reading.units if "multiplier" in u.features.get("senses", [])), None)
    if mult is None:
        return None
    scaled = _follow(mult, "scales")                     # must scale "as many" (a quantifier), "the number"
    if scaled is None or not ("quantifier" in scaled.features.get("senses", [])   # (a count-noun), or "as
                              or _key(scaled.surface) in (COUNT_NOUNS | DIMENSIONS)):  # long/far" (a
        return None                                                               # dimension) — not a verb
    # TIME-INDEXED relational ("twice as many boxes on Tuesday as she did on Wednesday") — the referent is
    # the SAME entity at a DIFFERENT time, identified by the 2nd "on <day>". We resolve the referent by
    # ENTITY (recency), not time, so we'd grab the wrong day's value and chain garbage → DECLINE. (A full
    # solve needs time-tagged relational quantities + a per-day referent + time-aware answer fold.)
    if sum(1 for u in reading.units if "time" in u.features.get("senses", [])) >= 2:
        return None
    # NOTE: a relative-clause referent ("twice the number (that) X has", "the number of flowers he
    # sold") was prototyped here (read subject/referent off POSITION around the multiplier, to survive
    # the relative clause's 2nd verb / the matrix "has" mis-reading as an auxiliary). It resolved the
    # sub-fact correctly but was REVERTED: the problems that use it are predominantly multi-step
    # (Monica's 3-year chain, Ali's multi-day shop) and fail downstream, so it traded +2 dev solves for
    # +3 confident-wrongs — net precision-negative. Deferred until multi-step composition is stronger;
    # such forms stay an honest DECLINE for now. See reading-bench-firewall-prefix memory.
    verbs = [u for u in reading.units if "verb" in u.features.get("senses", [])]
    subject = _follow(verbs[0], "subject") if len(verbs) == 1 else None
    if subject is None:
        return None
    # a subject that sits right after "as" is really the STANDARD, not the subject — the real subject was
    # elided from a prior conjunct ("[Jennifer bought] three times as many as BOB bought"). We'd mis-read
    # it as "Bob = 3 × recent" and commit garbage; the elided-subject inverse is unresolved → DECLINE.
    si = reading.units.index(subject)
    if si > 0 and _key(reading.units[si - 1].surface) == "as":
        return None
    # the referent: a NAMED quantity ("half as many as TIM" — a name other than the subject), else the
    # most recent prior quantity ("twice as many" — implicit, like coreference).
    named = [u for u in reading.units if "name" in u.features.get("senses", []) and u is not subject]
    if named:
        ref_ent = _entity(named[-1])
        referent = next((f for f in reversed(context or [])
                         if isinstance(f, Quantity) and f.entity == ref_ent), None)
        if referent is None:
            # BIDIRECTIONAL grounding — the named standard has no quantity yet, but if the SUBJECT does,
            # INVERT the relation: standard = subject / factor ("Tyrah has 6× as many pencils as Sarah;
            # Tyrah has 12" → Sarah = 2). The forward path only derives subject-FROM-standard; this grounds
            # the standard so the solve() fixpoint chains backward too (Sarah=2 → Tim = 8×2 = 16). PURE-RATIO
            # only: a comparative offset ("5 more than twice as many as B") inverts ambiguously → keep deferring.
            comp0 = any("comparative" in u.features.get("senses", []) for u in reading.units)
            subj_q = next((f for f in reversed(context or []) if isinstance(f, Quantity)
                           and f.entity == _entity(subject) and f.amount is not None), None)
            if subj_q is not None and not comp0:
                if "fraction" in mult.features:
                    num, denom = mult.features["fraction"]
                    inv = f"{_num(subj_q.amount)} * {denom} / {num}"
                else:
                    inv = f"{_num(subj_q.amount)} / {_num(mult.features['value'])}"
                return Quantity(ref_ent, subj_q.measure, _compute(inv),
                                _lemma(verbs[0].surface), derived=True)   # the relation's verb (run/have),
                #                                                          so the answer fold can match it
    else:                                                 # IMPLICIT referent: prefer the most-recent
        quants = [f for f in reversed(context or []) if isinstance(f, Quantity)]   # NON-derived baseline
        referent = next((f for f in quants if not f.derived), None) or next(iter(quants), None)
    if referent is None:                                  # ("Ella worked twice as long" scales AMBER, not
        return None                                       # the just-derived Armand sitting between them)
    if "fraction" in mult.features:                       # exact: (referent × num) / denom, divide LAST
        num, denom = mult.features["fraction"]            # ("12 × 2 / 3" = 8, dodging 0.666×12 float drift)
        expr = f"{_num(referent.amount)} * {num} / {denom}"
    else:
        expr = f"{_num(mult.features['value'])} * {_num(referent.amount)}"
    comp = next((u for u in reading.units if "comparative" in u.features.get("senses", [])), None)
    offset = next((u for u in reading.units if "value" in u.features.get("senses", [])), None)
    if comp is not None and offset is not None:          # "FIVE MORE than twice as many as Bob" → 2×Bob+5
        expr += f" + {COMPARATIVE_SIGN.get(_key(comp.surface), 1)} * {_num(offset.features['value'])}"
    return Quantity(_entity(subject), referent.measure, _compute(expr), _lemma(verbs[0].surface),
                    derived=True)


def _partitive_quantity(reading: Reading, context: list):
    """A PARTITIVE quantity — `fraction × a holding`, a relational CHANGE (the "of" makes the fraction a
    part of a SET, not a verb multiplier). "loses half OF them" → 0.5 × the subject's current holding;
    "buys a third OF what he had on Tuesday" → (1/3) × that holder's holding AT Tuesday. The of-clause
    decides the base: a verb + holder + time ("what he had on Tuesday") → `_holdings_at`; else the
    subject's own current set ("of them"). None if there's no base to take the fraction of."""
    units = reading.units
    frac = next((u for u in units if _fraction_parts(u.surface) is not None), None)   # unit OR non-unit
    fi = units.index(frac) if frac is not None else -1
    if frac is None or fi + 1 >= len(units) or _key(units[fi + 1].surface) != "of":   # "<frac> OF …"
        return None
    left_verbs = [u for k, u in enumerate(units) if k < fi and "verb" in u.features.get("senses", [])]
    if not left_verbs:                                    # the partitive attaches to the verb on its LEFT
        return None                                       # (a verb inside the of-clause is embedded)
    main_verb = left_verbs[-1]
    subject = _follow(main_verb, "subject")
    if subject is None:
        return None
    ent = _entity(subject)
    of = units[fi + 2:]
    of_verb = next((u for u in of if "verb" in u.features.get("senses", [])), None)
    of_pron = next((u for u in of if any(s in u.features.get("senses", []) for s in ("name", "pronoun"))), None)
    of_noun = next((u for u in of if "noun" in u.features.get("senses", [])), None)
    of_time = next((_key(u.surface) for u in of if "time" in u.features.get("senses", [])), None)
    if of_verb is not None and of_pron is not None:       # "… what HE had on Tuesday" — a holder's value
        ref_ent, ref_time = _entity(of_pron), of_time
    else:                                                 # "… of THEM" — the subject's own current set
        ref_ent, ref_time = ent, None
    measure = _descriptor(of_noun) if of_noun is not None else None
    if measure is None:                                   # no measure named → the referent's latest one
        recent = next((f for f in reversed(context or [])
                       if isinstance(f, Quantity) and f.entity == ref_ent), None)
        measure = recent.measure if recent is not None else None
    if measure is None:
        return None
    base = _holdings_at(ref_ent, measure, context or [], ref_time) if ref_time \
        else _holdings(ref_ent, measure, context or [])
    if base is None:
        return None
    num, denom = _fraction_parts(frac.surface)            # exact: base × num / denom (divide last)
    return Quantity(ent, measure, _compute(f"{_num(base)} * {num} / {denom}"),
                    _lemma(main_verb.surface), _time_at(reading, main_verb), derived=True)


def _comparative_quantity(reading: Reading, context: list):
    """A DERIVED quantity from a comparison — "Tim has 30 less apples than Martha" → `referent ± N`,
    the referent being the NAMED standard's holdings (resolved by name via `than`). None unless there's
    a comparative + a value + a known standard. "more" → +N; "less"/"fewer" → −N."""
    comp = next((u for u in reading.units if "comparative" in u.features.get("senses", [])), None)
    if comp is None:
        return None
    if any(_key(u.surface) == "times" for u in reading.units):   # "25 TIMES more" is multiplicative,
        return None                                              # not our additive ±N — don't guess
    standard = _follow(comp, "standard")
    value_unit = next((u for u in reading.units if "value" in u.features.get("senses", [])), None)
    verbs = [u for u in reading.units if "verb" in u.features.get("senses", [])]
    subject = next((_follow(v, "subject") for v in verbs if _follow(v, "subject") is not None), None)
    if value_unit is None or subject is None:            # multi-verb ("has been teaching") — any bound subj
        return None
    elided_measure = False
    if "measure" in value_unit.features:                 # "$10 more than William" — money value
        measure = value_unit.features["measure"]
    else:                                                # "30 less apples than Martha" — value+noun
        noun = _follow(value_unit, "quantifies")
        if noun is None:                                 # ELIDED measure — "Riley has 3 fewer." The noun is
            # gone, so the most-recent prior Quantity must supply BOTH measure and base. Restricted to the
            # BARE frame (no "than" at all): an anaphoric "47 more than that" reads correctly here but tends
            # to sit in a multi-step chain (Billy/Katelyn/Chloe) where a later part stays underived, so
            # deriving this one turns an honest decline into a partial-sum confident-wrong.
            if standard is not None or any(_key(u.surface) == "than" for u in reading.units):
                return None
            elided_measure = True
            measure = None
        else:
            measure = _descriptor(noun)
    # MEASURE-to-MEASURE: the standard is another MEASURE of the SAME subject (same head noun, different
    # attribute) — "2 fewer ANIMAL stickers than FLOWER stickers" → animal = subject's flower count ± N.
    # (Distinct from the entity-standard grounding below, which reads ANOTHER person's holdings.)
    if standard is not None and subject is not None and measure is not None \
            and "name" not in standard.features.get("senses", []) and "noun" in standard.features.get("senses", []):
        std_measure = _descriptor(standard)
        if std_measure[0] == measure[0] and std_measure != measure:
            base = _holdings(_entity(subject), std_measure, context or [])
            if base is not None:
                op = "-" if COMPARATIVE_SIGN.get(_key(comp.surface), 1) < 0 else "+"
                return Quantity(_entity(subject), measure,
                                _compute(f"{_num(base)} {op} {_num(value_unit.features['value'])}"),
                                _lemma(verbs[-1].surface), derived=True)
    if standard is not None:                             # explicit "… than Y" — Y's holdings, but expressed
        referent = _holdings(_entity(standard), measure, context or [])   # in the SUBJECT's frame: _holdings
        if referent is not None:                         # is signed (a loss nets −17.5), while stored amounts
            referent *= _verb_sign(_lemma(verbs[-1].surface))   # are magnitudes — so a loss compared with a
    else:                                                # loss ("lost 1.5 more than Seth") compares MAGNITUDES
        base = next((f for f in reversed(context or [])   # (17.5+1.5=19, not −17.5+1.5). IMPLICIT standard —
                     if isinstance(f, Quantity) and (elided_measure or f.measure == measure)  # "10 years less"
                     and f.amount is not None), None)    # — is a stored magnitude; an elided measure inherits
        referent = base.amount if base is not None else None   # the most-recent quantity's measure too.
        if elided_measure and base is not None:
            measure = base.measure
    if referent is None:
        return None                                      # standard's count unknown (e.g. forward ref)
    op = "-" if COMPARATIVE_SIGN.get(_key(comp.surface), 1) < 0 else "+"   # younger/less → −, older/more → +
    return Quantity(_entity(subject), measure,
                    _compute(f"{_num(referent)} {op} {_num(value_unit.features['value'])}"),
                    _lemma(verbs[-1].surface), derived=True)


@dataclass(frozen=True)
class Rate:
    """A per-unit rate: "Weng earns $12 per hour" → Rate("weng", 12, MONEY, "hour", "earn"). The total
    is `amount × (the quantity of per_unit)` — composed at answer time, not stored."""
    entity: str
    amount: float
    measure: tuple
    per_unit: str
    verb: str
    per_amount: float = 1            # "8 pages in 20 MINUTES" → amount=8, per_unit=minute, per_amount=20


@dataclass(frozen=True)
class RateRel:
    """A pending RELATIONAL rate: `subject`'s rate (of `verb`) = `factor` × `reference`'s rate. Resolved by
    the synthesis loop in EITHER direction — forward (reference's rate known → subject = factor × ref) or
    inverse (subject's rate known → reference = subject ÷ factor). So "Carole reads as fast as Anna (×1)
    but at half the speed of Brianna (×0.5)" chains Anna(1/min) → Carole(1/min) → Brianna(2/min)."""
    subject: str
    factor: float
    reference: str
    verb: str


def _rate(reading: Reading, context: list = None):
    """The rate a statement asserts — "$12 per hour" / "$12 an hour" / "20 pages a day" → Rate(entity,
    amount, measure, per_unit, verb). The per-marker is "per", or "a"/"an" before a unit noun when it
    sits right after a money value or a quantified measure-noun (so a plain article "a book" is NOT a
    rate). The measure is a self-measuring money value, or the noun the rate value quantifies. Else None."""
    units = reading.units
    per = next((u for u in units if "per" in u.features.get("senses", [])), None)
    rate_val = unit = rate_noun = None
    per_amount = 1
    if per is not None:                                  # explicit "per"
        rate_val, unit = _follow(per, "rate"), _follow(per, "unit")
    else:                                                # "a"/"an"/"every"/"each" as per — after the measure
        for k in range(1, len(units) - 1):
            if _key(units[k].surface) not in ("a", "an", "every", "each") \
                    or "noun" not in units[k + 1].features.get("senses", []):
                continue
            prev = units[k - 1]
            if "measure" in prev.features:               # "$12 an hour"
                rate_val, unit = prev, units[k + 1]
                break
            if "noun" in prev.features.get("senses", []):   # "20 pages a day" — the value quantifying prev,
                run, j = [], k - 1                           # or, for a COMPOUND noun ("7 apple pies a day"),
                while j >= 0 and "noun" in units[j].features.get("senses", []):  # any noun in the contiguous
                    run.append(units[j]); j -= 1             # run ending at prev (the value quantifies the
                v = next((x for x in units if "value" in x.features.get("senses", [])   # head 'apple', the
                          and _follow(x, "quantifies") in run), None)                   # rate-noun is 'pies')
                if v is not None:
                    rate_val, unit, rate_noun = v, units[k + 1], prev   # measure is the rate-noun (prev),
                    break                                               # not what the value quantifies
    if rate_val is None:                                 # "N <measure> in M <time-unit>" — a per-M rate
        inp = next((u for u in units if _key(u.surface) == "in"), None)
        tu = _follow(inp, "object") if inp is not None else None
        if tu is not None and _descriptor(tu)[0] in TIME_UNITS:
            per_v = next((x for x in units if "value" in x.features.get("senses", [])
                          and _follow(x, "quantifies") is tu), None)
            mv = next((x for x in units if "value" in x.features.get("senses", [])
                       and _follow(x, "quantifies") is not None
                       and _descriptor(_follow(x, "quantifies"))[0] not in TIME_UNITS), None)
            if per_v is not None and mv is not None:
                rate_val, unit, per_amount = mv, tu, per_v.features["value"]
            elif mv is not None:                         # "75 pages in AN hour" — no explicit duration value,
                ti = units.index(tu)                     # so the article a/an/each/every means a SINGLE unit
                if ti > 0 and _key(units[ti - 1].surface) in ("a", "an", "each", "every"):
                    rate_val, unit, per_amount = mv, tu, 1
    if rate_val is None:                                 # "N <time-unit> over M <time-unit>" — a
        ov = next((u for u in units if _key(u.surface) == "over"), None)   # time-over-time rate ("reads
        tu = _follow(ov, "object") if ov is not None else None             # 10 hours over 5 days" = 2 h/day).
        if tu is not None and _descriptor(tu)[0] in TIME_UNITS:            # BOTH sides must be time units
            per_v = next((x for x in units if "value" in x.features.get("senses", [])   # (a non-time
                          and _follow(x, "quantifies") is tu), None)                     # measure "30 points
            mv = next((x for x in units if "value" in x.features.get("senses", [])       # over 5 games" is
                       and _follow(x, "quantifies") is not None and x is not per_v        # not a duration
                       and _descriptor(_follow(x, "quantifies"))[0] in TIME_UNITS), None)  # rate — declines)
            if per_v is not None and mv is not None:
                rate_val, unit, per_amount = mv, tu, per_v.features["value"]
    if rate_val is None or unit is None:
        return None
    verbs = [u for u in units if "verb" in u.features.get("senses", [])]
    subject = _follow(verbs[0], "subject") if len(verbs) == 1 else None
    if subject is None:
        return None
    entity = _entity(subject)
    if entity == "rate":                                 # "(he) reads at a RATE of 50 pages an hour" — the
        # rate-marker noun "rate" was grabbed as the elided subject; recover the real entity from context
        # (the most-recent prior holder) so the two rates share an entity and `_synth_rate_chain` composes.
        entity = next((f.entity for f in reversed(context or [])
                       if isinstance(f, (Rate, Quantity)) and f.entity != "rate"), None)
        if entity is None:
            return None
    if "measure" in rate_val.features:                   # "$12" — a self-measuring money rate
        measure = rate_val.features["measure"]
    else:                                                # "20 PAGES a day" — the noun the value quantifies,
        mnoun = rate_noun or _follow(rate_val, "quantifies")   # or the compound rate-noun ("apple PIES")
        measure = _descriptor(mnoun) if mnoun is not None else None
    if measure is None:
        return None
    amount = rate_val.features["value"]
    # RELATIONAL RATE — "Sarah makes 5 times more money per hour THAN Connor": the rate is N × another
    # entity's rate ("times" operator + a comparative whose standard is a NAME). Resolve against that
    # entity's known rate of the same measure/per_unit; DEFER (None) if it isn't known yet (forward ref).
    comp = next((u for u in reading.units if "comparative" in u.features.get("senses", [])), None)
    std = _follow(comp, "standard") if comp is not None else None
    if std is not None and "name" in std.features.get("senses", []) \
            and any(_key(u.surface) == "times" for u in reading.units):
        base = next((f for f in reversed(context or []) if isinstance(f, Rate)
                     and f.entity == _entity(std) and f.measure == measure
                     and f.per_unit == _descriptor(unit)[0]), None)
        if base is None:
            return None                                  # standard's rate unknown yet — defer to the fixpoint
        amount = _compute(f"{_num(amount)} * {_num(base.amount)}")
    return Rate(entity, amount, measure,
                _descriptor(unit)[0], _lemma(verbs[0].surface), per_amount)


def _time_range_rate(reading: Reading):
    """A clock TIME-RANGE done every period is an hours-per-period Rate: "writes from 1 PM to 4 PM every
    night" → 4PM−1PM = 3 hours, "every night" → per day (a night is a daily occurrence) → Rate(3 hours
    per day). Needs a "from <clock> to <clock>" pair (a value + AM/PM meridiem each) and an "every/each
    <period>". Returns None unless the whole shape is present, so it never steals a plain quantity."""
    units = reading.units
    merid = [(i, _key(u.surface)) for i, u in enumerate(units) if _key(u.surface) in ("am", "pm")]
    if len(merid) != 2:
        return None
    hours = []                                           # the two clock times as 24-hour values
    for mi, mk in merid:
        v = next((units[j] for j in range(mi - 1, -1, -1)               # nearest preceding value
                  if "value" in units[j].features.get("senses", [])), None)
        if v is None:
            return None
        h = v.features["value"] % 12 + (12 if mk == "pm" else 0)        # 1 PM → 13, 4 PM → 16
        hours.append(h)
    span = hours[1] - hours[0]                            # text order = chronological (from … to …)
    if span <= 0:
        return None
    per = next((units[k + 1] for k in range(len(units) - 1)             # "every/each <period>"
                if _key(units[k].surface) in ("every", "each")
                and "noun" in units[k + 1].features.get("senses", [])), None)
    if per is None:
        return None
    per_unit = _descriptor(per)[0]
    per_unit = "day" if per_unit in ("night", "day") else per_unit      # a night is a daily occurrence
    if per_unit not in TIME_UNITS:
        return None
    verbs = [u for u in units if "verb" in u.features.get("senses", [])]
    subject = _follow(verbs[0], "subject") if verbs else None
    if subject is None:
        return None
    return Rate(_entity(subject), span, ("hour", frozenset()), per_unit, _lemma(verbs[0].surface), 1)


SPEED_WORDS = {"fast", "quick", "slow"}                   # manner adjectives that compare a rate
SPEED_NOUNS = {"speed", "pace"}                           # "half the SPEED of X"


def _rate_relations(reading: Reading):
    """Relational rate(s) keyed off a SPEED cue: "Carole reads as fast as Anna but at half the speed of
    Brianna" → [RateRel(carole, 1.0, anna), RateRel(carole, 0.5, brianna)]. Two shapes: "as <speed-adj>
    as <NAME>" (equality, ×1) and "<multiplier> the <speed-noun> of <NAME>" (×multiplier). Gated on a
    speed word/noun so it never hijacks a plain comparative; the synth resolves them bidirectionally."""
    units = reading.units
    if not any(_key(u.surface) in SPEED_WORDS or _key(u.surface) in SPEED_NOUNS for u in units):
        return None
    verbs = [u for u in units if "verb" in u.features.get("senses", [])]
    subject = _follow(verbs[0], "subject") if verbs else None
    if subject is None:
        return None
    subj, verb = _entity(subject), _lemma(verbs[0].surface)
    keys = [_key(u.surface) for u in units]
    rels = []
    for i, u in enumerate(units):
        if keys[i] in SPEED_WORDS and 0 < i < len(units) - 2 \
                and keys[i - 1] == "as" and keys[i + 1] == "as" \
                and "name" in units[i + 2].features.get("senses", []):   # "as fast as Anna" → ×1
            rels.append(RateRel(subj, 1.0, _entity(units[i + 2]), verb))
        if keys[i] in SPEED_NOUNS:                                        # "half the speed of Brianna"
            mult = next((units[j] for j in range(i - 1, -1, -1)
                         if "multiplier" in units[j].features.get("senses", [])), None)
            of = next((units[j] for j in range(i + 1, len(units)) if keys[j] == "of"), None)
            ref = _follow(of, "object") if of is not None else None
            if mult is not None and ref is not None and "name" in ref.features.get("senses", []):
                rels.append(RateRel(subj, mult.features["value"], _entity(ref), verb))
    return rels or None


def _per_occurrence_rate(reading: Reading):
    """A per-OCCURRENCE rate fronted by "For every/each <noun> …, <subject> <verb>s N <measure>": "For every
    sandwich that he eats, Sam eats four apples" → Rate(sam, 4, apple, per_unit=sandwich, eat). The leading
    "for every <noun>" names the per_unit (a non-time occurrence); the main clause gives the amount/measure/
    subject. The rate_duration synth then takes it × an occurrence COUNT (70 sandwiches → 280 apples)."""
    units = reading.units
    keys = [_key(u.surface) for u in units]
    if not (len(units) > 2 and keys[0] == "for" and keys[1] in ("every", "each")
            and "noun" in units[2].features.get("senses", [])):
        return None
    per_unit = _descriptor(units[2])[0]
    val = next((u for u in units if "value" in u.features.get("senses", [])              # "four apples"
                and _follow(u, "quantifies") is not None
                and _descriptor(_follow(u, "quantifies"))[0] != per_unit), None)
    if val is None:
        return None
    measure = _descriptor(_follow(val, "quantifies"))
    name = next((u for u in units if "name" in u.features.get("senses", [])), None)       # main subject (Sam)
    # the main verb is the one nearest the value (skip the relative-clause verb "that he eats")
    verbs = [u for u in units if "verb" in u.features.get("senses", [])]
    if name is None or not verbs:
        return None
    vi = units.index(val)
    verb = min(verbs, key=lambda v: abs(units.index(v) - vi))
    return Rate(_entity(name), val.features["value"], measure, per_unit, _lemma(verb.surface), 1)


def _for_duration(reading: Reading, rate: "Rate"):
    """A trailing "for <value> <time-unit>" duration ("…every day FOR ONE WEEK") → a Quantity counting that
    unit, so the rate_duration synth can accumulate the rate over it. Emitted ALONGSIDE the rate (the rate
    parse alone drops it). SKIPS a unit that is the rate's own MEASURE ("for 8 HOURS a day" — the 8 hours
    is the rate value, not a duration), which would double-count. Returns None if there's none."""
    units = reading.units
    for i, u in enumerate(units):
        if _key(u.surface) != "for":
            continue
        v = next((units[j] for j in range(i + 1, len(units))
                  if "value" in units[j].features.get("senses", [])), None)
        if v is None:
            continue
        qn = _follow(v, "quantifies")
        if qn is not None and _descriptor(qn)[0] in TIME_UNITS \
                and _descriptor(qn)[0] != rate.measure[0]:
            return Quantity(rate.entity, _descriptor(qn), v.features["value"], rate.verb)
    return None


REST_WORDS = {"rest", "remainder", "others"}


def _rest_quantity(reading: Reading, context: list):
    """The COMPLEMENT category — "the REST <verb>" → the population total − Σ(the stated subsets of the same
    measure). The population is a have/be quantity ("a class HAS 60 students"); the subsets are the other
    quantities of that measure ("40 passed" / a percent-of-count). Summed by MEASURE (entity keying of a
    plural subject is inconsistent), so e.g. "60 students; 40 passed; the rest failed" → 20 failed."""
    units = reading.units
    rest = next((u for u in units if _key(u.surface) in REST_WORDS), None)
    if rest is None:
        return None
    verbs = [u for u in units if "verb" in u.features.get("senses", [])
             and _key(u.surface) not in ("is", "are", "was", "were")]
    if len(verbs) != 1:
        return None
    subj = _follow(verbs[0], "subject")
    if subj is None or _key(subj.surface) not in REST_WORDS:   # "the rest" must BE the subject
        return None
    totals = [f for f in context if isinstance(f, Quantity)    # the population: a have/be total
              and f.verb in ("have", "be") and f.amount is not None]
    if not totals:
        return None
    total = totals[-1]
    subs = [f.amount for f in context if isinstance(f, Quantity) and f.measure == total.measure
            and f.verb not in ("have", "be") and f.amount is not None]
    expr = _num(total.amount) + "".join(f" - {_num(s)}" for s in subs)   # total − sub1 − sub2 …
    return Quantity(total.measure[0], total.measure, _compute(expr), _lemma(verbs[0].surface))


def _percent_quantity(reading: Reading, context: list):
    """A percentage OF A HOLDING/COUNT. Two shapes: (a) NO explicit base — "puts 20% more money" → 0.2 ×
    the matching prior quantity (the portion; its base is the referent a noun here names). (b) base is a
    NOUN — "40% OF the students passed" → 0.4 × the students' quantity (the count of students who passed).
    A VALUE base ("20% of 50") is pure arithmetic, handled elsewhere."""
    pct = next((u for u in reading.units if "percent" in u.features.get("senses", [])), None)
    if pct is None:
        return None
    if _follow(pct, "base") is not None:                  # "20% OF 50" — an explicit VALUE base: arithmetic
        return None
    of = next((u for u in reading.units if _key(u.surface) == "of"            # "X% OF the <noun>" — a
               and _follow(u, "anchor") is pct), None)                        # percent of a COUNT
    noun_base = None
    if of is not None:                                   # the of-phrase HEAD = the LAST noun before a verb
        units, oi = reading.units, reading.units.index(of)   # ("of his Grade-5 STUDENTS got …" → students,
        for u in units[oi + 1:]:                             # the head, not the "Grade 5" classifier)
            if "verb" in u.features.get("senses", []):
                break
            if "noun" in u.features.get("senses", []):
                noun_base = u
    if noun_base is not None and "noun" in noun_base.features.get("senses", []):
        ref = next((f for f in reversed(context or [])
                    if isinstance(f, Quantity) and f.measure == _descriptor(noun_base)), None)
        if ref is None:
            return None
        cverbs = [u for u in reading.units if "verb" in u.features.get("senses", [])
                  and _key(u.surface) not in ("is", "are", "was", "were")]
        cverb = _lemma(cverbs[0].surface) if cverbs else "have"
        return Quantity(_descriptor(noun_base)[0], _descriptor(noun_base),
                        _compute(f"{_num(pct.features['value'])} * {_num(ref.amount)}"), cverb)
    verbs = [u for u in reading.units if "verb" in u.features.get("senses", [])]
    subject = _follow(verbs[0], "subject") if len(verbs) == 1 else None
    if subject is None:
        return None
    measures = {_descriptor(u) for u in reading.units if "noun" in u.features.get("senses", [])}
    referent = next((f for f in reversed(context or [])
                     if isinstance(f, Quantity) and f.measure in measures), None)
    if referent is None:
        return None
    # CROSS-ENTITY "N% more/less THAN X" ("Mark has 50% more points than Eric") → the FULL derived amount
    # X × (1 ± pct) = 6 × 1.5 = 9, not just the portion (0.5×6=3). Gated on a comparative WITH a "than"
    # standard: a SAME-entity "puts 20% more money" (comparative, NO than-standard) keeps the portion
    # reading below, since its base is the entity's own holding that the fold already carries.
    comp = next((u for u in reading.units if "comparative" in u.features.get("senses", [])), None)
    std = _follow(comp, "standard") if comp is not None else None
    if std is not None and "name" in std.features.get("senses", []):   # standard is ANOTHER ENTITY ("than
        op = "-" if COMPARATIVE_SIGN.get(_key(comp.surface), 1) < 0 else "+"   # Eric"), not the measure noun
        ref = next((f for f in reversed(context or [])                 # ("20% more MONEY"): the full derived
                    if isinstance(f, Quantity) and f.entity == _entity(std)), None)   # amount X×(1±pct)
        if ref is None:                                  # the named standard's value isn't known YET (a
            return None                                  # forward ref: "John …than Jules" before Jules) —
        return Quantity(_entity(subject), referent.measure,   # DEFER so the fixpoint resolves it after the
                        _compute(f"{_num(ref.amount)} * (1 {op} {_num(pct.features['value'])})"),  # standard,
                        _lemma(verbs[0].surface), derived=True)   # never off a measure-matched stand-in (Stan)
    return Quantity(_entity(subject), referent.measure,
                    _compute(f"{_num(pct.features['value'])} * {_num(referent.amount)}"),
                    _lemma(verbs[0].surface))


def _container_quantity(reading: Reading):
    """CONTAINMENT quantities — "20 packets OF 100 grams" → 20 × 100 = 2000 grams. A value-noun pair
    straddles each side of an "of" (N containers of M units each); the product's measure is the INNER unit.
    CONJOINED of-phrases ("four books of 10 stamps AND six books of 15 stamps") each yield a product,
    summed at fold time — every "of" pairs with its NEAREST value-noun on each side. A NESTED "of" with no
    inner count ("100 grams OF sugar") contributes nothing (no value on its right). Returns a LIST (empty
    if no "of" has a value-noun pair on BOTH sides)."""
    units = reading.units
    verbs = [u for u in units if "verb" in u.features.get("senses", [])      # the MAIN verb — a relative-
             and _key(u.surface) not in ("is", "are", "was", "were")]        # clause copula ("that ARE 4
    subject = _follow(verbs[0], "subject") if len(verbs) == 1 else None       # pounds each") doesn't count
    if subject is None:
        return []
    ofs = [units.index(u) for u in units if _key(u.surface) == "of"]
    if not ofs:
        return []
    each_i = next((units.index(u) for u in units if _key(u.surface) == "each"), None)
    out = []
    for oi in ofs:
        # the of-PHRASE ends at the next preposition after THIS "of" (a later "of" bounds it) — a value
        # beyond it ("8 pages of a book IN 20 minutes") belongs to a different phrase, NOT the container
        # (the "each" relative clause is allowed in)
        next_prep = next((units.index(u) for u in units[oi + 1:]
                          if "preposition" in u.features.get("senses", [])), len(units))
        right_bound = max(next_prep, each_i + 1) if each_i is not None else next_prep
        left = right = None
        for u in units:
            if "value" not in u.features.get("senses", []):
                continue
            n = _follow(u, "quantifies")
            if n is None:
                continue
            ui, ni = units.index(u), units.index(n)
            if ui < oi and ni < oi:                      # "20 PACKETS of …" — count + noun both left;
                if left is None or ui > units.index(left):    # keep the one NEAREST "of"
                    left = u
            elif oi < ui < right_bound:                  # "… of 100 GRAMS" — count + noun right of "of",
                if right is None or ui < units.index(right):  # within the of-phrase; keep NEAREST "of"
                    right = u
        if left is None or right is None or _follow(left, "quantifies") is subject:
            continue                                     # the container can't be the SUBJECT ("FOUR people
        out.append(Quantity(_entity(subject), _descriptor(_follow(right, "quantifies")),   # lost a total of
                            _compute(f"{_num(left.features['value'])} * {_num(right.features['value'])}"),
                            _lemma(verbs[0].surface), _time_at(reading, verbs[0])))   # 103 kg" is not 4×103)
    return out


def _distributed_quantity(reading: Reading):
    """A DISTRIBUTED quantity — "gave 4 stickers EACH to 3 friends" → 4 × 3 = 12. "each" makes the
    per-recipient amount (the value-noun just before it) multiply by the recipient count (the other
    value). None unless "each" sits after a noun with two value-noun pairs around it."""
    units = reading.units
    each = next((u for u in units if _key(u.surface) == "each"), None)
    if each is None:
        return None
    verbs = [u for u in units if "verb" in u.features.get("senses", [])      # MAIN verb — a relative-clause
             and _key(u.surface) not in ("is", "are", "was", "were")]        # copula ("books that ARE 400
    subject = _follow(verbs[0], "subject") if len(verbs) == 1 else None       # pages each") doesn't count
    ei = units.index(each)
    if subject is None or ei == 0 or "noun" not in units[ei - 1].features.get("senses", []):
        return None
    per_noun = units[ei - 1]                              # "4 STICKERS each" — the distributed measure
    per_val = next((u for u in units if "value" in u.features.get("senses", [])
                    and _follow(u, "quantifies") is per_noun), None)
    count_val = next((u for u in units if "value" in u.features.get("senses", []) and u is not per_val
                      and _follow(u, "quantifies") is not None), None)   # "to 3 FRIENDS" — the count
    if per_val is None or count_val is None:
        return None
    total = _compute(f"{_num(per_val.features['value'])} * {_num(count_val.features['value'])}")
    return Quantity(_entity(subject), _descriptor(per_noun), total, _lemma(verbs[0].surface))


def _time_at(reading: Reading, verb_unit) -> str:
    """The time NODE a value under `verb_unit` is valid at — the `time` unit whose `associates`
    obligation binds this verb (so value@time is read off the binding, not scanned ad-hoc). None if
    no time timestamps this verb (a timeless value)."""
    for u in reading.units:
        if "time" in u.features.get("senses", []) and _follow(u, "associates") is verb_unit:
            return _key(u.surface)
    return None


def _distribution(reading: Reading):
    """The facts a distribution statement asserts — "<name> shared <measure> between/among <recipients>".
    The whole rides on `Quantity(distributor, measure, total, lemma)` (total None if unstated — "a certain
    amount"); the relation on `Distribution`. Recipients are a NAMED group's members, or a COUNT on the
    recipient noun ("among 3 sons"); measure = the `of`-object, a money value's measure, or a money word.
    None unless it's a distribute-verb with an identifiable set of recipients."""
    units = reading.units
    verbs = [u for u in units if "verb" in u.features.get("senses", [])]
    if len(verbs) != 1 or _lemma(verbs[0].surface) not in DISTRIBUTE_VERBS:
        return None
    subject = _follow(verbs[0], "subject")
    if subject is None or not any(s in subject.features.get("senses", []) for s in ("name", "noun")):
        return None                                      # distributor may be a name ("Sam") or noun ("a teacher")
    prep = next((u for u in units if _key(u.surface) in ("between", "among")), None)
    rnoun = _follow(prep, "object") if prep is not None else None
    vpos = units.index(verbs[0])                         # recipients are OBJECTS — a group AFTER the verb
    group = next((u for u in units if "members" in u.features and units.index(u) > vpos), None)
    recipients = tuple(group.features["members"]) if group is not None else ()
    if recipients:                                       # named ("Ken and Tony") → count is how many
        count = len(recipients)
    elif rnoun is not None:                              # unnamed ("3 sons") → the number on the noun
        cv = next((u for u in units if "value" in u.features.get("senses", [])
                   and _follow(u, "quantifies") is rnoun), None)
        count = int(cv.features["value"]) if cv is not None and cv.features["value"] == int(cv.features["value"]) else None
    else:
        count = None
    if not recipients and count is None:                 # no recipients we can name or count → no fact
        return None
    of_obj = next((_follow(u, "object") for u in units if _key(u.surface) == "of"
                   and _follow(u, "object") is not None), None)
    money_val = next((u for u in units if "measure" in u.features), None)
    # a value quantifying a NON-recipient noun is the shared measure ("30 CANDIES among 5 students")
    shared_q = next((u for u in units if "value" in u.features.get("senses", [])
                     and _follow(u, "quantifies") is not None and _follow(u, "quantifies") is not rnoun), None)
    if money_val is not None:                            # "$5250" — a self-measuring known total
        measure, total = money_val.features["measure"], money_val.features["value"]
    elif shared_q is not None:                           # "30 candies" — a known total of a counted noun
        measure, total = _descriptor(_follow(shared_q, "quantifies")), shared_q.features["value"]
    elif of_obj is not None:                             # "amount OF money" — measure named, total unstated
        measure, total = _descriptor(of_obj), None
    elif any(_key(u.surface) in _MONEY_WORDS for u in units):
        measure, total = MONEY, None
    else:
        return None
    ent = _entity(subject)
    manner = next((u for u in units if "manner" in u.features.get("senses", [])     # the method modifier
                   and _follow(u, "qualifies") is verbs[0]), None)                  # BOUND to this verb
    method = DISTRIBUTION_METHODS.get(_key(manner.surface)) if manner is not None else None
    return [Quantity(ent, measure, total, _lemma(verbs[0].surface)),
            Distribution(ent, recipients, measure, count, method,
                         _descriptor(rnoun) if rnoun is not None else None)]


def _temporal_order(reading: Reading):
    """The `Before` fact a "<timeA> is after/before <timeB>" statement asserts, or None — read off the
    discharged `orders` binding plus the after/before cue (the cue fixes the direction). Contingent on
    the obligation actually being met, so it stays a binding-derived fact."""
    times = [u for u in reading.units if "time" in u.features.get("senses", [])]
    if len(times) != 2 or _follow(times[0], "orders") is None:
        return None
    a, b = _key(times[0].surface), _key(times[1].surface)             # text order
    if any(_key(u.surface) == "after" for u in reading.units):        # "A is after B" → B earlier
        return Before(b, a)
    if any(_key(u.surface) == "before" for u in reading.units):       # "A is before B" → A earlier
        return Before(a, b)
    return None


def _purchase(reading: Reading, context: list = None):
    """A PURCHASE — "buys 4 candy bars that cost $2 each" → spends 4 × $2 = $8, a money LOSS. Two facts
    fold differently for one "buy" verb (you GAIN the items but LOSE the money), and `_verb_sign` is
    measure-agnostic, so the money outflow is emitted with the LOSS verb 'spend' (−) while the items keep
    'buy' (+). Gated to "buy/purchase <count> <items> … $P each": a buy verb, EXACTLY ONE 'each' marker,
    one money price, one item count, AND the buyer already holds money in context (the baseline the spend
    is netted against — "Todd has $20 … how much LEFT"). The baseline gate keeps it off a MULTI-item buy
    ("5 apples … and 2 oranges …", clause-split into single-purchase fragments), which has no prior
    holding and must DECLINE (we'd commit only one fragment's product). Returns None otherwise."""
    units = reading.units
    verb = next((u for u in units if "verb" in u.features.get("senses", [])
                 and _lemma(u.surface) in ("buy", "purchase")), None)
    if verb is None or sum(1 for u in units if _key(u.surface) == "each") != 1:
        return None                                      # exactly one "each" — a SINGLE purchase
    subject = _follow(verb, "subject")
    prices = [u for u in units if "value" in u.features.get("senses", []) and u.features.get("measure") == MONEY]
    counts = [u for u in units if "value" in u.features.get("senses", [])
              and _follow(u, "quantifies") is not None and _descriptor(_follow(u, "quantifies")) != MONEY]
    if subject is None or len(prices) != 1 or len(counts) != 1:
        return None                                      # multi-item → DECLINE (only one pair's product)
    if not any(isinstance(f, Quantity) and f.entity == _entity(subject) and f.measure == MONEY
               for f in (context or [])):
        return None                                      # no money baseline to net against → DECLINE
    price, count = prices[0], counts[0]
    item = _descriptor(_follow(count, "quantifies"))
    spent = _compute(f"{_num(count.features['value'])} * {_num(price.features['value'])}")
    return [Quantity(_entity(subject), item, count.features["value"], "buy"),
            Quantity(_entity(subject), MONEY, spent, "spend")]   # money out = count × price (a loss)


def _transfer_quantity(reading: Reading):
    """ "<entity> sold CLIPS to 48 of her friends" → 48 of CLIPS (one item per recipient). The bare-plural
    direct object is the measure; the RECIPIENT count (via "to") is the amount. None unless the dobj is
    bare (carries no count of its own) and a value quantifies the "to"-object."""
    units = reading.units
    verbs = [u for u in units if "verb" in u.features.get("senses", [])]
    subject = _follow(verbs[0], "subject") if len(verbs) == 1 else None
    if subject is None:
        return None
    dobj = _follow(verbs[0], "dobj")
    if dobj is None or "noun" not in dobj.features.get("senses", []):
        return None
    if any("value" in u.features.get("senses", []) and _follow(u, "quantifies") is dobj for u in units):
        return None                                      # dobj has its OWN count → not the to-N shape
    to = next((u for u in units if _key(u.surface) == "to" and "preposition" in u.features.get("senses", [])), None)
    to_obj = _follow(to, "object") if to is not None else None
    if to_obj is None or to_obj is dobj:
        return None
    n = next((u for u in units if "value" in u.features.get("senses", [])
              and _follow(u, "quantifies") is to_obj), None)
    if n is None:
        return None
    return [Quantity(_entity(subject), _descriptor(dobj), n.features["value"],
                     _lemma(verbs[0].surface), _time_at(reading, verbs[0]))]


def _list_cardinals(reading: Reading) -> set:
    """The units that are a value-LIST's set-size CARDINAL — "Malou got 91, 90, and 92 in her three
    quizzes": the "three" equals the count of the OTHER values quantifying the same noun ('quiz'), so it's
    the list size, not another datum. Returns their id()s. A genuine list needs ≥3 values on one noun (≥2
    data + the cardinal). Shared by _quantity (skip emitting it) and GUARD 3 (don't flag it unused-given)."""
    by_noun: dict = {}
    for u in reading.units:
        if "value" in u.features.get("senses", []):
            n = _follow(u, "quantifies")
            if n is not None:
                by_noun.setdefault(id(n), []).append(u)
    return {id(u) for vs in by_noun.values() if len(vs) >= 3
            for u in vs if u.features.get("value") == len(vs) - 1}


_TRANSFER_VERBS = {"give", "hand", "pass", "lend", "send"}


def _dative_transfer(reading: Reading):
    """A DATIVE transfer — "<giver> gave <recipient> $N" (no "to") credits the RECIPIENT +N AND debits the
    giver −N. The recipient is a NAME or a RESOLVED object-pronoun (him/her/them) stranded right after the
    transfer verb, before the value. "Tom gave Reggie $48" → [Tom −48, Reggie +48]; "father gave him $48" →
    the resolved "him" gains. A "to"-marked transfer ("gave 12 to his brother") is a DIFFERENT construct
    (GUARD 10 / distribution), so it's excluded. Returns the (giver, recipient) quantity pair(s), or None."""
    verbs = [u for u in reading.units if "verb" in u.features.get("senses", [])]
    if len(verbs) != 1 or _lemma(verbs[0].surface) not in _TRANSFER_VERBS:
        return None
    if any(_key(u.surface) == "to" for u in reading.units):
        return None
    vpos = reading.units.index(verbs[0])
    subj = _follow(verbs[0], "subject")
    subj_e = _entity(subj) if subj is not None else None
    # POSSESSIVE OWNERS in the clause ("Reggie's father" → Reggie) — a name immediately followed by a
    # possessive marker; an antecedent for an unresolved object pronoun ("…gave HIM"), disjoint from the subject.
    owners = [reading.units[k] for k in range(len(reading.units) - 1)
              if "name" in reading.units[k].features.get("senses", [])
              and "possessive" in reading.units[k + 1].features.get("senses", [])
              and _entity(reading.units[k]) != subj_e]
    rec = None                                           # recipient: name / resolved (or possessive-owner) pronoun
    for u in reading.units[vpos + 1:]:
        if "value" in u.features.get("senses", []):
            break
        if "name" in u.features.get("senses", []):
            rec = u
            break
        if "pronoun" in u.features.get("senses", []) and _key(u.surface) in ("him", "her", "them"):
            if _follow(u, "refers") is not None:
                rec = u
            elif len(owners) == 1:                       # "Reggie's father gave him $48" → him = Reggie (owner)
                rec = owners[0]
            else:
                return None                              # unresolved pronoun recipient → can't attribute → bail
            break
    if rec is None:
        return None
    giver = _entity(subj) if subj is not None and "name" in subj.features.get("senses", []) else None
    recip = _entity(rec)
    if recip == giver:
        return None
    out = []
    for u in reading.units:
        if "value" not in u.features.get("senses", []):
            continue
        if "measure" in u.features:                      # "$48" — a self-measuring money value
            meas, val = u.features["measure"], u.features["value"]
        else:
            noun = _follow(u, "quantifies")              # "5 books" — the value's measure noun
            if noun is None:
                continue
            meas, val = _descriptor(noun), u.features["value"]
        if giver is not None:                            # the giver's loss (skip if the giver is a non-name,
            out.append(Quantity(giver, meas, val, "give"))   # e.g. "his father" — don't track a noun-entity)
        out.append(Quantity(recip, meas, val, "receive"))
    return out or None


def _quantity(reading: Reading):
    """The quantities a "<entity> <verb>s <amount> …" statement asserts — ONE per value: a
    self-measuring money value ("earns $12") or a value quantifying a noun ("buys 2 apples"). A list,
    so a CONJOINED object yields several ("has 3 apples and 2 oranges" → two). The verb lemma carries
    the polarity. [] if there's no single verb with a subject."""
    verbs = [u for u in reading.units if "verb" in u.features.get("senses", [])   # a trailing GERUND
             and not (_key(u.surface).endswith("ing") and _follow(u, "subject") is None)]   # adjunct
    if len(verbs) != 1:                                  # ("spends 40 years TEACHING") is not a 2nd verb
        return []
    subject = _follow(verbs[0], "subject")
    if subject is None:
        return []
    # Two ADJACENT bare values ("10 $20" = ten twenty-dollar bills) are a compound denomination we
    # don't parse — never a genuine conjoined object ("3 apples AND 2 oranges" separates them). Decline.
    # EXCEPTION: a COMMA after the first value ("got 91, 90, and 92") marks a value LIST, not a denomination.
    vi = [k for k, u in enumerate(reading.units) if "value" in u.features.get("senses", [])]
    if any(b - a == 1 and not reading.units[a].surface.rstrip().endswith(",")
           for a, b in zip(vi, vi[1:])):
        return []
    cardinals = _list_cardinals(reading)                 # the set-size cardinal of a value list ("three
    #                                                      quizzes" beside 3 scores) — dropped, not a datum
    ent, lemma, when = _entity(subject), _lemma(verbs[0].surface), _time_at(reading, verbs[0])
    first = any("noun" in u.features.get("senses", []) and _descriptor(u)[0] in TIME_UNITS   # "in the FIRST
               and "first" in u.features.get("attributes", []) for u in reading.units)       # year …" override
    out = []
    for u in reading.units:
        if "value" not in u.features.get("senses", []):
            continue
        if id(u) in cardinals:                           # the list's set-size cardinal ("three quizzes")
            continue
        if "measure" in u.features:                      # "$12" — a self-measuring money value
            out.append(Quantity(ent, u.features["measure"], u.features["value"], lemma, when))
        else:
            noun = _follow(u, "quantifies")              # "3 APPLES" — the value's measure noun
            if noun is not None:
                if lemma == "turn" and _descriptor(noun)[0] == "year" and _time_offset(reading):
                    continue                              # "turned 3 a year ago" is a TIME-SHIFTED age we
                    # can't reliably read: the age (3) and the offset's "year" share the one 'year' token,
                    # so _time_offset can't separate them. Don't emit a (wrong) current-age fact — leave it
                    # unknown so a relational age over it DECLINES rather than committing off a stale age
                    # (Diana "twice as old as Grace … turned 3 a year ago" was committing 2×3=6).
                fp = first and _descriptor(noun)[0] not in TIME_UNITS   # flag the OVERRIDDEN count (40
                out.append(Quantity(ent, _descriptor(noun), u.features["value"], lemma, when,   # students),
                                    first_period=fp))                                           # not a duration
    return out


def _predication(reading: Reading):
    """The (subject, predicate, polarity, scope) a simple statement asserts, or None — the one verb
    and its subject; negated if a negator is present, universal if an all/every quantifier scopes it."""
    verbs = [u for u in reading.units if "verb" in u.features.get("senses", [])]
    if len(verbs) != 1:
        return None
    subject = _follow(verbs[0], "subject")
    if subject is None:
        return None
    obj = _follow(verbs[0], "dobj")
    return Predication(_descriptor(subject), _lemma(verbs[0].surface),
                       _verb_negated(verbs[0], reading), _universal(verbs[0], reading),
                       _descriptor(obj) if obj is not None else None)

# --- predicates & relations: Membership/Subset/Relation + predication verdicts --------------

@dataclass(frozen=True)
class Membership:
    """A known fact "<individual> is a <collection>": a named individual belongs to a collection,
    e.g. "Bob is a student" → Membership("bob", ("student", frozenset())). `negated` for "is not"."""
    member: str
    collection: tuple
    negated: bool = False


def _has_sense(unit, sense) -> bool:
    return unit is not None and sense in unit.features.get("senses", [])


def _copula_args(reading: Reading):
    """(subject, complement) units bound by the copula — read from its BINDINGS, not by counting.
    Works for statements ("Bob is a student") and fronted questions ("Is Bob a student?")."""
    cop = _copula_unit(reading)
    if cop is None:
        return (None, None)
    return (_follow(cop, "subject"), _follow(cop, "complement"))


def _membership(reading: Reading):
    """The membership a copula statement asserts ("X is a Y"), or None — read off the copula's bound
    subject (a name) and complement (a noun); polarity from a negation bound to the copula."""
    if any("value" in u.features.get("senses", []) for u in reading.units):
        return None                                      # "Kris is 24 years old" is a QUANTITY, not a
    subj, comp = _copula_args(reading)                   # membership — defer to the quantity extractors
    if _has_sense(subj, "name") and _has_sense(comp, "noun"):
        return Membership(_key(subj.surface), _descriptor(comp),
                          _verb_negated(_copula_unit(reading), reading))
    return None


@dataclass(frozen=True)
class Subset:
    """A universal relation between two collections. Positive ("Every X is a Y") → `sub` ⊆ `sup`:
    every member of `sub` is a member of `sup`. Negated ("No X are Y") → `sub` and `sup` are
    DISJOINT: no member of one is a member of the other."""
    sub: tuple
    sup: tuple
    negated: bool = False


def _subset(reading: Reading):
    """The subset/disjointness a universal copula statement asserts, or None — read off the copula's
    bound subject and complement (both nouns), with an all/every/no quantifier present. "Every X is a
    Y" → Subset(X, Y); "No X are Y" → Subset(X, Y, negated=True) (disjoint)."""
    has_universal = any("quantifier" in u.features.get("senses", []) and
                        _key(u.surface) in ("every", "all", "no") for u in reading.units)
    subj, comp = _copula_args(reading)
    if has_universal and _has_sense(subj, "noun") and _has_sense(comp, "noun"):
        return Subset(_descriptor(subj), _descriptor(comp), _verb_negated(_copula_unit(reading), reading))
    return None


def _property(reading: Reading):
    """A predicative-adjective fact ("The apple is red"), or None — a copula, one subject (noun or
    name), and one PREDICATIVE adjective (one that didn't merge into a noun). The predicate is the
    adjective; polarity from any negator. Distinct from attributive "red apple" (which merges)."""
    subj, comp = _copula_args(reading)
    if (_has_sense(subj, "noun") or _has_sense(subj, "name")) and _has_sense(comp, "adjective"):
        cop = _copula_unit(reading)
        return Predication(_descriptor(subj), _key(comp.surface),
                           _verb_negated(cop, reading), _universal(cop, reading))
    return None


def _collections_of(member: str, context: list) -> set:
    """Every collection `member` belongs to — directly, and transitively up POSITIVE Subset edges."""
    frontier = [m.collection for m in context
                if isinstance(m, Membership) and m.member == member and not m.negated]
    seen = set()
    while frontier:
        c = frontier.pop()
        if c in seen:
            continue
        seen.add(c)
        frontier += [f.sup for f in context if isinstance(f, Subset) and not f.negated and f.sub == c]
    return seen


def _is_member(member: str, target: tuple, context: list) -> bool:
    """Is `member` in collection `target`? True iff `target` is one of its (transitive) collections."""
    return target in _collections_of(member, context)


def _disjoint(a: tuple, b: tuple, context: list) -> bool:
    """Are collections `a` and `b` known disjoint? A negated Subset between them, either direction
    ("No X are Y" makes X and Y mutually exclusive)."""
    return any(isinstance(f, Subset) and f.negated and {f.sub, f.sup} == {a, b} for f in context)


@dataclass(frozen=True)
class Relation:
    """A comparative relation between two individuals, e.g. "Alice is taller than Bob" →
    Relation("alice", "taller", "bob"). Transitive (see _related)."""
    subject: str
    relation: str
    object: str


def _relation(reading: Reading):
    """The comparison a "<A> is <comparative> than <B>" statement asserts, or None — read off the
    bindings: the copula's subject (A), its complement (the comparative), and the comparative's
    bound `standard` (B)."""
    subj, comp = _copula_args(reading)
    if not _has_sense(comp, "comparative"):
        return None
    standard = _follow(comp, "standard")
    if subj is None or standard is None:
        return None
    return Relation(_key(subj.surface), _key(comp.surface), _key(standard.surface))


def _related(subj: str, rel: str, obj: str, context: list) -> bool:
    """Does `subj rel obj` hold, transitively? Reachable from subj to obj along `rel` edges (start
    from subj's direct successors, so nothing is its own comparative)."""
    frontier = [f.object for f in context if isinstance(f, Relation) and f.relation == rel
                and f.subject == subj]
    seen = set()
    while frontier:
        x = frontier.pop()
        if x == obj:
            return True
        if x in seen:
            continue
        seen.add(x)
        frontier += [f.object for f in context if isinstance(f, Relation) and f.relation == rel
                     and f.subject == x]
    return False


def _follow(unit, need):
    """The target of `unit`'s met obligation named `need`, or None."""
    if unit is None:
        return None
    for o in unit.features.get("obligations", []):
        if o.need == need and o.met:
            return o.target
    return None


def _verdict(yes: bool, no: bool) -> str:
    """Fold derivable-true / derivable-false into one verdict: both → "conflict" (the premises
    contradict), true → "yes", false → "no", neither → "undetermined" (we lack the information)."""
    if yes and no:
        return "conflict"
    return "yes" if yes else "no" if no else "undetermined"


def _predication_verdict(subject: tuple, predicate: str, context: list, obj: tuple = None) -> str:
    """The verdict for "does <subject> <predicate> [<object>]?". A universal fact transfers iff the
    subject is a member of its collection (transitively via Subset); the object must match too. yes
    AND no both derivable → "conflict"."""
    member = subject[0]
    preds = [f for f in context if isinstance(f, Predication)
             and f.predicate == predicate and f.object == obj]
    yes = Predication(subject, predicate, object=obj) in context \
        or any(f.universal and not f.negated and _is_member(member, f.subject, context) for f in preds)
    no = Predication(subject, predicate, negated=True, object=obj) in context \
        or any(f.universal and f.negated and _is_member(member, f.subject, context) for f in preds)
    return _verdict(yes, no)


def _question_subjects(reading: Reading, aux):
    """The entities a fronted question asks about + its verb lemma. Reads the verb's bound `subject`
    (the STRUCTURAL binding the parse produced — not a positional rescan) when it resolves; falls back
    to the collection between aux and verb only for a conjoined subject ("Tom and Mary") that the
    single-target `subject` obligation can't yet bind."""
    verb = _follow(aux, "asks_predication")
    q_verb = _lemma(verb.surface) if verb is not None else "have"
    subject = _follow(verb, "subject") if verb is not None else None
    if subject is not None:                              # a group's `members`, else the single entity
        return (subject.features.get("members") or [_entity(subject)]), q_verb
    units = reading.units
    ai, vi = units.index(aux), (units.index(verb) if verb is not None else len(units))
    entities = []                                        # flatten any group's members (comma-lists)
    for u in units[ai + 1:vi]:
        if any(s in u.features.get("senses", []) for s in ("name", "noun", "pronoun")):
            entities.extend(u.features.get("members") or [_entity(u)])
    return entities, q_verb


def _age_when_projection(r: Reading, context: list):
    """"How old will X be WHEN Y is/turns M?" → X_now + (M − Y_now). The future point is set by Y REACHING
    age M (not a "+Δ years" displacement), and ages advance together, so X gains the same (M − Y_now) years.
    Without this the question's two names (X and the when-clause's Y) both resolve as subjects and their ages
    are summed (Marianne 20 + Bella 8 = 28, not 20 + (18−8) = 30). Gated: a "when" clause whose entity Y
    reaches a target age M (an "is/turns/be <value>" after Y), a DISTINCT main subject X before "when", and
    both current ages known. None otherwise."""
    units = r.units
    when = next((u for u in units if _key(u.surface) == "when"), None)
    if when is None:
        return None
    wi = units.index(when)
    after = units[wi + 1:]
    if any("multiplier" in u.features.get("senses", []) or _key(u.surface) == "times" for u in after):
        return None                                      # "when Y is k× as old as X" is a RELATION, not a
        #                                                  literal target age → _age_solve_for_t handles it
    y = next((u for u in after if "name" in u.features.get("senses", [])), None)
    m = next((u.features["value"] for u in after if "value" in u.features.get("senses", [])), None)
    x = next((u for u in units[:wi] if "name" in u.features.get("senses", [])), None)
    if y is None or m is None or x is None or _entity(x) == _entity(y):
        return None
    x_now = _holdings(_entity(x), ("year", frozenset()), context)
    y_now = _holdings(_entity(y), ("year", frozenset()), context)
    if x_now is None or y_now is None:
        return None
    return _compute(f"{_num(x_now)} + ({_num(m)} - {_num(y_now)})")


def _age_solve_for_t(r: Reading, context: list):
    """"How old will X be WHEN Y is k times as old as X [is now]?" → solve for the future displacement t at
    which the MULTIPLICATIVE age relation holds, then return X's age then. Both ages advance together, so
    Y+t = k·(X+t) → t = (k·X − Y)/(1 − k); a PRESENT-anchored standard ("as old as X is NOW") fixes X →
    Y+t = k·X_now → t = k·X_now − Y_now. Gated: an age question with a "when" clause carrying a multiplicative
    factor, a distinct X (the question subject, before "when") and Y (after "when"), every after-clause name
    being X or Y (the relation is Y-vs-X, not a third party), pure-multiplicative (no additive offset), and
    both current ages known. k ≠ 1."""
    units = r.units
    if not (any("interrogative" in u.features.get("senses", []) for u in units)
            and any(_key(u.surface) == "old" for u in units)
            and any(_key(u.surface) == "will" and "auxiliary" in u.features.get("senses", []) for u in units)):
        return None
    when = next((u for u in units if _key(u.surface) == "when"), None)
    if when is None:
        return None
    wi = units.index(when)
    after = units[wi + 1:]
    if any("comparative" in u.features.get("senses", []) for u in units):
        return None                                      # an additive offset on the factor ("N years older
        #                                                  than") — not handled. (Senses, not surface: a
        #                                                  demoted kinship modifier "his OLDER brother" is a
        #                                                  `title`, not a comparative, so it doesn't trip this.)
    mult = next((u for u in after if "multiplier" in u.features.get("senses", [])), None)
    k = mult.features.get("value") if mult is not None else next(
        (after[i - 1].features["value"] for i, u in enumerate(after) if _key(u.surface) == "times"
         and i and "value" in after[i - 1].features.get("senses", [])), None)
    if k is None or k == 1:
        return None
    x = next((u for u in units[:wi] if "name" in u.features.get("senses", [])), None)
    y = next((u for u in after if "name" in u.features.get("senses", [])), None)
    if x is None or y is None or _entity(x) == _entity(y):
        return None
    if any(_entity(u) not in (_entity(x), _entity(y)) for u in after   # a THIRD entity in the relation →
           if "name" in u.features.get("senses", [])):                 # the equation isn't Y-vs-X; decline
        return None
    x_now = _holdings(_entity(x), ("year", frozenset()), context)
    y_now = _holdings(_entity(y), ("year", frozenset()), context)
    if x_now is None or y_now is None:
        return None
    anchored = any(_key(u.surface) in ("now", "today", "currently") for u in after)   # "as old as X is NOW"
    t = f"{_num(k)} * {_num(x_now)} - {_num(y_now)}" if anchored \
        else f"({_num(k)} * {_num(x_now)} - {_num(y_now)}) / (1 - {_num(k)})"
    return _compute(f"{_num(x_now)} + ({t})")

# --- ANSWERING & FACT ASSEMBLY: answer() / learn() / _facts_from() --------------------------

def answer(question: str, context: list, discourse: list = None):
    """Answer a question against a context of facts. A yes/no question ("Did the student pass?")
    returns "yes"/"no" by checking a Predication; a count question ("How many red apples?") returns
    an int by counting matching instances. Returns a list of Deficiency (what to ASK) when the
    question can't be answered. Reuses the same parse; dispatches on the interrogative kind. `discourse`
    resolves the question's own pronouns ("how much does SHE have?" → the entity she refers to)."""
    r = analyze(question)
    if discourse is not None:
        _resolve_references(r, discourse)
    unknown = [d for d in deficiencies(r) if d.kind == "unknown-word"]
    if unknown:
        return unknown                                   # don't guess about words we don't know

    # AVERAGE over a set — "what is the average height of the three people?" = Σ(values) / N. Handled FIRST:
    # "average" is a "what is …" phrasing the wh_value dispatch (expecting "what is <name>") would otherwise
    # decline. The cue is SPECIFIC (unlike "more than"), and average questions all decline today → only
    # blocked → {correct | decline}. Two modes over the SINGLE shared measure: (a) MULTI-OWNER — one net
    # holding per distinct owner (Reese/Daisy/Parker → 3 heights); (b) VALUE-LIST — one owner with several
    # quantities ("Malou got 91, 90, 92" → average those amounts, NOT the accumulated 273). DENOMINATOR
    # SAFETY: require exactly one shared measure (the question says "height", holdings are keyed 'inch'); ≥2
    # terms; and if the question states the set size, the term count MUST equal it (else DECLINE, not /wrong-N).
    if any(_key(u.surface) == "average" for u in r.units) and context:
        measures = {f.measure for f in context if isinstance(f, Quantity) and f.amount is not None}
        if len(measures) == 1:
            gq = next(iter(measures))
            qs = [f for f in context if isinstance(f, Quantity) and f.measure == gq and f.amount is not None]
            owners = {f.entity for f in qs}
            offset = 0
            if len(owners) == 1:                         # VALUE-LIST: average the individual amounts
                terms = [f.amount for f in qs]
            else:                                        # MULTI-OWNER: one net holding per owner
                terms = [_holdings(o, gq, context) for o in owners]
                if gq == ("year", frozenset()):          # "average AGE of the three IN N YEARS" — each
                    offset = _time_offset(r)             # member ages by N first, like the sibling TOTAL
            #                                               AGE branch below
            stated_n = next((u.features["value"] for u in r.units if "value" in u.features.get("senses", [])
                             and float(u.features["value"]).is_integer()), None)
            if terms and all(t is not None for t in terms) and len(terms) >= 2 \
                    and (stated_n is None or len(terms) == stated_n):
                expr = f"({' + '.join(_num(t) for t in terms)})"
                if offset:
                    expr = f"({expr} + {_num(offset)} * {len(terms)})"
                return _compute(f"{expr} / {len(terms)}")
        return "undetermined"

    # TOTAL AGE over a set — "what is the total of their ages now?" / "what will be their total age in N
    # years?" = Σ(each owner's age) [+ N × owner-count for a future projection]. Sibling of the average
    # branch above; handled FIRST so the "what is …" form isn't claimed by the wh_value handler. GATED on an
    # AGE cue + a "total"/"combined" word + ≥2 year-quantity owners, so non-age "total/combined" questions
    # keep routing to the grand-total fold below. (Xavier 36: 24+12; Sam 36: (6+3+18) + 3×3.)
    if any(_key(u.surface) in ("total", "combined") for u in r.units) and context \
            and any(_key(u.surface) in ("age", "old", "ages") for u in r.units) \
            and not any(_key(u.surface) == "many" for u in r.units):   # NOT the inverse "in how many
            # years will their total age be N?" (that solves for the DURATION, not the total) — it has
            # "many"; the forward "what is/will be the total age" does not.
        owners = {f.entity for f in context if isinstance(f, Quantity)
                  and f.measure == ("year", frozenset()) and f.amount is not None}
        ages = [_holdings(o, ("year", frozenset()), context) for o in owners]
        if ages and all(a is not None for a in ages) and len(ages) >= 2:
            offset = _time_offset(r)                     # "in N years" → each member ages by N
            expr = " + ".join(_num(a) for a in ages)
            if offset:
                expr = f"({expr}) + {_num(offset)} * {len(ages)}"
            return _compute(expr)
        return "undetermined"

    op_unit = next((u for u in r.units if "operator" in u.features.get("senses", [])), None)
    if op_unit is not None:                              # arithmetic: "What is 3 plus 2?"
        a, b = _follow(op_unit, "left"), _follow(op_unit, "right")
        if a is None or b is None:
            return [Deficiency("unanswerable", op_unit, "I couldn't read the arithmetic")]
        from reasoning import translate                  # reuse the audited safe evaluator
        val = translate.run_program(
            f"answer = {a.features['value']} {op_unit.features['op']} {b.features['value']}")
        return int(val) if val == int(val) else val
    percent = next((u for u in r.units if "percent" in u.features.get("senses", [])), None)
    if percent is not None:                              # "What is 20% of 50?" → fraction × base
        base = _follow(percent, "base")
        if base is None or "value" not in base.features:
            return [Deficiency("unanswerable", percent, "I couldn't find what the percentage is of")]
        from reasoning import translate
        val = translate.run_program(
            f"answer = {percent.features['value']} * {base.features['value']}")
        return int(val) if val == int(val) else val
    proj_offset = _time_offset(r)                        # GROWTH PROJECTION: a quantity that grows at a
    if proj_offset:                                      # RATE per year, valued at a future time → current
        growth = next((f for f in context if isinstance(f, Rate) and f.per_unit == "year"   # + rate×Δ. The
                       and f.verb in GROWTH_VERBS), None)        # explicit-rate generalisation of the age
        if growth is not None:                                   # shift ("grows 3 inches/yr; 20 now; after
            base = _holdings(growth.entity, growth.measure, context)   # 10 yrs?" → 20 + 3×10 = 50)
            if base is not None:
                return _compute(f"{_num(base)} + {_num(growth.amount)} * {_num(proj_offset)}")
    if any("interrogative" in u.features.get("senses", []) for u in r.units) \
            and any(_key(u.surface) == "old" for u in r.units):   # "How old is/will X be?" → age (years)
        when_proj = _age_when_projection(r, context)     # "how old will X be WHEN Y is/turns M" → X + (M − Y)
        if when_proj is not None:                        # (the future point is set by Y reaching M, not "+Δ")
            return when_proj
        solve_t = _age_solve_for_t(r, context)           # "WHEN Y is k× as old as X" → solve for the future t
        if solve_t is not None:                          # at which the relation holds, then X's age then
            return solve_t
        if any(_key(u.surface) == "when" for u in r.units):
            return "undetermined"                        # a "when <condition>" neither projection nor solve-for-t
            # resolved must DECLINE, never fall to the bare entity-age SUM below (Joel 5 + dad 32×3 = 101).
        offset = _time_offset(r)                         # the queried time vs now — age TRACKS the timeline:
        aux = next((u for u in r.units if "auxiliary" in u.features.get("senses", [])), None)   # age@(now+Δ)
        if aux is not None:                                                                     # = age_now+Δ
            entities, _ = _question_subjects(r, aux)
        else:                                            # "How old is X?" / "How many years old is X?" — the
            # entity asked about is the NAME (the copula's grammatical subject mis-resolves to the fronted
            # measure "years" in "how many years old", so prefer the name; fall back to the copula subject).
            name = next((u for u in r.units if "name" in u.features.get("senses", [])), None)
            if name is not None:
                entities = [_entity(name)]
            else:
                subj, _ = _copula_args(r)
                entities = [_entity(subj)] if subj is not None else []
        if not entities:
            return "undetermined"
        parts = []
        for ent in entities:
            h = _holdings(ent, ("year", frozenset()), context)
            if h is None:
                return "undetermined"
            parts.append(_num(h))
        if offset:
            parts.append(_num(offset))
        return _compute(" + ".join(parts))               # Σ(ages) + the timeline offset

    who = next((u for u in r.units if "wh_subject" in u.features.get("senses", [])), None)
    if who is not None:                                  # "Who <predicate>?" → subjects with it
        verb = _follow(who, "asks_predicate")
        if verb is None:
            return [Deficiency("unanswerable", who, "I couldn't tell what is being asked")]
        pred = _lemma(verb.surface)
        subs = sorted({f.subject[0] for f in context if isinstance(f, Predication)
                       and f.predicate == pred and not f.negated})
        return ", ".join(subs) if subs else "(no one)"
    what = next((u for u in r.units if "wh_value" in u.features.get("senses", [])), None)
    if what is not None:
        aux = next((u for u in r.units if "auxiliary" in u.features.get("senses", [])), None)
        if aux is not None:                              # "What does <subj> <verb>?" → the objects
            verb = _follow(aux, "asks_predication")
            subject = _follow(verb, "subject") if verb else None
            if subject is None:
                return [Deficiency("unanswerable", what, "I couldn't tell what is being asked")]
            subj, pred = _descriptor(subject), _lemma(verb.surface)
            objs = sorted({f.object[0] for f in context if isinstance(f, Predication)
                           and f.subject == subj and f.predicate == pred and f.object and not f.negated})
            return ", ".join(objs) if objs else "(nothing)"
        name = _follow(what, "asks_individual")          # "What is <name>?" → its collections
        if name is None:
            return [Deficiency("unanswerable", what, "I couldn't tell what is being asked")]
        member = _key(name.surface)
        cols = sorted({m.collection[0] for m in context
                       if isinstance(m, Membership) and m.member == member and not m.negated})
        return ", ".join(cols) if cols else "(unknown)"
    which = next((u for u in r.units if "wh_which" in u.features.get("senses", [])), None)
    if which is not None:        # "Which <noun> <predicate>?" → members of the noun that satisfy it
        coll_unit = _follow(which, "restricts")
        adjs = [u for u in r.units if "adjective" in u.features.get("senses", [])]
        verbs = [u for u in r.units if "verb" in u.features.get("senses", [])
                 and _key(u.surface) not in ("is", "are", "was", "were")]
        pred = _key(adjs[0].surface) if adjs else (_lemma(verbs[0].surface) if verbs else None)
        if coll_unit is None or pred is None:
            return [Deficiency("unanswerable", which, "I couldn't tell what is being asked")]
        coll = _descriptor(coll_unit)
        hits = sorted({f.subject[0] for f in context if isinstance(f, Predication)
                       and f.predicate == pred and not f.negated and f.object is None
                       and _is_member(f.subject[0], coll, context)})
        return ", ".join(hits) if hits else "(none)"

    qcomp = next((u for u in r.units if _key(u.surface) in ("more", "fewer")), None)
    if qcomp is not None and any(_key(u.surface) == "than" for u in r.units):  # "more X than Y?" count
        ns = sorted((u for u in r.units if "noun" in u.features.get("senses", [])),
                    key=lambda u: u.words[0].index)
        if len(ns) >= 2:
            counts = [sum(1 for inst in context if isinstance(inst, tuple)
                          and _matches(_descriptor(n), inst)) for n in ns[:2]]
            more = counts[0] > counts[1] if _key(qcomp.surface) == "more" else counts[0] < counts[1]
            return "yes" if more else "no"

    # The copula yes/no questions — but NOT when a "how many" interrogative is present: "How many
    # apples ARE LEFT?" is a count question, not the property question "are apples left?".
    has_interrogative = any("interrogative" in u.features.get("senses", []) for u in r.units)
    subj, comp = _copula_args(r)
    if not has_interrogative and _has_sense(comp, "comparative"):  # "Is A <comparative> than B?"
        standard = _follow(comp, "standard")
        if subj is not None and standard is not None:
            a, rel, b = _key(subj.surface), _key(comp.surface), _key(standard.surface)
            return _verdict(_related(a, rel, b, context),
                            _related(b, rel, a, context))   # B>A ⇒ NOT A>B (asymmetry)
    if not has_interrogative and _has_sense(subj, "name") and _has_sense(comp, "noun"):  # "Is X a Y?"
        member, target = _key(subj.surface), _descriptor(comp)
        yes = _is_member(member, target, context)
        no = any(isinstance(m, Membership) and m.member == member         # explicitly "not a Y", or
                 and m.collection == target and m.negated for m in context) \
            or any(_disjoint(c, target, context) for c in _collections_of(member, context))  # disjoint
        return _verdict(yes, no)
    if not has_interrogative:
        prop = _property(r)                              # "Is <subject> <adjective>?" property question
        if prop is not None:                             # a property is a Predication (adjective as
            return _predication_verdict(prop.subject, prop.predicate, context)   # predicate) → verdict

    aux = next((u for u in r.units if "auxiliary" in u.features.get("senses", [])), None)
    if aux is not None and not has_interrogative:        # "Did X <verb> [Y]?" → yes / no / undetermined
        verb = _follow(aux, "asks_predication")          # did → the verb being asked about (an
                                                         # interrogative present → it's a "how many …
                                                         # does …?" count/quantity question instead)
        subject = _follow(verb, "subject") if verb else None
        if subject is None:
            return [Deficiency("unanswerable", aux, "I couldn't tell what is being asked")]
        obj = _follow(verb, "dobj")
        return _predication_verdict(_descriptor(subject), _lemma(verb.surface), context,
                                    _descriptor(obj) if obj is not None else None)

    interro = next((u for u in r.units if "interrogative" in u.features.get("senses", [])), None)
    if interro is None:
        return [Deficiency("not-a-question", interro, "this is not a question I can answer")]
    _coll0 = _follow(_follow(interro, "queries"), "collection")               # "how many HOURS" → (hour,…)
    asked_unit = _descriptor(_coll0)[0] if _coll0 is not None else None
    kys = {_key(u.surface) for u in r.units}
    combined_q = bool(kys & {"combined", "combine", "combines", "altogether", "total"}) \
        or {"all", "together"} <= kys \
        or "in all" in question.lower()                  # "How many cans did the boys collect IN ALL?" → Σ
        #                                                  ("the two friends COMBINE to lose …" → a sum too)
    is_long = any(_key(u.surface) == "long" for u in r.units)
    # AGGREGATION CUE — bare "together" (without "all") is a sum cue ("how much did the two men earn
    # TOGETHER?" → Σ), but it's CONFOUNDED with the collaborative-rate sense ("how long to paint the house
    # together?" = a joint RATE, not a sum). The rate-inversion branch below is gated `not combined_q`, so
    # firing combined_q on a how-long/time question would skip it and sum rates into garbage. Restrict the
    # "together" trigger to NON-time questions, which the rate branch never claims. (Salvadore 2934, Anika 64.)
    if "together" in kys and not is_long and asked_unit not in TIME_UNITS:
        combined_q = True
    if (is_long or asked_unit in TIME_UNITS) and not combined_q:   # "How LONG / how many HOURS … to <verb>?"
        rates = [f for f in context if isinstance(f, Rate)]                   # → RATE INVERSION: target ÷
        def _inv_target(rate):                                               # rate, in per_unit (convert if
            return next((u for u in r.units if "value" in u.features.get("senses", [])   # asked). The target
                         and _follow(u, "quantifies") is not None                        # value quantifies
                         and _descriptor(_follow(u, "quantifies")) == rate.measure), None)  # the rate's measure
        # NOTE (deferred generalization): the target is sought only in the QUESTION units. "…2800 pages long
        # how many weeks…" (no comma) keeps the total in the question clause → found; a COMMA ("…long, how many
        # weeks…") splits the total into a PREMISE → a context-Quantity fallback (f.measure == rate.measure)
        # would solve it. Prototyped zero-regression but with ZERO benefit on real dev/test/permissive (the one
        # real case, John-bible, is already fixed upstream by the rate-marker entity recovery), so DEFERRED per
        # example-driven-deferral — re-add when a real comma-split rate-inversion problem forces it.
        # SELECT among rates (each must have a target the question quantifies): (1) one OWNED by a name in
        # the question ("how long does it take BRIANNA" → Brianna's 2 pg/min, not Anna's); (2) one whose
        # per_unit IS / converts to the asked unit ("15 pages/DAY" beats "5 pages/HOUR" for "how many
        # WEEKS"); (3) the first target-matching rate (preserves single-rate Joy/Sam).
        qnames = {_entity(u) for u in r.units if "name" in u.features.get("senses", [])}
        rate = next((f for f in rates if _inv_target(f) is not None and f.entity in qnames), None) \
            or next((f for f in rates if _inv_target(f) is not None and asked_unit is not None
                     and (asked_unit == f.per_unit or (f.per_unit, asked_unit) in CONVERSIONS)), None) \
            or next((f for f in rates if _inv_target(f) is not None), None) \
            or (rates[0] if rates else None)
        if rate is not None:                                                  # rate, in per_unit (convert if
            mv = _inv_target(rate)
            if mv is not None:
                target = _num(mv.features["value"])
                cv = next((u for u in r.units if "value" in u.features.get("senses", []) and u is not mv
                           and _follow(u, "quantifies") is not None), None)   # "3 BOOKS that are 400 pages"
                if cv is not None:
                    target += f" * {_num(cv.features['value'])}"
                expr = f"({target}) * {_num(rate.per_amount)} / {_num(rate.amount)}"   # "120 × 20 ÷ 8"
                if asked_unit in TIME_UNITS and asked_unit != rate.per_unit \
                        and (rate.per_unit, asked_unit) in CONVERSIONS:        # 300 min → 5 hours
                    expr = f"({expr}) * {_num(CONVERSIONS[(rate.per_unit, asked_unit)])}"
                return _compute(expr)
        if is_long:
            return "undetermined"                        # a how-long question with no usable rate
    collection = _follow(_follow(interro, "queries"), "collection")   # how → many → its collection
    query = _descriptor(collection) if collection is not None else None
    much = next((u for u in r.units if _key(u.surface) == "much"), None)
    if much is not None:                                 # "how much": read what `much` BOUND (no global
        coll = _follow(much, "collection")               # MONEY default) — an adjacent mass noun, or a
        if coll is not None and "verb" in coll.features.get("senses", []):   # result-measure verb ("how
            query = RESULT_MEASURE.get(_lemma(coll.surface))   # much did X EARN" → the earnings = MONEY)
        elif coll is not None:                           # "how much WATER" → that mass noun
            query = _descriptor(coll)
        else:                                            # bound nothing (e.g. "how much did he RUN") →
            query = None                                 # can't tell what's asked → decline, not MONEY
    # "how much CHANGE (did he get back / was he given)" = the MONEY returned after a purchase — the noun
    # "change" names the money-left query, computed exactly like "how much money is left" (have − Σspent).
    # Gate: a "how much" question mentioning "change" (the verb "change [tires]" pairs with "how many/how
    # long", never "how much", so requiring `much` excludes it). Sets the money query + remainder and rides
    # the proven remainder path below, which declines safely whenever it can't net one have against the spends.
    change_q = much is not None and any(_key(u.surface) == "change" for u in r.units)
    if change_q:
        query = MONEY
    remainder = change_q or any(_key(u.surface) in _REMAINDER for u in r.units)
    named = any("name" in u.features.get("senses", []) for u in r.units)   # NAMED entities ("Tom and Mary
    if combined_q and not named:                         # altogether") need the per-entity fold, not this
        gq = query                                       # "How many INCHES are all snakes COMBINED?" — a
        if gq is None:                                   # generic population → the GRAND TOTAL. A query-less
            measures = {f.measure for f in context if isinstance(f, Quantity) and f.amount is not None}
            gq = next(iter(measures)) if len(measures) == 1 else None   # "their combined experience" → the
        if gq is not None and remainder:                 # "how many do they have LEFT in total" → Σ each
            owners = {f.entity for f in context           # owner's NET holdings (signed: picked − gave −
                      if isinstance(f, Quantity) and f.measure == gq and f.amount is not None}  # sold),
            hs = [_holdings(o, gq, context) for o in owners]   # not the raw sum (which double-counts the
            if hs and all(h is not None for h in hs):          # gross alongside its own losses → Frank 210)
                return _compute(" + ".join(_num(h) for h in hs))
        if gq is not None:                               # one measure the context quantities share (years)
            terms = []                                   # sum every quantity convertible to it (cross-entity,
            for f in context:                            # cross-unit via CONVERSIONS)
                if isinstance(f, Quantity) and f.amount is not None:
                    if f.measure == gq:
                        terms.append(_num(f.amount))
                    elif (f.measure[0], gq[0]) in CONVERSIONS:
                        terms.append(f"{_num(f.amount)} * {_num(CONVERSIONS[(f.measure[0], gq[0])])}")
            if terms:
                return _compute(" + ".join(terms))
    if query is not None and any("verb" in u.features.get("senses", [])      # "How much <measure> was
                                 and _lemma(u.surface) in DISTRIBUTE_VERBS for u in r.units):  # shared?"
        shared = [f.amount for f in context if isinstance(f, Quantity) and f.measure == query   # → the
                  and f.verb in DISTRIBUTE_VERBS and f.amount is not None]   # PINNED distributed total
        if shared:
            return int(shared[0]) if shared[0] == int(shared[0]) else shared[0]
        return "undetermined"
    aux = next((u for u in r.units if "auxiliary" in u.features.get("senses", [])), None)
    comp = next((u for u in r.units if "comparative" in u.features.get("senses", [])), None)
    if comp is not None and aux is not None and query is not None:    # "How much more <measure> does
        standard = _follow(comp, "standard")                         # A have than B?" → A's − B's
        subjects, _ = _question_subjects(r, aux)                     # A = the verb's bound subject
        times = [u for u in r.units if "time" in u.features.get("senses", [])]
        than = next((u for u in r.units if _key(u.surface) == "than"), None)
        if len(subjects) == 1 and than is not None and len(times) == 2:   # ACROSS TIMES: one entity at
            tp = r.units.index(than)                                       # two times split by "than" —
            t1 = next((u for u in times if r.units.index(u) < tp), None)   # "…on Tuesday than on Monday"
            t2 = next((u for u in times if r.units.index(u) > tp), None)
            if t1 is not None and t2 is not None:
                a = _holdings_at(subjects[0], query, context, _key(t1.surface))
                b = _holdings_at(subjects[0], query, context, _key(t2.surface))
                if a is not None and b is not None:
                    diff = a - b if _key(comp.surface) == "more" else b - a
                    return int(diff) if diff == int(diff) else diff
            return "undetermined"
        # the comparative often binds its standard to the MEASURE noun ("more PAIRS"), not the entity being
        # compared. When the bound standard isn't a NAME and the question carries a comparison marker
        # ("compared to Jim" / "than Jim"), recover the standard as the non-subject NAME. ("How many more
        # pairs does Anthony have compared to Jim?" → Anthony − Jim.)
        if (standard is None or "name" not in standard.features.get("senses", [])) \
                and any(_key(u.surface) in ("than", "compared", "versus") for u in r.units):
            standard = next((u for u in r.units if "name" in u.features.get("senses", [])
                             and _entity(u) not in subjects), None)
        if standard is not None and len(subjects) == 1:
            a = _holdings(subjects[0], query, context)
            b = _holdings(_entity(standard), query, context)
            if a is not None and b is not None:
                diff = a - b if _key(comp.surface) == "more" else b - a   # "less"/"fewer" → B − A
                return int(diff) if diff == int(diff) else diff
        return "undetermined"
    if aux is not None and query is not None and query[0] == "time":   # "How many times does X <verb>?"
        subjects, action = _question_subjects(r, aux)
        if subjects:
            counts = [f.count for f in context if isinstance(f, Frequency)
                      and f.entity == subjects[0] and f.action == action]
            if counts:
                return int(counts[0]) if counts[0] == int(counts[0]) else counts[0]
            return "undetermined"
    # ELIDED COUNT-NOUN — "how many does Steven have?" omits the measure noun, so `query` is None and the
    # per-entity fold below can't run. If the context quantities share exactly ONE measure, infer it as the
    # query (the single salient thing to count) — mirrors the query-less combined-fold's measure inference
    # (#102). Decline-safe: only when unambiguous (one measure); two+ measures keep query None → decline.
    if query is None and any(_key(u.surface) == "many" for u in r.units):
        measures = {f.measure for f in context if isinstance(f, Quantity) and f.amount is not None}
        if len(measures) == 1:
            query = next(iter(measures))
    qverb_unit = next((u for u in r.units if "verb" in u.features.get("senses", [])
                       and _key(u.surface) not in ("is", "are", "was", "were")), None)
    # "How many STUDENTS passed?" — no aux; the query noun IS the subject. Only when a matching count-fact
    # exists (so it never preempts the remainder / count-instances branches).
    noaux_match = (aux is None and query is not None and qverb_unit is not None and not remainder
                   and any(isinstance(f, Quantity) and f.entity == query[0] and f.measure == query
                           and f.verb == _lemma(qverb_unit.surface) for f in context))
    if noaux_match:
        entities, q_verb, q_time = [query[0]], _lemma(qverb_unit.surface), None
    elif aux is not None and query is not None:           # "How many <measure> do <entities> <verb>?"
        entities, q_verb = _question_subjects(r, aux)    # the verb's bound subject(s), structurally
        q_time = next((_key(u.surface) for u in r.units if "time" in u.features.get("senses", [])), None)
    else:
        entities = None
    if change_q:                                         # "how much change" is ALWAYS the money REMAINDER
        entities = None                                  # (have − Σspent), never an entity-verb count: the
        #                                                  vacuous trailing verb ("get [back]"/"receive") has
        #                                                  no matching events, so skip the verb fold and take
        #                                                  the remainder path below (like "how much money is left").
    if query is not None and entities is not None:
        if entities:
            terms = []                                   # each conjunct's contribution, summed once at the end
            for ent in entities:
                if q_verb in ("have", "own") and q_time is not None:   # TIME-AWARE: the value VALID at
                    h = _holdings_at(ent, query, context, q_time)      # the queried time, folded along
                    if h is None:                                      # the timeline (state vs change)
                        return "undetermined"
                    terms.append(_num(h))
                    continue
                qs = [f for f in context if isinstance(f, Quantity)
                      and f.entity == ent and f.measure == query]
                if not qs and not query[1]:              # BARE HEAD ("how many STICKERS") with no exact
                    qs = [f for f in context if isinstance(f, Quantity)   # match → sum the entity's SUB-TYPES
                          and f.entity == ent and f.measure[0] == query[0]]   # under that head (8 flower +
                #   6 animal stickers → 14). Reached only when no bare-head quantity exists, so it never
                #   double-counts; the fold below signs each by its verb (have/used/…).
                # Both CONVERT branches below skip TIME-unit pairs: a time quantity in the context
                # is usually a DURATION ("for one week", "on each of nine days"), not a holding —
                # converting one commits garbage ("90 days" → 2160 hours). The rate-query path owns
                # legitimate time conversion.
                if not qs:                               # CONVERT: "how many KILOGRAMS" when we hold grams
                    qs = [Quantity(ent, query, _compute(f"{_num(f.amount)} * "
                                   f"{_num(CONVERSIONS[(f.measure[0], query[0])])}"), f.verb)
                          for f in context if isinstance(f, Quantity) and f.entity == ent
                          and f.amount is not None and (f.measure[0], query[0]) in CONVERSIONS
                          and not (f.measure[0] in TIME_UNITS and query[0] in TIME_UNITS)]
                elif q_verb in ("have", "own"):          # MIXED units in a holdings fold: extend the
                    qs = qs + [Quantity(ent, query,      # exact-unit matches with CONVERTIBLE holdings
                                        _compute(f"{_num(f.amount)} * "     # in other units ("has 3
                                                 f"{_num(CONVERSIONS[(f.measure[0], query[0])])}"),
                                        f.verb)          # GALLONS, drank 13 OUNCES, how many ounces
                               for f in context if isinstance(f, Quantity)  # left" → 3·128 − 13).
                               and f.entity == ent and f.amount is not None # Gated to the have/own
                               and f.measure[0] != query[0]                 # remainder fold only.
                               and (f.measure[0], query[0]) in CONVERSIONS
                               and not (f.measure[0] in TIME_UNITS and query[0] in TIME_UNITS)]
                # POLARITY IS RELATIVE TO THE QUESTION: "how many do you HAVE" folds holdings
                # (baseline + gains - losses); "how many did you SELL" COUNTS the sell events (+).
                if q_verb in ("have", "own"):
                    folded = [f"{_verb_sign(f.verb)} * {_num(f.amount)}" for f in qs]
                else:
                    folded = [_num(f.amount) for f in qs if f.verb == q_verb]   # events of THIS verb
                # FIRST-PERIOD EXCEPTION: "teaches 50 a year … in 10 years … the FIRST year only 40" →
                # override + rate×(duration−1) = 40 + 50×9. The override (40) is year 1; the rate covers
                # the rest. (Without an override the rate×duration path below handles the plain case.)
                override = next((f for f in qs if f.verb == q_verb and f.first_period), None)
                rate = next((f for f in context if isinstance(f, Rate) and f.entity == ent
                             and f.measure == query and f.verb == q_verb), None)
                if override is not None and rate is not None:
                    dur = next((u.features["value"] for u in r.units if "value" in u.features.get("senses", [])
                                and _follow(u, "quantifies") is not None
                                and _descriptor(_follow(u, "quantifies"))[0] == rate.per_unit), None)
                    if dur is not None:
                        terms.append(f"{_num(override.amount)} + {_num(rate.amount)} * ({_num(dur)} - 1)")
                        continue
                if folded:
                    terms.extend(folded)
                    continue
                rate = next((f for f in context if isinstance(f, Rate) and f.entity == ent     # rate ×
                             and f.measure == query and f.verb == q_verb), None)                # per-unit
                if rate is None and query == MONEY:         # CROSS-ENTITY price: "$5.50 per pound" (stated
                    rate = next((f for f in context if isinstance(f, Rate) and f.measure == MONEY  # of beef/
                                 and _holdings(ent, (f.per_unit, frozenset()), context) is not None), None)
                per_qty = _holdings(ent, (rate.per_unit, frozenset()), context) if rate else None
                if per_qty is None and rate is not None:    # "…write in 3 DAYS?" — per-unit count is in
                    per_qty = next((u.features["value"] for u in r.units    # the QUESTION, not a premise
                                    if "value" in u.features.get("senses", []) and _follow(u, "quantifies")
                                    is not None and _descriptor(_follow(u, "quantifies"))[0] == rate.per_unit), None)
                if per_qty is None and rate is not None:    # CONVERT: a premise quantity in another unit
                    for f in context:                       # ("50 minutes" for an hourly rate → 50/60 hr)
                        if isinstance(f, Quantity) and f.entity == ent and f.amount is not None \
                                and (f.measure[0], rate.per_unit) in CONVERSIONS:
                            base = _holdings(ent, f.measure, context)
                            if base is not None:
                                per_qty = _compute(f"{_num(base)} * "
                                                   f"{_num(CONVERSIONS[(f.measure[0], rate.per_unit)])}")
                                break
                if per_qty is None:
                    return "undetermined"                # no relevant quantity/rate for this conjunct
                terms.append(f"{_num(rate.amount)} * {_num(per_qty)}")
            return _compute(" + ".join(terms)) if terms else "undetermined"
    if remainder:                                        # "How many [<measure>] are left?" → the net
        measure = query                                  # HOLDINGS of the (implicit) owner — no aux/entity
        if measure is None:                              # "how many are left" — measure from the latest qty
            recent = next((f for f in reversed(context) if isinstance(f, Quantity)), None)
            measure = recent.measure if recent is not None else None
        if measure is not None:
            owners = {f.entity for f in context if isinstance(f, Quantity) and f.measure == measure}
            if len(owners) == 1:                         # one holder → its net holdings; else ambiguous
                total = _holdings(next(iter(owners)), measure, context)
                if total is not None:
                    return int(total) if total == int(total) else total
        return "undetermined"
    if query is None:
        # ABSTRACT/ELIDED MEASURE over an ACCUMULATION — "how FAR did she walk for 2 hours?" has no measure
        # noun, but if the context holds ONE measure, ONE owner, and ≥2 quantities (a sum the normal path
        # missed), the answer is that owner's net holding (Hazel: 2 + 4 = 6). The ≥2 gate keeps a single-fact
        # "how much did Tom run?" (5 miles) DECLINING per #74's no-guess design — this only rescues an
        # accumulation the measure-less question couldn't dispatch.
        qs = [f for f in context if isinstance(f, Quantity) and f.amount is not None]
        if len(qs) >= 2 and len({f.measure for f in qs}) == 1 and len({f.entity for f in qs}) == 1:
            total = _holdings(qs[0].entity, qs[0].measure, context)
            if total is not None:
                return int(total) if total == int(total) else total
        return [Deficiency("unanswerable", interro, "I couldn't tell what to count")]
    if not any(isinstance(inst, tuple) and inst[0] == query[0] for inst in context):
        return "undetermined"        # the queried TYPE isn't present as instances (e.g. "how much money"
        # when only `son` instances exist, or the amount lives in Quantities) — decline, never a bogus 0.
        # (A type that IS present but with 0 matches — "how many RED apples", no red ones — stays a real 0.)
    return sum(1 for inst in context if isinstance(inst, tuple) and _matches(query, inst))


def instances(statement: str) -> list:
    """Parse a "there are N <collection>" statement into N copies of the collection's descriptor —
    the instance set `answer()` queries. The number word ranges over the collection (same
    `collection` obligation as any quantifier) and carries its value via NUMBERS. Returns [] when no
    count+collection can be read, so an unparseable statement teaches us nothing rather than a guess.
    Concatenate over several statements to build a context."""
    r = analyze(statement)
    for u in r.units:
        if "value" not in u.features.get("senses", []):
            continue
        collection = _follow(u, "quantifies")
        if collection is not None:
            return [_descriptor(collection)] * int(u.features["value"])
    return []


def _verdict_steps(subject: tuple, predicate: str, context: list, q: str, fact: str,
                   obj: tuple = None) -> list:
    """Derivation steps for a (subject, predicate[, object]) yes/no query — shared by the verb (aux)
    and the adjective (property) branches. `q` opens the question ("does"/"is"); `fact` is how a
    stated fact reads ("" for a verb, "is" for an adjective)."""
    def line(text):
        return " ".join(text.split())                    # tidy doubled spaces from an empty `fact`
    obj_s = f" {obj[0]}" if obj else ""
    verdict = _predication_verdict(subject, predicate, context, obj)
    steps = [line(f"{q} {subject[0]!r} {predicate}{obj_s}? → {verdict}")]
    if Predication(subject, predicate, object=obj) in context:
        steps.append(line(f"directly stated: {subject[0]} {fact} {predicate}{obj_s}"))
    if Predication(subject, predicate, negated=True, object=obj) in context:
        steps.append(line(f"directly stated: {subject[0]} {fact} NOT {predicate}{obj_s}"))
    for f in context:                                    # universal facts that reach the subject
        if isinstance(f, Predication) and f.universal and f.predicate == predicate and f.object == obj \
                and _is_member(subject[0], f.subject, context):
            steps.append(line(f"{subject[0]!r} is a {f.subject[0]}; "
                              f"{'no ' if f.negated else 'all '}{f.subject[0]} {fact} {predicate}"))
    if verdict == "undetermined":
        steps.append("nothing in context settles it — lack of information")
    if verdict == "conflict":
        steps.append("both true and false are derivable — the premises contradict")
    return steps


def explain(question: str, context: list) -> list:
    """The human-readable derivation steps behind `answer(question, context)` — what was queried,
    which facts were checked, and how the verdict follows."""
    r = analyze(question)
    unknown = [d.message for d in deficiencies(r) if d.kind == "unknown-word"]
    if unknown:
        return unknown
    subj, comp = _copula_args(r)
    if _has_sense(comp, "comparative"):                  # comparative derivation
        standard = _follow(comp, "standard")
        if subj is not None and standard is not None:
            a, rel, b = _key(subj.surface), _key(comp.surface), _key(standard.surface)
            fwd, rev = _related(a, rel, b, context), _related(b, rel, a, context)
            return [f"is {a!r} {rel} than {b!r}? → {_verdict(fwd, rev)}",
                    f"{a} {rel} than {b} (transitively)? {'yes' if fwd else 'no'}",
                    f"{b} {rel} than {a}, so NOT the reverse (asymmetry)? {'yes' if rev else 'no'}"]
    if _has_sense(subj, "name") and _has_sense(comp, "noun"):    # membership derivation
        member, target = _key(subj.surface), _descriptor(comp)
        yes = _is_member(member, target, context)
        no = any(isinstance(m, Membership) and m.member == member and m.collection == target
                 and m.negated for m in context) \
            or any(_disjoint(c, target, context) for c in _collections_of(member, context))
        cols = sorted(c[0] for c in _collections_of(member, context))
        steps = [f"is {member!r} a {target[0]}? → {_verdict(yes, no)}",
                 f"{member!r} is a: {', '.join(cols) or 'nothing known'}"]
        if no:
            steps.append(f"and it is stated/derivable that {member!r} is NOT a {target[0]}")
        return steps
    prop = _property(r)                                  # property derivation (adjective predicate)
    if prop is not None:
        return _verdict_steps(prop.subject, prop.predicate, context, "is", "are")

    aux = next((u for u in r.units if "auxiliary" in u.features.get("senses", [])), None)
    if aux is not None:                                  # yes/no derivation
        verb = _follow(aux, "asks_predication")
        subject = _follow(verb, "subject") if verb else None
        if subject is None:
            return ["couldn't tell what is being asked"]
        obj = _follow(verb, "dobj")
        return _verdict_steps(_descriptor(subject), _lemma(verb.surface), context, "does", "",
                              _descriptor(obj) if obj is not None else None)
    interro = next((u for u in r.units if "interrogative" in u.features.get("senses", [])), None)
    if interro is not None:                              # count derivation
        coll = _follow(_follow(interro, "queries"), "collection")
        if coll is not None:
            q = _descriptor(coll)
            n = sum(1 for inst in context if isinstance(inst, tuple) and _matches(q, inst))
            return [f"count of {q}: {n} matching instance(s)"]
    return ["not a question I can answer"]


def learn(statement: str, discourse: list = None, context: list = None) -> list:
    """Parse a statement into context facts — the one ingestion door. A count statement ("There are
    three red apples") → instances; a subject-verb statement ("The student passed") → a Predication;
    a bare collection ("red apple") → one instance. [] when nothing parses, so we never guess.

    `discourse` (entity names, most-recent LAST) threads coreference across sentences: a pronoun's
    `refers` obligation is resolved against it before extraction, and the statement's own subject is
    appended after, so a later pronoun can find it. `context` (the facts so far) lets a RELATIONAL
    quantity ("twice as many") resolve its referent quantity."""
    r = analyze(statement)
    if discourse is not None:
        _resolve_references(r, discourse)
    facts = _facts_from(r, context if context is not None else [])
    if discourse is not None:                            # remember this statement's subject as a discourse
        verbs = [u for u in r.units if "verb" in u.features.get("senses", [])]  # entry (entity, is_name).
        non_cop = [v for v in verbs if _key(v.surface) not in ("is", "are", "was", "were", "be")]
        subj = _follow(non_cop[0], "subject") if len(non_cop) == 1 else None    # the non-copula MAIN verb's
        #                                                    subject ("James buys … that are …" → James). A
        if subj is None and len(verbs) == 1 and not non_cop:   # BARE copula ("Tina is 10") records its subject
            cs = _follow(verbs[0], "subject")                  # too — but ONLY a NAME (so "She is …" can later
            if cs is not None and "name" in cs.features.get("senses", []):   # corefer to Tina); a common-noun
                subj = cs                                      # copula subject ("the PRICE of beef is $5") must
        if subj is not None:                                   # NOT pollute the discourse (it broke he→James)
            discourse.append((_entity(subj), "name" in subj.features.get("senses", [])))   # James)
        elif facts and len(r.units) > 1 and _key(r.units[0].surface) == "for" \
                and _key(r.units[1].surface) in ("every", "each"):   # the per-occurrence construct "For
            ent = next((f.entity for f in facts if getattr(f, "entity", None)   # every X, Sam eats N Y" —
                        and any(_entity(u) == f.entity                          # the generic finder skips it
                        and "name" in u.features.get("senses", []) for u in r.units)), None)  # (2 verbs), so
            if ent is not None:                          # register the fact's NAME entity for a later pronoun.
                discourse.append((ent, True))            # Scoped to this construct to keep coref blast radius small.
    return facts


def _facts_from(reading: Reading, context: list = None) -> list:
    r = reading
    to = _temporal_order(r)                              # "<time> is after/before <time>" → Before fact
    if to is not None:
        return [to]
    dist = _distribution(r)                              # "<name> shared <measure> between <recipients>"
    if dist is not None:                                 # → unknown-amount node + a Distribution relation
        return dist
    # FUTURE age with a SUB-YEAR shift the year-machinery can't convert ("In 18 months, she will be 10 years
    # old") — storing a plain current age (10) ignores the shift and the relation off it commits a wrong
    # (Antonio = 10/2 = 5). The age path is year-only, so DECLINE rather than fold the months as years.
    if any(_key(u.surface) == "will" and "auxiliary" in u.features.get("senses", []) for u in r.units) \
            and any(_key(u.surface) == "old" for u in r.units):
        off_prep = next((u for u in r.units if "preposition" in u.features.get("senses", [])
                         and _key(u.surface) in ("in", "after")), None)
        off_obj = _follow(off_prep, "object") if off_prep is not None else None
        if off_obj is not None and _descriptor(off_obj)[0] in ("month", "week", "day"):
            return []
    verbs = [u for u in r.units if "verb" in u.features.get("senses", [])]
    if len(verbs) == 1:                                  # a group-subject STATEMENT ("Tom and Mary have
        subj = _follow(verbs[0], "subject")              # 5 apples") is distributive/collective — ambiguous,
        if subj is not None and "members" in subj.features \
                and not any(_key(u.surface) in ("total", "combined") for u in r.units):   # but an explicit
            return []                                    # TOTAL ("they walk a TOTAL of 70 miles") is an
            #                                              unambiguous collective → let the fact form
    if any("existential" in u.features.get("senses", []) for u in r.units):   # "there are N <coll>" → N
        for u in r.units:                                # instances (existential-gated, so "Tom has three
            if "value" in u.features.get("senses", []):  # apples"/"three years younger" stay arithmetic)
                coll = _follow(u, "quantifies")
                if coll is not None:
                    return [_descriptor(coll)] * int(u.features["value"])
    sa = _simultaneous_ages(r)                           # "X was A years old when Y was B years old" → both
    if sa is not None:                                   # ages (a constant-gap pair) at the same reference
        return sa
    fa = _future_age(r)                                  # "(in N years) E will be X years old" → E_now=X−N?
    if fa is not None:
        return [fa]
    ca = _comparative_age(r, context)                    # "X is N years older than Y" → Y_age ± N?
    if ca is not None:
        return [ca]
    ra = _relational_age(r, context)                     # "X is N times as old as Y" → X_age = N × Y_age?
    if ra is not None:
        return [ra]
    pas = _possessive_age_statement(r)                    # "Ron's age is 43" → Quantity(ron, year, 43)
    if pas is not None:
        return [pas]
    pap = _possessive_age_parts(r)                        # "X's age is k× Y's age" / "X is k× Y's age" →
    if pap is not None:                                   # X_age = k × Y_age (the possessive frame)
        subj_e, std_e, k = pap
        delta = _time_offset(r)                           # "In Δ years, X will be k× Y's age" shifts BOTH
        std_now = any(_key(u.surface) in ("now", "today", "currently") for u in r.units)   # …unless Y is
        #                                                  anchored to the present ("the age Y is CURRENTLY")
        y = _holdings(std_e, ("year", frozenset()), context)
        if y is not None:                                 # FORWARD: X_now = k·(Y_now+Δ) − Δ; std_now drops +Δ
            y_ref = _num(y) if std_now else f"({_num(y)} + {_num(delta)})"
            x = f"{_num(k)} * {y_ref} - {_num(delta)}" if delta else f"{_num(k)} * {_num(y)}"
            return [Quantity(subj_e, ("year", frozenset()), _compute(x), "be")]
        x_now = _holdings(subj_e, ("year", frozenset()), context)   # BACKWARD: subject known, derive standard
        if x_now is not None and k:                       # Y_now = (X_now+Δ)/k − Δ ("Suzy 20; Suzy+4 = 2·(Mary+4)"
            tail = "" if std_now else f" - {_num(delta)}"   # → Mary = 24/2 − 4 = 8); std_now drops the −Δ
            yv = f"({_num(x_now)} + {_num(delta)}) / {_num(k)}{tail}" if delta \
                else f"{_num(x_now)} / {_num(k)}"
            return [Quantity(std_e, ("year", frozenset()), _compute(yv), "be")]
        return []                                         # neither age known → DEFER (fixpoint chains), and
        #                                                   crucially don't fall to _frequency (bogus Freq)
    if _relational_age_factor(r) is not None and _copula_args(r)[0] is not None:
        return []                                        # Y's age not yet known → DEFER (the fixpoint
        # chains the multi-hop: Anne=2×Emile, Emile=6×Maude, Maude=8 → 96; never a bare predication)
    mult = next((u for u in r.units if "multiplier" in u.features.get("senses", [])), None)
    scaled = _follow(mult, "scales") if mult is not None else None
    if scaled is not None and ("quantifier" in scaled.features.get("senses", [])     # "twice as many" /
                               or _key(scaled.surface) in (COUNT_NOUNS | DIMENSIONS)):  # the number / as long
        rq = _relational_quantity(r, context)            # "<entity> has twice as many" → derived, or
        return [rq] if rq is not None else []            # decline (no referent) — never a bare predication
    frac = next((u for u in r.units if _fraction_parts(u.surface) is not None), None)  # unit OR non-unit
    if frac is not None:                                  # "<fraction> OF <referent>" — a partitive part
        fi = r.units.index(frac)                          # of a holding ("loses half of them" → 0.5×held;
        if fi + 1 < len(r.units) and _key(r.units[fi + 1].surface) == "of":   # "a third of …"; NOT a Freq)
            pq = _partitive_quantity(r, context)
            return [pq] if pq is not None else []        # unresolved → defer (fixpoint retries; else declines)
    s = _subset(r)                                       # "Every X is a Y" → universal membership?
    if s is not None:
        return [s]
    m = _membership(r)                                   # "<name> is a <noun>" → membership?
    if m is not None:
        return [m]
    prop = _property(r)                                  # "<subject> is <adjective>" → property?
    if prop is not None:
        return [prop]
    rel = _relation(r)                                   # "<A> is <comparative> than <B>" → relation?
    if rel is not None:
        return [rel]
    rr = _rate_relations(r)                              # "Carole reads as fast as Anna but half Brianna's
    if rr is not None:                                    # speed" → relational rate(s) (resolved bidirectionally)
        return rr
    fr = _frequency(r)                                   # "<entity> <verb>s twice" → frequency?
    if fr is not None:
        return [fr]
    trr = _time_range_rate(r)                            # "writes from 1 PM to 4 PM every night" → 3 h/day?
    if trr is not None:
        return [trr]
    por = _per_occurrence_rate(r)                        # "for every sandwich … eats 4 apples" → 4/sandwich?
    if por is not None:
        return [por]
    rate = _rate(r, context)                             # "<entity> earns $12 per hour" → rate?
    if rate is not None:                                 # a trailing "for one week" → a duration alongside it
        dur = _for_duration(r, rate)
        return [rate, dur] if dur is not None else [rate]
    cq = _comparative_quantity(r, context)               # "<A> has 30 less <X> than <B>" → derived?
    if cq is not None:
        return [cq]
    comp = next((u for u in r.units if "comparative" in u.features.get("senses", [])), None)
    if comp is not None and _follow(comp, "standard") is not None \
            and any("value" in u.features.get("senses", []) for u in r.units):
        return []                                        # a comparative-quantity structure we couldn't
        # resolve (the standard's count is unknown — a forward ref) → DEFER (don't fall through to a
        # flat _quantity); the solve() fixpoint will retry it once the standard is learned.
    pq = _percent_quantity(r, context)                   # "puts 20% more money" → 0.2 × holding?
    if pq is not None:
        return [pq]
    rq = _rest_quantity(r, context)                      # "the REST failed" → total − Σ(stated subsets)?
    if rq is not None:
        return [rq]
    if any(_key(u.surface) in REST_WORDS for u in r.units):
        return []                                        # "the rest …" but no total yet → DEFER (the
        # solve() fixpoint retries once the population total / subsets are learned, e.g. a trailing "if")
    pct = next((u for u in r.units if "percent" in u.features.get("senses", [])), None)
    if pct is not None and _follow(pct, "base") is None \
            and len([u for u in r.units if "verb" in u.features.get("senses", [])]) == 1 \
            and any("noun" in u.features.get("senses", []) for u in r.units):
        return []                                        # percent-of-holding, referent not yet known → defer
    cq = _container_quantity(r)                          # "20 packets of 100 grams" → 20×100 = 2000?
    if cq:                                               # (conjoined of-phrases → a product each)
        return cq
    pu = _purchase(r, context)                           # "buys 4 candy bars that cost $2 each" → −$8?
    if pu is not None:
        return pu
    dq = _distributed_quantity(r)                        # "gave 4 stickers each to 3 friends" → 4×3?
    if dq is not None:
        return [dq]
    tq = _transfer_quantity(r)                           # "sold clips to 48 friends" → 48 clips (one each)
    if tq is not None:
        return tq
    dt = _dative_transfer(r)                             # "Tom gave Reggie $48" → Reggie +48 AND Tom −48
    if dt is not None:
        return dt
    q = _quantity(r)                                     # "<entity> has 3 apples and 2 oranges" → list
    if q:
        return q
    p = _predication(r)                                  # subject-verb statement?
    if p is not None:
        return [p]
    d = collection_descriptor(r)                         # bare collection phrase?
    return [d] if d is not None else []


# --- the read–SYNTHESIZE loop: reading BINDS what's present, synthesis DERIVES what's implied --------
# Reading discharges obligations by binding to words that are THERE. Some obligations have no such word
# — their target exists only by IMPLICATION (a time never explicitly ordered but derivable by
# transitivity; later: an implied time, an "earlier value" standard). The synthesize() driver runs to a
# fixpoint: it dispatches the registered synthesizers (keyed by the fact KIND they produce) over the
# facts gathered so far, folds in whatever they derive, and repeats. The OUTSTANDING obligations are the
# agenda (passed to each synthesizer). New reasoning is added by REGISTERING a synthesizer — never a
# one-off check. Anything still unfilled after the fixpoint stays a deficiency, never a guess.
def _before(a: str, b: str, facts: list) -> bool:
    """True if time-node `a` is earlier than `b` under the TRANSITIVE closure of the Before facts
    (relational order — no calendar rank). DFS over Before edges."""
    adj = {}
    for f in facts:
        if isinstance(f, Before):
            adj.setdefault(f.earlier, set()).add(f.later)
    seen, stack = set(), [a]
    while stack:
        x = stack.pop()
        for y in adj.get(x, ()):
            if y == b:
                return True
            if y not in seen:
                seen.add(y)
                stack.append(y)
    return False


def _synth_transitive_order(facts: list, readings: list, agenda: set) -> list:
    """One-hop transitive ordering: `a before b` ∧ `b before c` ⟹ `a before c`. Iterated to full
    closure by the driver's fixpoint, so a chain (Tue→Sat→Mon→Wed) is filled over successive rounds —
    front-loaded multi-step reasoning. (Registered for the `orders`/Before kind.)"""
    befores = [f for f in facts if isinstance(f, Before)]
    out = []
    for f1 in befores:
        for f2 in befores:
            if f1.later == f2.earlier and f1.earlier != f2.later:
                cand = Before(f1.earlier, f2.later)
                if cand not in facts and cand not in out:
                    out.append(cand)
    return out


def _synth_narrative_order(facts: list, readings: list, agenda: set) -> list:
    """Values stated in SEQUENCE are narrated chronologically: consecutive DISTINCT value@time nodes (in
    the order their facts appear) → a Before edge — UNLESS those two times are already ordered (so an
    explicit/transitive order always wins, and we never add a contradicting edge). The default that lets
    "On Monday … On Tuesday … On Wednesday …" be queryable without an explicit "after" in every sentence."""
    seq = []
    for f in facts:
        if isinstance(f, Quantity) and f.time is not None and f.time not in seq:
            seq.append(f.time)
    out = []
    for a, b in zip(seq, seq[1:]):
        if a != b and not _before(a, b, facts) and not _before(b, a, facts):
            cand = Before(a, b)
            if cand not in out:
                out.append(cand)
    return out


def _synth_distribution(facts: list, readings: list, agenda: set) -> list:
    """PIN an unknown distributed total by back-linking through its `Distribution`: once EVERY recipient's
    holding of the measure is known, the whole = their SUM → derive `Quantity(distributor, measure, sum,
    "share")`. This is the unknown-node's `value` obligation discharged by inference (not a question-time
    heuristic). Idempotent: skip a Distribution whose total is already resolved."""
    out = []
    for f in facts:
        if not isinstance(f, Distribution):
            continue
        if any(isinstance(q, Quantity) and q.entity == f.distributor and q.measure == f.measure
               and q.verb in DISTRIBUTE_VERBS and q.amount is not None for q in facts):
            continue                                     # already pinned
        shares = [_holdings(r, f.measure, facts) for r in f.recipients]
        if shares and all(s is not None for s in shares):
            out.append(Quantity(f.distributor, f.measure,
                                _compute(" + ".join(_num(s) for s in shares)), "share"))
    return out


def _underspecified_distribution(context: list):
    """A Distribution we can't resolve because the SPLIT METHOD is missing/non-computable: the whole is
    KNOWN, but `method` isn't "equal" (None, or "randomly"/"optimally"…) AND no recipient has an explicit
    share. Returns that Distribution (→ a "how was it shared?" deficiency) or None. NOTE (future, not now):
    when a verb is blocked for want of a manner like this, instead of declining we could (a) fall back on a
    CONTEXT-DEPENDENT default method, or (b) enumerate an answer PER plausible manner. For now: ask."""
    for d in context:
        if not isinstance(d, Distribution) or d.method == "equal":
            continue
        total_known = any(isinstance(q, Quantity) and q.entity == d.distributor and q.measure == d.measure
                          and q.verb in DISTRIBUTE_VERBS and q.amount is not None for q in context)
        holders = d.recipients or ((d.recipient_noun[0],) if d.recipient_noun else ())
        has_shares = any(_holdings(h, d.measure, context) is not None for h in holders)
        if total_known and not has_shares:
            return d
    return None


def _synth_equal_split(facts: list, readings: list, agenda: set) -> list:
    """The EQUAL-SPLIT reading of a Distribution: a KNOWN whole shared `equally` among `count` recipients
    → each gets whole ÷ count. Derives a `get` Quantity per recipient — by name if named, else keyed to
    the recipient noun ("each son got …"). The per-share is inferred, not asked at question-time."""
    out = []
    for f in facts:
        if not isinstance(f, Distribution) or f.method != "equal" or not f.count:
            continue
        total = next((q.amount for q in facts if isinstance(q, Quantity) and q.entity == f.distributor
                      and q.measure == f.measure and q.verb in DISTRIBUTE_VERBS and q.amount is not None), None)
        if total is None:
            continue
        per = _compute(f"{_num(total)} / {_num(f.count)}")
        holders = f.recipients or ((f.recipient_noun[0],) if f.recipient_noun else ())
        for h in holders:
            cand = Quantity(h, f.measure, per, "get")
            if cand not in facts and cand not in out:
                out.append(cand)
    return out


def _synth_rate_duration(facts: list, readings: list, agenda: set) -> list:
    """A Rate accumulated over a stated DURATION → a concrete Quantity: "makes 7 pies a day … does this
    for 12 days" → Quantity(cooper, pie, 7×12, make), which then folds with later events (− eaten …).
    Fires when a same-entity Quantity counts the rate's per_unit (e.g. "12 days" for a per-day rate); a
    DIFFERENT-measure duration only (so the rate's own count-noun isn't mistaken for its duration). The
    derived total carries the rate's verb, so holdings sees production, not a stray day-count."""
    out = []
    for rt in facts:
        if not isinstance(rt, Rate):
            continue
        dur = next((q.amount for q in facts if isinstance(q, Quantity) and q.entity == rt.entity
                    and q.measure[0] == rt.per_unit and q.amount is not None
                    and q.measure != rt.measure), None)
        if dur is None:                                  # a CONVERTIBLE-unit duration ("one WEEK" for a
            rate_units = {x.per_unit for x in facts if isinstance(x, Rate)}   # per-DAY rate → 7 days). Skip
            conv = next(((q.amount, CONVERSIONS[(q.measure[0], rt.per_unit)]) for q in facts  # a quantity
                         if isinstance(q, Quantity) and q.entity == rt.entity and q.amount is not None
                         and q.measure != rt.measure and (q.measure[0], rt.per_unit) in CONVERSIONS
                         and q.measure[0] not in rate_units), None)   # whose unit is some rate's EXACT
            if conv is not None:                          # per_unit (it's THAT rate's duration — e.g. Tom's
                dur = _compute(f"{_num(conv[0])} * {_num(conv[1])}")   # 7 days feeds the per-day rate, not
                                                          # the per-hour one via a day→hour conversion)
        if dur is None:
            continue
        total = _compute(f"{_num(rt.amount)} * {_num(dur)} / {_num(rt.per_amount)}")
        cand = Quantity(rt.entity, rt.measure, total, rt.verb, derived=True)
        if cand not in facts and cand not in out:
            out.append(cand)
    return out


def _synth_rate_chain(facts: list, readings: list, agenda: set) -> list:
    """Two same-entity rates that share a unit COMPOSE into one: "3 hours per DAY" × "5 pages per HOUR"
    → 15 pages per day (the HOUR cancels). Fires when r1.measure == r2.per_unit; the product carries r2's
    measure over r1's per_unit and r2's verb. Derived; the inversion/duration paths then consume it
    (James: 15 pg/day, then 735 ÷ 15 = 49 days → 7 weeks)."""
    out = []
    rates = [f for f in facts if isinstance(f, Rate)]
    for r1 in rates:
        for r2 in rates:
            if r1 is r2 or r1.entity != r2.entity or r1.measure[0] != r2.per_unit:
                continue
            amt = _compute(f"{_num(r2.amount)} * {_num(r1.amount)} / {_num(r1.per_amount)} "
                           f"/ {_num(r2.per_amount)}")
            cand = Rate(r1.entity, amt, r2.measure, r1.per_unit, r2.verb, 1)
            if cand not in facts and cand not in out:
                out.append(cand)
    return out


def _synth_rate_relation(facts: list, readings: list, agenda: set) -> list:
    """Resolve a RateRel into a concrete Rate, EITHER direction (so a chain resolves across fixpoint
    rounds): forward — reference's rate known → subject = factor × reference; inverse — subject's rate
    known → reference = subject ÷ factor. Anna(1/min) → Carole = 1×Anna → Brianna = Carole ÷ 0.5 = 2/min.
    The derived rate copies the known rate's measure/per_unit/verb (only the amount scales)."""
    out = []
    def rate_of(ent):
        return next((f for f in facts if isinstance(f, Rate) and f.entity == ent), None)
    for rel in facts:
        if not isinstance(rel, RateRel):
            continue
        subj_rate, ref_rate = rate_of(rel.subject), rate_of(rel.reference)
        if ref_rate is not None and subj_rate is None:               # forward
            amt = _compute(f"{_num(rel.factor)} * {_num(ref_rate.amount)}")
            cand = Rate(rel.subject, amt, ref_rate.measure, ref_rate.per_unit, ref_rate.verb,
                        ref_rate.per_amount)
        elif subj_rate is not None and ref_rate is None and rel.factor != 0:   # inverse
            amt = _compute(f"{_num(subj_rate.amount)} / {_num(rel.factor)}")
            cand = Rate(rel.reference, amt, subj_rate.measure, subj_rate.per_unit, subj_rate.verb,
                        subj_rate.per_amount)
        else:
            continue
        if cand not in facts and cand not in out:
            out.append(cand)
    return out


# obligation/fact KIND → derivation (facts, readings, agenda) -> new facts. Register here to add reasoning.
SYNTHESIZERS = {"orders": _synth_transitive_order, "narrative": _synth_narrative_order,
                "distribution": _synth_distribution, "equal_split": _synth_equal_split,
                "rate_duration": _synth_rate_duration, "rate_chain": _synth_rate_chain,
                "rate_relation": _synth_rate_relation}


def _outstanding(readings: list) -> set:
    """The set of still-UNMET obligation needs across the readings — the synthesis agenda (what KINDS of
    fact we still need to try to derive)."""
    return {o.need for r in (readings or []) for u in r.units
            for o in u.features.get("obligations", []) if not o.met}


def synthesize(facts: list, readings: list = None) -> list:
    """The DERIVE step of the read–synthesize loop: to a fixpoint, run the registered synthesizers over
    the facts gathered so far and fold in what they imply. Returns the augmented fact list (existing +
    derived). Idempotent once closed."""
    facts = list(facts)
    changed = True
    while changed:
        changed = False
        agenda = _outstanding(readings)
        for fn in SYNTHESIZERS.values():
            for f in fn(facts, readings, agenda):
                if f not in facts:
                    facts.append(f)
                    changed = True
    return facts

# --- clause & question analysis: split clauses, find the question, per-clause helpers -------

def _has_verb(text: str) -> bool:
    # do/does/did are PRIMARILY auxiliaries; a clause fragment shouldn't count as having its own verb on
    # their account ("how many apples do Tom | and Mary have" must NOT split the "Tom and Mary" group).
    return any("verb" in u.features.get("senses", []) and _key(u.surface) not in ("do", "does", "did")
               for u in analyze(text).units)


def _main_verb(text: str):
    """The surface of the last verb in a clause — the action to lend to an elided neighbour."""
    verbs = [u for u in analyze(text).units if "verb" in u.features.get("senses", [])]
    return verbs[-1].surface if verbs else None


def _is_name_word(word: str) -> bool:
    """The token (minus punctuation) is a single proper NAME unit — used to spot a coordinated name list."""
    u = analyze(word.strip(_PUNCT)).units
    return len(u) == 1 and "name" in u[0].features.get("senses", [])


def _is_elided_clause(text: str) -> bool:
    """A verb-less clause whose verb is ELIDED: it has a SUBJECT (name/noun) BEFORE its first quantity
    ("her grandparents twice as much", "Mary 5 apples") — distinct from a bare conjoined object
    ("2 oranges": the quantity comes first, no subject)."""
    units = analyze(text).units
    qi = next((k for k, u in enumerate(units)
               if any(s in u.features.get("senses", []) for s in ("value", "multiplier"))), None)
    return qi is not None and any(
        any(s in units[k].features.get("senses", []) for s in ("name", "noun")) for k in range(qi))


def _clause_subject(text: str):
    """The SUBJECT surface of a clause — the first name/noun BEFORE its first content verb — or None if the
    clause opens straight with a verb (a subjectless conjunct like "is 3 years older than Yusaf")."""
    units = analyze(text).units
    vi = next((k for k, u in enumerate(units) if "verb" in u.features.get("senses", [])
               and _key(u.surface) not in ("do", "does", "did")), None)
    if vi is None:
        return None
    subj = next((units[k] for k in range(vi)
                 if any(s in units[k].features.get("senses", []) for s in ("name", "noun", "pronoun"))), None)
    return subj.surface if subj is not None else None


def _is_value_first_relation(text: str) -> bool:
    """A VALUE-FIRST coordinate relation whose subject AND verb are elided: "2 fewer toys than Amanda",
    "twice as many peppers as cucumbers", "4 more cows than goats" (a common-noun standard), "35 fewer
    children than THE NUMBER OF adults" (tolerating the elided re-quantification wrapper). It OPENS with a
    value/multiplier (so `_is_elided_clause` — which needs a subject before the value — rejects it as a bare
    object like "2 oranges"), but a COMPARATIVE (more/less/fewer) or a MULTIPLIER makes it a relation, and a
    NAME or NOUN/ADJECTIVE standard after "than"/"as" (possibly past a "the number/amount of" wrapper) pins
    the other entity — `_affine_relation`'s coordinate-noun fallback can consume a noun/adjective standard
    too, not just a name. Distinguishes the relation-conjunct from a genuine phrase-join ("3 apples and 2
    oranges" — no comparative, no factor)."""
    units = analyze(text).units
    qi = next((k for k, u in enumerate(units)
               if any(s in u.features.get("senses", []) for s in ("value", "multiplier"))), None)
    if qi is None or qi != 0:                          # must OPEN with the value/multiplier (subject elided)
        return False
    has_comp = any(_key(u.surface) in ("more", "less", "fewer") and "comparative" in u.features.get("senses", [])
                   for u in units)
    has_mult = any("multiplier" in u.features.get("senses", []) for u in units)
    if not (has_comp or has_mult):
        return False
    for k, u in enumerate(units):                      # a NAME or NOUN/ADJECTIVE standard right after "than"/"as"
        if _key(u.surface) not in ("than", "as"):
            continue
        i = k + 1
        if i < len(units) and _key(units[i].surface) in ("the", "a", "an") and i + 2 < len(units) \
                and _key(units[i + 1].surface) in COUNT_NOUNS and _key(units[i + 2].surface) == "of":
            i += 3                                      # skip the elided "the NUMBER/AMOUNT of" wrapper
        elif i < len(units) and _key(units[i].surface) in ("the", "a", "an"):
            i += 1                                      # skip a bare article ("than THE potatoes")
        if i < len(units) and any(s in units[i].features.get("senses", []) for s in ("name", "noun", "adjective")):
            return True
    return False


def _supply_verb(clause: str, verb: str):
    """Insert `verb` after the elided clause's subject (its first name/noun) — "Mary 5 apples" +
    "has" → "Mary has 5 apples". None if there's no subject word to anchor to."""
    if verb is None:
        return None
    subj = next((u for u in analyze(clause).units
                 if any(s in u.features.get("senses", []) for s in ("name", "noun"))), None)
    if subj is None:
        return None
    idx, words = subj.words[-1].index, clause.split()
    if idx >= len(words):
        return None
    return " ".join(words[:idx + 1] + [verb] + words[idx + 1:])


def _split_clauses(sentence: str) -> list:
    """Split a sentence into INDEPENDENT clauses joined by ';'/'and'/comma — ONLY where the left has its
    own verb AND the right either has one too OR is an elided clause that can BORROW the left's verb. A
    phrase-joining "and" ("3 apples and 2 oranges", "Tom and Mary") does NOT split. Recursive, so a
    chain of clauses (and a leading "If P, Q?" premise) all separate."""
    for sep in ("; ", ", and ", ", but ", ", so ", " if ", " and ", " while ", ", "):
        i = sentence.find(sep)
        while i != -1:
            left, right = sentence[:i].strip(), sentence[i + len(sep):].strip()
            # COORDINATED NAME LIST: "…have Megan, Kelcie, and Greg read?" — the "Megan, Kelcie, and Greg"
            # items are subjects sharing the TRAILING verb ("read"), not separate clauses. Splitting on any of
            # the list's commas/"and" truncates the question and strands a bogus premise ("Greg read?" — the
            # 3-name question-list bug). Fires (for a comma/"and" sep) when the left ENDS with a NAME and the
            # right BEGINS with a NAME and the right carries NO value/multiplier of its own (a real second
            # clause — "…and Mary has 5" — does, so it still splits). The whole list stays one clause.
            _lt, _rtoks = left.split(), right.split()
            if _rtoks and _rtoks[0].lower() == "and":         # a ", " that landed just before a list's "and"
                _rtoks = _rtoks[1:]                            # ("Kelcie, | and Greg read?") — skip the "and"
            # the ending name must be a LIST item (after a verb/comma), NOT a comparison STANDARD ("8 more
            # than Mark, and Mark has …" / "as many as Dilan and Ashley" — "Mark"/"Dilan" follow than/as and
            # begin a REAL second clause / a combined standard, which must still split).
            _std = len(_lt) >= 2 and _lt[-2].lower().strip(_PUNCT) in ("than", "as")
            # COMBINED STANDARD: "… as Jake and Clementine combined" — the right conjunct is just
            # "<Name> combined." (a name + a combined-marker, no verb, no value): the two names form
            # ONE summed standard, not a second clause. Keep the coordination intact for the
            # combined-standard reader (the _std rule below would otherwise sever it, stranding a
            # bogus "Clementine combined." premise).
            if sep in (", ", ", and ", " and ") and _std and _lt and _rtoks \
                    and _is_name_word(_lt[-1]) and _is_name_word(_rtoks[0]) \
                    and len(_rtoks) >= 2 \
                    and _rtoks[1].lower().strip(_PUNCT) in ("combined", "together", "altogether"):
                i = sentence.find(sep, i + 1)
                continue
            if sep in (", ", ", and ", " and ") and _lt and _rtoks and not _std \
                    and _is_name_word(_lt[-1]) and _is_name_word(_rtoks[0]) \
                    and not any(s in u.features.get("senses", []) for u in analyze(right).units
                                for s in ("value", "multiplier")):
                i = sentence.find(sep, i + 1)
                continue
            if left.lower().startswith(("for every", "for each")):
                i = sentence.find(sep, i + 1)            # "For every X, <main>" is ONE per-occurrence
                continue                                 # clause (the rate's per_unit + the main amount)
            if right.lower().startswith(("who ", "whom ")) and _has_verb(left):
                # RELATIVE CLAUSE "<Name>, who VERBs …" — the "who" refers to the antecedent (the name right
                # before the comma), and the clause predicates a SECOND relation about it. Rewrite "who" → the
                # antecedent so it learns as an independent premise ("Katie, who runs 4× as Cole" → "Katie runs
                # 4× as Cole"), letting a ratio/comparative CHAIN resolve. Person-only ("who"); "which"/"that"
                # stay reserved below for the per-item-price relative clause.
                ref = left.split()[-1].strip(_PUNCT)
                synth = f"{ref} {right[right.find(' ') + 1:]}".strip() if " " in right else ""
                if synth and _has_verb(synth):
                    return _split_clauses(left) + _split_clauses(synth)
                i = sentence.find(sep, i + 1)
                continue
            if right.lower().startswith(("which ", "each of which ", "each of them ", "that cost",
                                         "that costs", "that each cost")):
                i = sentence.find(sep, i + 1)            # a RELATIVE clause modifying the left's object
                continue                                 # ("bought 5 books, each of which cost $2") — keep
                #                                          together so _purchase reads the per-item price
            if _has_verb(left):
                if _has_verb(right):
                    # STATIVE subject elision: "Ali is 8 and is 3 years older than Yusaf" — the right conjunct
                    # has a verb but NO subject; supply the left's. GATED to a COPULA/stative right verb
                    # (is/are/was/were/has/have/had): the general elision (below) was REVERTED because it
                    # mis-fired on ACTION verbs ("She gave X and bought Y" → per-recipient/running-sum gaps,
                    # confident-wrongs 39→41), but a stative "is/has N more/older than Y" is a clean relation.
                    rwords = {_key(w) for w in right.split()}
                    is_question = right.rstrip().endswith("?") \
                        or rwords & {"how", "what", "which", "who", "whom", "whose", "why", "when", "where"}
                    if not is_question and _clause_subject(right) is None:
                        lsubj = _clause_subject(left)
                        rverb = next((_key(u.surface) for u in analyze(right).units
                                      if "verb" in u.features.get("senses", [])), None)
                        # a "then <verb>…" continuation ("spent $1.75 … and then spent another $1.25") is the
                        # SAME subject acting again — supply it for ANY verb (the "then" cue makes the sequential
                        # same-subject reading unambiguous, unlike a bare action-verb conjunct).
                        then_cont = right.lower().startswith("then ")
                        if lsubj is not None and (then_cont
                                                  or rverb in ("is", "are", "was", "were", "has", "have", "had")):
                            return _split_clauses(left) + _split_clauses(f"{lsubj} {right}")
                    # NOTE: general SUBJECT elision (action-verb right conjunct) stays REVERTED — it exposes
                    # multi-step gaps (per-recipient "each" distribution, "had $N left" inversion, running sums)
                    # that turn previously-declined problems into partial-answer confident-wrongs.
                    return _split_clauses(left) + _split_clauses(right)
                if _is_elided_clause(right):           # the right borrows the left's verb (elision)
                    synth = _supply_verb(right, _main_verb(left))
                    if synth:
                        return _split_clauses(left) + _split_clauses(synth)
                if _is_value_first_relation(right):    # VALUE-FIRST coordinate relation: "Anna has 3× toys as
                    # Mandy and 2 fewer toys than Amanda" — the right conjunct elides BOTH subject and verb
                    # (it opens with the value). Supply the left's subject + main verb so it learns as an
                    # independent relation. Gated (comparative/ratio + name standard) so a bare "and 2 oranges"
                    # phrase-join never triggers it.
                    lsubj, lverb = _clause_subject(left), _main_verb(left)
                    if lsubj is not None and lverb is not None:
                        return _split_clauses(left) + _split_clauses(f"{lsubj} {lverb} {right}")
                if sep in (", ", ", and ", " and "):
                    # COMPARATIVE LIST CONJUNCT, ELIDED STANDARD: "produced 237 potatoes, 60 fewer cucumbers"
                    # — a value-first COMPARATIVE conjunct with NO "than"/"as" AT ALL (so the branch above
                    # can't fire) compares to the PREVIOUS list item: the left's own trailing quantified
                    # noun. Supply subject + verb + "than the <noun>". Gated hard: the right opens with the
                    # value, carries a more/less/fewer comparative, no verb, no marker; the left must END in
                    # a noun a value quantifies (a genuine quantity-list item, not an arbitrary clause tail).
                    runits = analyze(right).units
                    if runits and "value" in runits[0].features.get("senses", []) \
                            and any(_key(u.surface) in ("more", "less", "fewer")
                                    and "comparative" in u.features.get("senses", []) for u in runits) \
                            and not any(_key(u.surface) in ("than", "as") for u in runits) \
                            and not any("verb" in u.features.get("senses", []) for u in runits):
                        lunits = analyze(left).units
                        lsubj, lverb = _clause_subject(left), _main_verb(left)
                        last = lunits[-1] if lunits else None
                        if lsubj is not None and lverb is not None and last is not None \
                                and "noun" in last.features.get("senses", []) \
                                and any("value" in u.features.get("senses", [])
                                        and _follow(u, "quantifies") is last for u in lunits):
                            std = last.surface.strip(_PUNCT)
                            return _split_clauses(left) + \
                                _split_clauses(f"{lsubj} {lverb} {right} than the {std}")
            i = sentence.find(sep, i + 1)
    return [sentence]


def _question_durations(reading: Reading, context: list) -> list:
    """Time-unit quantities stated in the QUESTION clause ("…how many pages does he read in 7 DAYS?").
    Question values are normally read at answer-time, but a rate×duration CHAIN whose duration lives in
    the question (not a premise) needs the duration as a synth SEED so the chain can compose: Tom's "10
    hours over 5 days" (2 h/day) × the question's "7 days" → 14 hours, then "50 pages/hour" × 14 → 700.
    The rate_duration synth chains the two rates once the day-seed is in context. Gated tightly — a seed
    is emitted ONLY when the question time-value's measure matches some rate's per_unit (the sole legit
    consumer), so a stray time value ("in 5 years" with no per-year rate) injects nothing. Carries the
    rate's entity+verb so the synth matches; derived-flagged so it never trips unused-given / equality."""
    seeds = []
    # GROWTH rates (grow/gain/…) are handled by the offset growth-projection path (baseline + rate×Δ);
    # seeding their duration would double-count (the derived total folds into the baseline). Only seed
    # from-scratch PRODUCTION rates (read/make/earn/…), whose total is the standalone rate×duration.
    rates = [f for f in context if isinstance(f, Rate) and f.verb not in GROWTH_VERBS]
    if not rates:
        return seeds
    for u in reading.units:
        if "value" not in u.features.get("senses", []):
            continue
        qn = _follow(u, "quantifies")
        if qn is None or _descriptor(qn)[0] not in TIME_UNITS:
            continue
        meas, amt = _descriptor(qn), u.features["value"]
        for rt in rates:
            if meas[0] != rt.per_unit:
                continue
            cand = Quantity(rt.entity, meas, amt, rt.verb, derived=True)
            if cand not in seeds and cand not in context:
                seeds.append(cand)
    return seeds


# Words that SELECT a subgroup of a partitioned container set ("the FIRST two tanks", "the OTHER two",
# "ANOTHER tank") — the structural signature of a partition (distinct from a plain "N of the apples").
_PARTITION_SELECTORS = {"first", "other", "another", "next", "last", "remaining"}


def _subgroup_count(reading: Reading):
    """The COUNT of members a subgroup-selector picks out, or None. Three surface forms:
    "the first/other TWO …" (value right of a selector word), "N OF the tanks" (value left of "of"),
    or a bare "<value> <container>" only when a selector word is also present in the clause."""
    units = reading.units
    for k, u in enumerate(units):
        if "value" not in u.features.get("senses", []):
            continue
        prevk = _key(units[k - 1].surface) if k > 0 else ""
        nextk = _key(units[k + 1].surface) if k + 1 < len(units) else ""
        if prevk in _PARTITION_SELECTORS:        # "the other TWO", "the first TWO"
            return u.features["value"]
        if nextk == "of":                        # "1 OF the tanks" (partition-level gates provide safety)
            return u.features["value"]
    return None


def _subgroup_container(reading: Reading):
    """The CONTAINER noun a subgroup partitions ("the first two TANKS" / "1 of the TANKS"), or None —
    the noun adjacent to the count selector. Used to gate: the container must differ from the queried
    measure (a partition counts CONTAINERS, each holding some quantity of the asked measure)."""
    units = reading.units
    for k, u in enumerate(units):
        if "value" not in u.features.get("senses", []):
            continue
        prevk = _key(units[k - 1].surface) if k > 0 else ""
        nxt = next((x for x in units[k + 1:] if "noun" in x.features.get("senses", [])), None)
        if prevk in _PARTITION_SELECTORS and nxt is not None \
                and units.index(nxt) == k + 1:   # "first two TANKS" — noun immediately follows the count
            return _descriptor(nxt)[0]
        if k + 1 < len(units) and _key(units[k + 1].surface) == "of" and nxt is not None:
            return _descriptor(nxt)[0]           # "1 of the TANKS"
    return None


def _partition(premises: list, question: str):
    """Solve a PARTITION-and-AGGREGATE problem, or None if the shape doesn't apply. A container set is
    split into named subgroups ("the first two … the other two … 1 of the tanks"), each member holding a
    per-member quantity of the asked measure; the answer is Σ (subgroup_count × per_member), optionally ×
    a period asked in the question ("…in four weeks"). The per-member value — including a RELATIONAL one
    ("twice as many fish each as the first", "2 fewer gallons each than the first two") — is resolved by
    the ordinary `learn` machinery against the running per-member context; only the subgroup COUNT and the
    Σ-fold are new here. Tightly gated: ≥2 subgroups, a partition selector word present, and a container
    that differs from the queried measure (so a plain "3 of the apples … 4 of the apples" never fires)."""
    qr = analyze(question)
    interro = next((u for u in qr.units if "interrogative" in u.features.get("senses", [])), None)
    if interro is None:
        return None
    coll = _follow(_follow(interro, "queries"), "collection")
    target = _descriptor(coll) if coll is not None else None
    if target is None:
        return None
    portions, ctx, containers, saw_selector = [], [], set(), False
    for p in premises:
        rp = analyze(p)
        cnt = _subgroup_count(rp)
        if cnt is None:
            continue
        facts = learn(p, [], ctx)
        pm = next((f.amount for f in facts if isinstance(f, Quantity)
                   and f.measure == target and f.amount is not None), None)
        if pm is None:
            continue
        saw_selector = saw_selector or any(_key(u.surface) in _PARTITION_SELECTORS for u in rp.units)
        cont = _subgroup_container(rp)
        if cont is not None:
            containers.add(cont)
        portions.append((cnt, pm))
        ctx += facts
    if len(portions) < 2 or not saw_selector:
        return None
    if not containers or target[0] in containers:        # the partition must be over CONTAINERS, not the
        return None                                      # asked measure itself ("3 of the apples …")
    total = _compute(" + ".join(f"{_num(c)} * {_num(v)}" for c, v in portions))
    # PERIOD: "…how many gallons will she need in four weeks?" → × the question's time-unit count.
    period = next((u.features["value"] for u in qr.units if "value" in u.features.get("senses", [])
                   and _follow(u, "quantifies") is not None
                   and _descriptor(_follow(u, "quantifies"))[0] in TIME_UNITS), None)
    if period is not None:
        total = _compute(f"{_num(total)} * {_num(period)}")
    return total


def _queried_measure(question: str):
    """The measure a 'how many/much <measure>' question asks about, or None."""
    qr = analyze(question)
    interro = next((u for u in qr.units if "interrogative" in u.features.get("senses", [])), None)
    if interro is None:
        return None
    coll = _follow(_follow(interro, "queries"), "collection")
    return _descriptor(coll) if coll is not None else None

# --- decline-safety guards: DECLINE when an operative quantity/rate/multiplier is dropped ---

def _period_unapplied(question_reading: Reading, premise_readings: list, context: list) -> bool:
    """DECLINE-SAFETY: True when the question asks for a per-PERIOD total ("…how many in N weeks/days?")
    but the period value N never entered the computation (absent from ARITHMETIC_LOG) AND the premises
    describe a RECURRING action the period should have scaled — i.e. we committed a number without applying
    the demanded period scaling, so the structure is unhandled. Only TIME-unit-quantifying question values
    count as periods (enumeration counts "the 3 PEOPLE" quantify non-time nouns → ignored). The recurrence
    gate is essential: "Tom HAS 5 apples … in 7 days?" is a static holding the period correctly leaves at 5
    (no recurrence → don't decline); "buys 2 … EVERY school day … in 3 weeks?" recurs → the unapplied
    period means we dropped the scaling → decline. The prerequisite for safe vocabulary growth."""
    periods = {round(float(u.features["value"]), 6) for u in question_reading.units
               if "value" in u.features.get("senses", []) and u.features.get("value") is not None
               and _follow(u, "quantifies") is not None
               and _descriptor(_follow(u, "quantifies"))[0] in TIME_UNITS}
    if not periods:
        return False
    recurs = any(_key(u.surface) in ("every", "per", "each") or _key(u.surface) in DAYPARTS
                 for rp in premise_readings for u in rp.units) \
        or any(isinstance(f, (Rate, Frequency)) for f in context)
    if not recurs:
        return False
    computed = set()
    for prog, _res in ARITHMETIC_LOG:
        computed |= {round(float(m), 6) for m in re.findall(r"\d+\.?\d*", prog)}
    return any(p not in computed for p in periods)


def _dropped_unit_quantity(premise_readings: list, question_reading: Reading) -> bool:
    """DECLINE-SAFETY (GUARD 12): True when a stated number that quantifies a measurement UNIT (time /
    distance / weight / volume) or is a MONEY value never entered the computation (absent from
    ARITHMETIC_LOG) — an OPERATIVE quantity we dropped, so the structure is unhandled → decline. Object-noun
    counts ("3 snakes", "3 people") are NOT units and stay exempt (enumeration counts are often legitimately
    uncomputed). Generalizes the period guard to every unit/money quantity; the broad firewall-safe guard
    that lets future vocabulary growth turn unknown-word→{correct | decline}, never →wrong."""
    non_time_units = UNIT_NOUNS - TIME_UNITS   # TIME periods are handled by the recurrence-gated GUARD 11
    need = set()                               # (a static "…in 7 days?" must NOT decline); here: distance /
    for rd in list(premise_readings) + [question_reading]:   # weight / volume / money — always operative.
        for u in rd.units:
            if "value" not in u.features.get("senses", []) or u.features.get("value") is None:
                continue
            if u.features.get("measure") == MONEY:
                need.add(round(float(u.features["value"]), 6))
                continue
            qn = _follow(u, "quantifies")
            if qn is not None and _descriptor(qn)[0] in non_time_units:
                need.add(round(float(u.features["value"]), 6))
    if not need:
        return False
    computed = set()
    for prog, _res in ARITHMETIC_LOG:
        computed |= {round(float(m), 6) for m in re.findall(r"\d+\.?\d*", prog)}
    return any(n not in computed for n in need)


def _unapplied_multi_rate(premise_readings: list) -> bool:
    """DECLINE-SAFETY (GUARD 13): a MULTI-RATE purchase/charge we don't compose → decline. Fires when a
    premise pairs a per-item price ("$P each / per <noun>") with an item COUNT that never reached the
    computation ("three movie tickets for $12 each" → 3×12 dropped, only 12 added), OR when the premises
    carry ≥2 distinct per-item prices (a priced list — "$a each … $b per packet …" — we'd sum without the
    per-item quantities). An "each/per" price is what makes a nearby count OPERATIVE (vs a bare enumeration
    count "3 snakes", which has no price → never triggers). Catches the multi-rate residue GUARD 12 misses
    (those prices ARE summed, so no money value is 'dropped'; the error is the unapplied counts)."""
    computed = set()
    for prog, _res in ARITHMETIC_LOG:
        computed |= {round(float(m), 6) for m in re.findall(r"\d+\.?\d*", prog)}
    per_item_prices = 0
    for rd in premise_readings:
        money = [u for u in rd.units if u.features.get("measure") == MONEY]
        has_each = any(_key(u.surface) in ("each", "per") for u in rd.units)
        if not (money and has_each):
            continue
        per_item_prices += len(money)
        for u in rd.units:                               # (a) a count linked to the price, never applied
            if "value" in u.features.get("senses", []) and u.features.get("value") is not None \
                    and u.features.get("measure") != MONEY:
                qn = _follow(u, "quantifies")
                if qn is not None and _descriptor(qn)[0] not in UNIT_NOUNS \
                        and round(float(u.features["value"]), 6) not in computed:
                    return True
    return per_item_prices >= 2                           # (b) a multi-rate priced list


def _dropped_multiplier(premise_readings: list) -> bool:
    """DECLINE-SAFETY (GUARD 14): a stated relational MULTIPLIER ("7 times", "twice"=2, "one-third") whose
    EVIDENCE never reached the computation → a dropped relational-chain link → decline. Evidence = the
    integer factor itself ("7 times" → 7), or for a FRACTION the DENOMINATOR ("one-third" → 3; fractions are
    computed as num/denom, so the decimal never appears literally but the denom does). Catches multi-step
    chains that mis-resolve and commit a partial ("Emily = 7× Sandra, Sandra = 3× Betty" → 7×Betty drops the
    3×). The residue the unit/money/multi-rate guards miss (the dropped factor isn't a unit or a price)."""
    need = set()
    for rd in premise_readings:
        for u in rd.units:
            if "multiplier" not in u.features.get("senses", []):
                continue
            if "fraction" in u.features:
                need.add(round(float(u.features["fraction"][1]), 6))      # the denominator
            else:
                v = u.features.get("value")
                if v is not None and float(v) == int(float(v)) and float(v) >= 2:
                    need.add(round(float(v), 6))                          # an integer factor ≥ 2
    if not need:
        return False
    computed = set()
    for prog, _res in ARITHMETIC_LOG:
        computed |= {round(float(m), 6) for m in re.findall(r"\d+\.?\d*", prog)}
    return any(n not in computed for n in need)


def _dropped_each_attribute(premise_readings: list) -> bool:
    """DECLINE-SAFETY (GUARD 15): a per-EACH attribute multiplier we dropped → decline. The "each"/"every"
    quantifier turns a nearby object count into a MULTIPLIER ("7 starfish with 5 arms EACH" → 7×5; "EACH
    daisy has 8 petals" → ×8), so that count is OPERATIVE — unlike a bare enumeration count ("3 snakes")
    GUARD 12 deliberately exempts. Fires when a premise carries an each/every quantifier and a value
    quantifying a NON-TIME, NON-MONEY object noun that never reached the computation (absent from
    ARITHMETIC_LOG). TIME per-each ("every 30 minutes") is a rate/period (GUARDs 11) not an attribute, and a
    clock TIME-RANGE premise ("1 PM to 4 PM every night") consumes its clocks into a span — both excluded."""
    computed = set()
    for prog, _res in ARITHMETIC_LOG:
        computed |= {round(float(m), 6) for m in re.findall(r"\d+\.?\d*", prog)}
    for rd in premise_readings:
        units = rd.units
        if not any("quantifier" in u.features.get("senses", []) and _key(u.surface) in ("each", "every")
                   for u in units):
            continue
        if any(_key(u.surface) in ("am", "pm") for u in units):       # clock values consumed into a span
            continue
        for i, u in enumerate(units):
            if "value" not in u.features.get("senses", []) or u.features.get("value") is None:
                continue
            if u.features.get("measure") == MONEY:
                continue
            nxt = units[i + 1] if i + 1 < len(units) else None         # the object this count quantifies
            if nxt is not None and _descriptor(nxt)[0] in TIME_UNITS:   # "every 30 MINUTES" — a rate, not attr
                continue
            if round(float(u.features["value"]), 6) not in computed:
                return True
    return False


def _container_giveaway(premises: list, question: str, context: list):
    """EQUAL-SPLIT into containers, then GIVE some containers away → the contents lost. "28 marbles … into
    4 bags … the same number in each bag … gives one bag away … how many marbles left?" → per-bag = 28/4 =
    7, lose 1×7 = 7, answer 28−7 = 21. The contents and the containers are DIFFERENT measures; the give is
    counted in CONTAINERS but the question asks the CONTENTS, so the give converts via the per-container
    share. Tightly gated: an equal-split marker ("same … each"), a whole of the asked measure, a container
    count (a `put` of a different measure), and a `give` of that container measure. None otherwise."""
    if not any("same" in p.lower() and "each" in p.lower() for p in premises):
        return None
    target = _queried_measure(question)
    if target is None:
        return None
    whole = next((f for f in context if isinstance(f, Quantity) and f.measure == target
                  and f.verb in ("have", "put") and f.amount is not None), None)
    container = next((f for f in context if isinstance(f, Quantity) and f.measure != target
                      and f.verb == "put" and f.amount is not None), None)
    if whole is None or container is None or not container.amount:
        return None
    give = next((f for f in context if isinstance(f, Quantity) and f.measure == container.measure
                 and f.verb == "give" and f.amount is not None), None)
    if give is None:
        return None
    per = _compute(f"{_num(whole.amount)} / {_num(container.amount)}")    # contents per container
    return _compute(f"{_num(whole.amount)} - {_num(give.amount)} * {_num(per)}")


def _measure_mod(rp: Reading, head: str):
    """The content-word modifier immediately before the measure head noun ("PARKING tickets" → 'parking',
    "much money" → None — 'much' is a quantifier). Distinguishes compound measures the head-only descriptor
    collapses ('parking ticket' vs 'traffic ticket'), INCLUDING unknown-word qualifiers (no sense)."""
    func = {"quantifier", "article", "value", "preposition", "verb", "pronoun", "name",
            "multiplier", "comparative", "operator"}
    for i, u in enumerate(rp.units):
        if _descriptor(u)[0] == head and i > 0:
            prev = rp.units[i - 1]
            if _key(prev.surface).isalpha() and not (set(prev.features.get("senses") or []) & func):
                return _key(prev.surface)
    return None


def _noun_std_entity(rp: Reading, after_idx: int):
    """The COMMON-NOUN standard for a NO-NAMES ratio/offset clause (used by `_ratio_relation`/
    `_offset_ratio_relation`/`_pure_offset_relation`'s noun-entity fallback): the token IMMEDIATELY after an
    "as"/"than" marker — "twice as many pigs AS COWS" / "24 more blue marbles THAN RED MARBLES" — but ONLY if
    that immediate token IS itself a noun/adjective, tolerating an elided "the NUMBER/AMOUNT of" re-
    quantification wrapper right after the marker ("35 fewer children THAN THE NUMBER OF adults" → adults;
    same idiom `_ratio_relation`'s NAME path already reads via its "of"-frame check). Otherwise deliberately
    NOT a scan-ahead search: "twice as many books AS SHE finished last month" has "she" (a pronoun)
    immediately after "as" — a self-referential RELATIVE CLAUSE ("as many as SHE finished"), not a second
    coordinate-noun entity — scanning past the pronoun to grab "month" further along caused a real
    confident-wrong (a temporal reference misread as a second entity). None if there's no marker, or the
    (possibly wrapper-skipped) next token isn't a noun/adjective."""
    tail = rp.units[after_idx + 1:]
    marker = next((k for k, u in enumerate(tail) if _key(u.surface) in ("as", "than")), None)
    if marker is None or marker + 1 >= len(tail):
        return None
    i = marker + 1
    if _key(tail[i].surface) in ("the", "a", "an") and i + 2 < len(tail) \
            and _key(tail[i + 1].surface) in COUNT_NOUNS and _key(tail[i + 2].surface) == "of":
        i += 3                                              # skip the elided "the NUMBER/AMOUNT of" wrapper
    elif _key(tail[i].surface) in ("the", "a", "an"):
        i += 1                                              # skip a bare ARTICLE ("than THE potatoes") — an
        #                                                     article can never BE the standard, and the token
        #                                                     right after it is the same immediate head the
        #                                                     no-scan-ahead rule intends (unlike a pronoun,
        #                                                     which stays a hard stop)
    if i >= len(tail):
        return None
    nxt = tail[i]
    if "noun" in nxt.features.get("senses", []) or "adjective" in nxt.features.get("senses", []):
        return nxt
    return None


def _asked_noun_entity(qr: Reading):
    """The COMMON-NOUN entity a QUESTION asks about, for the coordinate-noun affine family: the noun "many"/
    "much" quantifies ("how MANY goats does he have?" → goats), or — when there's no such quantifier — the
    noun right after a bare "the (total) NUMBER/AMOUNT OF X" phrase ("What is the total number of guests
    served?" → guests, a common GSM8K imperative-question wording with no "how many" at all). None if
    neither pattern is found."""
    many = next((u for u in qr.units if _key(u.surface) in ("many", "much")
                 and "quantifier" in u.features.get("senses", [])), None)
    if many is not None:
        coll = _follow(many, "collection")
        return _noun_entity_key(coll) if coll is not None else None
    for i, u in enumerate(qr.units):
        if _key(u.surface) in COUNT_NOUNS and i + 1 < len(qr.units) and _key(qr.units[i + 1].surface) == "of":
            nxt = qr.units[i + 2] if i + 2 < len(qr.units) else None
            if nxt is not None and "noun" in nxt.features.get("senses", []):
                return _noun_entity_key(nxt)
    return None

# --- ARITHMETIC SYSTEM-SOLVERS: relation extraction, then the solver families (see registry) ---

def _ratio_relation(rp: Reading):
    """A single pure-RATIO relation in a clause → (subject, factor, standard), where subject = factor ×
    standard. A clause with EXACTLY two names unifies every surface form: the subject is the name BEFORE the
    verb, the standard is the OTHER name, the factor is the clause's multiplier or fraction. Covers "A has k×
    as many/much <M> as B", "A is k× as old as B", "A is 1/3 the age of B", "A is twice B's age", "A is half
    of B's age". Also covers a COMMON-NOUN pair with NO names at all ("twice as many PIGS as COWS", "twice as
    many RED BALLS as BLUE") via `_noun_entity_key`/`_noun_std_entity` — the coordinate-noun/subtype-partition
    affine family reuses this same extractor. None if there's no factor, not exactly two names (and not a
    no-names noun-pair either), a comparative/offset (pure-ratio only — "N more/less than" is a different,
    firewall-risky shape), the ratio is over a RATE ADJECTIVE ("twice as FAST/quick as") — speed doesn't scale
    like a plain value (twice as fast = HALF the time, not double), so folding it as a direct ratio on
    whatever value the standard states elsewhere is a silent inversion bug; that shape belongs to the
    dedicated rate-cluster machinery, not this generic value-ratio extractor — or the clause is governed by
    "needs"/"need" ("Amanda NEEDS to have twice as many as Katrina" states a TARGET Amanda doesn't hold yet,
    not Amanda's current value — misreading it as a plain ratio is a silent deficit/current-state conflation
    this extractor doesn't model)."""
    if any("comparative" in u.features.get("senses", []) for u in rp.units) \
            or any(_key(u.surface) in ("more", "less", "older", "younger", "fewer", "fast", "quick", "quickly",
                                        "need", "needs")
                   for u in rp.units):
        return None
    mult = next((u for u in rp.units if "multiplier" in u.features.get("senses", [])), None)
    if mult is not None:
        k = (mult.features["fraction"][0] / mult.features["fraction"][1]) if "fraction" in mult.features \
            else mult.features.get("value")
    else:
        frac = next((u for u in rp.units if _fraction_parts(u.surface) is not None), None)
        if frac is None:
            return None
        num, den = _fraction_parts(frac.surface); k = num / den
    if k is None:
        return None
    names = [u for u in rp.units if "name" in u.features.get("senses", [])]
    verbs = [u for u in rp.units if "verb" in u.features.get("senses", [])]
    if len(names) != 2:
        # NOT-TWO-NAMES fallback: a coordinate/subtype COMMON-NOUN ratio, with 0 names (bare "twice as many
        # pigs as cows") or 1 (an outer possessor, "Brett has 24 more BLUE MARBLES than RED MARBLES" — Brett
        # owns both, isn't one of the two ratio entities). The noun "many"/"much" quantifies is the subject
        # ("twice AS MANY pigs as cows" → pigs), the standard is whatever noun/adjective follows the
        # clause's "as"/"than" marker after it.
        many = next((u for u in rp.units if _key(u.surface) in ("many", "much")
                     and "quantifier" in u.features.get("senses", [])), None)
        subj_u = _follow(many, "collection") if many is not None else None
        if subj_u is None:
            return None
        std_u = _noun_std_entity(rp, rp.units.index(subj_u))
        if std_u is None:
            return None
        subj_key, std_key = _noun_entity_key(subj_u), _noun_entity_key(std_u)
        if subj_key == std_key:
            return None
        return subj_key, k, std_key
    if len(names) != 2 or not verbs:
        return None
    vpos = rp.units.index(verbs[0])
    subj = next((u for u in names if rp.units.index(u) < vpos), None)   # the subject precedes the verb;
    if subj is None:                                                   # the standard is the other name
        return None
    std = next(u for u in names if u is not subj)
    # the standard must sit in a genuine RATIO FRAME — after "as" ("as old as B"), after "of" ("the age of
    # B"), as a possessor ("B's age"), or an IMPLICIT relative clause with the "that"/"which" elided ("as
    # much money DARWIN HAS" = "...as Darwin has"; the standard is immediately followed by a POSSESSION verb
    # — deliberately narrow, not ANY verb, so a mistagged common noun standard ("the CDs SOLD at $10") isn't
    # misread as a name-ratio via an unrelated passive modifier). Else the factor isn't relating the two
    # names (e.g. "bought half the CDs" — a count of an object, not a ratio between people) → reject.
    si = rp.units.index(std)
    prev = _key(rp.units[si - 1].surface) if si > 0 else ""
    nxt = rp.units[si + 1] if si + 1 < len(rp.units) else None
    if prev not in ("as", "of", "that") \
            and not (nxt is not None and ("possessive" in nxt.features.get("senses", [])
                                           or _key(nxt.surface) in POSSESSION_VERBS)):
        return None                                                   # "that B Ved" is a relative-clause
        #                                                               standard ("1/4 of the apples that
        #                                                               Kylie picked"); "the CDs" is not
    return _entity(subj), k, _entity(std)


def _offset_ratio_relation(rp: Reading):
    """An OFFSET-RATIO relation → (subject, factor, standard, offset_signed) where subject = factor × standard
    + offset. The affine twin of `_ratio_relation` for "X has N more/less than k times [as many M as] Y"
    ("Justin has 8 more than twice as many pencils as Sabrina" → J = 2·S + 8; "Devin has 5 less than half the
    years Tom has" → D = ½·T − 5). POSITIONAL parse: the OFFSET value precedes the comparative ("8 more"), the
    FACTOR is a multiplier AFTER "than" ("twice"). Requires an explicit multiplier — a bare "N more than Y"
    (no factor) is the firewall-risky offset shape we keep declining, not this one. Exactly two names, the
    standard in a genuine ratio frame (after as/of/that), like `_ratio_relation`. None if the clause is
    governed by "needs"/"need" — "Amanda NEEDS 12 more to have twice as many as Katrina" states a DEFICIT to
    reach a target (Amanda + 12 = 2·Katrina), the OPPOSITE equation from "Amanda HAS 12 more than twice as
    many as Katrina" (Amanda = 2·Katrina + 12) this extractor assumes; silently applying the wrong equation
    is a confident-wrong risk, not a parsing nuance to special-case here. Covers ANY comparative adjective via
    the shared `COMPARATIVE_SIGN` table, not just "more"/"less"/"fewer" — "600 square feet LARGER than 4
    times Benedict's house" — EXCLUDING "older"/"younger" (the age domain's own temporal-shift machinery
    owns those, same reasoning as `_pure_offset_relation`)."""
    if any(_key(u.surface) in ("need", "needs") for u in rp.units):
        return None
    comp = next((u for u in rp.units if "comparative" in u.features.get("senses", [])
                 and _key(u.surface) not in ("older", "younger")), None)
    if comp is None:
        return None
    ci = rp.units.index(comp)
    sign = float(COMPARATIVE_SIGN.get(_key(comp.surface), 1))
    off = next((u for u in reversed(rp.units[:ci])                     # offset = the value RIGHT before the
               if "value" in u.features.get("senses", []) and u.features.get("value") is not None), None)
    if off is None:                                                   # comparative ("8 more than …")
        return None
    mult = next((u for u in rp.units[ci + 1:] if "multiplier" in u.features.get("senses", [])), None)
    if mult is None:                                                  # require an explicit factor after "than"
        return None
    k = (mult.features["fraction"][0] / mult.features["fraction"][1]) if "fraction" in mult.features \
        else mult.features.get("value")
    if k is None:
        return None
    names = [u for u in rp.units if "name" in u.features.get("senses", [])]
    verbs = [u for u in rp.units if "verb" in u.features.get("senses", [])]
    if len(names) != 2:
        # NOT-TWO-NAMES fallback: a coordinate/subtype COMMON-NOUN offset-ratio ("three fewer than twice as
        # many cows as pigs") — same "many"-collection subject as `_ratio_relation`'s fallback.
        many = next((u for u in rp.units if _key(u.surface) in ("many", "much")
                     and "quantifier" in u.features.get("senses", [])), None)
        subj_u = _follow(many, "collection") if many is not None else None
        if subj_u is None:
            return None
        std_u = _noun_std_entity(rp, rp.units.index(subj_u))
        if std_u is None:
            return None
        subj_key, std_key = _noun_entity_key(subj_u), _noun_entity_key(std_u)
        if subj_key == std_key:
            return None
        return subj_key, k, std_key, sign * off.features["value"]
    if len(names) != 2 or not verbs:
        return None
    vpos = rp.units.index(verbs[0])
    subj = next((u for u in names if rp.units.index(u) < vpos), None)
    if subj is None:
        return None
    std = next(u for u in names if u is not subj)
    si = rp.units.index(std)                                          # the standard must sit in a ratio frame
    prev = _key(rp.units[si - 1].surface) if si > 0 else ""           # (after as/of/that, or an implicit
    nxt = rp.units[si + 1] if si + 1 < len(rp.units) else None        # relative "Y HAS"), like _ratio_relation
    if prev not in ("as", "of", "that") \
            and not (nxt is not None and ("possessive" in nxt.features.get("senses", [])
                                           or _key(nxt.surface) in POSSESSION_VERBS)):
        return None
    return _entity(subj), k, _entity(std), sign * off.features["value"]


# --- system-solver shared gates --------------------------------------------------------------
# Every arithmetic system-solver (registered in `_EARLY_SYSTEMS`/`_LATE_SYSTEMS`) recognizes ONE
# tightly-gated problem shape and declines everything else. Three mechanical gates recur across
# all of them — extracted here (the same drift signal, near-identical inlined boilerplate, that
# the 27-inline-solver registry refactor fixed):
#   * `_has_digit` — the "is this premise/question VALUED" probe: a system must classify every
#     valued premise it sees; an unclassified one means "not this shape" → decline;
#   * `_has_comparative` — "how many MORE X than Y" is always another shape;
#   * `_gated_pos_int` / `_gated_pos` / `_gated_nonneg` — the commit gate on the audited result.


def _has_digit(text: str) -> bool:
    """Any digit character — the systems' probe for a VALUED premise or question."""
    return any(ch.isdigit() for ch in text)


def _has_comparative(ql: str) -> bool:
    """A comparative cue in the lowered question — comparatives are always another shape."""
    return any(w in ql for w in ("more", "fewer", "less", "than"))


def _gated_pos_int(result):
    """The standard commit gate: the audited result ships only as a POSITIVE INTEGER (these
    shapes count things); an error string from _compute, zero, a negative or a fraction
    declines instead of committing."""
    ok = isinstance(result, (int, float)) and result > 0 and float(result).is_integer()
    return result if ok else None


def _gated_pos(result):
    """The commit gate for shapes whose result may be fractional (money, hours) — positive only."""
    ok = isinstance(result, (int, float)) and result > 0
    return result if ok else None


def _gated_nonneg(result):
    """The commit gate for remainder shapes — zero is a legitimate answer ("none left")."""
    ok = isinstance(result, (int, float)) and result >= 0
    return result if ok else None


def _sum_ratio_system(premises: list, question: str):
    """An N-UNKNOWN SUM+RATIO-CHAIN system: several entities, each a multiple of another (relations may
    CHAIN), and a COMBINED TOTAL → solve for the asked one by PIVOT REDUCTION. "Amy, Jeremy, Chris combined
    age 132; Amy = ⅓·Jeremy; Chris = 2·Amy" → reduce all to the root Jeremy (coeffs 1+⅓+⅔ = 2) → Jeremy =
    132/2 = 66. Generalizes (and subsumes) the 2-entity case (Jean = 3·Jane, +$76 → Jane 19). The forward
    fold can't invert this (nothing is grounded). PURE-RATIO only. TIGHTLY gated — these shapes also appear
    in CORRECT forward problems: a unique ROOT (one entity never a relation subject), a CONNECTED tree (every
    entity reduces to the root, no cycle / multi-definition), and the asked measure must MATCH the total's
    measure incl. qualifier (rejects "combined YEARS … how many MONTHS", and "parking" vs "traffic" tickets).
    None if the shape doesn't apply."""
    qr = analyze(question)
    qnames = [u for u in qr.units if "name" in u.features.get("senses", [])]
    if not qnames:
        return None
    asked = _entity(qnames[0])
    asked_measure = _queried_measure(question)
    if asked_measure is not None and "verb" in analyze(asked_measure[0]).units[0].features.get("senses", []):
        asked_measure = RESULT_MEASURE.get(asked_measure[0])           # "how much did X EARN" → money
    # OFFSET-TAINTED SYSTEM: a premise with both a factor and a comparative offset ("CJ has 5 MORE than
    # TWICE …") is a relation we can't fold into the pure linear system — _ratio_relation drops it, leaving
    # an INCOMPLETE system that would still "solve" off the remaining relations. Decline the whole system.
    for p in premises:
        rp = analyze(p)
        has_factor = any("multiplier" in u.features.get("senses", []) for u in rp.units) \
            or any(_fraction_parts(u.surface) is not None for u in rp.units)
        if has_factor and any(_key(u.surface) in ("more", "less", "older", "younger", "fewer")
                              for u in rp.units):
            return None
        # A STANDALONE OFFSET relation ("Anna has 2 fewer toys than Amanda") alongside the ratios is the same
        # incompleteness in a separate clause: _ratio_relation drops it (comparative), so the pure-ratio system
        # would silently ignore Amanda and mis-solve off the remaining ratio (Anna=3·Mandy → 142/4 = 35.5).
        # This is an AFFINE system — defer to `_affine_system`. (A pure-ratio system has no offset relations.)
        if _pure_offset_relation(rp) is not None:
            return None
    rels = {}                                                          # subject → (factor, standard)
    rel_mod = rel_desc = None
    for p in premises:
        rp = analyze(p)
        if _name_count(rp) != 2:
            continue                       # not a genuine 2-name relation — may be `_ratio_relation`'s
        rr = _ratio_relation(rp)           # coordinate-noun fallback firing, a DIFFERENT family's turf
        if rr is None:
            continue
        subj_e, k, std_e = rr
        if subj_e in rels:                                             # a subject defined twice → reject
            return None
        rels[subj_e] = (k, std_e)
        # carry over #3h's qualifier checks:
        if asked_measure is not None and any(_descriptor(u)[0] == asked_measure[0] for u in rp.units):
            rel_mod = _measure_mod(rp, asked_measure[0])               # a separate pre-modifier ('parking'),
            rel_desc = next((_descriptor(u) for u in rp.units          # AND the full descriptor incl. a
                             if _descriptor(u)[0] == asked_measure[0]), None)   # CONDENSED adj ('red')
    if not rels:
        return None
    knowns = {}                                                        # entities with a stated ABSOLUTE value
    for p in premises:                                                 # ("Delta took 8 donuts" → delta=8) —
        rp = analyze(p)                                                # a part of the total that isn't a ratio
        if any("multiplier" in u.features.get("senses", []) for u in rp.units) \
                or any(_fraction_parts(u.surface) is not None for u in rp.units) \
                or any(_key(u.surface) in ("more", "less", "fewer") for u in rp.units):
            continue
        nm = [u for u in rp.units if "name" in u.features.get("senses", []) and " and " not in _entity(u)]
        kv = next((u for u in rp.units if "value" in u.features.get("senses", [])           # value of the
                   and u.features.get("value") is not None and _follow(u, "quantifies") is not None  # asked
                   and asked_measure is not None and _descriptor(_follow(u, "quantifies")) == asked_measure
                   ), None) if asked_measure is not None else None
        if len(nm) == 1 and kv is not None and _entity(nm[0]) not in rels:
            knowns[_entity(nm[0])] = kv.features["value"]
    total = _combined_total(premises, asked_measure, rel_mod, rel_desc)
    if total is None:
        return None
    entities = set(rels) | {std for _k, std in rels.values()} | set(knowns) | {asked}
    free = [e for e in entities if e not in rels and e not in knowns]   # the pivot: the one entity that is
    if len(free) != 1:                                                 # neither a ratio-subject nor known
        return None
    coeff = {free[0]: 1.0}                                             # propagate coeff = factor × coeff[std]
    for _ in range(len(entities) + 1):                                # to a fixpoint along the relation tree
        for e, (k, std) in rels.items():
            if std in coeff and e not in coeff:
                coeff[e] = k * coeff[std]
    # every entity must be reducible to the pivot OR a known (else disconnected / cyclic) → reject
    if any(e not in coeff and e not in knowns for e in entities):
        return None
    denom = sum(coeff.values())
    if denom == 0:
        return None
    if asked in knowns:                                               # the asked part is itself stated
        return knowns[asked]
    # pivot = (Total − Σ knowns) / Σ coeff ; answer = coeff[asked] × pivot ("Delta 8 + Beta 3·Gamma + Gamma
    # = 40" → Gamma = (40−8)/4 = 8). With no knowns this is exactly #3r's Total / Σ coeff.
    pivot = _compute(f"({_num(total)} - ({_num(sum(knowns.values()))})) / {_num(denom)}") if knowns \
        else _compute(f"{_num(total)} / {_num(denom)}")
    return pivot if coeff[asked] == 1 else _compute(f"{_num(coeff[asked])} * {_num(pivot)}")


def _combined_total(premises: list, asked_measure, rel_mod, rel_desc):
    """The stated COMBINED TOTAL over the system's entities (the #3h total-finder, shared by the pure-ratio
    `_sum_ratio_system` and the offset `_offset_sum_system`). Same gates: a combined/total/together cue, no
    comparative in the clause, and a measure/qualifier match to the asked measure. None if no such total."""
    for p in premises:
        if not any(w in p.lower() for w in ("combined", "total", "together", "between them", "in all",
                                            "share", "shared", "altogether")):
            continue
        rp = analyze(p)
        if any("comparative" in u.features.get("senses", []) for u in rp.units):
            continue
        tot_nouns = [_descriptor(u)[0] for u in rp.units if u.features.get("senses") == ["noun"]]
        # UNIT/MEASURE GATE: the asked measure must match the total's measure (else "combined YEARS … how
        # many MONTHS" would commit a wrong-unit number); money totals often have no measure noun ("$76").
        if asked_measure is not None and tot_nouns and asked_measure[0] not in tot_nouns \
                and "money" not in str(asked_measure):
            continue
        if asked_measure is not None and rel_mod is not None and _measure_mod(rp, asked_measure[0]) != rel_mod:
            continue                                                   # "traffic" total ≠ "parking" relation
        tot_desc = next((_descriptor(u) for u in rp.units
                         if asked_measure is not None and _descriptor(u)[0] == asked_measure[0]), None)
        if rel_desc is not None and tot_desc is not None and rel_desc != tot_desc:
            continue                                                   # condensed-qualifier 'red' ≠ 'blue'
        vals = [u for u in rp.units if "value" in u.features.get("senses", [])
                and u.features.get("value") is not None]
        # Prefer the value that quantifies the ASKED MEASURE — a total clause often leads with a PEOPLE-COUNT
        # ("Together 3 friends collected 411 shells" → the total is 411 shells, not 3 friends; "the three boys
        # have 930 stamps" → 930, not 3). Fall back to the first value (a measure-less money total "$76").
        tv = None
        if asked_measure is not None:
            tv = next((u for u in vals if _follow(u, "quantifies") is not None
                       and _descriptor(_follow(u, "quantifies"))[0] == asked_measure[0]), None)
        if tv is None and vals:
            tv = vals[0]
        if tv is not None:
            return tv.features["value"]
    return None


def _pure_offset_relation(rp: "Reading"):
    """A PURE additive comparative "X has N more/fewer <M> than Y" (NO factor) → (subject, standard, signed_N).
    Covers ANY comparative surface, not just "more"/"less"/"fewer" — the adjectival forms "X is N pounds
    HEAVIER/lighter than Y", "N inches TALLER/shorter" etc. via the shared `COMPARATIVE_SIGN` table (the same
    sign lookup the age/holdings domains already use). EXCLUDES "older"/"younger" — the dedicated age-domain
    machinery (`_comparative_age` and friends) owns those, with its own temporal-shift handling this generic
    extractor doesn't do; letting it also claim age comparatives caused real regressions (a plain "younger
    than" premise no longer reached the age solver). The no-multiplier twin of `_offset_ratio_relation`; safe
    only inside a sum-system (the total pins the pair, so the bare offset — normally too under-determined to
    fold — becomes solvable). Exactly two names, standard after "than"/"as". None if the clause is governed
    by "needs"/"need" — "Loris needs 3 more to have the same as Lamont" states a DEFICIT (Loris + 3 = Lamont),
    the OPPOSITE equation from "Loris has 3 more than Lamont" (Loris = Lamont + 3) this extractor assumes."""
    if any(_key(u.surface) in ("need", "needs") for u in rp.units):
        return None
    comp = next((u for u in rp.units if "comparative" in u.features.get("senses", [])
                 and _key(u.surface) not in ("older", "younger")), None)
    if comp is None:
        return None
    if any("multiplier" in u.features.get("senses", []) for u in rp.units) \
            or any(_fraction_parts(u.surface) is not None for u in rp.units):
        return None                                                    # a factor present → not the pure shape
    ci = rp.units.index(comp)
    sign = float(COMPARATIVE_SIGN.get(_key(comp.surface), 1))
    off = next((u for u in reversed(rp.units[:ci]) if "value" in u.features.get("senses", [])
                and u.features.get("value") is not None), None)
    if off is None:
        return None
    names = [u for u in rp.units if "name" in u.features.get("senses", [])]
    verbs = [u for u in rp.units if "verb" in u.features.get("senses", [])]
    if len(names) != 2:
        # NOT-TWO-NAMES fallback: a coordinate/subtype COMMON-NOUN pure offset ("Brett has 24 more BLUE
        # MARBLES than RED MARBLES" — Brett is an outer possessor, not one of the two ratio entities) — no
        # "many"/multiplier here, so the subject is the noun right after the comparative.
        subj_u = next((u for u in rp.units[ci + 1:]
                       if "noun" in u.features.get("senses", []) or "adjective" in u.features.get("senses", [])),
                      None)
        if subj_u is None:
            return None
        std_u = _noun_std_entity(rp, rp.units.index(subj_u))
        if std_u is None:
            return None
        subj_key, std_key = _noun_entity_key(subj_u), _noun_entity_key(std_u)
        if subj_key == std_key:
            return None
        return subj_key, std_key, sign * off.features["value"]
    if len(names) != 2 or not verbs:
        return None
    vpos = rp.units.index(verbs[0])
    subj = next((u for u in names if rp.units.index(u) < vpos), None)
    if subj is None:
        return None
    std = next(u for u in names if u is not subj)
    si = rp.units.index(std)
    prev = _key(rp.units[si - 1].surface) if si > 0 else ""
    if prev not in ("than", "as"):
        return None
    return _entity(subj), _entity(std), sign * off.features["value"]


def _offset_sum_pure(premises: list, question: str):
    """A 2-ENTITY PURE additive offset + combined total → solve. "Anais has 30 more toys than Kamari; there
    are 160 toys altogether → Kamari = (160 − 30)/2 = 65." The NO-FACTOR twin of `_offset_sum_system` (which
    requires a multiplier). subj = std + c and subj + std = T ⇒ std = (T − c)/2, subj = T − std. TIGHTLY gated:
    EXACTLY one pure-offset relation, NO factor/ratio anywhere (else it's the factored or ratio shape), exactly
    the two related entities, the asked one among them, and a measure-matched combined total. None otherwise."""
    qr = analyze(question)
    qnames = [u for u in qr.units if "name" in u.features.get("senses", [])]
    if not qnames:
        return None
    asked = _entity(qnames[0])
    asked_measure = _queried_measure(question)
    if asked_measure is not None and "verb" in analyze(asked_measure[0]).units[0].features.get("senses", []):
        asked_measure = RESULT_MEASURE.get(asked_measure[0])
    offs, rel_mod, rel_desc = [], None, None
    for p in premises:
        rp = analyze(p)
        if _name_count(rp) != 2:
            continue                       # not a genuine 2-name relation — may be `_pure_offset_relation`'s
        rr = _pure_offset_relation(rp)      # coordinate-noun fallback firing, a DIFFERENT family's turf
        if rr is None:
            continue
        offs.append(rr)
        if asked_measure is not None and any(_descriptor(u)[0] == asked_measure[0] for u in rp.units):
            rel_mod = _measure_mod(rp, asked_measure[0])
            rel_desc = next((_descriptor(u) for u in rp.units if _descriptor(u)[0] == asked_measure[0]), None)
    if len(offs) != 1:
        return None
    alltext = " ".join(premises + [question]).lower()          # dollars and cents both normalise to the
    if ("$" in alltext or "dollar" in alltext) and "cent" in alltext:   # 'money' measure, hiding the 100×
        return None                                            # scale gap — mixing them needs a conversion we
        #                                                        don't do ("$3 total, 50 cents more" → decline)
    measures = set()
    for p in premises:                                                 # NO factor/ratio anywhere → pure only
        rp = analyze(p)
        if any("multiplier" in u.features.get("senses", []) for u in rp.units) \
                or any(_fraction_parts(u.surface) is not None for u in rp.units) \
                or any(_key(u.surface) in ("times", "twice", "double", "triple", "half") for u in rp.units):
            return None                                                # "5 TIMES more" is multiplicative, not ±
        for u in rp.units:                                             # collect every value's unit — a MIXED-
            if "value" in u.features.get("senses", []) and u.features.get("value") is not None:
                qn = _follow(u, "quantifies")                          # unit system ("$3" total vs "50 cents"
                m = _descriptor(qn) if qn is not None else u.features.get("measure")   # offset) needs a
                if m is not None:                                      # conversion we don't do → decline
                    measures.add(m[0])
    if len(measures) > 1:
        return None
    subj_e, std_e, c = offs[0]
    if subj_e == std_e or asked not in (subj_e, std_e):
        return None
    total = _combined_total(premises, asked_measure, rel_mod, rel_desc)
    if total is None:
        return None
    std_v = _compute(f"({_num(total)} - ({_num(c)})) / 2")
    subj_v = _compute(f"{_num(total)} - ({_num(std_v)})")
    return subj_v if asked == subj_e else std_v


def _offset_sum_system(premises: list, question: str):
    """A 2-UNKNOWN OFFSET SUM-system: two entities, one AFFINE relation (subject = factor × standard + offset),
    and a COMBINED TOTAL → solve. "Justin + Sabrina have 50 pencils; Justin has 8 more than twice as many as
    Sabrina" → S = (50 − 8)/(2+1) = 14. The affine extension of `_sum_ratio_system`, which DECLINES any
    offset-tainted system (it can only fold pure ratios); kept SEPARATE to isolate the firewall-riskier offset
    shape from the mature pure-ratio path. TIGHTLY gated: EXACTLY ONE offset relation, NO pure-ratio relation
    alongside it (a mixed/3-way system is out of scope → let it decline), exactly the two related entities, the
    asked entity among them, and the #3h measure/qualifier match on the total. None if the shape doesn't apply."""
    qr = analyze(question)
    qnames = [u for u in qr.units if "name" in u.features.get("senses", [])]
    if not qnames:
        return None
    asked = _entity(qnames[0])
    asked_measure = _queried_measure(question)
    if asked_measure is not None and "verb" in analyze(asked_measure[0]).units[0].features.get("senses", []):
        asked_measure = RESULT_MEASURE.get(asked_measure[0])           # "how many did X PICK" → its measure
    offs, rel_mod, rel_desc = [], None, None
    for p in premises:
        rp = analyze(p)                                                # carry over #3h's qualifier checks
        if _name_count(rp) != 2:
            continue                       # not a genuine 2-name relation — may be `_offset_ratio_relation`'s
        rr = _offset_ratio_relation(rp)     # coordinate-noun fallback firing, a DIFFERENT family's turf
        if rr is None:
            continue
        offs.append(rr)
        if asked_measure is not None and any(_descriptor(u)[0] == asked_measure[0] for u in rp.units):
            rel_mod = _measure_mod(rp, asked_measure[0])
            rel_desc = next((_descriptor(u) for u in rp.units if _descriptor(u)[0] == asked_measure[0]), None)
    if len(offs) != 1:                                                 # exactly one offset relation
        return None
    if any(_ratio_relation(analyze(p)) is not None for p in premises):  # a mixed system (offset + pure ratio)
        return None                                                    # is out of scope — decline it here
    subj_e, k, std_e, c = offs[0]
    if subj_e == std_e or asked not in (subj_e, std_e):
        return None
    total = _combined_total(premises, asked_measure, rel_mod, rel_desc)
    if total is None or k == -1:
        return None
    # subj = k·std + c and subj + std = T  ⇒  std = (T − c)/(k+1),  subj = T − std.
    std_v = _compute(f"({_num(total)} - ({_num(c)})) / {_num(k + 1)}")
    subj_v = _compute(f"{_num(total)} - ({_num(std_v)})")
    return subj_v if asked == subj_e else std_v


def _affine_relation(rp: "Reading"):
    """Any single AFFINE relation in a clause → (subject, factor, standard, offset) with subject = factor ×
    standard + offset, unifying the three relation extractors: `_offset_ratio_relation` ("8 more than twice
    Y" → k=2, c=8), `_ratio_relation` ("k× as many as Y" → c=0), `_pure_offset_relation` ("N more than Y" →
    k=1). None if the clause holds no two-name relation."""
    orr = _offset_ratio_relation(rp)
    if orr is not None:
        subj, k, std, c = orr
        return subj, k, std, c
    rr = _ratio_relation(rp)
    if rr is not None:
        subj, k, std = rr
        return subj, k, std, 0.0
    por = _pure_offset_relation(rp)
    if por is not None:
        subj, std, c = por
        return subj, 1.0, std, c
    return None


def _affine_system(premises: list, question: str):
    """An N-UNKNOWN MIXED AFFINE system — the generalization that subsumes both `_sum_ratio_system` (pure
    ratios) and `_offset_sum_system` (one 2-entity affine relation). Each entity is an AFFINE function of a
    single free PIVOT (value = A·pivot + B); relations may be ratio (X = k·Y), offset (X = Y ± c) OR combined
    (X = k·Y ± c), and MIX freely across ≥2 entities, pinned by a COMBINED TOTAL. "Anna = 3·Mandy and 2 fewer
    than Amanda; 142 toys total → Mandy 20": reduce to the pivot Mandy (A: 1,3,3; B: 0,0,2), pivot = (142−ΣB)/
    ΣA = 140/7 = 20. Runs ONLY after the two mature solvers decline (a pure-ratio or single-affine shape is
    theirs), so it can only ADD coverage. A double-defined subject (Anna is subject of both its relations) is
    handled by INVERTING the second into a relation for the other entity (Amanda = Anna + 2). TIGHTLY gated:
    a combined total, ≥2 relations (a genuine system), a UNIQUE free pivot (one entity that is no relation's
    subject), every entity reducible to it (connected, acyclic), and the asked entity among them. None
    otherwise."""
    qr = analyze(question)
    qnames = [u for u in qr.units if "name" in u.features.get("senses", [])]
    if not qnames:
        return None
    asked = _entity(qnames[0])
    asked_measure = _queried_measure(question)
    if asked_measure is not None and "verb" in analyze(asked_measure[0]).units[0].features.get("senses", []):
        asked_measure = RESULT_MEASURE.get(asked_measure[0])
    # GATE A — a SUM question ("how many altogether/in all/total") asks for Σ, not a single entity; this solver
    # returns ONE entity's value, so decline (Mona/Jasmine/Rachel — the asked "entity" is just the first name).
    if any(w in question.lower() for w in ("altogether", "in all", " total", "combined", "in total")):
        return None
    # GATE C — the ambiguous "N times more/less than Y" idiom (gold reads it as ×N, but with no "as many as"
    # frame `_affine_relation` mis-reads it as a +N offset — Ali/Nada/John): decline the whole system.
    for p in premises:
        if re.search(r"\btimes (more|less|fewer)\b", p.lower()):
            return None
    rels = {}                                                          # subject → (k, std, c): subj = k·std + c
    rel_mod = rel_desc = None
    for p in premises:
        rp = analyze(p)
        if _name_count(rp) != 2:
            continue                       # not a genuine 2-name relation — may be `_affine_relation`'s
        rel = _affine_relation(rp)         # coordinate-noun fallback firing, a DIFFERENT family's turf
        if rel is None:
            continue
        subj_e, k, std_e, c = rel
        if k == 0 or subj_e == std_e:
            return None
        if subj_e in rels:                                            # subject already defined → INVERT the
            if std_e in rels:                                         # relation to define the OTHER entity;
                return None                                           # both defined → over-constrained → bail
            rels[std_e] = (1.0 / k, subj_e, -c / k)                   # std = (subj − c)/k
        else:
            rels[subj_e] = (k, std_e, c)
        if asked_measure is not None and any(_descriptor(u)[0] == asked_measure[0] for u in rp.units):
            rel_mod = _measure_mod(rp, asked_measure[0])
            rel_desc = next((_descriptor(u) for u in rp.units
                             if _descriptor(u)[0] == asked_measure[0]), None)
    if len(rels) < 2:                                                 # a genuine SYSTEM (the 2-entity single
        return None                                                  # relation is `_offset_sum_system`'s)
    total = _combined_total(premises, asked_measure, rel_mod, rel_desc)
    if total is None:
        return None
    # GATE B — the total must be the MAXIMUM stated premise value. In a sum-system the combined total is ≥ every
    # part and every offset, so a LARGER unconsumed value means `_combined_total` grabbed the wrong number — it
    # matches a total-cue clause's FIRST value, which is often a PEOPLE-COUNT ("Together 3 friends watched 411
    # videos" → 3, not 411; "the three boys have 930 stamps" → 3, not 930). Reject rather than mis-solve.
    stated = [u.features["value"] for p in premises for u in analyze(p).units
              if "value" in u.features.get("senses", []) and u.features.get("value") is not None]
    if stated and total < max(stated):
        return None
    entities = set(rels) | {std for _k, std, _c in rels.values()} | {asked}
    free = [e for e in entities if e not in rels]                    # the pivot: the one entity that is no
    if len(free) != 1:                                               # relation's subject
        return None
    coeff = {free[0]: (1.0, 0.0)}                                    # value[e] = A·pivot + B; propagate
    for _ in range(len(entities) + 1):                              # affinely along the relation tree
        for e, (k, std, c) in rels.items():
            if std in coeff and e not in coeff:
                a_std, b_std = coeff[std]
                coeff[e] = (k * a_std, k * b_std + c)
    if any(e not in coeff for e in entities):                        # disconnected / cyclic → reject
        return None
    sum_a = sum(a for a, _b in coeff.values())
    sum_b = sum(b for _a, b in coeff.values())
    if sum_a == 0:
        return None
    # T = Σ(A)·pivot + Σ(B)  ⇒  pivot = (T − ΣB)/ΣA;  answer = A[asked]·pivot + B[asked].
    pivot = _compute(f"({_num(total)} - ({_num(sum_b)})) / {_num(sum_a)}")
    a_ask, b_ask = coeff[asked]
    return _compute(f"{_num(a_ask)} * {_num(pivot)} + ({_num(b_ask)})")

# --- system family: common-noun / coordinate-noun entities ----------------------------------

def _noun_affine_system(premises: list, question: str):
    """The COORDINATE/SUBTYPE-NOUN twin of `_affine_system`: entities are COMMON NOUNS (via
    `_affine_relation`'s noun-entity fallback — "twice as many pigs as cows", "4 more cows than goats"), not
    names, and the stated total is over a CATEGORY word ("56 ANIMALS total" for pig/cow/goat entities) rather
    than a literal noun match. `_combined_total`'s strict noun-matching (needed elsewhere to avoid grabbing
    the wrong value) would reject this — a hypernym check ("animal" ⊇ pig/cow/goat) is a whole separate,
    unbuilt feature — so this solver takes a NARROWER, self-contained shortcut instead: TRUST any total-cue
    clause's single value as the target sum, but ONLY for a system whose relations are CONFIRMED noun-based
    (the underlying premise has 0 or 1 names — an outer possessor like "farmer"/"Brett" is fine, but NOT the
    2-name shape `_affine_system` already owns) — this keeps the shortcut from ever competing with the
    named-entity system's own (stricter, already-tested) total-matching. Same pivot-propagation as
    `_affine_system`: an entity value = A·pivot + B, propagated from the one FREE entity (no relation's
    subject) via ≥2 relations, T = Σ(A)·pivot + Σ(B). "A farmer has twice as many pigs as cows, and 4 more
    cows than goats. If the farmer has 56 animals total, how many goats does he have?" → pivot=goats=11."""
    if any(w in question.lower() for w in ("altogether", "in all", " total", "combined", "in total")):
        return None                                       # a sum question is a different shape, not this one
    for p in premises:
        if re.search(r"\btimes (more|less|fewer)\b", p.lower()):
            return None                                   # ambiguous ×N idiom → decline (GATE C)
    rels = {}
    for p in premises:
        if any(w in p.lower() for w in ("total", "combined", "altogether", "together")):
            continue                                      # the total clause itself isn't a relation
        rp = analyze(p)
        if sum(1 for u in rp.units if "name" in u.features.get("senses", [])) == 2:
            continue                                      # a genuine 2-NAME relation is _affine_system's turf
        rel = _affine_relation(rp)
        if rel is None:
            continue
        subj_e, k, std_e, c = rel
        if k == 0 or subj_e == std_e:
            return None
        if subj_e in rels:                                # subject already defined → invert, like
            if std_e in rels:                              # `_affine_system`
                return None
            rels[std_e] = (1.0 / k, subj_e, -c / k)
        else:
            rels[subj_e] = (k, std_e, c)
    if len(rels) < 2:
        return None                                       # a genuine N-entity SYSTEM, like `_affine_system`
    total = None
    for p in premises:
        if not any(w in p.lower() for w in ("total", "combined", "altogether", "together")):
            continue
        vals = [u for u in analyze(p).units
                if "value" in u.features.get("senses", []) and u.features.get("value") is not None]
        if len(vals) == 1:
            total = vals[0].features["value"]
            break
    if total is None:
        return None
    entities = set(rels) | {std for _k, std, _c in rels.values()}
    free = [e for e in entities if e not in rels]
    if len(free) != 1:
        return None
    coeff = {free[0]: (1.0, 0.0)}
    for _ in range(len(entities) + 1):
        for e, (k, std, c) in rels.items():
            if std in coeff and e not in coeff:
                a_std, b_std = coeff[std]
                coeff[e] = (k * a_std, k * b_std + c)
    if any(e not in coeff for e in entities):
        return None
    sum_a = sum(a for a, _b in coeff.values())
    sum_b = sum(b for _a, b in coeff.values())
    if sum_a == 0:
        return None
    qr = analyze(question)
    asked = _asked_noun_entity(qr)
    if asked is None or asked not in coeff:
        return None
    pivot = _compute(f"({_num(total)} - ({_num(sum_b)})) / {_num(sum_a)}")
    a_ask, b_ask = coeff[asked]
    return _compute(f"{_num(a_ask)} * {_num(pivot)} + ({_num(b_ask)})")


def _noun_anchored_sum_system(premises: list, question: str):
    """The ANCHOR-based twin of `_noun_affine_system`: no combined/category total is stated, but ONE entity
    has a bare absolute value (a noun ANCHOR — "Hannah's family has ten PIGS", via `_noun_anchor_fact`,
    ignoring the outer possessor Hannah). The question asks for a CATEGORY SUM ("how many ANIMALS do they
    have?") — a noun that is NOT itself one of the specific relation entities, implying Σ over all of them
    (unlike `_anchored_sum_system`'s name family, which needs an explicit "altogether"/"total" cue — a
    category noun in the question already signals the sum here). Same "0-1 names per premise" safety check
    as `_noun_affine_system` (never competes with the 2-name system), and the SAME unused-given firewall as
    the named anchored family: every premise must classify as a relation or an anchor. "Hannah's family has
    ten pigs. They have three fewer than twice as many cows as pigs and six more goats than cows. How many
    animals do they have?" → pig=10 (anchor), cow=2·10−3=17, goat=17+6=23, Σ=50. Handles a NEGATED question
    as a COMPLEMENT sum (Σ over every entity EXCEPT the one named after "not"): "how many of her houses are
    NOT yellow?" → green+red = 160 (not the full Σ of 190) — but only when the excluded token is itself a
    known entity; an unresolvable negation still declines. Also declines when the question carries its OWN
    numeric value ("...and 5 students to every teacher, how many TEACHERS are there?") — a real confident-
    wrong (180 vs gold 36) came from a conversion clause getting glued onto the question by clause-splitting;
    a bare "how many X" question never has a number of its own, so a stray one signals unaccounted info this
    solver has no way to fold in (here, a students-per-teacher ratio, not a category sum at all)."""
    qr_check = analyze(question)
    if any("value" in u.features.get("senses", []) and u.features.get("value") is not None
           for u in qr_check.units):
        return None
    for p in premises:
        if any(w in p.lower() for w in ("total", "combined", "altogether", "together")):
            return None                                    # a stated total is _noun_affine_system's turf
        if re.search(r"\btimes (more|less|fewer)\b", p.lower()):
            return None                                    # ambiguous ×N idiom → decline (GATE C)
    rels, anchors = {}, {}
    for p in premises:
        rp = analyze(p)
        if sum(1 for u in rp.units if "name" in u.features.get("senses", [])) == 2:
            return None                                    # a genuine 2-name relation is _affine_system's turf
        rel = _affine_relation(rp)
        anc = None if rel is not None else _noun_anchor_fact(rp)
        if rel is None and anc is None:
            return None                                    # unused-given firewall, like the named family
        if rel is not None:
            subj_e, k, std_e, c = rel
            if k == 0 or subj_e == std_e:
                return None
            if subj_e in rels:
                if std_e in rels:
                    return None
                rels[std_e] = (1.0 / k, subj_e, -c / k)
            else:
                rels[subj_e] = (k, std_e, c)
        else:
            e, v = anc
            if e in anchors:
                return None
            anchors[e] = v
    if len(rels) < 1 or len(anchors) != 1:
        return None
    entities = set(rels) | {std for _k, std, _c in rels.values()}
    anchor_e, anchor_v = next(iter(anchors.items()))
    if anchor_e not in entities:
        return None
    free = [e for e in entities if e not in rels]
    if len(free) != 1:
        return None
    coeff = {free[0]: (1.0, 0.0)}
    for _ in range(len(entities) + 1):
        for e, (k, std, c) in rels.items():
            if std in coeff and e not in coeff:
                a_std, b_std = coeff[std]
                coeff[e] = (k * a_std, k * b_std + c)
    if any(e not in coeff for e in entities):
        return None
    a_anc, b_anc = coeff[anchor_e]
    if a_anc == 0:
        return None
    pivot = _compute(f"({_num(anchor_v)} - ({_num(b_anc)})) / {_num(a_anc)}")
    qr = analyze(question)
    asked = _asked_noun_entity(qr)
    if asked is None or asked in coeff:
        return None                                        # a specific entity ask — not this SUM shape
    # COMPLEMENT sum: "how many <category> are NOT <subtype>?" → Σ over every entity EXCEPT the excluded one
    # (the subtype named right after "not"/"n't"). Reuses the full-Σ machinery verbatim, dropping one term.
    # Tightly gated: the excluded token must ITSELF be one of the system's entities — a negation we can't
    # resolve to a known entity DECLINES (conflating a complement with the full Σ was a confident-wrong, 190
    # vs the complement's 160: Isabella's green/yellow/red houses, "not yellow" → green+red).
    qtok = [_key(w.surface) for u in qr.units for w in u.words]
    if any(s == "negation" for u in qr.units for s in u.features.get("senses", [])):
        excluded = next((qtok[i + 1] for i, w in enumerate(qtok[:-1])
                         if w in ("not", "n't") and qtok[i + 1] in coeff), None)
        if excluded is None:
            return None
        summed = {e: c for e, c in coeff.items() if e != excluded}
    else:
        summed = coeff
    total = " + ".join(f"({_num(a)} * {_num(pivot)} + ({_num(b)}))" for a, b in summed.values())
    return _compute(total)


def _noun_residual_sum_system(premises: list, question: str):
    """The SUBTYPE-PARTITION twin: adjective-qualified subtypes of ONE head noun ("red/blue/green BALLS"),
    where the total is stated directly in the SAME (bare, unqualified) head noun ("Ryan has 40 balls" — no
    hypernym/category guessing needed, unlike `_noun_affine_system`'s total), and the ASKED entity is the
    explicit textual "the REST are <qualifier>" residual — never itself defined by a relation. "Ryan has 40
    balls. There are twice as many red balls as blue while the rest are green. If there are 11 blue balls,
    how many green balls are there?" → red=2·11=22, green=40−22−11=7. Same unused-given firewall (every
    premise must classify as the total, an anchor, a relation, or the "rest" marker) and 0-1-names-per-
    premise safety check as the rest of the coordinate-noun family."""
    if any(w in question.lower() for w in ("altogether", "in all", " total", "combined", "in total")):
        return None                                        # an explicit sum cue is a different shape
    for p in premises:
        if re.search(r"\btimes (more|less|fewer)\b", p.lower()):
            return None
    rels, anchors, residual, total = {}, {}, None, None
    for p in premises:
        rest_m = re.match(r"^(the\s+)?rest\s+(are|is)\s+([a-z]+)", p.strip(), re.I)
        if rest_m:
            if residual is not None:
                return None
            residual = _key(rest_m.group(3))
            continue
        rp = analyze(p)
        if sum(1 for u in rp.units if "name" in u.features.get("senses", [])) == 2:
            return None                                     # a genuine 2-name relation is _affine_system's turf
        rel = _affine_relation(rp)
        if rel is not None:
            subj_e, k, std_e, c = rel
            if k == 0 or subj_e == std_e:
                return None
            if subj_e in rels:
                if std_e in rels:
                    return None
                rels[std_e] = (1.0 / k, subj_e, -c / k)
            else:
                rels[subj_e] = (k, std_e, c)
            continue
        vals = [u for u in rp.units if "value" in u.features.get("senses", []) and u.features.get("value") is not None]
        qn = _follow(vals[0], "quantifies") if len(vals) == 1 else None
        if qn is not None and "noun" in qn.features.get("senses", []):
            if qn.features.get("attributes"):                # a QUALIFIED noun — a per-subtype anchor
                e = _noun_entity_key(qn)
                if e in anchors:
                    return None
                anchors[e] = vals[0].features["value"]
            else:                                             # a BARE noun — the head-noun TOTAL
                if total is not None:
                    return None
                total = vals[0].features["value"]
            continue
        return None                                          # unclassified premise — the same firewall as
        #                                                       the rest of the anchored family
    if residual is None or total is None or len(rels) < 1 or len(anchors) != 1:
        return None
    entities = set(rels) | {std for _k, std, _c in rels.values()}
    if residual in entities:
        return None                                          # the residual must be UNCOVERED by any relation
    anchor_e, anchor_v = next(iter(anchors.items()))
    if anchor_e not in entities:
        return None
    free = [e for e in entities if e not in rels]
    if len(free) != 1:
        return None
    coeff = {free[0]: (1.0, 0.0)}
    for _ in range(len(entities) + 1):
        for e, (k, std, c) in rels.items():
            if std in coeff and e not in coeff:
                a_std, b_std = coeff[std]
                coeff[e] = (k * a_std, k * b_std + c)
    if any(e not in coeff for e in entities):
        return None
    a_anc, b_anc = coeff[anchor_e]
    if a_anc == 0:
        return None
    pivot = _compute(f"({_num(anchor_v)} - ({_num(b_anc)})) / {_num(a_anc)}")
    qr = analyze(question)
    asked = _asked_noun_entity(qr)
    if asked != residual:
        return None                                          # only the RESIDUAL entity — a covered entity
        #                                                       is a different (unbuilt) single-ask variant
    covered_sum = " + ".join(f"({_num(a)} * {_num(pivot)} + ({_num(b)}))" for a, b in coeff.values())
    return _compute(f"{_num(total)} - ({covered_sum})")

# --- system family: anchored (no stated total — one entity has a bare absolute value) -------

def _anchor_fact(rp: "Reading"):
    """A single ANCHOR fact: an ABSOLUTE value stated for exactly one NAMED entity, with no relation to any
    other entity ("Cecil has $600", "If David has 15 shells" → (Cecil, 600) / (David, 15)). Also covers a
    COMMON-NOUN anchor with NO names ("A pet store has six dogs for sale.", "If there are 11 blue balls" →
    (dog, 6) / (blue, 11)) — the coordinate-noun/subtype-partition affine family's twin of the named case;
    the entity is whatever the value's `quantifies` link points to. None if the clause carries a comparative/
    multiplier/fraction (that's a RELATION, not an anchor), a RECURRENCE marker ("every"/"each"/"per" —
    "Sofie plans to walk 10 miles EVERY DAY" is a per-day RATE, not a flat anchor; folding the bare 10
    directly gave a real confident-wrong, 5 vs gold 35, dropping the "in 7 days" multiplication this solver
    has no mechanism to apply), or doesn't name exactly one entity holding exactly one value — the anchor is
    what `_anchored_sum_system` pins its free pivot to when the problem states no combined total."""
    if any("comparative" in u.features.get("senses", []) for u in rp.units) \
            or any("multiplier" in u.features.get("senses", []) for u in rp.units) \
            or any(_fraction_parts(u.surface) is not None for u in rp.units) \
            or any(_key(u.surface) in ("every", "each", "per") for u in rp.units):
        return None
    names = [u for u in rp.units if "name" in u.features.get("senses", [])]
    if not any("verb" in u.features.get("senses", []) for u in rp.units):
        return None
    vals = [u for u in rp.units if "value" in u.features.get("senses", []) and u.features.get("value") is not None]
    if len(vals) != 1:
        return None
    if not names:
        qn = _follow(vals[0], "quantifies")
        if qn is None or "noun" not in qn.features.get("senses", []):
            return None
        return _noun_entity_key(qn), vals[0].features["value"]
    if len(names) != 1:
        return None
    return _entity(names[0]), vals[0].features["value"]


def _noun_anchor_fact(rp: "Reading"):
    """A COMMON-NOUN anchor, tolerating an OUTER POSSESSOR name ("Hannah's family has ten PIGS" → (pig, 10),
    ignoring Hannah — unlike `_anchor_fact`, which prioritizes a bare name subject and would wrongly anchor
    to Hannah herself). Used by `_noun_anchored_sum_system`, the anchor-based twin of `_noun_affine_system`
    for when no combined/category total is stated. None under the same comparative/multiplier/fraction/
    recurrence-marker/single-value/verb gates as `_anchor_fact` (a "per day"-style rate isn't a flat anchor),
    or if the value doesn't quantify a genuine noun."""
    if any("comparative" in u.features.get("senses", []) for u in rp.units) \
            or any("multiplier" in u.features.get("senses", []) for u in rp.units) \
            or any(_fraction_parts(u.surface) is not None for u in rp.units) \
            or any(_key(u.surface) in ("every", "each", "per") for u in rp.units):
        return None
    if not any("verb" in u.features.get("senses", []) for u in rp.units):
        return None
    vals = [u for u in rp.units if "value" in u.features.get("senses", []) and u.features.get("value") is not None]
    if len(vals) != 1:
        return None
    qn = _follow(vals[0], "quantifies")
    if qn is None or "noun" not in qn.features.get("senses", []):
        return None
    return _noun_entity_key(qn), vals[0].features["value"]


_NEEDS_INVERSE = re.compile(
    r"\b([A-Z][a-z]+) needs (\d+|[a-z]+) more \w+ to have "
    r"(?:the same number|(twice|thrice|double|half|(?:\d+|[a-z]+) times) as (?:many|much) \w+) "
    r"as ([A-Z][a-z]+)")


def _needs_inverse_relation(premise: str):
    """The DEFICIT-TO-TARGET premise read (#208) — "Amanda needs 12 more marbles to have twice as
    many marbles as Katrina" states Amanda + 12 = 2·Katrina, i.e. subject = k·standard − n; "Loris
    needs three more books to have the same number as Lamont" is the k=1 case. → (subj, k, std,
    −n). This is the PREMISE-side twin of the needs-idiom the single twin's question guard
    declines — the frame is exact, so the inversion is safe. None otherwise."""
    m = _NEEDS_INVERSE.search(premise)
    if m is None:
        return None
    n = float(m.group(2)) if m.group(2).isdigit() else NUMBERS.get(m.group(2))
    if not n:
        return None
    mult = m.group(3)
    if mult is None:
        k = 1.0                                          # "the same number as"
    else:
        k = {"twice": 2.0, "thrice": 3.0, "double": 2.0, "half": 0.5}.get(mult)
        if k is None:
            tok = mult.split()[0]
            k = float(NUMBERS.get(tok, tok if tok.isdigit() else 0) or 0)
    if not k:
        return None
    return m.group(1).lower(), k, m.group(4).lower(), -n


def _edit1(a: str, b: str) -> bool:
    """True iff the two strings are exactly ONE edit apart (insert/delete/substitute) — the
    near-name unifier for GSM8K's own cross-clause misspellings ("Jefferey"/"Jeffery")."""
    la, lb = len(a), len(b)
    if abs(la - lb) > 1 or a == b:
        return False
    if la == lb:
        return sum(x != y for x, y in zip(a, b)) == 1
    if la > lb:
        a, b, la, lb = b, a, lb, la
    i = j = diff = 0
    while i < la and j < lb:
        if a[i] != b[j]:
            diff += 1
            if diff > 1:
                return False
            j += 1
        else:
            i += 1
            j += 1
    return True


def _elided_ratio(rp, premise: str):
    """A single-name ratio clause whose standard is ELIDED — "Flora has twice as many books",
    "Stephanie's bike is worth twice as much" — → (subject_entity, k). The standard is anaphoric;
    `_anchored_affine_coeffs` binds it to the PREVIOUS classified premise's entity (nearest
    antecedent, the natural read of comparative ellipsis). None unless: a multiplier/fraction is
    present; the clause has an as-many/as-much frame with NO explicit standard after it (an
    "as X" tail is `_ratio_relation`'s explicit shape / the coordinate-noun family's turf); no
    stated value; no comparative (an offset is a different relation; "times more" is banned
    upstream); exactly one name."""
    if any("value" in u.features.get("senses", []) and u.features.get("value") is not None
           for u in rp.units):
        return None
    if any("comparative" in u.features.get("senses", []) for u in rp.units):
        return None
    pl = premise.lower()
    if re.search(r"\bas (?:many|much) (?:\w+ ){0,3}?as\b", pl) or " than" in pl:
        return None                                     # an explicit standard — another family's
    if not re.search(r"\bas (?:many|much)\b", pl) \
            and not re.search(r"\b(?:half|twice|double|thrice) (?:of )?(?:his|her|their) "
                              r"(?:height|weight|size|length)\b", pl):
        return None                                     # the as-many/as-much elided frame, or the
        #                                                 possessive-MEASURE frame ("half her
        #                                                 height" → k× the antecedent, #222)
    mult = next((u for u in rp.units if "multiplier" in u.features.get("senses", [])), None)
    if mult is None:
        return None
    k = (mult.features["fraction"][0] / mult.features["fraction"][1]) if "fraction" in mult.features \
        else mult.features.get("value")
    if not k:
        return None
    names = [u for u in rp.units if "name" in u.features.get("senses", [])]
    if len(names) != 1:
        return None
    return _entity(names[0]), float(k)


def _anchored_affine_coeffs(premises: list, question: str):
    """Shared extraction for the ANCHOR-pinned affine family (`_anchored_sum_system`/`_anchored_single_system`):
    builds the same relation graph as `_affine_system`, but pins the free pivot from a bare ABSOLUTE value (an
    "anchor", e.g. "Cecil has $600") instead of a stated combined total. Returns (coeff, pivot) where
    coeff[e]=(A, B) is UNRESOLVED — value[e] = A·pivot + B — and `pivot` is the anchor's own number. None if:
    the problem is AGE-typed ("old"/"older"/"younger"/"age" anywhere in premises or question) — the dedicated
    age-domain machinery (`_comparative_age` and friends) owns ages, with careful TEMPORAL-SHIFT handling
    ("in N years, X will be…") this generic solver has no notion of, so letting it also claim age problems
    caused real mis-fires (a future-shifted ratio LOOKS like a plain ratio relation structurally, but silently
    drops the shift); a combined-total cue is present (that's `_affine_system`'s turf); the ambiguous "N times
    more/less" idiom is used; ANY premise fails to classify as a relation (2 names) or an anchor (1 name) — an
    unused-given firewall of its own, since these self-contained systems run before GUARD 3 and so must guard
    the same way (an unclassified premise may hide a depletion action or an unsupported relation frame); there
    doesn't have a UNIQUE free entity (one that's no relation's subject) reachable from the anchor by
    forward propagation (disconnected / cyclic); the anchor itself may sit ANYWHERE in the graph, not just on
    the free entity — "Ed weighs 146 and is 38 lighter than Al" anchors the DEPENDENT entity Ed, so the pivot
    (Al's ultimate free ancestor) is recovered by back-substituting the anchor's equation; or an ANCHOR's
    value and a relation's OFFSET value carry UNCONVERTED, different measures ("Movie C was 1.25 HOURS"
    anchoring in hours, "5 MINUTES longer" offsetting in minutes) — this solver never converts units, so
    folding them together silently mixed hours and minutes as if they were the same number (a real confident-
    wrong: 1.5625 vs gold 20 minutes). Deliberately narrow: only the ANCHOR's own value (unambiguous — an
    anchor premise has exactly one value) and a relation's OFFSET value (when c≠0, matched by magnitude) are
    checked — an INCIDENTAL value elsewhere in a relation clause ("half as many pages as Lucy IN 1 HOUR", a
    rate's constant duration, never itself part of the arithmetic) must NOT count, or it wrongly declines a
    correct pure-ratio system (a regression this exact fix introduced and then had to narrow)."""
    # "older sister"/"younger brother" are KINSHIP descriptors, not an age computation — strip them before
    # the age check so a NON-age problem (shoe size, height) that merely names an older/younger sibling isn't
    # blanket-declined by the age guard ("Jasmine and her OLDER SISTER Alexa … combined shoe size?" → 21). A
    # real age relation ("3 years older THAN", "as old as", "years old", "X's age") keeps its trigger.
    _agetext = re.sub(r"\b(older|younger) +(" + "|".join(KINSHIP) + r")\b", " ",
                      " ".join(premises + [question]).lower())
    if re.search(r"\b(old|older|younger|age|ages|aged)\b", _agetext):
        return None
    # KIN-APPOSITION NORMALIZATION (#207, the age-chain's trick on counts): "His sister Flora has
    # twice as many books" / "than his brother Fred" name ONE person, but the kin noun counts as a
    # second (or third) name, so the premise mis-classifies (a 2-name apposition even extracted a
    # bogus sister=2×flora relation). The kinship is decorative for the algebra — keep the name.
    premises = [re.sub(rf"\b(?:[Hh]is|[Hh]er|[Tt]heir) (?:older |younger |little |big |other )?"
                       rf"(?:{'|'.join(KINSHIP)}),? ([A-Z][a-z]+)\b", r"\1", p)
                for p in premises]
    # LOCAL CONJUNCT SPLIT (#215): a long "If A…, and B…, and C…" sentence can reach here with
    # two relations still fused in one premise (the global splitter took only the last conjunct).
    # Split at ", and <Name> <verb>" — worst case a fragment fails to classify and the family
    # declines exactly as it does today. #216 adds the MISSING-PERIOD fusion ("In total Emma
    # spent $58 If Elsa spent twice as much" — GSM8K's own typo) via a mid-premise " If " split.
    premises = [part for p in premises
                for part in re.split(r"(?:, and | If )(?=[A-Z][a-z]+ (?:has|have|had|is|was|spent|"
                                     r"earns?|makes?|gets?|owns?))", p)]
    # PROPER-NOUN EVENT ADJUNCT (#216): "…as Amanda in their school's Book Tournament" — the
    # capitalized event name inflates the name count and the premise mis-classifies. The
    # adjunct is scene-setting; strip it (worst case: decline, as today).
    premises = [re.sub(r" in (?:his|her|their) \w+['’]s [A-Z]\w+(?: [A-Z]\w+)?", "", p)
                for p in premises]
    if any(w in p.lower() for p in premises
           for w in ("combined", "total", "together", "between them", "altogether")
           # #216: "In total EMMA spent $58" is a SINGLE-ENTITY amount, not a combined total —
           # the narrow leading form is exempt; any other total-word premise still declines.
           if not re.match(r"[Ii]n total [A-Z]\w+ (?:spent|has|had|made|earned|received)\b", p.strip())):
        return None                                                  # a stated total is _affine_system's turf
    # "share"/"shared" signals a DISTRIBUTED total ("Mr. Sam SHARED $5250 between his two sons") — but NOT
    # the purpose infinitive "20 cookies TO SHARE in class" (intent, no total), which wrongly tripped this
    # guard and blocked a legitimate anchored-sum ("Mona brought 20 … Jasmine 5 fewer … altogether?" → 60).
    if any(re.search(r"\bshared?\b", p.lower()) and not re.search(r"\bto (be )?shared?\b", p.lower())
           for p in premises):
        return None
    for p in premises:
        if re.search(r"\btimes (more|less|fewer)\b", p.lower()):
            return None                                             # ambiguous ×N idiom → decline (GATE C)
    rels, anchors, measures = {}, {}, set()
    rps = [analyze(p) for p in premises]
    cast_n = _cast_size(rps)               # for the SET-SIZE-cardinal skip below
    last_entity = None                     # nearest antecedent for the elided-standard ratio
    for p, rp in zip(premises, rps):
        two_names = _name_count(rp) == 2
        if not any(s in u.features.get("senses", []) for u in rp.units
                   for s in ("value", "multiplier", "comparative", "interrogative", "aggregator")) \
                and not any(_fraction_parts(u.surface) is not None for u in rp.units) \
                and not p.rstrip().endswith("?") \
                and not (two_names and re.search(r"\b(as|than)\b", p.lower())):
            continue                       # a purely DECLARATIVE premise with NO number/factor/comparative
            #                                 at all, and NOT itself a question fragment, can't hide any
            #                                 dropped quantity ("Stacy and Emily also buy chips for the
            #                                 party" just introduces entities) — skip it, don't decline.
            #                                 EXCLUDES an interrogative/aggregator word OR a trailing "?"
            #                                 ("how many … TOTAL have Megan, Kelcie" / "Greg read?" — both
            #                                 MIS-SPLIT fragments of the ACTUAL question "...Megan, Kelcie,
            #                                 and Greg read?", a known clause-splitting gap for a 3-name
            #                                 question list) — skipping either silently would drop Greg
            #                                 entirely and sum only Megan+Kelcie (40 vs gold 65). ALSO
            #                                 excludes a 2-name clause with "as"/"than" ("Jorge has an EQUAL
            #                                 NUMBER of cards AS Matias" — "equal" isn't a recognized
            #                                 multiplier, but "as" still signals a REAL, just-unsupported
            #                                 relation; skipping it silently dropped Jorge=Matias, 34 vs gold
            #                                 48) — unlike a truly unclassified premise that DOES carry a
            #                                 number this solver failed to fold, which stays a decline below
        if _set_size_cardinal(rp, cast_n) and not p.rstrip().endswith("?"):
            continue                       # the premise's only number COUNTS THE CAST ("four players
            #                                 scored points" in a 4-name problem) — scene-setting, not a
            #                                 dropped quantity; see `_set_size_cardinal`
        nc = _name_count(rp)
        rel = _affine_relation(rp) if nc == 2 else None      # exactly 2 names — else this may be the
        anc = _anchor_fact(rp) if (rel is None and nc == 1) else None   # coordinate-noun fallback firing,
        if rel is None and anc is None and nc == 2:
            rel = _needs_inverse_relation(p)             # "needs 12 more to have twice as many as K"
        elided = False
        if rel is None and anc is None and nc == 1 and last_entity is not None:
            el = _elided_ratio(rp, p)                        # "Flora has twice as many books" — the
            if el is not None and el[0] != last_entity:      # standard is the nearest antecedent
                rel = (el[0], el[1], last_entity, 0.0)
                elided = True
        if rel is None and anc is None:                       # which is a DIFFERENT family's turf (see
            return None                    # an UNCLASSIFIED premise (e.g. a depletion action like "gave out
            #                                 half her apples", or an unsupported relation frame like "an equal
            #                                 number … as") may hide information this solver can't fold
        if rel is not None:
            subj_e, k, std_e, c = rel
            if k == 0 or subj_e == std_e:
                return None
            if c != 0:                     # the OFFSET's own measure (matched by magnitude — the ONE value
                off_u = next((u for u in rp.units if "value" in u.features.get("senses", [])   # this
                              and u.features.get("value") is not None                          # relation's
                              and abs(u.features["value"]) == abs(c)), None)                    # arithmetic
                if off_u is not None:                                                           # actually
                    qn = _follow(off_u, "quantifies")                                          # uses — NOT
                    m = _descriptor(qn) if qn is not None else off_u.features.get("measure")    # every value
                    if m is not None and m[0] not in COUNT_NOUNS:               # in the clause; "the NUMBER
                        measures.add(m[0])                                      # of X" resolves to "number"
                        #                                                         itself, not X — skip it
            if subj_e in rels:                                     # subject already defined → invert into
                if std_e in rels:                                  # a relation for the OTHER entity, like
                    return None                                     # `_affine_system`
                rels[std_e] = (1.0 / k, subj_e, -c / k)
            else:
                rels[subj_e] = (k, std_e, c)
            if not elided:                    # COORDINATED elided clauses share ONE standard ("her
                last_entity = subj_e          # brother has thrice as much WHILE her sister has half
            #                                   as much" — both elide "as Joanna's"); an elliptically
            #                                   introduced subject never becomes the next antecedent
            #                                   (Joanna: sister←brother mis-bound 44 ≠ gold 36)
        else:
            e, v = anc
            if e in anchors:
                return None
            anchors[e] = v
            last_entity = e
            vals = [u for u in rp.units if "value" in u.features.get("senses", [])
                    and u.features.get("value") is not None]
            if len(vals) == 1:                          # an anchor premise has EXACTLY one value (unambiguous)
                qn = _follow(vals[0], "quantifies")
                m = _descriptor(qn) if qn is not None else vals[0].features.get("measure")
                if m is not None and m[0] not in COUNT_NOUNS:
                    measures.add(m[0])
    if len(measures) > 1:
        return None                             # mixed, unconverted units → decline rather than mis-fold
    if len(rels) < 1 or len(anchors) != 1:
        return None
    entities = set(rels) | {std for _k, std, _c in rels.values()}
    anchor_e, anchor_v = next(iter(anchors.items()))
    if anchor_e not in entities:
        # NEAR-NAME UNIFICATION (#215): GSM8K itself misspells names between clauses
        # ("Jefferey caught twice…" vs "If Jeffery caught 60") — unify the anchor with a
        # UNIQUE entity at edit-distance 1, names ≥5 chars (short names stay strict).
        near = [e for e in entities if len(anchor_e) >= 5 and len(e) >= 5
                and _edit1(anchor_e, e)]
        if len(near) != 1:
            return None
        anchor_e = near[0]
    free = [e for e in entities if e not in rels]                  # the pivot: the one entity that is no
    if len(free) != 1:                                             # relation's subject (may differ from the
        return None                                                # anchor's own entity)
    coeff = {free[0]: (1.0, 0.0)}                                  # value[e] = A·pivot + B, propagated from
    for _ in range(len(entities) + 1):                              # the free pivot along the relation tree
        for e, (k, std, c) in rels.items():
            if std in coeff and e not in coeff:
                a_std, b_std = coeff[std]
                coeff[e] = (k * a_std, k * b_std + c)
    if any(e not in coeff for e in entities):                       # disconnected / cyclic → reject
        return None
    a_anc, b_anc = coeff[anchor_e]
    if a_anc == 0:
        return None
    # anchor_v = A_anchor·pivot + B_anchor  ⇒  pivot = (anchor_v − B_anchor)/A_anchor (identity when the
    # anchor IS the free pivot: A=1, B=0, pivot=anchor_v directly — no division, as before).
    pivot = _compute(f"({_num(anchor_v)} - ({_num(b_anc)})) / {_num(a_anc)}")
    return coeff, pivot


def _anchored_sum_system(premises: list, question: str):
    """The ANCHORED-SUM twin of `_affine_system`: instead of a COMBINED TOTAL pinning the pivot, one entity
    has a stated ABSOLUTE value (an "anchor") and NO total is given — the question instead asks for the SUM
    of every entity, OR of SPECIFIC named entities if the question names 2+ of them directly ("how many
    marbles do CARL AND CAL have combined?" sums only those two, not every entity in the system — a real
    confident-wrong (392 vs gold 336) surfaced this: a 3-entity system where the question named only 2).
    "Cecil has $600. Catherine has $250 less than twice Cecil's money. Carmela has $50 more than twice
    Cecil's money. How much do they have altogether?" → pivot=Cecil=600 directly (no division needed);
    answer = Σ(A_e·600 + B_e) = 2800. Runs only when `_affine_system` (a stated total) and the pure/offset
    sum-systems all decline — a SUM question ("altogether"/"in all"/"total") with NO stated total is this
    solver's shape, not theirs. Delegates the relation/anchor extraction to `_anchored_affine_coeffs` (shared
    with `_anchored_single_system`); adds its OWN sum-cue gate and a "dozen"-measure decline (the anchor's
    "6 dozen" already converts to raw units internally, so a "how many DOZEN" question needs a ÷12 we don't
    do)."""
    if not any(w in question.lower() for w in ("altogether", "in all", " total", "combined", "in total",
                                               " together")):        # " together" (#207): "own together?" —
        return None                                                  # not a SUM question — not this shape
        #                                                              kept in sync with the single twin's
        #                                                              decline list (else it intercepts)
    # DEFER to `_chain_count_price` (dispatched before us): a money-spend total WITH a per-item price is a
    # count×price problem — folding only the counts would drop the price (Dorothy 22≠33). It re-invokes us
    # with a plain count question ("how many in total?") to get the count, so this gate never blocks that call.
    ql = question.lower()
    if any(w in ql for w in ("spend", "spent", "pay", "paid", "cost")) and _unit_price(question) is not None:
        return None
    asked_measure = _queried_measure(question)
    if asked_measure is not None and "dozen" in asked_measure[1]:
        return None
    got = _anchored_affine_coeffs(premises, question)
    if got is None:
        return None
    coeff, pivot = got
    # a comma/"and"-joined name list ("Carl and Cal") merges into ONE unit spanning multiple words — split
    # back into individual entity keys by word, skipping "and" (same gotcha as `_residual_sum_system`).
    qunits = analyze(question).units
    named = [_key(w.surface) for u in qunits if "name" in u.features.get("senses", [])
             for w in u.words if _key(w.surface) != "and"]
    # ALSO count a capitalized question word that IS a system entity but was mis-tagged as a common noun
    # ("Bill" → the money-noun sense, "Rose" → the flower) — else "how many do Bill and Harry have combined?"
    # sees only one name, skips the subset, and wrongly sums ALL (Bill/Harry/Sue 720 ≠ 672).
    cap_entities = [_key(w.surface) for u in qunits for w in u.words
                    if w.surface[:1].isupper() and _key(w.surface) in coeff and _key(w.surface) not in named]
    qnames = named + cap_entities
    if len(qnames) >= 2:
        if any(e not in coeff for e in qnames):
            return None                # a named entity outside the system — not this solver's shape
        summed = {e: coeff[e] for e in qnames}
    else:
        summed = coeff                 # no specific names (e.g. "how much do THEY have altogether") — sum all
    return _compute(" + ".join(f"({_num(a)} * {_num(pivot)} + ({_num(b)}))" for a, b in summed.values()))


def _anchored_single_system(premises: list, question: str):
    """The ANCHORED-SINGLE twin: same anchor-pinned relation graph as `_anchored_sum_system`, but the question
    asks for ONE named entity's value (not the sum) — "Al is 25 pounds heavier than Ben. Ben is 16 pounds
    lighter than Carl. Ed weighs 146 pounds and is 38 pounds lighter than Al. Find Carl's weight." → pivot=Ed
    (anchor), propagate to Al, then Ben, then Carl. Declines a SUM-cue question (that's the sum twin's shape),
    a "needs...to have as large as" DEFICIT-TO-TARGET question (the same "needs"-idiom risk as the relation
    extractors — "how many stamps does SHE NEED to ADD to have a collection AS LARGE AS Bert's?" asks
    Bert−Peggy, not Bert's raw value; naively grabbing the first name in the question gave a confident-wrong,
    900 vs gold 825), and requires the asked entity to be a NAME reachable from the anchor."""
    if any(w in question.lower() for w in ("altogether", "in all", " total", "combined", "in total",
                                           " together")):            # " together" in sync with the sum twin
        return None                                                  # a sum question is the other twin's shape
    if re.search(r"\bneeds?\b", question.lower()):
        return None
    qr = analyze(question)
    if any("comparative" in u.features.get("senses", []) for u in qr.units):
        return None       # "how many MORE does X have COMPARED TO Y" asks a DIFFERENCE, not a raw value
    qnames = [u for u in qr.units if "name" in u.features.get("senses", [])]
    if not qnames:
        return None
    asked = _entity(qnames[0])
    got = _anchored_affine_coeffs(premises, question)
    if got is None:
        return None
    coeff, pivot = got
    if asked not in coeff:
        return None
    a, b = coeff[asked]
    return _compute(f"{_num(a)} * {_num(pivot)} + ({_num(b)})")


def _anchored_difference_system(premises: list, question: str):
    """The ANCHORED-DIFFERENCE twin: same anchor-pinned relation graph, but the question names TWO entities
    and asks how much MORE one has than the other — "Anton has three times as many cards as Heike. Ann has
    six times as many cards as Heike. If Ann has 60 cards, how many more cards does Ann have than Anton?" →
    Heike=10 (from Ann=60=6·Heike), Anton=30, Ann−Anton=30. Requires the question to carry a comparative
    sense (declined by `_anchored_single_system`, so the two never collide) and EXACTLY two names — the first
    named (textually) minus the second, matching the "X … more … than Y" surface order."""
    qr = analyze(question)
    if not any("comparative" in u.features.get("senses", []) for u in qr.units):
        return None
    qnames = [u for u in qr.units if "name" in u.features.get("senses", [])]
    if len(qnames) != 2:
        return None
    e1, e2 = _entity(qnames[0]), _entity(qnames[1])
    if e1 == e2:
        return None
    got = _anchored_affine_coeffs(premises, question)
    if got is None:
        return None
    coeff, pivot = got
    if e1 not in coeff or e2 not in coeff:
        return None
    a1, b1 = coeff[e1]
    a2, b2 = coeff[e2]
    if re.search(r"\b(?:less|fewer)\b[^.?]*\bthan\b", question.lower()):
        (a1, b1), (a2, b2) = (a2, b2), (a1, b1)   # "how much LESS does X have than Y" → Y − X
    return _compute(f"({_num(a1)} * {_num(pivot)} + ({_num(b1)})) - "
                    f"({_num(a2)} * {_num(pivot)} + ({_num(b2)}))")


def _anchored_average_system(premises: list, question: str):
    """The ANCHORED-AVERAGE twin: the question asks for the MEAN of the N entities (Σ ÷ N) instead of the
    sum — "Rachel weighs 75 pounds, 6 pounds less than Jimmy and 15 pounds more than Adam. What is the
    average weight of the three people?" → Σ=216 over {Rachel,Jimmy,Adam}, ÷3 = 72. Reuses the exact sum
    machinery (`_anchored_affine_coeffs`, shared with `_anchored_sum_system`); the only new behaviour is
    the division. SAFETY: never divide by a GUESSED N — the question must STATE a group count that matches
    the number of entities the coeffs captured (`n in q_ints`), so a system that captured a subset (a
    missing/unsupported relation, e.g. an "as tall as" equality) DECLINES rather than dividing by the wrong
    denominator. Age-typed averages ("average age of the three") already decline inside
    `_anchored_affine_coeffs`, so this never competes with the age domain's own average branch."""
    ql = question.lower()
    if "average" not in ql:
        return None                                                  # not an average question
    if any(w in ql for w in ("altogether", "in all", " total", "combined", "in total")):
        return None                                                  # a sum question is the other twin's shape
    got = _anchored_affine_coeffs(premises, question)
    if got is None:
        return None
    coeff, pivot = got
    n = len(coeff)
    q_ints = {int(u.features["value"]) for u in analyze(question).units
              if "value" in u.features.get("senses", []) and float(u.features["value"]).is_integer()}
    if n not in q_ints:                                              # the stated group size must match N
        return None
    total = " + ".join(f"({_num(a)} * {_num(pivot)} + ({_num(b)}))" for a, b in coeff.values())
    return _compute(f"({total}) / {n}")


def _residual_sum_system(premises: list, question: str):
    """The RESIDUAL twin: a stated total names THREE (or more) entities ("Jermaine, Terrence, and Emilee earn
    a total of $90"), but only SOME of them are related/anchored elsewhere ("Jermaine earns $5 more than
    Terrence"; "Terrence earns $30") — the ASKED entity (Emilee) is never mentioned again at all. Unlike
    `_affine_system` (which requires every named entity to reduce to the pivot), this solves for the ONE
    entity left OUT of that graph: residual = total − Σ(every OTHER named entity's value). Tightly gated: the
    total clause must name ≥3 entities EXPLICITLY, OR use a bare PRONOUN ("If THEY need 10 bags total") with
    the ≥3 names inferred from every OTHER premise ("Jeremy buys 3 bags... Stacy buys 4 bags... how many
    should Emily buy?" — no premise ever lists all three together) — the OTHER premises (anchor/relation
    graph, via the shared `_anchored_affine_coeffs`) must cover ALL BUT EXACTLY ONE of them, and the asked
    entity must BE that one uncovered residual — else this isn't the residual shape (or another solver
    already owns it)."""
    tot_names = tot_val = tot_clause = None
    for p in premises:
        if not any(w in p.lower() for w in ("total", "combined", "altogether", "together")):
            continue
        rp = analyze(p)
        name_units = [u for u in rp.units if "name" in u.features.get("senses", [])]
        # a comma/"and"-joined subject list ("Jermaine, Terrence, and Emilee") merges into ONE unit whose
        # surface spans multiple words — split back into individual entity keys, skipping "and" itself.
        names = [_key(w.surface) for u in name_units for w in u.words if _key(w.surface) != "and"]
        vals = [u for u in rp.units if "value" in u.features.get("senses", []) and u.features.get("value") is not None]
        if not vals:
            continue
        if len(names) < 3:
            if names:
                continue                   # 1-2 explicit names but not the full set — ambiguous, skip
            # a PRONOUN total ("they need 10 bags total") — infer the name set from every OTHER premise
            other_names = {_key(w.surface) for op in premises if op is not p
                           for u in analyze(op).units if "name" in u.features.get("senses", [])
                           for w in u.words if _key(w.surface) != "and"}
            if len(other_names) < 3:
                continue
            names = sorted(other_names)
        tot_names, tot_val, tot_clause = names, vals[0].features["value"], p
        break
    if tot_val is None:
        return None
    qr = analyze(question)
    qnames = [u for u in qr.units if "name" in u.features.get("senses", [])]
    if not qnames:
        return None
    asked = _entity(qnames[0])
    if asked not in tot_names:
        return None
    rest = [p for p in premises if p is not tot_clause]
    got = _anchored_affine_coeffs(rest, question)
    if got is not None:
        coeff, pivot = got
        covered = [e for e in tot_names if e in coeff]
        residual = [e for e in tot_names if e not in coeff]
        if len(residual) != 1 or residual[0] != asked:
            return None                          # not the residual shape — 0 or ≥2 uncovered, or the asked
        #                                           entity isn't the uncovered one (another solver's turf)
        covered_sum = " + ".join(f"({_num(a)} * {_num(pivot)} + ({_num(b)}))" for a, b in
                                 (coeff[e] for e in covered))
        return _compute(f"{_num(tot_val)} - ({covered_sum})")
    # NO-RELATION fallback: `_anchored_affine_coeffs` requires ≥1 relation between entities (its pivot-
    # propagation has nothing to propagate otherwise) and declines a purely independent-anchors system
    # ("Jeremy buys 3 bags... Stacy buys 4 bags... they need 10 total, how many should Emily buy?" — no
    # ratio/offset relates Jeremy, Stacy, or Emily to each other at all). Extract bare per-name anchors
    # directly instead: every "rest" premise must be a single-name anchor or purely declarative (no
    # relations at all — a 2-name premise here means a REAL relation exists and this fallback doesn't apply).
    anchors = {}
    for p in rest:
        rp = analyze(p)
        if not any(s in u.features.get("senses", []) for u in rp.units
                   for s in ("value", "multiplier", "comparative", "interrogative", "aggregator")) \
                and not any(_fraction_parts(u.surface) is not None for u in rp.units) \
                and not p.rstrip().endswith("?") \
                and not (_name_count(rp) == 2 and re.search(r"\b(as|than)\b", p.lower())):
            continue                             # purely declarative — skip, doesn't hide a number (an
            #                                       interrogative/aggregator word, a trailing "?", or a
            #                                       2-name "as"/"than" clause all mean REAL info is present
            #                                       — never skip those, see the sibling gate in
            #                                       `_anchored_affine_coeffs`)
        if _name_count(rp) != 1:
            return None                          # a relation (or an ambiguous multi-name clause) exists —
        anc = _anchor_fact(rp)                   # `_anchored_affine_coeffs` already tried and failed above,
        if anc is None:                          # so this ISN'T the no-relation shape after all
            return None
        e, v = anc
        if e in anchors:
            return None
        anchors[e] = v
    covered = [e for e in tot_names if e in anchors]
    residual = [e for e in tot_names if e not in anchors]
    if len(residual) != 1 or residual[0] != asked:
        return None
    return _compute(f"{_num(tot_val)} - ({' + '.join(_num(anchors[e]) for e in covered)})")


def _two_relation_system(premises: list, question: str):
    """TWO relations between the SAME entity PAIR, with NO anchor or total — a self-contained 2×2 linear
    system. "Brett has 24 more blue marbles than red marbles. He has 5 times as many blue marbles as red
    marbles. How many red marbles?" → blue = red+24 AND blue = 5·red, so red = (0−24)/(1−5) = 6. EVERY premise
    must be an affine relation on the SAME (subject, standard) pair with DIFFERENT factors — parallel (k1==k2)
    has no unique solution (two same-slope offsets at different times, e.g. "30 more … currently" / "80 more
    … 2 years ago", correctly decline). Tightly gated: exactly two relations, nothing else, and the question
    must ask for one of the two entities (works for a common-noun pair via `_asked_noun_entity`, or a named
    pair via the question's name)."""
    rels = []
    for p in premises:
        rel = _affine_relation(analyze(p))
        if rel is None:
            return None                                      # every premise must be one of the two relations
        rels.append(rel)
    if len(rels) != 2:
        return None
    (s1, k1, t1, c1), (s2, k2, t2, c2) = rels
    if not (s1 == s2 and t1 == t2 and s1 != t1) or k1 == k2:
        return None                                          # not the same pair, or parallel (no solution)
    std = _compute(f"({_num(c2)} - ({_num(c1)})) / ({_num(k1)} - ({_num(k2)}))")
    subj = _compute(f"{_num(k1)} * {_num(std)} + ({_num(c1)})")
    # the asked entity is whichever of the pair the question names — a common-noun subtype (`_asked_noun_
    # entity` / a noun key) OR a name. Match against {s1, t1} directly (a bare `_asked_noun_entity` can return
    # the MEASURE noun, e.g. "coins", for a NAMED pair — so try all candidates and keep the one that IS an entity).
    qr = analyze(question)
    cands = [_asked_noun_entity(qr)] \
        + [_entity(u) for u in qr.units if "name" in u.features.get("senses", [])] \
        + [_noun_entity_key(u) for u in qr.units if "noun" in u.features.get("senses", [])]
    asked = next((a for a in cands if a in (s1, t1)), None)
    if asked == t1:
        return std
    if asked == s1:
        return subj
    return None                                              # asks for neither entity — not this shape


_GOAL_VERBS = {"collect", "save", "earn", "raise", "reach", "gather", "sell", "read", "make", "buy",
               "score", "run", "walk", "swim", "bake", "catch", "pick", "plant", "build", "write",
               "complete", "finish", "produce", "grow", "donate", "sew", "knit", "get"}


def _target_contributions_system(premises: list, question: str):
    """TARGET minus CONTRIBUTIONS: a stated GOAL to reach ("need to collect 100 cans") minus the amounts
    gathered so far, answering "how many MORE are still needed". "Alyssa and Abigail need to collect 100
    empty cans. Alyssa collected 30, Abigail collected 43. How many more should they collect?" → 100−73 = 27.
    Read from the RAW premise values because the general fold drops them (the elided-object "collected 30" is
    a bare Predication, no measure). Distinguished from the "needs N MORE to HAVE k× Y" DEFICIT idiom (which
    it must NOT touch — Amanda/Lena) by a target premise with "need … to <goal-verb>" and NO "more"/"to have".
    Tightly gated: EVERY premise is the goal (exactly one value), a bare name+count contribution (1-2 values,
    no "more"/"need"), or value-free — anything else declines."""
    ql = question.lower()
    if "how many more" not in ql and "how much more" not in ql:
        return None
    target, contrib = None, []
    for p in premises:
        pl = f" {p.lower()} "
        rp = analyze(p)
        vs = [u.features["value"] for u in rp.units if "value" in u.features.get("senses", [])]
        nm = [u for u in rp.units if "name" in u.features.get("senses", [])]
        is_goal = "need" in pl and " to " in pl and "more" not in pl and "to have" not in pl \
            and any(f" {g}" in pl for g in _GOAL_VERBS)
        if is_goal:
            if target is not None or len(vs) != 1:
                return None                                  # two goals / an ambiguous target → not this shape
            target = vs[0]
        elif nm and 1 <= len(vs) <= 2 and "more" not in pl and "need" not in pl:
            contrib.extend(vs)                               # a per-name amount gathered so far
        elif not vs:
            continue                                         # a value-free premise (context) is harmless
        else:
            return None                                      # an unaccounted value → decline
    if target is None or not contrib:
        return None
    return _compute(f"{_num(target)} - ({' + '.join(_num(c) for c in contrib)})")


def _total_between_residual_system(premises: list, question: str):
    """A category TOTAL split "IN TOTAL BETWEEN" named parts, some parts stated, asking the RESIDUAL part:
    "Mark has 12 candy bars in total between Mars bars, Snickers, and Butterfingers. He has 3 Snickers and 2
    Mars bars. How many Butterfingers does he have?" → 12 − (3+2) = 7. Reads raw premise values (the general
    fold can't attach the brand-name parts to the category total). Tightly gated by the "in total between/
    among" cue; every other premise is a bare part-count or value-free. Same arithmetic as
    `_target_contributions_system` (total − Σ parts), a DIFFERENT surface — the general "total − Σ" shape is
    too common to trust, so each keeps its OWN specific cue."""
    if "how many" not in question.lower():
        return None
    total, parts = None, []
    for p in premises:
        pl = f" {p.lower()} "
        vs = [u.features["value"] for u in analyze(p).units if "value" in u.features.get("senses", [])]
        if len(vs) == 1 and ("in total between" in pl or "in total among" in pl):
            if total is not None:
                return None
            total = vs[0]
        elif vs and "more" not in pl and "need" not in pl and "total" not in pl:
            parts.extend(vs)
        elif not vs:
            continue
        else:
            return None
    if total is None or not parts:
        return None
    return _compute(f"{_num(total)} - ({' + '.join(_num(c) for c in parts)})")


def _inject_bare_ages(prem_readings: list, all_readings: list, facts_of: list, context: list) -> None:
    """BARE AGE — in an AGE-typed problem ("…as old as…", "older/younger than…"), a copula "X is N" with no
    unit ("If Job is 5") states X's AGE = N. The bare value quantifies no noun, so `_quantity` emits nothing
    and a relational-age chain can't ground. A bare equation has no dimension of its own, so infer it from
    the problem's age framing: inject Quantity(X, year, N), letting the fixpoint chain (Job 5 → Stephanie 20
    → Freddy 18). GATED on age cues so a bare "X is N" in a non-age problem is untouched. Mutates facts_of +
    context in place; shared by solve() and the CLI paragraph loop so they don't diverge (cf. #104)."""
    if not any(_key(u.surface) in ("old", "older", "younger", "age", "ages")
               for rp in all_readings for u in rp.units):
        return
    for i, rp in enumerate(prem_readings):
        if any(isinstance(f, Quantity) for f in (facts_of[i] or [])):
            continue                                     # already produced a quantity → not a bare equation
        verbs = [u for u in rp.units if "verb" in u.features.get("senses", [])]
        if len(verbs) != 1 or _key(verbs[0].surface) not in ("is", "are", "was", "were"):
            continue
        subj = _follow(verbs[0], "subject")
        if subj is None or "name" not in subj.features.get("senses", []):
            continue
        bare = next((u for u in rp.units if "value" in u.features.get("senses", [])
                     and "measure" not in u.features and _follow(u, "quantifies") is None), None)
        if bare is not None:
            q = Quantity(_entity(subj), ("year", frozenset()), bare.features["value"], "be")
            facts_of[i] = (facts_of[i] or []) + [q]
            context.append(q)


_DEPLETION_VERBS = {"take", "eat", "remove", "drink", "consume", "use", "sell", "spend", "lose", "pick"}

# --- system family: scene depletion & backward inversion ------------------------------------

def _scene_depletion(question: str, context: list, prem_readings: list):
    """A POOL depleted by takes — "There were 349 pieces of candy in a bowl. Talitha took 108, Solomon took
    153. How many pieces are left?" → 349 − 108 − 153 = 88. The existential "there were N X" stores N
    INSTANCES (a base count), not a holding Quantity, and each take is credited to the takER, so the
    remainder fold finds no single owner to net. Compute base(#instances of the measure) − Σ(depletion-verb
    Quantities of the measure). GATED: a left/remain question; an instance-base; EVERY measure-Quantity is a
    depletion verb (an addition would break the plain base − Σ); and NO unused given — every stated premise
    number must be the base or a depletion, else a conversion/per-unit count ("128 ounces in a GALLON … 3
    gallons", "8 slices in a PIZZA … 2 pizzas") means the base needs computing → decline. None otherwise."""
    ql = question.lower()
    if "left" not in ql and "remain" not in ql:
        return None
    m = _queried_measure(question)
    if m is None:
        return None
    base = sum(1 for f in context if isinstance(f, tuple) and f[0] == m[0])
    allq = [f for f in context if isinstance(f, Quantity) and f.measure == m and f.amount is not None]
    depl = [f for f in allq if f.verb in _DEPLETION_VERBS]
    if base <= 0 or not depl or len(depl) != len(allq):   # all measure-quantities must be depletions
        return None
    used = {round(float(base), 6)} | {round(float(f.amount), 6) for f in depl}
    stated = {round(float(u.features["value"]), 6) for rp in prem_readings for u in rp.units
              if "value" in u.features.get("senses", []) and u.features.get("value") is not None}
    if stated - used:                                     # a conversion factor / container count → the base
        return None                                       # isn't the plain instance total → decline
    return _compute(f"{base} - (" + " + ".join(_num(f.amount) for f in depl) + ")")


def _backward_depletion(premises: list, question: str):
    """The BACKWARD twin of `_scene_depletion`: an UNKNOWN initial pool depleted by spends to a KNOWN final →
    initial = final + Σ(depletions). "There was some money in the cookie jar. Doris spent $6. Martha spent
    half as much [$3]. There were $15 left. How much was in the jar at first?" → 15 + 6 + 3 = 24. Self-contained
    (re-learns premises, like `_sum_ratio_system`) so it can run before GUARD 8's "at first" decline. TIGHTLY
    GATED — the inversion class is firewall-risky: the question asks an ORIGINAL value; a single FINAL holding
    flagged by "left"/"remain"/"now"; every OTHER measure-quantity is a DEPLETION verb (NO gain — "gave him"/
    received/added would raise the pool, so initial = final + Σ would over-count: Randy 3500≠3000); and NO
    depletion references the running total ("half of the REMAINING" — unresolvable backward: Isabel). None
    otherwise."""
    pl = " ".join(premises).lower()
    if not any(p in pl for p in ("left", "remain", "now")):
        return None
    # a GAIN to the pool (received / "gave him" / added / more) breaks the losses-only formula → not this shape
    if any(w in pl for w in ("received", "receive", "got ", "gained", "gain ", "added", " more ",
                             "gave him", "gave her", "gives him", "gives her")):
        return None
    if any(w in pl for w in ("the remaining", "the rest", "what was left", "what is left", "what's left")):
        return None                                          # a running-total-dependent depletion (Isabel)
    disc, ctx = [], []
    for p in premises:
        rp = analyze(p)
        f = learn(p, disc, ctx)
        # GUARD-4-like: a premise STATING a multiplier/fraction/percent but producing NO quantity dropped an
        # operation we can't fold ("buys another HALF the amount he had left" → a fraction-of-remaining GAIN
        # that didn't resolve; Tim 30≠22). Decline rather than commit an inversion missing that operation.
        if any(s in u.features.get("senses", []) for u in rp.units for s in ("multiplier", "percent")) \
                and not any(isinstance(x, Quantity) for x in (f or [])):
            return None
        if f:
            ctx += f
    qs = [f for f in ctx if isinstance(f, Quantity) and f.amount is not None]
    measures = {f.measure for f in qs}
    if len(measures) != 1 or not qs:
        return None
    # the FINAL holding: a non-depletion quantity whose premise carried the "left"/"remain"/"now" flag.
    finals = [f for f in qs if f.verb not in _DEPLETION_VERBS]
    depl = [f for f in qs if f.verb in _DEPLETION_VERBS]
    if len(finals) != 1 or not depl:                         # exactly one final; ≥1 depletion; nothing else
        return None
    if len(finals) + len(depl) != len(qs):                   # every quantity is final-or-depletion (no gain)
        return None
    # NO-UNUSED-GIVEN (mirrors `_scene_depletion`): every STATED money value must surface as the final or a
    # depletion. A dropped value means the parse missed an operation (Josh's 2nd "spent $1.25" lost to subject-
    # elision → 6+1.75=7.75≠9) and Σ would be incomplete → DECLINE rather than commit a partial inversion.
    used = {round(float(finals[0].amount), 6)} | {round(float(f.amount), 6) for f in depl}
    stated = {round(float(u.features["value"]), 6) for p in premises for u in analyze(p).units
              if "value" in u.features.get("senses", []) and u.features.get("value") is not None}
    if stated - used:
        return None
    return _compute(f"{_num(finals[0].amount)} + (" + " + ".join(_num(f.amount) for f in depl) + ")")


def _backward_inversion(premises: list, question: str):
    """A single-entity BACKWARD inversion with GAINS and losses → initial = final − Σ(signed deltas). "Randy had
    some money. Smith gave him $200 [+200]. Randy gave Sally $1200 [−1200]. $2000 left. How much at first?" →
    2000 − (200 − 1200) = 3000. Distinct from `_backward_depletion` (a multi-entity LOSSES-ONLY pool): here the
    operations are the ASKED entity's OWN signed deltas — the dative now captures "Smith gave HIM $200" as Randy
    +200, so the gain that made #4b decline (its no-gain gate) is finally representable. Self-contained. GATED
    like the depletion: a "left"/"now"/"in the end" final, exactly one final + ≥1 delta of one measure, no dropped
    multiplier (fraction-of-remaining), and NO unused given (every stated value captured) → else decline."""
    qr = analyze(question)
    qnames = [u for u in qr.units if "name" in u.features.get("senses", [])]
    if not qnames:
        return None
    asked = _entity(qnames[0])
    disc, ctx, prem_facts = [], [], []
    for p in premises:
        rp = analyze(p)
        f = learn(p, disc, ctx) or []
        if any(s in u.features.get("senses", []) for u in rp.units for s in ("multiplier", "percent")) \
                and not any(isinstance(x, Quantity) for x in f):
            return None                                      # a dropped fraction-of-remaining operation → decline
        prem_facts.append((p, f))
        ctx += f
    aq = [(p, f) for (p, fs) in prem_facts for f in fs
          if isinstance(f, Quantity) and f.entity == asked and f.amount is not None]
    if not aq or len({f.measure for (p, f) in aq}) != 1:
        return None
    finals = [f for (p, f) in aq if f.verb in ("have", "be")          # the KNOWN final, from a "left"/"now"/
              and any(w in p.lower() for w in ("left", "remain", "now", "in the end", "end of"))]   # "end" cue
    deltas = [f for (p, f) in aq if f.verb not in ("have", "be") and f not in finals]
    if len(finals) != 1 or not deltas:
        return None
    used = {round(float(finals[0].amount), 6)} | {round(float(d.amount), 6) for d in deltas}
    stated = {round(float(u.features["value"]), 6) for p in premises for u in analyze(p).units
              if "value" in u.features.get("senses", []) and u.features.get("value") is not None}
    if stated - used:                                        # a dropped operation → an incomplete inversion
        return None
    delta_sum = " + ".join(f"{_verb_sign(d.verb)} * {_num(d.amount)}" for d in deltas)
    return _compute(f"{_num(finals[0].amount)} - ({delta_sum})")


# NB: no "rose"/"risen" — they collide with the common name "Rose" (a false UP cue that breaks the XOR).
_PCT_UP = {"raise", "raised", "raises", "increase", "increased", "increases"}
_PCT_DOWN = {"discount", "discounts", "off", "sale", "decrease", "decreased", "decreases",
             "down", "lower", "lowered", "reduced", "reduce", "cheaper"}
_PCT_Q_ACCEPT = {"pay", "pays", "paid", "new", "final", "cost", "costs", "now", "charge"}
# inverse (find-the-whole) / aggregate (multi-period) / count question words → not the new-value shape.
_PCT_Q_BLOCK = {"original", "save", "saved", "savings", "total", "left", "remain", "remaining",
                "remained", "difference", "many", "before", "without", "raise"}

# --- system family: percent + self-multiple -------------------------------------------------

def _self_multiple_sum(premises: list, question: str):
    """SELF-REFERENTIAL MULTIPLE + SUM — one subject does an amount over two periods, the second a MULTIPLE of
    the first (the multiplier refers BACK to the first, not to another entity): "Roger rode 2 miles this
    morning, then 5 times THAT AMOUNT in the evening. How many miles total?" → 2 + 5·2 = 2·(1+5) = 12; "Tom
    read 10 pages … and twice AS MANY in the evening" → 10·3 = 30. TIGHTLY gated: EXACTLY one base value + one
    multiplier + one subject NAME (a second name would make "as many as <Y>" a cross-entity ratio, not
    anaphoric); an anaphoric back-reference ("that amount/much/many" or a bare "as many/as much" — which, with
    a single name, cannot be "as <name>"); a two-period join ("and"/"then"); and a TOTAL question (bare "how
    many <M> did <subj> VERB", or an explicit total cue — never a single-period ask). Answer = base·(1+k)."""
    readings = [analyze(p) for p in premises]
    text = " ".join(premises).lower()
    # Require the EXPLICIT back-reference "that amount/much/many". A bare "as many/as much" is unreliable — it
    # may carry a STANDARD ("as many fish AS cats and dogs combined" → aggregate ratio, Ed 15) or sit in a RATE
    # ("$600 every weekday and twice as much on the weekend" → per-day, restaurant) — both mis-fire as base·(1+k).
    anaphor = any(ph in text for ph in ("that amount", "that much", "that many"))
    if not anaphor or not (" and " in text or " then " in text):
        return None
    vals = [u for rp in readings for u in rp.units if "value" in u.features.get("senses", [])
            and u.features.get("value") is not None]
    mults = [u for rp in readings for u in rp.units if "multiplier" in u.features.get("senses", [])]
    names = {_entity(u) for rp in readings for u in rp.units if "name" in u.features.get("senses", [])}
    if len(vals) != 1 or len(mults) != 1 or len(names) != 1:
        return None
    qr = analyze(question)
    if any("value" in u.features.get("senses", []) and u.features.get("value") is not None for u in qr.units):
        return None
    # TOTAL question only — a bare "how many <M> did <subj> VERB" (no single-period qualifier) or an explicit
    # total cue. A period word ("evening", "Tuesday") in the question asks ONE part → out of scope → decline.
    ql = question.lower()
    period_words = ("morning", "afternoon", "evening", "night", "monday", "tuesday", "wednesday",
                    "thursday", "friday", "saturday", "sunday", "first", "second")
    if any(w in ql for w in period_words):
        return None
    mu = mults[0]
    k = (mu.features["fraction"][0] / mu.features["fraction"][1]) if "fraction" in mu.features \
        else mu.features.get("value")
    if k is None:
        return None
    base = vals[0].features["value"]
    r = _compute(f"{_num(base)} * {_num(1 + k)}")
    return round(r, 9) if isinstance(r, float) else r


def _percent_change(premises: list, question: str):
    """Apply a single PERCENT CHANGE to a stated money base and report the NEW value — "a bicycle sold for
    $220 last year was increased by 15%. What is the new price?" → 220 × 1.15 = 253; "$2000 ticket, 30%
    discount. How much does he pay?" → 2000 × 0.70 = 1400. TIGHTLY gated to the clean 1-step shape: EXACTLY
    one money value (a value-sense unit with a measure) and EXACTLY one percent across the premises (a 3rd
    number ⇒ multi-step ⇒ decline); EXACTLY one direction cue (raise/increase ↑ XOR discount/off/down ↓ —
    "N% more/less than the ORIGINAL" is the inverse find-the-whole shape, deliberately NOT a cue here); and a
    question asking for the NEW value (an accept word pay/new/cost, and none of the inverse/aggregate/count
    words original/save/total/left/many). None if any gate fails — every other percent problem stays declined."""
    readings = [analyze(p) for p in premises]
    pcts = [u for rp in readings for u in rp.units if "percent" in u.features.get("senses", [])]
    # EVERY value-sense number counts (incl. bare object counts like "3 shirts" that lack a measure) — a 3rd
    # number means the problem is multi-step (per-item, quantity) ⇒ decline. The single base must be money.
    vals = [u for rp in readings for u in rp.units if "value" in u.features.get("senses", [])
            and u.features.get("value") is not None]
    if len(pcts) != 1 or len(vals) != 1 or "measure" not in vals[0].features:
        return None
    qr = analyze(question)                               # a NUMBER in the question (e.g. "buy 2 pounds … for
    if any("value" in u.features.get("senses", []) and u.features.get("value") is not None   # a 4 member
           for u in qr.units):                           # family") means it scales the new value ⇒ multi-step
        return None
    keys = {_key(u.surface) for rp in readings for u in rp.units}
    up, down = keys & _PCT_UP, keys & _PCT_DOWN
    if bool(up) == bool(down):                           # need EXACTLY one direction (XOR); ambiguous ⇒ decline
        return None
    qkeys = {_key(w) for w in question.lower().split()}
    if not (qkeys & _PCT_Q_ACCEPT) or (qkeys & _PCT_Q_BLOCK):
        return None
    base, p = vals[0].features["value"], pcts[0].features["value"]
    factor = 1 + p if up else 1 - p
    r = _compute(f"{_num(base)} * {_num(factor)}")       # snap binary drift (early return skips solve()'s snap)
    return round(r, 9) if isinstance(r, float) else r


_GROUP_PAIRS = [("boys", "girls"), ("men", "women"), ("male", "female"), ("males", "females"),
                ("boy", "girl"), ("man", "woman"), ("gentlemen", "ladies")]
_GROUP_WORDS = {w for pr in _GROUP_PAIRS for w in pr}


def _group_relation(a: str, b: str):
    """'same' if the two group words are identical, 'comp' if they are a known complementary pair
    (boys/girls, men/women, …), else None (unrelated → can't infer a fraction)."""
    if a == b:
        return "same"
    return "comp" if any({a, b} == {x, y} for x, y in _GROUP_PAIRS) else None


def _group_after_copula(r: "Reading"):
    """The first partition-group word (boys/girls/…) appearing after a copula in a reading — the predicate
    of "P% … ARE boys". None if there's no such group noun."""
    for i, u in enumerate(r.units):
        if _key(u.surface) in ("are", "is", "were", "was"):
            g = next((_key(v.surface) for v in r.units[i + 1:] if _key(v.surface) in _GROUP_WORDS), None)
            if g is not None:
                return g
    return None


def _percent_population(premises: list, question: str):
    """A TWO-GROUP population partition — a percent splits a population into complementary groups (boys/girls,
    men/women); recover the asked group. Every group's count is total × fraction, where fraction = P if the
    group is the percent's group, else 1−P (the complement). Two entry points share the formula: a TOTAL is
    given ("50 people, 30% are boys → girls = 50 × 0.70 = 35"), or ONE GROUP'S COUNT is given ("60% are girls,
    boys = 300 → girls = 300 × 0.6/0.4 = 450", since total = C/f_base). TIGHTLY gated — exactly one number +
    one percent in the premises (nothing in the question), the percent's group and the question's group both
    resolvable to same/complement of each other, and a recognized base. None otherwise."""
    readings = [analyze(p) for p in premises]
    pcts = [(r, u) for r in readings for u in r.units if "percent" in u.features.get("senses", [])]
    vals = [(r, u) for r in readings for u in r.units if "value" in u.features.get("senses", [])
            and u.features.get("value") is not None]
    if len(pcts) != 1 or len(vals) != 1:
        return None
    qr = analyze(question)
    if any("value" in u.features.get("senses", []) and u.features.get("value") is not None for u in qr.units):
        return None
    P = pcts[0][1].features["value"]
    G1 = _group_after_copula(pcts[0][0])                 # the percent's group ("… are boys")
    Gq = next((_key(u.surface) for u in qr.units if _key(u.surface) in _GROUP_WORDS), None)   # asked group
    if G1 is None or Gq is None:
        return None

    def frac(g):
        rel = _group_relation(g, G1)
        return P if rel == "same" else (1 - P) if rel == "comp" else None

    fq = frac(Gq)
    if fq is None or not 0 < fq < 1:
        return None
    val_r, val_u = vals[0]
    C = val_u.features["value"]
    Gc = next((_key(u.surface) for u in val_r.units if _key(u.surface) in _GROUP_WORDS), None)
    if Gc is None:                                        # the number is the TOTAL population → group = N × f
        r = _compute(f"{_num(C)} * {_num(fq)}")
    else:                                                 # the number is ONE group's count → total = C / f_base
        fc = frac(Gc)
        if fc is None or fc <= 0:
            return None
        r = _compute(f"{_num(C)} * {_num(fq)} / {_num(fc)}")
    return round(r, 9) if isinstance(r, float) else r


def _percent_original(premises: list, question: str):
    """The INVERSE of `_percent_change`: a known money value is a PERCENT of an unknown ORIGINAL → recover the
    original by division. Three frames (by how the percent relates the value to the original): "$15000 cost
    40% OF the original → 15000 / 0.40 = 37500"; "$480 at a 20% DISCOUNT → 480 / (1 − 0.20) = 600"; "$7500 is
    25% LESS than the original → 480 / 0.75"; "$X is 25% MORE than the original → X / 1.25". TIGHTLY gated like
    the forward twin — exactly one money value + one percent (no other number in premises OR question ⇒ decline),
    a question asking for the ORIGINAL (the token that makes the forward resolver decline, so the two never
    collide), and a recognized frame. None otherwise."""
    if "original" not in {_key(w) for w in question.lower().split()}:
        return None
    readings = [analyze(p) for p in premises]
    pcts = [(rp, i, u) for rp in readings for i, u in enumerate(rp.units)
            if "percent" in u.features.get("senses", [])]
    vals = [u for rp in readings for u in rp.units if "value" in u.features.get("senses", [])
            and u.features.get("value") is not None]
    if len(pcts) != 1 or len(vals) != 1 or "measure" not in vals[0].features:
        return None
    qr = analyze(question)
    if any("value" in u.features.get("senses", []) and u.features.get("value") is not None for u in qr.units):
        return None
    rp, pi, punit = pcts[0]
    p, x = punit.features["value"], vals[0].features["value"]
    pnext = _key(rp.units[pi + 1].surface) if pi + 1 < len(rp.units) else ""
    keys = {_key(u.surface) for r in readings for u in r.units}
    if pnext == "of":                                    # "P% OF the original" → X = P · original
        factor = p
    elif keys & {"more", "increased", "increase", "higher"}:   # "P% MORE than original" → X = (1+P) · original
        factor = 1 + p
    elif keys & {"discount", "off", "sale", "less", "decrease", "decreased", "lower", "reduced", "cheaper"}:
        factor = 1 - p                                   # "P% DISCOUNT / LESS than original" → X = (1−P) · original
    else:
        return None
    if factor <= 0:
        return None
    r = _compute(f"{_num(x)} / {_num(factor)}")
    return round(r, 9) if isinstance(r, float) else r


def _proportion(premises: list, question: str):
    """A direct PROPORTION — "If 12 bags of oranges weigh 24 pounds, how much do 8 bags weigh?" → 24 × 8/12 =
    16. A premise pairs a COUNT (12 bags) with a measure (24 pounds) for the same entity and verb; the
    question gives a NEW count (8 bags) and asks "how MUCH" the measure is → measure × new_count / count.
    TIGHTLY gated: a "how much" question (asking an amount, not "how many <noun>"), one value quantifying a
    count-noun + a matching verb; a premise with exactly two same-entity, same-verb quantities whose heads
    are the count and a different measure. None otherwise."""
    qr = analyze(question)
    if not (any("interrogative" in u.features.get("senses", []) for u in qr.units)
            and any(_key(u.surface) == "much" for u in qr.units)):   # "how MUCH" → an amount, not a count
        return None
    qval = next((u for u in qr.units if "value" in u.features.get("senses", [])
                 and _follow(u, "quantifies") is not None), None)
    qverb = next((_lemma(u.surface) for u in qr.units if "verb" in u.features.get("senses", [])
                  and _key(u.surface) not in ("is", "are", "was", "were", "do", "does", "did")), None)
    if qval is None or qverb is None:
        return None
    count_head = _descriptor(_follow(qval, "quantifies"))[0]
    for p in premises:
        qs = [f for f in learn(p) if isinstance(f, Quantity) and f.amount is not None]
        if len(qs) != 2 or qs[0].entity != qs[1].entity:
            continue
        cnt = next((f for f in qs if f.measure[0] == count_head and f.verb == qverb), None)
        oth = next((f for f in qs if f.measure[0] != count_head and f.verb == qverb), None)
        if cnt is None or oth is None or cnt.amount == 0:
            continue
        return _compute(f"{_num(oth.amount)} * {_num(qval.features['value'])} / {_num(cnt.amount)}")
    return None

# --- system family: rates (per-unit extrapolation / difference / sum / race / remainder) ----

def _rate_extrapolation(premises: list, question: str, context: list):
    """RATE × DURATION-IN-QUESTION — "Luis drives 80 miles in 2 hours. How far will he go in 15 minutes?" →
    (80 per 2 hours) × (15 min → 0.25 hr) ÷ 2 = 10. A single Rate in context + a question asking "how
    far/much/many … in N <time>" → rate.amount × (N converted to the rate's per_unit) ÷ rate.per_amount.
    Gated: exactly one rate, the question is a how-far/much/many interrogative carrying a duration value in a
    time-unit (the EXTRAPOLATION target), and that unit converts to the rate's per_unit. None otherwise."""
    if len(context) != 1 or not isinstance(context[0], Rate):
        return None                                      # a PURE single-rate problem only — any other fact
        #                                                  (a count, a second rate, a multi-period split) means
        #                                                  the answer isn't a bare rate×duration (Tammy's
        #                                                  trees→packs→$, Ralph's weekday+weekend, Mark's
        #                                                  weekly increase all commit a partial otherwise).
    rate = context[0]
    prem_vals = [u.features["value"] for p in premises for u in analyze(p).units
                 if "value" in u.features.get("senses", [])]
    if any(abs(v - rate.amount) > 1e-9 and abs(v - rate.per_amount) > 1e-9 for v in prem_vals):
        return None                                      # an UNUSED premise number (Mark's weekly +4, Ralph's
        #                                                  weekend 6) means the answer isn't a bare rate ×
        #                                                  duration — decline (the engine's unused-given rule)
    qr = analyze(question)
    if not (any("interrogative" in u.features.get("senses", []) for u in qr.units)
            and any(_key(u.surface) in ("far", "much", "many", "long") for u in qr.units)):
        return None
    dur = next((u for u in qr.units if "value" in u.features.get("senses", [])
                and _follow(u, "quantifies") is not None
                and _descriptor(_follow(u, "quantifies"))[0] in TIME_UNITS), None)
    if dur is None:
        return None
    du = _descriptor(_follow(dur, "quantifies"))[0]
    if rate.per_amount == 1 and du == rate.per_unit:
        return None                                      # the plain "amount × duration" (matching unit,
        #                                                  per_amount 1) is the existing rate×duration path's
        #                                                  job — and it handles first-year exceptions etc. that
        #                                                  this bare product would clobber (Adam 490, not 500)
    if du == rate.per_unit:
        per = _num(dur.features["value"])
    elif (du, rate.per_unit) in CONVERSIONS:
        per = f"{_num(dur.features['value'])} * {_num(CONVERSIONS[(du, rate.per_unit)])}"
    else:
        return None
    return _compute(f"{_num(rate.amount)} * ({per}) / {_num(rate.per_amount)}")


def _rate_compound(premises: list, question: str, context: list):
    """COMPOUND-DURATION rate — "Lisa walks 10 meters each minute. Every day she walks for an hour. How many
    meters in two days?" → 10/min × (1 hour → 60 min) × 2 days = 1200. A single work/distance rate, a premise
    giving a per-PERIOD activity duration ("for a/N <dur> … every/each <period>"), and the question giving a
    PERIOD count ("in N <period>"). answer = rate × (duration → per_unit) × periods. None otherwise."""
    rates = [f for f in context if isinstance(f, Rate)]
    if len(rates) != 1 or len(context) != 1:
        return None
    rate = rates[0]
    dur_amt = dur_u = period_u = None
    for p in premises:
        pr = analyze(p)
        forp = next((u for u in pr.units if _key(u.surface) == "for"
                     and "preposition" in u.features.get("senses", [])), None)
        if forp is None:
            continue
        fi = pr.units.index(forp)
        tu = next((u for u in pr.units[fi + 1:fi + 4] if "noun" in u.features.get("senses", [])
                   and _descriptor(u)[0] in TIME_UNITS), None)
        if tu is None:
            continue
        vu = next((u.features["value"] for u in pr.units if "value" in u.features.get("senses", [])
                   and _follow(u, "quantifies") is tu), None)
        if vu is None:                                    # "for AN hour" → a single unit
            ti = pr.units.index(tu)
            vu = 1 if ti > 0 and _key(pr.units[ti - 1].surface) in ("a", "an") else None
        pu = next((_descriptor(pr.units[k + 1])[0] for k in range(len(pr.units) - 1)
                   if _key(pr.units[k].surface) in ("every", "each")
                   and _descriptor(pr.units[k + 1])[0] in TIME_UNITS), None)
        if vu is not None and pu is not None:
            dur_amt, dur_u, period_u = vu, _descriptor(tu)[0], pu
            break
    if dur_amt is None:
        return None
    qr = analyze(question)
    num = next((u.features["value"] for u in qr.units if "value" in u.features.get("senses", [])
                and _follow(u, "quantifies") is not None
                and _descriptor(_follow(u, "quantifies"))[0] == period_u), None)
    if num is None:
        return None
    if dur_u == rate.per_unit:
        per = _num(dur_amt)
    elif (dur_u, rate.per_unit) in CONVERSIONS:
        per = f"{_num(dur_amt)} * {_num(CONVERSIONS[(dur_u, rate.per_unit)])}"
    else:
        return None
    return _compute(f"{_num(rate.amount)}/{_num(rate.per_amount)} * ({per}) * {_num(num)}")


def _rate_race(premises: list, question: str, context: list):
    """RATE RACE (inversion difference) — "Apple runs 3 mph, Mac runs 4 mph. In minutes, how much FASTER will
    Mac run a 24-mile race?" → 24/3 − 24/4 = 2 hr = 120 min. Two rates (same measure & per_unit), a TARGET
    distance/amount in the question (a value of the rates' measure), and a faster/longer cue with an asked
    time-unit → (target/slow − target/fast) converted to that unit. None otherwise."""
    rates = [f for f in context if isinstance(f, Rate)]
    if len(rates) != 2 or len(context) != 2:
        return None
    if rates[0].measure != rates[1].measure or rates[0].per_unit != rates[1].per_unit:
        return None
    qr = analyze(question)
    if not any(_key(u.surface) in ("faster", "longer", "slower", "quicker") for u in qr.units):
        return None
    target = next((u.features["value"] for u in qr.units if "value" in u.features.get("senses", [])
                   and _follow(u, "quantifies") is not None
                   and _descriptor(_follow(u, "quantifies"))[0] == rates[0].measure[0]), None)
    au = next((_descriptor(u)[0] for u in qr.units if "noun" in u.features.get("senses", [])
               and _descriptor(u)[0] in TIME_UNITS), None)
    if target is None or au is None:
        return None
    r0, r1 = rates[0].amount / rates[0].per_amount, rates[1].amount / rates[1].per_amount
    slow, fast = (rates[0], rates[1]) if r0 < r1 else (rates[1], rates[0])
    diff = f"{_num(target)} / ({_num(slow.amount)}/{_num(slow.per_amount)}) " \
           f"- {_num(target)} / ({_num(fast.amount)}/{_num(fast.per_amount)})"
    if au == slow.per_unit:
        return _compute(diff)
    if (slow.per_unit, au) in CONVERSIONS:               # time difference in per_unit → the asked unit
        return _compute(f"({diff}) * {_num(CONVERSIONS[(slow.per_unit, au)])}")
    return None


def _rate_remainder(premises: list, question: str, context: list):
    """RATE REMAINDER — "Two dogs walk a TOTAL of 70 miles a week. The first walks 2 miles a day. How many
    miles a day does the OTHER walk?" → 70/week (=10/day) − 2/day = 8/day. Exactly two rates (same measure);
    one is the group TOTAL (its premise carries total/combined/together), the other a component; the question
    asks the remaining component in some per_unit. answer = (total − component), each normalized to that
    per_unit. None otherwise."""
    rates = [f for f in context if isinstance(f, Rate)]
    if len(rates) != 2 or rates[0].measure != rates[1].measure:
        return None
    if any(isinstance(f, Quantity) and f.amount is not None and f.measure[0] == rates[0].measure[0]
           for f in context):
        return None                                      # an extra quantity OF THE RATE'S MEASURE → multi-step
        #                                                  (a bare count like "two dogs" is a different measure)

    def from_total_premise(rate):
        for p in premises:
            if any(w in p.lower() for w in ("total", "combined", "together")) \
                    and any(isinstance(f, Rate) and abs(f.amount - rate.amount) < 1e-9 for f in learn(p)):
                return True
        return False

    total = next((r for r in rates if from_total_premise(r)), None)
    if total is None:
        return None
    comp = next(r for r in rates if r is not total)
    qr = analyze(question)                                # the asked per_unit: "how many miles A DAY"
    pu = next((_descriptor(qr.units[k + 1])[0] for k in range(len(qr.units) - 1)
               if _key(qr.units[k].surface) in ("a", "an", "per", "each", "every")
               and _descriptor(qr.units[k + 1])[0] in TIME_UNITS), None)
    if pu is None:
        return None

    def per(rate):                                        # the rate's amount expressed PER `pu`
        base = f"{_num(rate.amount)}/{_num(rate.per_amount)}"
        if rate.per_unit == pu:
            return base
        if (rate.per_unit, pu) in CONVERSIONS:            # "70 per week" → per day = 70 / (days in a week)
            return f"({base}) / {_num(CONVERSIONS[(rate.per_unit, pu)])}"
        return None

    pt, pc = per(total), per(comp)
    if pt is None or pc is None:
        return None
    return _compute(f"({pt}) - ({pc})")


def _rate_sum(premises: list, question: str, context: list):
    """MULTI-ENTITY RATE SUM — "Anna 30 pages/60 min, Bob 27/60 min, Cherry 25/60 min. They have read for 240
    min. How many pages in TOTAL?" → (30+27+25)/60 × 240 = 328. ≥2 rates (same measure & per_unit) and
    nothing else; a single DURATION (a time-value in the premises/question that is NOT a rate's per-marker);
    a total-cue question. answer = Σ(amount/per_amount) × (duration → per_unit). None otherwise."""
    rates = [f for f in context if isinstance(f, Rate)]
    if len(rates) < 2 or any(isinstance(f, Quantity) and f.amount is not None for f in context):
        return None                                      # ≥2 rates and NO extra real quantity (a multi-step
        #                                                  given) — a bare descriptor from the duration clause
        #                                                  ("reading for 240 min" → ('minute',…)) is tolerated
    if len({(r.measure, r.per_unit) for r in rates}) != 1:
        return None
    per_unit = rates[0].per_unit
    if not any(w in question.lower() for w in ("total", "altogether", "combined", "in all", "together")):
        return None
    per_amounts = {r.per_amount for r in rates}
    dur = du = None
    for text in premises + [question]:                   # the duration: a time-value that is NOT a rate's
        for u in analyze(text).units:                    # per-marker (so not the "60 minutes" of the rate)
            if "value" in u.features.get("senses", []) and _follow(u, "quantifies") is not None \
                    and _descriptor(_follow(u, "quantifies"))[0] in TIME_UNITS:
                v, unit = u.features["value"], _descriptor(_follow(u, "quantifies"))[0]
                if v not in per_amounts or unit != per_unit:
                    dur, du = v, unit
    if dur is None:
        return None
    if du == per_unit:
        d = _num(dur)
    elif (du, per_unit) in CONVERSIONS:
        d = f"{_num(dur)} * {_num(CONVERSIONS[(du, per_unit)])}"
    else:
        return None
    total = " + ".join(f"{_num(r.amount)}/{_num(r.per_amount)}" for r in rates)
    return _compute(f"({total}) * ({d})")


def _rate_difference(premises: list, question: str, context: list):
    """RATE DIFFERENCE × DURATION — "Janet reads 80 pages a day, Belinda 30 pages a day. How many MORE pages
    does Janet read in 6 weeks?" → (80 − 30) × 42 = 2100; "how many more miles did Frank run in an hour than
    Jim?" → (10 − 8) × 1 = 2. EXACTLY two rates (same measure & per_unit) and nothing else; the question's
    subject is A, the other rate is B; answer = (A_per_unit − B_per_unit) × (duration → per_unit). Gated to a
    "how many/much MORE <measure>" question with a duration, every premise number consumed by the two rates."""
    if len(context) != 2 or not all(isinstance(f, Rate) for f in context):
        return None
    rA0, rB0 = context
    if rA0.measure != rB0.measure or rA0.per_unit != rB0.per_unit:
        return None
    prem_vals = [u.features["value"] for p in premises for u in analyze(p).units
                 if "value" in u.features.get("senses", [])]
    consumed = {rA0.amount, rA0.per_amount, rB0.amount, rB0.per_amount}
    if any(all(abs(v - c) > 1e-9 for c in consumed) for v in prem_vals):
        return None                                      # an unused premise number → not a bare difference
    qr = analyze(question)
    if not (any("interrogative" in u.features.get("senses", []) for u in qr.units)
            and any("comparative" in u.features.get("senses", []) and _key(u.surface) == "more"
                    for u in qr.units)):
        return None
    aux = next((u for u in qr.units if "auxiliary" in u.features.get("senses", [])), None)
    subs = _question_subjects(qr, aux)[0] if aux is not None else []
    A = next((r for r in context if r.entity in subs), None)
    if A is None:
        return None
    B = next(r for r in context if r is not A)
    dval = next((u for u in qr.units if "value" in u.features.get("senses", [])
                 and _follow(u, "quantifies") is not None
                 and _descriptor(_follow(u, "quantifies"))[0] in TIME_UNITS), None)
    if dval is not None:
        dur, du = dval.features["value"], _descriptor(_follow(dval, "quantifies"))[0]
    else:                                                # "in AN hour" / "a day" → a single per-unit
        u = qr.units
        pair = next(((u[k], u[k + 1]) for k in range(len(u) - 1)
                     if _key(u[k].surface) in ("a", "an", "each", "every")
                     and _descriptor(u[k + 1])[0] in TIME_UNITS), None)
        if pair is None:
            return None
        dur, du = 1, _descriptor(pair[1])[0]
    if du == A.per_unit:
        d = _num(dur)
    elif (du, A.per_unit) in CONVERSIONS:
        d = f"{_num(dur)} * {_num(CONVERSIONS[(du, A.per_unit)])}"
    else:
        return None
    return _compute(f"({_num(A.amount)}/{_num(A.per_amount)} - {_num(B.amount)}/{_num(B.per_amount)}) * ({d})")


def _ps_each_after(rp, k):
    """Money unit k is immediately followed by "each"/"apiece" — a genuine per-ITEM price."""
    nxt = rp.units[k + 1] if k + 1 < len(rp.units) else None
    return nxt is not None and _key(nxt.surface) in ("each", "apiece")


def _ps_at_or_each(rp, k):
    """Per-item price cue for the sell/revenue shape: preceded by "at" OR followed by each/apiece
    (a bare "for $P" is a TOTAL → not a unit price)."""
    prev = rp.units[k - 1] if k > 0 else None
    return (prev is not None and _key(prev.surface) == "at") or _ps_each_after(rp, k)


def _product_sum_core(premises: list, verbs: tuple, price_cue, require_all_prices: bool):
    """The shared Σ(count × price) core behind `_shopping_total` / `_revenue_product_sum` (they
    were near-clones): learn the premises, require EVERY money value to be a genuine per-item
    price (`price_cue` decides the surface cue), then STRICTLY alternate (item-count,
    money-price) over the `verbs` quantities — a leftover unpaired quantity declines. With
    `require_all_prices`, a premise whose price didn't LEARN (a locative prefix "At a coffee
    shop, 7 customers…" drops the first clause's facts) also declines rather than silently
    omitting its product (coffee 67≠32). Returns the audited sum, or None."""
    disc, ctx, readings = [], [], [analyze(p) for p in premises]
    for p in premises:
        f = learn(p, disc, ctx)
        if f:
            ctx += f
    money_units = [(rp, k) for rp in readings for k, u in enumerate(rp.units)
                   if "value" in u.features.get("senses", [])
                   and "money" in str(u.features.get("measure"))]
    if not money_units:
        return None
    for rp, k in money_units:
        if not price_cue(rp, k):
            return None
    qs = [f for f in ctx if isinstance(f, Quantity) and f.verb in verbs and f.amount is not None]
    products, i = [], 0
    while i < len(qs) - 1:                                # STRICT alternation: (item-count, money-price)+
        a, b = qs[i], qs[i + 1]
        if a.measure != MONEY and b.measure == MONEY:
            products.append(f"{_num(a.amount)} * {_num(b.amount)}")
            i += 2
        else:
            return None
    if i != len(qs) or not products:                     # leftover unpaired quantity → not a clean shape
        return None
    if require_all_prices and len(products) != len(money_units):
        return None
    return _compute(" + ".join(f"({p})" for p in products))


def _shopping_total(premises: list, question: str):
    """A SHOPPING TOTAL — "buys 3 toys at $10 each, 2 packs at $5 each, 5 shirts at $6 each. How much did she
    spend in all?" → Σ(count × price) = 3·10 + 2·5 + 5·6 = 70. The counts and per-item prices already parse as
    separate buy-quantities; only the per-each products + sum are missing. TIGHTLY gated (the shape collides
    with "for $80" totals, discounts, and per-piece questions, which all carry "each"): the question asks a
    spend TOTAL; EVERY money price must be immediately followed by "each"/"apiece" (a genuine per-item price,
    NOT "four pizzas for $80"); NO discount/sale/off; and the buy-quantities STRICTLY alternate item-count then
    price so each price pairs with its count (`_product_sum_core`). None otherwise."""
    ql = question.lower()
    # require an explicit TOTAL cue (not a bare "how much does he spend?", whose 2nd "X for $Y each" pair may
    # have been split INTO the question clause → an incomplete premise pairing, Alexander 5≠9).
    if not (("how much" in ql) and any(w in ql for w in ("spend", "spent", "pay", "paid"))
            and any(w in ql for w in ("in all", "total", "altogether", "combined"))):
        return None
    if any(_key(u.surface) in ("each", "apiece") for u in analyze(question).units):
        return None                                          # shopping content stranded in the question clause
    pl = " ".join(premises).lower()
    if any(w in pl for w in ("discount", "sale", " off", "% ", "coupon", "free")):
        return None
    return _product_sum_core(premises, ("buy", "purchase"), _ps_each_after,
                             require_all_prices=False)


def _revenue_product_sum(premises: list, question: str):
    """The REVENUE / SELL twin of `_shopping_total` — "the baker sold 453 cakes at $12 and 126 pies at $7.
    How much did the baker earn?" → Σ(count × price) = 453·12 + 126·7 = 6318. Same product-sum math
    (`_product_sum_core`), but the price attaches via "at $P" (a per-item price with NO "each") rather than
    requiring "each", and the question asks a revenue total (earn/make) as well as spend/pay. TIGHTLY gated
    to keep it off "for $80" TOTAL prices (Luigi's four pizzas) and discounts/tiers: (1) the question asks
    "how much" + earn/make/spend/pay, NO profit/more/less/change/left/each/discount cue; (2) every money
    value is a genuine PER-ITEM price; (3) NO discount/sale/off/%/commission/free/per in the premises;
    (4) the buy/sell/order quantities STRICTLY alternate, every one consumed, every price learned.
    Σ(count×price). None otherwise. Registered AFTER `_shopping_total`, which claims its own each-marked
    buy shape first (they never disagree — both compute the same product-sum)."""
    ql = question.lower()
    if not (("how much" in ql) and any(w in ql for w in ("earn", "earned", "make", "made",
                                                          "spend", "spent", "pay", "paid"))):
        return None
    if any(w in ql for w in ("profit", "more", "less", "fewer", "change", "left", "discount",
                             "percent", "commission", "each")):
        return None
    if any("value" in u.features.get("senses", []) for u in analyze(question).units):
        return None                                          # a value in the question → content stranded there
    pl = " ".join(premises).lower()
    if any(w in pl for w in ("discount", "sale", " off", "% ", "percent", "coupon", "free",
                             "commission", "profit", " per ", "tax", "tip")):
        return None
    return _product_sum_core(premises, ("buy", "purchase", "sell", "order"), _ps_at_or_each,
                             require_all_prices=True)


_CC_LOSS = {"sell", "sold", "give", "gave", "given", "gives", "use", "used", "eat", "ate", "eaten",
            "lost", "lose"}


def _container_contents_sum(premises: list, question: str):
    """CONTAINER × CONTENTS product-sum — "Ella has 4 bags with 20 apples each and 6 bags with 25 apples each;
    she sells 200; how many apples are left?" → 4·20 + 6·25 − 200 = 30. The COUNT twin of `_revenue_product_sum`
    (which pairs a count with a money PRICE): here each container-count pairs with a following CONTENTS-count of
    the QUESTIONED item, and a stated item LOSS (sell/give/eat …) is subtracted. The counts/contents parse as
    separate buy/have quantities that alternate (container, item); only the per-container products + sum are
    missing. TIGHTLY gated: a "how many <item>" question (not how-much/each/per/more); NO dozen/percent/
    fraction/relational/remaining cue (those are other shapes); STRICT (container, item) alternation with a
    following item-count, ≥2 products, every non-loss quantity paired. Σ(container·contents) − Σloss. None
    otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+?)s?\b", ql)
    if m is None or "how much" in ql or "each" in ql or " per " in ql or "more" in ql:
        return None
    item = m.group(1)
    if item in UNIT_NOUNS:
        return None                                          # a MEASUREMENT/time item (minutes/miles) is a
        #                                                      rate/duration problem, not discrete containers (Rosie 50≠30)
    body = " ".join(premises).lower()
    if any(w in body for w in ("dozen", "%", "percent", "twice", "times as", "half", "remaining",
                               "the rest", " per ")):        # " per " → a RATE problem, not containers
        return None
    disc, ctx = [], []
    for p in premises:
        f = learn(p, disc, ctx)
        if f:
            ctx += f
    qs = [f for f in ctx if isinstance(f, Quantity) and f.amount is not None]
    pairs, losses, pending = [], [], None
    for f in qs:
        if f.measure[0] != item:                             # a container-count (bags/boxes/pages …) — hold it
            pending = f.amount
        elif pending is not None:                            # (container, contents) → a product
            pairs.append((pending, f.amount))
            pending = None
        elif f.verb in _CC_LOSS:                             # a stated item loss ("sells 200")
            losses.append(f.amount)
        else:
            return None                                      # a bare item count with no container → not this shape
    if len(pairs) < 2 or pending is not None:                # need ≥2 container×contents products, all paired
        return None
    expr = " + ".join(f"({_num(c)} * {_num(m2)})" for c, m2 in pairs)
    if losses:
        expr = f"({expr}) - ({' + '.join(_num(x) for x in losses)})"
    return _compute(expr)


def _unit_price(text: str):
    """A single per-ITEM money price stated in `text`, or None. Requires an explicit per-item cue (one/each/
    every/a/per <item> cost(s) $P, or "$P each/apiece", or "$P per <item>") so a bare total ("bought it for
    $80") is never mistaken for a unit price. Returns the float price."""
    for pat in (r"\b(?:one|each|every|a|per)\s+[a-z]+\s+(?:costs?|cost|sells?\s+for)\s+\$(\d+(?:\.\d+)?)",
                r"\$(\d+(?:\.\d+)?)\s+(?:each|apiece)\b",
                r"\$(\d+(?:\.\d+)?)\s+per\s+[a-z]+"):
        m = re.search(pat, text, re.I)
        if m:
            return float(m.group(1))
    return None


def _chain_count_price(premises: list, question: str):
    """CHAIN-COUNT × UNIT-PRICE — a ratio/offset chain of an item's counts + a single per-item price + a
    money-SPEND total question → (Σ count) × price. "Dorothy buys ½ as many pens as Julia; Julia 3× Robert;
    Robert 4 pens; one pen costs $1.50; how much did they spend in total on pens?" → 22 × 1.50 = 33. The
    total COUNT is already computed by `_anchored_sum_system` (measure-blind — it sums the anchored chain and
    ignores the price value); this wraps it: extract the price, get the count, multiply. Registered BEFORE
    `anchored_sum` so it intercepts the money framing (anchored_sum alone would commit the bare count 22).
    Tightly gated: a "how much … spend/pay/cost … total" question, a clear per-item price, and a chain the
    count-system actually solves. None otherwise (→ falls through to the plain count systems)."""
    ql = question.lower()
    if not (("how much" in ql)
            and any(w in ql for w in ("spend", "spent", "pay", "paid", "cost", "make", "earn"))
            and (any(w in ql for w in ("total", "altogether", "in all"))
                 or re.search(r"\bsells? all\b|\bsold all\b",
                              ql + " " + " ".join(premises).lower()))):
        return None                                      # revenue asks ride a "sell all" totality cue
        #                                                  (the If-clause may split into a premise)
    if any(w in ql for w in ("more", "less", "fewer", "change", "left", "discount", "percent", "each of")):
        return None
    price = _unit_price(question) or _unit_price(" ".join(premises))
    if price is None:
        return None
    count_premises = [p for p in premises                # the wrapper owns the money framing: the count
                      if _unit_price(p) is None          # system sees only the count chain (a "They sell
                      and not (re.search(r"\bsell|\bsold", p.lower())     # X for $P each" or a digit-free
                               and not _has_digit(p))]                    # "if they sell all" clause would
    count = _anchored_sum_system(count_premises, "how many in total?")    # trip its premise firewall)
    #     synthetic COUNT question: sums the anchored chain, sidestepping anchored_sum's own
    #     money-price decline gate (which defers to us)
    if not isinstance(count, (int, float)) or isinstance(count, bool):
        return None
    return _compute(f"{_num(count)} * {price}")


_FRAC_WORDS = {"half": 0.5, "a third": 1 / 3, "a quarter": 0.25, "a fourth": 0.25, "a fifth": 0.2,
               "a sixth": 1 / 6, "one-half": 0.5, "one-third": 1 / 3, "one-fourth": 0.25, "one-fifth": 0.2,
               "one-sixth": 1 / 6, "two-thirds": 2 / 3, "three-fourths": 0.75, "three-quarters": 0.75,
               "two-fifths": 0.4, "three-fifths": 0.6,
               # UNHYPHENATED spellings ("one third of her brown shirts") — same values as the hyphenated
               "one half": 0.5, "one third": 1 / 3, "one quarter": 0.25, "one fourth": 0.25,
               "one fifth": 0.2, "one sixth": 1 / 6, "two thirds": 2 / 3, "three fourths": 0.75,
               "three quarters": 0.75, "two fifths": 0.4, "three fifths": 0.6}
_LOSS_VERBS = ("ate", "eat", "eaten", "gave", "give", "gives", "given", "spent", "spend", "took", "take",
               "taken", "used", "use", "removed", "remove", "scared", "scare", "lost", "lose", "sold",
               "sell", "drank", "drink", "threw", "throw")


def _fraction_value(s: str):
    """A fraction word/slash ("half", "one-fourth", "a third", "5/6") → its float, else None."""
    s = s.lower().strip()
    if s in _FRAC_WORDS:
        return _FRAC_WORDS[s]
    m = re.match(r"(\d+)/(\d+)$", s)
    return int(m.group(1)) / int(m.group(2)) if m else None


def _fraction_remainder_system(premises: list, question: str):
    """FRACTION-OF-BASE REMAINDER — a single stated POOL of an item, reduced by loss clauses that are each a
    FRACTION OF THAT POOL or a LITERAL count, then "how many <item> left/remain?" → N − Σ(fraction×N | literal).
    "There were 148 peanuts; Brock ate one-fourth of the peanuts; Bonita ate 29 peanuts; how many remain?" →
    148 − 148·¼ − 29 = 82. Reads RAW premise values (the fraction-partitive "¼ of the peanuts" produces no
    fact in the general fold — a stated 0.25 with no attached quantity — so a system is the safe route). VERY
    tightly gated, because fraction-remainder is a treacherous class (chained "of the remaining", derived/
    multi-entity bases, relative reductions all mis-compute): (1) a "left/remain" question naming the item;
    (2) the base is an EXPLICIT single POOL frame of that item ("there were/made/baked/grew/had N <item>" —
    NOT "bought", which starts a buy-chain with no single pool, Bonnie/Samuel); (3) every reduction is a loss
    verb + (fraction OF the item | a literal count), with ≥1 fraction; (4) NO chained base ("remaining"/"rest"/
    "of what"), NO relative reduction ("N less/more/than" — Bert's "2 less"), NO percent/each/times-as. None
    otherwise (→ the general depletion fold, which would drop the fraction and commit N − literals)."""
    ql = question.lower()
    m_item = re.search(r"how many (\w+?)s?\s+(?:are|were|is|do|does|remain|left|will|has|have)", ql) \
        or re.search(r"how many (\w+?)s?\b", ql)
    if m_item is None or not re.search(r"\b(left|remain|remaining)\b", ql):
        return None
    if "how much" in ql or "more" in ql:
        return None
    item = re.escape(m_item.group(1))
    body = " ".join(premises)
    low = body.lower()
    if any(w in low for w in ("remaining", "the rest", "of what", "percent", "%", " each ", "twice", "times as")):
        return None
    if len({q_ for _, q_ in re.findall(rf"\b(\d+)\s+([a-z]+)\s+{item}s?\b", low)}) >= 2:
        return None    # ≥2 QUALIFIED subtype pools ("26 blue shirts and 36 brown shirts") — that's the
        #                subtype twin's shape (_subtype_fraction_remainder_system); grabbing the FIRST pool
        #                as the single base would commit half·pool₁ against the wrong total (deferral, so
        #                the two family members never both claim — the collisions discipline)
    mb = re.search(rf"\b(?:there\s+(?:were|are|was)|had|has|made|baked|grew)\s+(\d+)\s+(?:\w+\s+)?{item}s?\b", low)
    if mb is None:
        return None
    n = float(mb.group(1))
    reductions, saw_fraction = [], False
    for p in premises:
        pl = p.lower()
        if not any(re.search(rf"\b{v}\b", pl) for v in _LOSS_VERBS):
            continue
        if re.search(r"\b(less|more|fewer|than)\b", pl):
            return None                                      # a RELATIVE reduction ("2 less") we don't model
        mf = re.search(rf"(half|a third|a quarter|a fourth|a fifth|a sixth|one-\w+|two-\w+|three-\w+|\d+/\d+)"
                       rf"\s+of\s+(?:the\s+(?:\w+\s+)?{item}s?|them|it)\b", pl)
        if mf:
            f = _fraction_value(mf.group(1))
            if f is None:
                return None
            reductions.append(n * f)
            saw_fraction = True
            continue
        ml = re.search(r"\b(\d+)\b", pl)                     # a literal reduction (Bonita ate 29)
        if ml and float(ml.group(1)) != n:
            reductions.append(float(ml.group(1)))
    if not saw_fraction or not reductions:
        return None                                          # require ≥1 fraction-of-base (the whole point)
    return _compute(f"{_num(n)} - ({' + '.join(_num(x) for x in reductions)})")


def _subtype_fraction_remainder_system(premises: list, question: str):
    """SUBTYPE FRACTION REMAINDER — the MULTI-pool twin of _fraction_remainder_system: ≥2 QUALIFIED subtype
    pools of the questioned item ("26 blue shirts and 36 brown shirts"), each fraction loss binding to ITS
    OWN subtype ("half of her blue shirts", "a third of her brown shirts") → Σpools − Σ(fᵢ·poolᵢ). Mary g37:
    (26+36) − (13+12) = 37. WHY a system: the general fold computes "half" but silently DROPS any other
    fraction-partitive, committing Σ − half·pool₁ (49 ≠ 37) — worse, the clause splitter strands the second
    fraction INSIDE the question string, so this scans premises + question uniformly. Gates mirror the
    single-pool twin (loss verb, no chained base / relative / percent / each / times-as), plus: every
    fraction must name a distinct known subtype, and EVERY digit in the text must be a pool value or a
    fraction component (stranded content → decline, never a partial sum)."""
    ql = question.lower()
    m_item = re.search(r"how many (\w+?)s?\s+(?:are|were|is|do|does|remain|left|will|has|have)", ql) \
        or re.search(r"how many (\w+?)s?\b", ql)
    if m_item is None or not re.search(r"\b(left|remain|remaining)\b", ql):
        return None
    if "how much" in ql or "more" in ql:
        return None
    item = re.escape(m_item.group(1))
    low = (" ".join(premises) + " " + question).lower()
    if any(w in low for w in ("remaining", "the rest", "of what", "percent", "%", " each ", "twice", "times as")):
        return None
    if re.search(r"\b(less|fewer|than)\b", low):
        return None                                          # a RELATIVE reduction we don't model
    pools = {}
    for mv, qual in re.findall(rf"\b(\d+)\s+([a-z]+)\s+{item}s?\b", low):
        if qual in pools:
            return None                                      # duplicate subtype → ambiguous, decline
        pools[qual] = float(mv)
    if len(pools) < 2:
        return None                                          # single pool → the single-pool twin's shape
    if not any(re.search(rf"\b{v}\b", low) for v in _LOSS_VERBS):
        return None
    fracs = re.findall(rf"(half|(?:a|one|two|three)[ -]\w+|\d+/\d+)"
                       rf"\s+of\s+(?:the\s+|her\s+|his\s+|their\s+|its\s+)?([a-z]+)\s+{item}s?\b", low)
    if not fracs:
        return None
    # EVERY fraction cue in the text must be one we captured — an unrecognized form ("one third" before it
    # was lexicalized, "four sevenths") that the tight regex misses would silently drop a reduction and
    # commit a PARTIAL remainder (the exact 49≠37 confident-wrong class this system exists to kill)
    cues = re.findall(r"\b(half|halves|thirds?|quarters?|fourths?|fifths?|sixths?|sevenths?|eighths?"
                      r"|ninths?|tenths?|\d+/\d+)\b", low)
    if len(cues) != len(fracs):
        return None
    reductions, used = [], set()
    for fs, qual in fracs:
        f = _fraction_value(fs)
        if f is None or qual not in pools or qual in used:
            return None                                      # a fraction of an unknown/repeated subtype
        used.add(qual)
        reductions.append(pools[qual] * f)
    accounted = {_num(v) for v in pools.values()}
    for fs, _ in fracs:
        accounted.update(re.findall(r"\d+", fs))
    if any(d not in accounted for d in re.findall(r"\d+", low)):
        return None                                          # a stranded number we didn't consume
    return _compute(f"({' + '.join(_num(v) for v in pools.values())})"
                    f" - ({' + '.join(_num(x) for x in reductions)})")


_FC_STEP = re.compile(
    r"(half|(?:a|an|one|two|three)[ -](?:half|third|thirds|quarter|quarters|fourth|fourths|fifth"
    r"|fifths|sixth|sixths|seventh|sevenths|eighth|eighths|ninth|ninths|tenth|tenths)"
    r"|\d+/\d+|\d+(?:\.\d+)?\s*(?:%|percent))\s+of\s+((?:[a-z'’]+\s+){0,4}[a-z'’]+)")
_FC_REMAINDER_ANCHOR = re.compile(r"\b(?:remaining|rest|remainder|left)\b")


def _fraction_depletion_chain_system(premises: list, question: str):
    """FRACTION DEPLETION CHAIN — one pool reduced by SEQUENTIAL partitive steps where later steps
    anchor to the REMAINDER: "Julia has $40. She spends half of her money on a game. She spends a
    quarter of what she has left. How much does she have left?" → 40·(1−½)·(1−¼) = 15; "36
    seagulls; 1/4 of them scared away; 1/3 of the remaining birds fly off; how many left?" →
    36·¾·⅔ = 18. The single-pool `_fraction_remainder_system` EXCLUDES remaining/rest chains
    (deferral, so the family members never both claim); this is that chain shape. A percent step
    ("30 percent of the remaining") is a fraction here — anchored, so the countable-percent wrong
    class can't fire. TIGHTLY gated: a digit-free left/remain question with no comparative; ONE
    base value (money "$40" or "N <item>"); the FIRST step is BASE-anchored (them/it/his money/the
    <base item>) and its clause carries a depletion cue; every LATER step must be REMAINDER-anchored
    (a second base-anchored step is the partition shape, not this one); ≥1 remainder step; every
    fraction cue in the text captured as a step; every digit accounted; no each/times/literal
    losses; a positive integer remainder. None otherwise."""
    ql = question.lower()
    if not re.search(r"\b(?:left|remain|remains|remaining|still)\b|to finish", ql) \
            or not ("how many" in ql or "how much" in ql) \
            or _has_digit(ql) or _has_comparative(ql):
        return None                                      # "must she read … to finish" asks the remainder
    segs = [p.lower() for p in premises]
    body = " ".join(segs)
    if " each" in body or "times" in body or _FC_STEP.search(ql):
        return None
    if re.search(r"\b(?:at first|beginning|begin|originally|start with)\b", ql):
        return None                                      # a backward find-the-initial ask — not ours
    base = item = None
    base_seg = -1
    for si, seg in enumerate(segs):
        mm = re.search(r"\$\s*(\d+(?:,\d{3})*(?:\.\d+)?)", seg)
        mi = re.search(r"\b(\d+(?:,\d{3})*)\s+([a-z]+)", seg)
        if mm is not None:
            base, item, base_seg, base_span = float(mm.group(1).replace(",", "")), "money", si, mm.span()
            break
        if mi is not None and not re.match(r"\d+/", seg[mi.start():]):
            noun = _singular_of(mi.group(2)) or mi.group(2)
            base, item, base_seg, base_span = float(mi.group(1).replace(",", "")), noun, si, mi.span()
            break
    if base is None or base <= 0:
        return None
    steps = []                                           # (seg, pos, fraction, kind) in text order
    spans = [[] for _ in segs]
    spans[base_seg].append(base_span)
    for si, seg in enumerate(segs):
        for m in _FC_STEP.finditer(seg):
            f = _fraction_value(m.group(1))
            if f is None:
                pm = re.match(r"(\d+(?:\.\d+)?)\s*(?:%|percent)", m.group(1))
                if pm is None:
                    return None
                p = float(pm.group(1))
                if not 0 < p < 100:
                    return None
                f = p / 100
            anchor = m.group(2)
            if _FC_REMAINDER_ANCHOR.search(anchor):
                kind = "remainder"
            elif re.match(r"(?:them|it|all\b|his |her |their |the |these |those )", anchor) \
                    and (item in ("money",) and "money" in anchor
                         or any((_singular_of(w) or w) == item for w in anchor.split())
                         or re.match(r"(?:them|it)\b", anchor)):
                kind = "base"
            else:
                return None                              # an anchor we can't place — never guess
            if not 0 < f < 1:
                return None
            steps.append((si, m.start(), f, kind))
            spans[si].append(m.span())
    if len(steps) < 2 or steps[0][3] != "base" \
            or any(k != "remainder" for _, _, _, k in steps[1:]):
        return None
    first_clause = segs[steps[0][0]]
    if not (any(re.search(r"\b" + v, first_clause) for v in _LOSS_VERBS)
            or " away" in first_clause or re.search(r"\bread", first_clause)):
        return None                                      # the base step needs a depletion cue
        #                                                  (reading pages consumes them — Coral)
    cues = re.findall(r"\b(?:half|halves|thirds?|quarters?|fourths?|fifths?|sixths?|sevenths?"
                      r"|eighths?|ninths?|tenths?|\d+/\d+|\d+(?:\.\d+)?\s*(?:%|percent))", body)
    if len(cues) != len(steps):
        return None                                      # an uncaptured fraction cue → partial chain
    for si, seg in enumerate(segs):                      # every digit accounted
        for m in re.finditer(r"\d+(?:,\d{3})*(?:\.\d+)?|\.\d+", seg):
            if not any(a <= m.start() and m.end() <= b for a, b in spans[si]):
                return None
    expr = _num(base)
    for _, _, f, _ in sorted(steps):
        expr = f"({expr}) * (1 - {_num(f)})"
    result = _compute(expr)
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


_FPR_STEP = re.compile(
    r"(half|(?:a|an|one|two|three)[ -](?:half|third|thirds|quarter|quarters|fourth|fourths|fifth"
    r"|fifths|sixth|sixths|seventh|sevenths|eighth|eighths|ninth|ninths|tenth|tenths)|\d+/\d+)"
    r"(?:\s+of\s+(?:all\s+)?(?:the\s+|their\s+|his\s+|her\s+)?[a-z]+)?"
    r"\s+(?:are|were|is|was|had been)\s+([a-z]+)")


def _pool_literal_relational_remaining_system(premises: list, question: str):
    """POOL − LITERAL − K×LITERAL, ASK A FRACTION OF THE REMAINING — "a 120-page book; yesterday
    she read 12 pages; today twice as many as yesterday; she wants to read half of the remaining
    pages tomorrow — how many?" → (120 − 12 − 24)/2 = 42. The literal+relational consumption pair
    materializes no usable facts (the relational step anchors to 'yesterday', a time word), so
    RAW text is read. TIGHTLY gated: a digit-free "how many <item> should/must/need" ask; ONE
    "<f> of the remaining <item>" cue; ONE "<P>-<item> book" (or "<P> <item>" copula) pool; ONE
    literal step; ONE "k times as many … as yesterday/that" relational step; nothing else valued;
    a positive integer. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or _has_digit(ql) \
            or not re.search(r"\b(?:should|must|need|needs) \w+ read\b|\bshould \w+ read\b|"
                             r"\bhow many \w+ (?:should|must)\b", ql):
        return None
    item = _singular_of(m.group(1)) or m.group(1)
    body = " ".join(p.lower() for p in premises) + " " + ql
    fm = re.search(rf"(half|a third|a quarter|two-thirds|\d+/\d+) of the remaining {re.escape(item)}s?\b",
                   body)
    if fm is None:
        return None
    f = _fraction_value(fm.group(1))
    if f is None or not 0 < f < 1:
        return None
    pm = re.search(rf"(\d+)[- ]{re.escape(item)} book\b", body) \
        or re.search(rf"is (\d+) {re.escape(item)}s? long\b", body)
    lm = re.search(rf"read (\d+) {re.escape(item)}s?\b", body)
    km = re.search(r"read (twice|three times|four times) as many [a-z]+ as (?:she |he )?"
                   r"(?:read )?(?:yesterday|that)\b", body)
    if pm is None or lm is None or km is None:
        return None
    pool, lit = float(pm.group(1)), float(lm.group(1))
    k = {"twice": 2.0, "three times": 3.0, "four times": 4.0}[km.group(1)]
    used = {pm.group(1), lm.group(1)}
    if any(d not in used for d in re.findall(r"\d+", body)):
        return None                                      # a stray value → not this shape
    result = _compute(f"({_num(pool)} - {_num(lit)} - {_num(k)} * {_num(lit)}) * {_num(f)}")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


_BFC_STEP = re.compile(
    r"(half|(?:a|an|one|two|three)[ -](?:half|third|thirds|quarter|quarters|fourth|fourths|fifth"
    r"|fifths|sixth|sixths|seventh|sevenths|eighth|eighths|ninth|ninths|tenth|tenths)|\d+/\d+)"
    r"\s+(?:of\s+)?((?:[a-z'’]+\s+){0,4}[a-z'’]+)")


def _backward_fraction_chain_system(premises: list, question: str):
    """BACKWARD FRACTION CHAIN — the INVERSE of the depletion chain: sequential fraction losses
    ending in a KNOWN final, asked the ORIGINAL: "Lucy lost one-third of her money, spent
    one-fourth of the remainder, and was left with $15; how much at the beginning?" → M·⅔·¾ = 15
    → 30; "Jenny had $24 left after spending 3/7 of her money; how much is HALF of her original
    amount?" → (24 ÷ 4/7)/2 = 21. GUARD 8 declines backward-initial asks so the fold never
    commits a partial here — this system claims only the fully-modeled chain. TIGHTLY gated: a
    digit-free original/at-first/beginning ask ('half of the original' halves the answer); ONE
    final "left with/had $F left"; every fraction step anchored (the FIRST base-anchored, later
    ones remainder-anchored) with a loss cue in the body; every fraction cue captured; every
    digit accounted; the original and the answer positive integers. None otherwise."""
    ql = question.lower()
    if not re.search(r"\b(?:at first|at the beginning|beginning|originally|original)\b", ql) \
            or not ("how much" in ql or "how many" in ql) or _has_digit(ql) \
            or _has_comparative(ql):
        return None
    halve = re.search(r"half of (?:her|his|their|the) original", ql) is not None
    body = " ".join(p.lower() for p in premises)
    if " each" in body or "times" in body:
        return None
    fmatch = re.search(r"(?:left with|had|has) \$?(\d+(?:,\d{3})*(?:\.\d+)?)(?: left)?\b", body)
    if fmatch is None or "left" not in fmatch.group(0) and "left with" not in body:
        return None
    final = float(fmatch.group(1).replace(",", ""))
    if not re.search(r"\b(?:spend|spent|spending|lost|lose|losing|gave|give|used|use)", body):
        return None                                      # the chain needs a loss cue
    steps = []
    for m in _BFC_STEP.finditer(body):
        f = _fraction_value(m.group(1))
        if f is None or not 0 < f < 1:
            return None
        anchor = m.group(2)
        if _FC_REMAINDER_ANCHOR.search(anchor):
            kind = "remainder"
        elif re.match(r"(?:her|his|their|the|my) [a-z'’]+|(?:money|amount|it|them|savings)\b",
                      anchor):
            kind = "base"
        else:
            return None                                  # an anchor we can't place — never guess
        steps.append((f, kind, m.group(1)))
    if not steps or steps[0][1] != "base" or any(k != "remainder" for _, k, _ in steps[1:]):
        return None
    cues = re.findall(r"\b(?:half|halves|thirds?|quarters?|fourths?|fifths?|sixths?|sevenths?"
                      r"|eighths?|ninths?|tenths?|\d+/\d+)\b", body)
    if len(cues) != len(steps):
        return None                                      # an uncaptured fraction cue → partial chain
    used = {fmatch.group(1)}
    for _, _, tok in steps:
        used |= set(re.findall(r"\d+", tok))
    for d in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?", body):
        if d not in used and not all(x in used for x in re.findall(r"\d+", d)):
            return None                                  # a body digit we didn't consume
    keep = 1.0
    for f, _, _ in steps:
        keep *= (1 - f)
    if keep <= 0:
        return None
    expr = f"{_num(final)} / {_num(keep)}"
    if halve:
        expr = f"({expr}) / 2"
    result = _compute(expr)
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


def _fraction_partition_rest_system(premises: list, question: str):
    """FRACTION PARTITION + REST — fractions of ONE total label categories (STATIVE copulas, not
    depletions); the asked category is the unlabeled REST: "sold a total of 72 computers; half of
    their sales are laptops, one-third are netbooks, and the rest are desktops; how many
    desktops?" → 72·(1−½−⅓) = 12; "42 raspberries, blackberries, and blueberries were picked in
    total; half of all the berries had been raspberries, a third were blackberries; how many were
    blueberries?" → 7. The depletion-chain twin declines a second BASE-anchored fraction — this
    claims exactly that shape when it is a copula partition. TIGHTLY gated: a digit-free "how
    many <cat>" question with NO left/remain (that's depletion) and no comparative; the asked
    category named in the body (as the rest or in the enumeration); ONE total (on a "total"-cued
    premise); ≥2 copula-labeled fractions naming DISTINCT categories ≠ the asked one; no
    both/either overlap talk; Σf < 1; every fraction cue captured; every digit accounted; a
    positive integer rest. None otherwise."""
    ql = question.lower()
    qm = re.search(r"how many (?:of the\w* )?(?:\w+ )??(?:were |are )?([a-z]+)", ql)
    if qm is None or re.search(r"\b(?:left|remain|remains|remaining)\b", ql) \
            or _has_digit(ql) or _has_comparative(ql):
        return None
    asked = _singular_of(qm.group(1)) or qm.group(1)
    if asked in ("there", "total", "them", "all", "they"):
        return None                                      # a total/pronoun ask, not a rest category
    segs = [p.lower() for p in premises]
    body = " ".join(segs)
    if "%" in body or "percent" in body or "times" in body or " each" in body \
            or "both" in body + " " + ql or "either" in ql or "neither" in ql:
        return None
    if not re.search(rf"\b(?:{re.escape(asked)}s?|{re.escape(qm.group(1))})\b", body):
        return None                                      # the rest category must be NAMED, never assumed
        #                                                  (match the question's surface too — "peaches")
    total = total_noun = None
    spans = [[] for _ in segs]
    for si, seg in enumerate(segs):
        if "total" not in seg:
            continue
        tm = re.search(r"\b(\d+(?:,\d{3})*)\b\s*([a-z]*)", seg)
        if tm is not None:
            if total is not None:
                return None
            total = float(tm.group(1).replace(",", ""))
            total_noun = _singular_of(tm.group(2)) or tm.group(2)
            spans[si].append((tm.start(1), tm.end(1)))
    if total is None or total <= 0:
        return None
    if asked == total_noun:
        return None                                      # "how many students…" asks the TOTAL noun —
        #                                                  the whole pool, not the unlabeled rest
    fracs, cats = [], set()
    for si, seg in enumerate(segs + [ql]):
        for m in _FPR_STEP.finditer(seg):
            f = _fraction_value(m.group(1))
            if f is None or not 0 < f < 1:
                return None
            cat = _singular_of(m.group(2)) or m.group(2)
            if cat in cats:
                return None                              # a duplicate category → ambiguous
            cats.add(cat)
            fracs.append(f)
            if si < len(segs):
                spans[si].append(m.span())
    if len(fracs) < 2 or asked in cats:
        return None
    cues = re.findall(r"\b(?:half|halves|thirds?|quarters?|fourths?|fifths?|sixths?|sevenths?"
                      r"|eighths?|ninths?|tenths?|\d+/\d+)\b", body + " " + ql)
    if len(cues) != len(fracs):
        return None                                      # an uncaptured fraction cue → partial partition
    for si, seg in enumerate(segs):
        for m in re.finditer(r"\d+(?:,\d{3})*(?:\.\d+)?|\.\d+", seg):
            if not any(a <= m.start() and m.end() <= b for a, b in spans[si]):
                return None
    if sum(fracs) >= 1:
        return None
    result = _compute(f"{_num(total)} * (1 - {' - '.join(_num(f) for f in fracs)})")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


def _equal_share(question: str, context: list, premises: list):
    """POOL-AND-REDISTRIBUTE — "Mark has 30 candies, Peter 25, John 35. They combine their candies and share
    them equally. How many will EACH have?" → (30+25+35)/3 = 30. Same Σ/N math as the `average` branch (#3l)
    but triggered by a SHARE-EQUALLY premise + a per-each result question, not the word "average". The
    recognizer needs the premise text (the "share equally" cue isn't in the question), so it lives in solve(),
    not answer(). GATED: a share/divide/split/combine + equal cue in a premise; the question asks "how
    many/much … EACH … have/get"; a SINGLE shared measure with ≥2 owners; and (denominator safety, as #3l) any
    set-size the question states must equal the owner count. Σ(each owner's net holding) / owner-count. None
    otherwise."""
    ql = question.lower()
    if "each" not in ql or not any(w in ql for w in ("how many", "how much")) \
            or not any(w in ql for w in ("have", "get", "receive", "end up")):
        return None
    pl = " ".join(premises).lower()
    if not (any(w in pl for w in ("share", "shares", "shared", "divide", "divided", "split", "distribute",
                                  "combine", "combined")) and any(w in pl for w in ("equal", "equally", "evenly"))):
        return None
    if any(isinstance(f, Distribution) for f in context):
        return None                                        # one whole split among a COUNT (Mr. Sam $5250 ÷ 3
        #                                                    sons) is the existing equal-split handler's job —
        #                                                    its synthesized per-recipient share would here be
        #                                                    wrongly pooled with the distributor's own holding
    if any(w in pl for w in ("the rest", "remaining", "remainder", " left ", "kept")):
        return None                                        # "kept 20 and shared THE REST among his friends" is
        #                                                    a remainder distributed to OTHERS, not a pool among
        #                                                    the owners (Harold 100 → 80÷5, not Σ holdings ÷ N)
    measures = {f.measure for f in context if isinstance(f, Quantity) and f.amount is not None}
    if len(measures) != 1:
        return None
    gq = next(iter(measures))
    owners = {f.entity for f in context if isinstance(f, Quantity) and f.measure == gq
              and f.amount is not None and f.entity != gq[0]}   # exclude a NOUN-entity ("the rest" → entity
    if len(owners) < 2:                                         # 'marble' == measure head), only real holders
        return None
    terms = [_holdings(o, gq, context) for o in owners]
    if not all(t is not None for t in terms):
        return None
    qr = analyze(question)                                 # set-size safety: a stated count > 1 (a recipient
    stated_n = next((u.features["value"] for u in qr.units if "value" in u.features.get("senses", [])  # set size,
                     and float(u.features["value"]).is_integer() and u.features["value"] > 1), None)   # not the
    if stated_n is not None and stated_n != len(owners):   # "one" of "each ONE of them") must equal owner count
        return None
    result = _compute(f"({' + '.join(_num(t) for t in terms)}) / {len(owners)}")
    if isinstance(result, float) and not result.is_integer():
        return None                                        # a clean pool divides evenly; a fraction means the
        #                                                    holdings didn't all resolve (a relation deferred)
    return result


# ═══ WHOLE-TEXT SYSTEM-SOLVERS ════════════════════════════════════════════════════════════════
# Everything from here to the registries is the WHOLE-TEXT solver class: each system recognizes
# ONE tightly-gated problem shape and reads RAW premise text (regexes over clauses), because the
# shape's clauses materialize no usable facts in the general fold (double frequencies, relational
# day chains, stated conversion factors…). They differ from the obligation-parsing systems above
# (_sum_ratio…_total_between_residual), which work over LEARNED facts. Shared discipline:
#   * a digit-free (or single-excised-digit) question gate — `_has_digit` / `_has_comparative`;
#   * classify EVERY valued premise; an unclassified one → decline ("not this shape");
#   * commit through `_gated_pos_int` / `_gated_pos` / `_gated_nonneg` on the audited result.
# Register new ones in `_EARLY_SYSTEMS`/`_LATE_SYSTEMS` and run `reading_diff collisions` after.

_PER_DAY_CUES = ("a day", "each day", "per day", "every day", "daily")


def _daily_share_system(premises: list, question: str):
    """DAILY SHARE — a stated TOTAL consumed over a stated DURATION, asked per day: "James buys 60
    sodas, had 10 already, finishes all in 1 week. How many sodas does he drink a day?" → 70/7 = 10;
    "two books of 180 and 100 pages, finish both in two weeks, how many pages every day?" → 280/14.
    TIGHTLY gated: the question asks "how many <item> … <per-day cue>" with NO comparative ("how many
    MORE pages per day than…" is another shape) and no value of its own; ONE duration (a week/day
    Quantity, or an "in N week(s)/day(s)" phrase in a premise); every OTHER valued fact is either an
    item quantity with a NON-LOSS verb or a SET-SIZE (a cardinal whose measure head is the entity the
    item quantities hang on — "TWO BOOKS of 180 and 100 pages"); the share is a POSITIVE INTEGER."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or not any(c in ql for c in _PER_DAY_CUES):
        return None
    if _has_comparative(ql) or _has_digit(ql):
        return None
    item = _singular_of(m.group(1)) or m.group(1)
    if item in UNIT_NOUNS or "noun" not in LEXICON.get(item, ()):
        return None
    disc, ctx = [], []
    for p in premises:
        fs = learn(p, disc, ctx)
        if fs:
            ctx += fs
    qs = [f for f in ctx if isinstance(f, Quantity) and f.amount is not None]
    items = [f for f in qs if f.measure[0] == item]
    if not items or any(f.verb in LOSS_VERBS for f in items):
        return None
    carriers = {f.entity for f in items}                 # a cardinal counting the item-CARRIER noun is
    #                                                      scene-setting ("two books" for page items)
    days = None
    dur_q = [f for f in qs if f.measure[0] in ("week", "day") and f not in items]
    if len(dur_q) == 1:
        days = dur_q[0].amount * (7 if dur_q[0].measure[0] == "week" else 1)
    elif not dur_q:
        stated = []
        for p in premises:
            for n, u in re.findall(r"\bin (\w+) (week|day)s?\b", p.lower()):
                v = NUMBERS.get(n, float(n) if n.isdigit() else 0)
                if v:
                    stated.append((v, u))
        if len(stated) == 1:
            days = stated[0][0] * (7 if stated[0][1] == "week" else 1)
    if days is None or days <= 0:
        return None
    for f in qs:                                         # every remaining value must be accounted for
        if f in items or (dur_q and f is dur_q[0]):
            continue
        if f.measure[0] in carriers and f.amount == float(int(f.amount)):
            continue                                     # the set-size cardinal ("two books", "one book")
        return None
    result = _compute(f"({' + '.join(_num(f.amount) for f in items)}) / {_num(days)}")
    return _gated_pos_int(result)


def _herd_rate_week_system(premises: list, question: str):
    """COUNT × PER-HEAD DAILY RATE × 7 — "A farmer has 52 cows. Each cow gives 5 liters of milk a
    day. How many liters does the farmer get in a week?" → 52·5·7 = 1820. TIGHTLY gated: the
    question asks the RATE's measure over "a week" (no comparative, no value); exactly TWO valued
    premises — a COUNT of some noun C, and a rate premise whose Quantity hangs on ENTITY C (each
    C…), measures the ASKED head, and carries a per-day cue in its text. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or not re.search(r"\bin (a|one) week\b", ql):
        return None
    if _has_comparative(ql) or _has_digit(ql):
        return None
    asked = _singular_of(m.group(1)) or m.group(1)
    valued = []
    disc, ctx = [], []
    for p in premises:
        fs = [f for f in (learn(p, disc, ctx) or []) if isinstance(f, Quantity) and f.amount is not None]
        if len(fs) > 1:
            return None
        if fs:
            valued.append((p, fs[0]))
            ctx += fs
    if len(valued) != 2:
        return None
    rate_pair = next((v for v in valued if v[1].measure[0] == asked
                      and any(c in v[0].lower() for c in _PER_DAY_CUES)), None)
    count_pair = next((v for v in valued if v is not rate_pair), None)
    if rate_pair is None or count_pair is None:
        return None
    rate, count = rate_pair[1], count_pair[1]
    if rate.entity != count.measure[0] or count.amount != float(int(count.amount)):
        return None                                      # the rate must hang on EACH counted head
    return _gated_pos(_compute(f"{_num(count.amount)} * {_num(rate.amount)} * 7"))


_WEEKDAYS = ("sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday")
_ZERO_CUES = ("nothing", "skipped", "did not", "didn't", "none")


_ORDINAL_DAYS = {"first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6}


def _ordinal_day_chain_residual_system(premises: list, question: str):
    """ORDINAL-DAY CHAIN + EQUAL-SPLIT RESIDUAL — "collecting 500 tins in a week; first day 50;
    second day 3 times that number; third day 50 fewer than the second day; equal number on the
    remaining days; how many each day for the rest of the week?" → (500 − (50+150+100)) / (7−3)
    = 50. TIGHTLY gated: a digit-free "each day … rest of the week" question; an equal-split cue
    ("equal number … remaining days") in a premise or the question; ONE weekly target premise
    ("N <item> in a week"); consecutive ordinal-day premises from the FIRST day, each resolving
    to a value — a literal, "k times that number" (× previous), or "N fewer than … the <ordinal>
    day" (that day's value − N); every digit premise classified; a positive-integer share. None
    otherwise."""
    ql = question.lower()
    if _has_digit(ql) or "day" not in ql \
            or not ("rest of the week" in ql or "remaining days" in ql):
        return None
    body = " ".join(premises).lower()
    if not ("equal" in body or "equal" in ql) or "remaining days" not in body + " " + ql:
        return None
    target = None
    day_vals: dict = {}
    for p in premises:
        pl = p.lower()
        om = re.search(r"on the (\w+) day", pl)
        tm = re.search(r"(\d+(?:\.\d+)?) \w+ in a week", pl)
        if om is not None and om.group(1) in _ORDINAL_DAYS:
            n = _ORDINAL_DAYS[om.group(1)]
            if n in day_vals:
                return None
            rest = pl[om.end():]
            km = re.search(r"(\d+(?:\.\d+)?) times that number", rest)
            fm = re.search(r"(\d+(?:\.\d+)?) \w+ fewer than[^.]*on the (\w+) day", rest)
            lm = re.search(r"(\d+(?:\.\d+)?)", rest)
            if km is not None:
                if n - 1 not in day_vals:
                    return None
                day_vals[n] = float(km.group(1)) * day_vals[n - 1]
            elif fm is not None:
                ref = _ORDINAL_DAYS.get(fm.group(2))
                if ref is None or ref not in day_vals:
                    return None
                day_vals[n] = day_vals[ref] - float(fm.group(1))
            elif lm is not None:
                day_vals[n] = float(lm.group(1))
            else:
                return None                              # an ordinal day with no resolvable value
        elif tm is not None and target is None:
            target = float(tm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if target is None or not day_vals or sorted(day_vals) != list(range(1, len(day_vals) + 1)):
        return None                                      # days must be consecutive from the first
    remaining = 7 - len(day_vals)
    if remaining < 1 or any(v < 0 for v in day_vals.values()):
        return None
    result = _compute(f"({_num(target)} - ({' + '.join(_num(day_vals[k]) for k in sorted(day_vals))}))"
                      f" / {remaining}")
    return _gated_pos_int(result)


def _weekday_base_delta_system(premises: list, question: str):
    """WEEKDAY BASE ± DAY DELTAS — "jogs 30 minutes every day during weekdays; Tuesday 5 minutes
    more; 25 more on Friday; total hours this week?" → (30·5 + 5 + 25)/60 = 3; "an hour a day
    during weekdays; Thursday cut short by 20; 10 more on Friday; minutes that week?" →
    60·5 − 20 + 10 = 290. TIGHTLY gated: a digit-free "how many hours/minutes … week" question;
    ONE weekday-restricted per-day base premise ("N minutes"/"an hour" + "during weekdays");
    every OTHER digit premise only "cut short … by N minutes" (−) / "N minutes more" (+) deltas
    naming a weekday; an hours answer must divide exactly by 60. None otherwise."""
    ql = question.lower()
    unit = "hour" if "how many hours" in ql else ("minute" if "how many minutes" in ql else None)
    if unit is None or "week" not in ql or _has_digit(ql):
        return None
    base = None
    deltas = []
    for p in premises:
        pl = p.lower()
        has_digit = _has_digit(p)
        if ("during weekdays" in pl or "on weekdays" in pl) and base is None:
            bm = re.search(r"(\d+(?:\.\d+)?) minutes", pl)
            if bm is not None:
                base = float(bm.group(1))
            elif re.search(r"\ban hour\b", pl):
                base = 60.0
            else:
                return None
            continue
        cuts = re.findall(r"cut short [^.]*?by (\d+(?:\.\d+)?) minutes", pl)
        mores = re.findall(r"(\d+(?:\.\d+)?) minutes more", pl)
        if (cuts or mores) and any(d in pl for d in _WEEKDAYS):
            deltas += [-float(c) for c in cuts] + [float(m) for m in mores]
            if len(cuts) + len(mores) != len(re.findall(r"\d+(?:\.\d+)?", pl)):
                return None                              # a stray value beside the deltas
        elif has_digit:
            return None                                  # an unclassified valued premise
    if base is None:
        return None
    total = base * 5 + sum(deltas)
    if total <= 0:
        return None
    if unit == "hour":
        if total % 60:
            return None
        result = _compute(f"({_num(base)} * 5 + {_num(sum(deltas))}) / 60")
    else:
        result = _compute(f"{_num(base)} * 5 + {_num(sum(deltas))}")
    return _gated_pos(result)


def _weekday_rate_weeks_system(premises: list, question: str):
    """WEEKDAY-ONLY RATE × WEEKS — "jogs 5 miles per day on weekdays only; how many miles over
    three weeks?" → 5·5·3 = 75. The weekday restriction means 5 countable days, never 7 — the
    exact mis-projection (5·7·3 = 105) that kept the jog vocab excluded. TIGHTLY gated: a
    digit-free "how many <X> … over/in/after <N> weeks" question; ONE premise with a per-day
    rate of X AND a weekday cue; no other valued premise; positive integer. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    wm = re.search(r"(?:over|in|after) (\w+|\d+) weeks", ql)
    if m is None or wm is None or _has_digit(ql) \
            or _has_comparative(ql):
        return None
    weeks = NUMBERS.get(wm.group(1), float(wm.group(1)) if wm.group(1).isdigit() else 0)
    if not weeks:
        return None
    asked = _singular_of(m.group(1)) or m.group(1)
    rate = None
    for p in premises:
        pl = p.lower()
        rm = re.search(r"(\d+(?:\.\d+)?) " + re.escape(asked) + r"s? per day", pl)
        if rm is not None and rate is None \
                and ("weekdays only" in pl or "on weekdays" in pl or "during weekdays" in pl):
            rate = float(rm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if rate is None:
        return None
    result = _compute(f"{_num(rate)} * 5 * {_num(weeks)}")
    return _gated_pos_int(result)


def _salary_hourly_rate_system(premises: list, question: str):
    """MONTHLY SALARY → HOURLY RATE — "monthly salary is $576; works 8 hours a day for 6 days a
    week; hourly rate?" → 576 / (8·6·4) = 3 (the GSM8K month = 4 weeks convention). TIGHTLY
    gated: a digit-free "hourly rate" question; ONE monthly-salary premise; ONE "H hours a day
    for D days a week" premise; nothing else valued; an exact positive quotient. None
    otherwise."""
    ql = question.lower()
    if "hourly rate" not in ql or _has_digit(ql):
        return None
    salary = hours = days = None
    for p in premises:
        pl = p.lower()
        sm = re.search(r"monthly salary is \$(\d+(?:\.\d+)?)", pl)
        hm = re.search(r"(\d+(?:\.\d+)?) hours a day for (\d+) days a week", pl)
        if sm is not None and salary is None:
            salary = float(sm.group(1))
        elif hm is not None and hours is None:
            hours, days = float(hm.group(1)), float(hm.group(2))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if salary is None or hours is None:
        return None
    result = _compute(f"{_num(salary)} / ({_num(hours)} * {_num(days)} * 4)")
    return _gated_pos_int(result)


def _weekly_need_per_person_daily_system(premises: list, question: str):
    """WEEKLY NEED ÷ PER-PERSON SHARE ÷ 7 — "needs 7 gallons of blood per week; 2 pints per
    person; how many people each day?" → 7·8 / 2 / 7 = 4 (gallon→pint via CONVERSIONS). TIGHTLY
    gated: a digit-free "how many people … each day" question; ONE weekly-need premise; ONE
    per-person premise (units equal or convertible); nothing else valued; positive integer.
    None otherwise."""
    ql = question.lower()
    if "how many people" not in ql or "each day" not in ql or _has_digit(ql):
        return None
    need = share = None
    for p in premises:
        pl = p.lower()
        nm = re.search(r"(\d+(?:\.\d+)?) (\w+) of \w+ per week", pl)
        sm = re.search(r"(\d+(?:\.\d+)?) (\w+) of \w+ per person", pl)
        if nm is not None and need is None:
            need = float(nm.group(1)), _singular_of(nm.group(2)) or nm.group(2)
        elif sm is not None and share is None:
            share = float(sm.group(1)), _singular_of(sm.group(2)) or sm.group(2)
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if need is None or share is None:
        return None
    factor = 1 if need[1] == share[1] else CONVERSIONS.get((need[1], share[1]))
    if factor is None:
        return None
    result = _compute(f"{_num(need[0])} * {_num(factor)} / {_num(share[0])} / 7")
    return _gated_pos_int(result)


def _per_second_minutes_week_system(premises: list, question: str):
    """PER-SECOND RATE × MINUTES/DAY × WEEK — "10 liters per second; works 10 minutes each day;
    the amount in one week?" → 10·600·7 = 42000. TIGHTLY gated: a digit-free "in one week"
    amount question; ONE per-second rate premise; ONE "M minutes each day" premise; nothing
    else valued; positive integer. None otherwise."""
    ql = question.lower()
    if "in one week" not in ql and "in a week" not in ql or _has_digit(ql):
        return None
    rate = minutes = None
    for p in premises:
        pl = p.lower()
        rm = re.search(r"(\d+(?:\.\d+)?) \w+ per second", pl)
        mm = re.search(r"(\d+(?:\.\d+)?) minutes each day", pl)
        if rm is not None and rate is None:
            rate = float(rm.group(1))
        elif mm is not None and minutes is None:
            minutes = float(mm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if rate is None or minutes is None:
        return None
    result = _compute(f"{_num(rate)} * {_num(minutes)} * 60 * 7")
    return _gated_pos_int(result)


def _phased_weeks_average_system(premises: list, question: str):
    """PHASED WEEKS → AVERAGE — "1 apple a day for two weeks; the next three weeks the same
    number as the total of the first two; the next two weeks 3 a day; over these 7 weeks, the
    weekly average?" → (14 + 14 + 42) / 7 = 10. TIGHTLY gated: an "over these W weeks … average
    a week" question whose ONLY digit is W; phase 1 "N a day for <w1> weeks"; a digit-free
    "same number … total of the first <w1> weeks" echo phase; phase 3 "next <w3> weeks … M a
    day"; the phase weeks summing to W; positive integer. None otherwise."""
    ql = question.lower()
    qm = re.search(r"over these (\d+) weeks", ql)
    if qm is None or "average" not in ql \
            or _has_digit(ql.replace(qm.group(0), "")):
        return None
    q_weeks = float(qm.group(1))
    p1 = p2w = p3 = None
    for p in premises:
        pl = p.lower()
        m1 = re.search(r"(\d+(?:\.\d+)?) \w+ a day for (\w+|\d+) weeks", pl)
        m2 = re.search(r"next (\w+|\d+) weeks[^.]*same number[^.]*total of the first", pl)
        m3 = re.search(r"next (\w+|\d+) weeks[^.]*?(\d+(?:\.\d+)?) \w+ a day", pl)
        def wk(tok):
            return NUMBERS.get(tok, float(tok) if tok.isdigit() else None)
        if m3 is not None and m2 is None and p3 is None:
            w = wk(m3.group(1))
            if w is None:
                return None
            p3 = float(m3.group(2)) * 7 * w, w
        elif m2 is not None and p2w is None and not _has_digit(p):
            w = wk(m2.group(1))
            if w is None:
                return None
            p2w = w
        elif m1 is not None and p1 is None:
            w = wk(m1.group(2))
            if w is None:
                return None
            p1 = float(m1.group(1)) * 7 * w, w
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if p1 is None or p2w is None or p3 is None or p1[1] + p2w + p3[1] != q_weeks:
        return None
    total = p1[0] + p1[0] + p3[0]                        # the echo phase repeats phase 1's total
    result = _compute(f"{_num(total)} / {_num(q_weeks)}")
    return _gated_pos_int(result)


def _pet_plus_food_cost_system(premises: list, question: str):
    """PET + CONSUMABLE COST — "a puppy that cost $10; enough food for 3 weeks; eats 1/3 cup a
    day; a bag with 3.5 cups costs $2; how much did all of this cost?" → 10 + (21·⅓)/3.5·2 =
    14. TIGHTLY gated: a digit-free "how much did all of this cost" question; ONE "cost $A"
    base; ONE "for W weeks" duration; ONE "N/D cup a day" rate; ONE "bag … C cups costs $B"
    premise; the bag division exact; positive integer. None otherwise."""
    ql = question.lower()
    if "how much did all of this cost" not in ql or _has_digit(ql):
        return None
    base = weeks = frac = bag_cups = bag_price = None
    for p in premises:
        pl = p.lower()
        bm = re.search(r"cost \$(\d+(?:\.\d+)?)", pl)
        wm = re.search(r"for (\d+) weeks", pl)
        fm = re.search(r"(\d+)/(\d+) cup", pl)
        gm = re.search(r"bag[^.]*?(\d+(?:\.\d+)?) cups costs \$(\d+(?:\.\d+)?)", pl)
        if gm is not None and bag_cups is None:
            bag_cups, bag_price = float(gm.group(1)), float(gm.group(2))
        elif fm is not None and frac is None:
            frac = float(fm.group(1)) / float(fm.group(2))
        elif bm is not None and base is None:
            base = float(bm.group(1))
        elif wm is not None and weeks is None:
            weeks = float(wm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if None in (base, weeks, frac, bag_cups, bag_price):
        return None
    cups = weeks * 7 * frac
    bags = cups / bag_cups
    if abs(bags - round(bags)) > 1e-9:
        return None                                      # the bag division must be exact
    result = _compute(f"{_num(base)} + {_num(round(bags))} * {_num(bag_price)}")
    return _gated_pos_int(result)


def _pet_food_remainder_system(premises: list, question: str):
    """PET-FOOD REMAINDER — "three dogs; each eats 1/2 of a pound twice a day; bought 30 pounds;
    how many pounds left after a week?" → 30 − 3·0.5·2·7 = 9. TIGHTLY gated: a digit-free "how
    many pounds … left after a week" question; a count-of-animals premise; ONE "each <animal>
    eats N/D of a pound … twice/K-times a day" premise; ONE "bought T pounds" premise; no other
    valued premise; non-negative result. None otherwise."""
    ql = question.lower()
    if re.search(r"how many pounds .*left after a week", ql) is None \
            or _has_digit(ql):
        return None
    count = frac = per_day = total = None
    for p in premises:
        pl = p.lower()
        cm = re.search(r"has (\w+) \w+s\b", pl)
        em = re.search(r"each \w+ eats (\d+)/(\d+) of a pound", pl)
        bm = re.search(r"bought (\d+(?:\.\d+)?) pounds", pl)
        if em is not None and frac is None:
            frac = float(em.group(1)) / float(em.group(2))
            per_day = 2 if "twice a day" in pl else None
            km = re.search(r"(\w+) times a day", pl)
            if per_day is None and km is not None:
                per_day = NUMBERS.get(km.group(1))
            if per_day is None:
                return None
        elif bm is not None and total is None:
            total = float(bm.group(1))
        elif cm is not None and count is None and not _has_digit(p):
            count = NUMBERS.get(cm.group(1))
            if count is None:
                return None
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if None in (count, frac, per_day, total):
        return None
    result = _compute(f"{_num(total)} - {_num(count)} * {_num(frac)} * {_num(per_day)} * 7")
    return _gated_nonneg(result)


def _orchard_pack_revenue_system(premises: list, question: str):
    """ORCHARD → PACKS → REVENUE — "10 trees, picks 12 oranges each day; sells 6-packs for $2;
    how much earned after 3 weeks selling all?" → 10·12·21/6·2 = 840. TIGHTLY gated: a "how much
    money … after W weeks" question whose ONLY digit is W; ONE trees×per-day premise; ONE
    "K-packs … for $P" premise; no other valued premise; the pack division exact; positive
    integer. None otherwise."""
    ql = question.lower()
    wm = re.search(r"after (\d+) weeks", ql)
    if "how much money" not in ql or wm is None \
            or _has_digit(ql.replace(wm.group(0), "")):
        return None
    weeks = float(wm.group(1))
    trees = per_day = pack = price = None
    for p in premises:
        pl = p.lower()
        tm = re.search(r"(\d+) \w+ trees[^.]*?pick (\d+) \w+ each day", pl)
        km = re.search(r"(\d+)-packs? of \w+ for \$(\d+(?:\.\d+)?)", pl)
        if tm is not None and trees is None:
            trees, per_day = float(tm.group(1)), float(tm.group(2))
        elif km is not None and pack is None:
            pack, price = float(km.group(1)), float(km.group(2))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if None in (trees, per_day, pack, price):
        return None
    total = trees * per_day * 7 * weeks
    if total % pack:
        return None                                      # the pack division must be exact
    result = _compute(f"{_num(total)} / {_num(pack)} * {_num(price)}")
    return _gated_pos_int(result)


def _shared_item_cost_system(premises: list, question: str):
    """SHARED DAILY ITEM → COST — "shares half of a small apple with her dog every day; an apple
    weighs 1/4 of a pound; $2.00 a pound; enough to last 2 weeks?" → she and the dog eat ONE
    whole apple a day between them: 14·0.25·2 = 7. TIGHTLY gated: a digit-free "how much will
    she spend" question; a digit-free "shares half of a … every day" premise; ONE "N/D of a
    pound" weight; ONE "$P a pound" price; ONE "last for W weeks" duration; no other valued
    premise; positive result. None otherwise."""
    ql = question.lower()
    if "how much" not in ql or "spend" not in ql or _has_digit(ql):
        return None
    body = " ".join(premises).lower()
    if not re.search(r"shares half of a [^.]*every day", body):
        return None
    weight = price = weeks = None
    for p in premises:
        pl = p.lower()
        wm = re.search(r"(\d+)/(\d+) of a pound", pl)
        pm = re.search(r"\$(\d+(?:\.\d+)?) a pound", pl)
        lm = re.search(r"last for (\d+) weeks", pl)
        if wm is not None and weight is None:
            weight = float(wm.group(1)) / float(wm.group(2))
        elif pm is not None and price is None:
            price = float(pm.group(1))
        elif lm is not None and weeks is None:
            weeks = float(lm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if None in (weight, price, weeks):
        return None
    result = _compute(f"{_num(weeks)} * 7 * {_num(weight)} * {_num(price)}")
    return _gated_pos(result)


def _everyday_plus_half_subdays_system(premises: list, question: str):
    """EVERY-DAY RATE + HALF-RATE SUB-ACTIVITY — "watches TV 4 hours every day; on game days he
    plays for half as long as he watches TV; plays 3 days a week; how long watching TV and
    playing?" → 4·7 + 2·3 = 34. The game-day count rides INSIDE the question clause. TIGHTLY
    gated: a "how long" question whose ONLY digit is the "N days a week" count; ONE digit premise
    (the every-day hours rate); a digit-free "half as long as" premise; positive integer. None
    otherwise."""
    ql = question.lower()
    if "how long" not in ql:
        return None
    dm = re.search(r"(\d+) days? a week", ql)
    count_premise = None
    if dm is not None:
        if _has_digit(ql.replace(dm.group(0), "")):
            return None
    else:
        # the #206 conditional-question split moves "If he plays … 4 days a week" out of the
        # question into a premise — accept it from an "If"-conditional premise whose ONLY
        # digit is the count (same tightness as the in-question read).
        if _has_digit(ql):
            return None
        for p in premises:
            pl = p.lower()
            m = re.search(r"(\d+) days? a week", pl)
            if m is not None and pl.lstrip().startswith("if ") \
                    and not _has_digit(pl.replace(m.group(0), "")):
                dm, count_premise = m, p
                break
        if dm is None:
            return None
    sub_days = float(dm.group(1))
    rate = None
    half_seen = False
    for p in premises:
        if p is count_premise:
            continue
        pl = p.lower()
        rm = re.search(r"for (\d+(?:\.\d+)?) hours every day", pl)
        if rm is not None and rate is None:
            rate = float(rm.group(1))
        elif "half as long as" in pl and not _has_digit(p):
            half_seen = True
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if rate is None or not half_seen or not 0 < sub_days <= 7:
        return None
    result = _compute(f"{_num(rate)} * 7 + {_num(rate)} / 2 * {_num(sub_days)}")
    return _gated_pos_int(result)


def _paired_daily_rate_week_system(premises: list, question: str):
    """PAIRED DAILY RATES × TIMES-A-WEEK — "Five times a week, Onur bikes 250 km a day; Hanil
    bikes 40 more km in a day; total distance the two friends bike in a week?" → (250 + 290)·5
    = 2700. Both premises materialize ZERO facts (the double frequency drops everything).
    TIGHTLY gated: a digit-free "total distance … two friends … week" question; ONE "<word>
    times a week … N <unit> a day" premise; ONE "M more <unit> … a day" companion premise; no
    other valued premise; positive integer. None otherwise."""
    ql = question.lower()
    if "total distance" not in ql or "two friends" not in ql or "week" not in ql \
            or _has_digit(ql):
        return None
    base = delta = times = None
    for p in premises:
        pl = p.lower()
        bm = re.search(r"(\w+) times a week[^.]*?(\d+(?:\.\d+)?) \w+ a day", pl)
        dm = re.search(r"(\d+(?:\.\d+)?) more \w+", pl)
        if bm is not None and base is None:
            times = NUMBERS.get(bm.group(1))
            base = float(bm.group(2))
            if not times:
                return None
        elif dm is not None and delta is None:
            delta = float(dm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if base is None or delta is None or times is None:
        return None
    result = _compute(f"({_num(base)} + {_num(base)} + {_num(delta)}) * {_num(times)}")
    return _gated_pos_int(result)


def _weekday_production_revenue_system(premises: list, question: str):
    """WEEKDAY PRODUCTION × WEEKS × PRICE — "makes cakes during the five weekdays; 4 cakes a day;
    sells for $8; in 4 weeks sold all; how much money did she collect?" → 4·5·4·8 = 640. TIGHTLY
    gated: a digit-free "how much money … collect/earn/make" question; a digit-free "during the
    five weekdays" premise; ONE "makes N <item> a day" premise; ONE "$P" price premise; ONE
    "in W weeks" premise; no other valued premise; positive integer. None otherwise."""
    ql = question.lower()
    if "how much money" not in ql or _has_digit(ql) \
            or not any(v in ql for v in ("collect", "earn", "make")):
        return None
    body = " ".join(premises).lower()
    if "during the five weekdays" not in body:
        return None
    per_day = price = weeks = None
    for p in premises:
        pl = p.lower()
        mm = re.search(r"makes (\d+(?:\.\d+)?) \w+ a day", pl)
        pm = re.search(r"for \$(\d+(?:\.\d+)?)", pl)
        wm = re.search(r"in (\d+) weeks", pl)
        if mm is not None and per_day is None:
            per_day = float(mm.group(1))
        elif pm is not None and price is None:
            price = float(pm.group(1))
        elif wm is not None and weeks is None:
            weeks = float(wm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if per_day is None or price is None or weeks is None:
        return None
    result = _compute(f"{_num(per_day)} * 5 * {_num(weeks)} * {_num(price)}")
    return _gated_pos_int(result)


def _named_day_chain_split_system(premises: list, question: str):
    """NAMED-DAY CHAIN + EVEN WEEKEND SPLIT — "On Monday 4 hours then twice this long on Tuesday;
    Wed/Thu/Fri 3 hours each day; total of 25 over the week; remaining split evenly between
    Saturday and Sunday; how many hours on Saturday?" → (25 − (4 + 8 + 9)) / 2 = 2. TIGHTLY
    gated: a digit-free "how many hours … on Saturday/Sunday" question; the even-split cue;
    the Monday-then-twice-Tuesday premise; the three-day each-day premise; a weekly total; and
    EXACTLY those three numbers in the whole body. None otherwise."""
    ql = question.lower()
    if re.search(r"how many hours .*on (saturday|sunday)", ql) is None \
            or _has_digit(ql):
        return None
    body = " ".join(premises).lower()
    if "evenly between saturday and sunday" not in body:
        return None
    m1 = re.search(r"on monday[^.]*?(\d+(?:\.\d+)?) hours[^.]*twice this long on tuesday", body)
    m2 = re.search(r"on wednesday, thursday, and friday[^.]*?(\d+(?:\.\d+)?) hours each day", body)
    m3 = re.search(r"total of (\d+(?:\.\d+)?) hours over the week", body)
    if not (m1 and m2 and m3) or len(re.findall(r"\d+(?:\.\d+)?", body)) != 3:
        return None
    n, m, t = float(m1.group(1)), float(m2.group(1)), float(m3.group(1))
    result = _compute(f"({_num(t)} - ({_num(n)} + 2 * {_num(n)} + 3 * {_num(m)})) / 2")
    return _gated_pos_int(result)


def _rate_hours_clock_week_system(premises: list, question: str):
    """PER-HOUR RATE × (SPAN-DAYS + CLOCK-SPAN) — "mends 3 pairs in an hour; Monday to Thursday
    8 hours each day; Friday works from 8am to 11am; how many in a week?" → 3 · (4·8 + 3) = 105.
    TIGHTLY gated: a digit-free "how many <X> … in a week" question; ONE per-hour rate premise;
    ONE "from <day> to <day> … N hours each day" span premise; ONE "from Ham to Ham" clock
    premise (same-am span, end > start); no other valued premise; positive integer. None
    otherwise."""
    ql = question.lower()
    if re.search(r"how many \w+", ql) is None or "week" not in ql \
            or _has_digit(ql):
        return None
    rate = span_hours = clock_hours = None
    for p in premises:
        pl = p.lower()
        rm = re.search(r"(\d+(?:\.\d+)?) \w+ (?:of \w+ )?in an hour", pl)
        sm = re.search(r"from (\w+) to (\w+)[^.]*?(\d+(?:\.\d+)?) hours each day", pl)
        cm = re.search(r"from (\d+)am to (\d+)am", pl)
        if rm is not None and rate is None:
            rate = float(rm.group(1))
        elif sm is not None and span_hours is None \
                and sm.group(1) in _WEEKDAYS and sm.group(2) in _WEEKDAYS:
            days = _WEEKDAYS.index(sm.group(2)) - _WEEKDAYS.index(sm.group(1)) + 1
            if days < 2:
                return None
            span_hours = days * float(sm.group(3))
        elif cm is not None and clock_hours is None and int(cm.group(2)) > int(cm.group(1)):
            clock_hours = int(cm.group(2)) - int(cm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if rate is None or span_hours is None or clock_hours is None:
        return None
    result = _compute(f"{_num(rate)} * ({_num(span_hours)} + {_num(clock_hours)})")
    return _gated_pos_int(result)


def _sales_funnel_week_system(premises: list, question: str):
    """SALES FUNNEL × WEEK — "visits 50 houses a day; 20% of them buy; of those, half buy a $50
    set and the other half a $150 set; how much does he sell a week working 5 days a week?" →
    50 · 0.20 · (50+150)/2 · 5 = 5000. TIGHTLY gated: a "how much … sell/earn/make … week"
    question whose ONLY digit is the days/week count; ONE per-day visit-count premise; ONE
    "P% of them" conversion premise (no other value); exactly TWO "half buy … $A" price premises
    (the two halves averaging is exact); no other valued premise; positive integer. None
    otherwise."""
    ql = question.lower()
    if "how much" not in ql or "week" not in ql \
            or not any(v in ql for v in ("sell", "earn", "make")):
        return None
    dm = re.search(r"(\d+) days? a week", ql)
    if dm is None or _has_digit(ql.replace(dm.group(0), "")):
        return None
    days = float(dm.group(1))
    visits = pct = None
    halves = []
    for p in premises:
        pl = p.lower()
        vm = re.search(r"(\d+(?:\.\d+)?) \w+ (?:per|a|each) day", pl)
        cm = re.search(r"(\d+(?:\.\d+)?)\s*% of them buy", pl)
        hm = re.search(r"half buy[^.]*?\$(\d+(?:\.\d+)?)", pl)
        if hm is not None:
            if len(halves) >= 2 or len(re.findall(r"\d+(?:\.\d+)?", pl.replace("$", ""))) != 1:
                return None
            halves.append(float(hm.group(1)))
        elif cm is not None and pct is None:
            pct = float(cm.group(1))
        elif vm is not None and visits is None:
            visits = float(vm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if visits is None or pct is None or len(halves) != 2 or not 0 < pct <= 100:
        return None
    result = _compute(f"{_num(visits)} * {_num(pct)} / 100 * "
                      f"({_num(halves[0])} + {_num(halves[1])}) / 2 * {_num(days)}")
    return _gated_pos_int(result)


def _workweek_boost_system(premises: list, question: str):
    """WORKWEEK WITH ONE BOOSTED DAY — "borrows an average of 40 books every day; every Friday
    the number is 40% higher than the daily average; how many in a week if open from Monday to
    Friday?" → 4·40 + 40·1.4 = 216. TIGHTLY gated: a digit-free "how many <X> … week" question
    carrying a "from <weekday> to <weekday>" open-span; ONE per-day average premise; ONE boost
    premise naming exactly ONE weekday (inside the span) with an "N% higher" factor; no other
    valued premise; positive integer. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    sm = re.search(r"from (\w+) to (\w+)", ql) \
        or next((mm for p in premises if not _has_digit(p)
                 for mm in [re.search(r"open from (\w+) to (\w+)", p.lower())] if mm), None)
    if m is None or sm is None or "week" not in ql or _has_digit(ql):
        return None                                      # the open-span may sit in a split-off premise
    lo, hi = sm.group(1), sm.group(2)
    if lo not in _WEEKDAYS or hi not in _WEEKDAYS:
        return None
    span = _WEEKDAYS.index(hi) - _WEEKDAYS.index(lo) + 1
    if span < 2:
        return None
    base = pct = None
    boost_day = None
    for p in premises:
        pl = p.lower()
        bm = re.search(r"average of (\d+(?:\.\d+)?)[^.]*?(?:every|a|per|each) day", pl)
        hm = re.search(r"(\d+(?:\.\d+)?)\s*% higher", pl)
        days_here = [d for d in _WEEKDAYS if d in pl]
        if bm is not None and base is None and not days_here:
            base = float(bm.group(1))
        elif hm is not None and pct is None and len(days_here) == 1:
            pct, boost_day = float(hm.group(1)), days_here[0]
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if base is None or pct is None or not 0 < pct <= 100 \
            or _WEEKDAYS.index(lo) > _WEEKDAYS.index(boost_day) \
            or _WEEKDAYS.index(boost_day) > _WEEKDAYS.index(hi):
        return None
    result = _compute(f"{_num(base)} * {span - 1} + {_num(base)} * (1 + {_num(pct)} / 100)")
    return _gated_pos_int(result)


def _boosted_rate_duration_system(premises: list, question: str):
    """PERCENT-BOOSTED RATE × DURATION — "Brendan can cut 8 yards per day; a lawnmower helped him
    cut more yards by Fifty percent per day; how many yards after a week?" → 8·1.5·7 = 84.
    TIGHTLY gated: a "how many <X> … after a week / in N weeks" question (the only question digit
    may be the week count); ONE base premise (a per-day value of X); ONE percent-boost premise
    (percent + a more/increase/higher cue, and NO weekday/average mention — a "40% higher every
    FRIDAY" is a workweek structure, another shape); no other valued premise; positive integer.
    The banned "N times more" idiom is NOT read (percent only). None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or _has_comparative(ql) \
            or any(d in ql for d in _WEEKDAYS):
        return None
    asked = m.group(1)
    days = 7 if re.search(r"\bafter (a|one) week\b", ql) else None
    wm = re.search(r"\bin (\w+|\d+) weeks?\b", ql)
    if days is None and wm is not None:
        n = NUMBERS.get(wm.group(1), float(wm.group(1)) if wm.group(1).isdigit() else 0)
        days = n * 7 if n else None
        if _has_digit(ql.replace(wm.group(0), "")):
            return None                                  # a question digit beyond the week count
    elif _has_digit(ql):
        return None
    if days is None:
        return None
    base = pct = None
    for p in premises:
        pl = p.lower()
        bm = re.search(r"(\d+(?:\.\d+)?) " + re.escape(asked) + r"\b[^.]*?(?:per|a|each) day", pl)
        pm = re.search(r"(\w+|\d+)(?:%| percent)", pl)
        if bm is not None and base is None:
            base = float(bm.group(1))
            continue
        if pm is not None and any(c in pl for c in ("more", "increase", "higher")):
            if pct is not None or any(d in pl for d in _WEEKDAYS) or "average" in pl:
                return None
            pct = NUMBERS.get(pm.group(1), float(pm.group(1)) if pm.group(1).isdigit() else 0)
            if not pct:
                return None
            continue
        if _has_digit(p):
            return None                                  # an unclassified valued premise
    if base is None or pct is None or not 0 < pct <= 100:
        return None
    result = _compute(f"{_num(base)} * (1 + {_num(pct)} / 100) * {_num(days)}")
    return _gated_pos_int(result)


def _doubling_days_sum_system(premises: list, question: str):
    """DOUBLING-DAYS GEOMETRIC SUM — "the first day she spends 5 minutes; each following day twice
    as much as the day before; after the 5th day …; how much time that week?" → 5·(2⁵−1) = 155.
    TIGHTLY gated: a digit-free "how much/many … week" total question; a FIRST-DAY value premise;
    a digit-free DOUBLING premise ("twice as much … as the day before/previous day"); an "after
    the Nth day" limit; no other valued premise; positive integer sum. None otherwise."""
    ql = question.lower()
    if "week" not in ql or not ("how much" in ql or "how many" in ql) \
            or _has_digit(ql) \
            or _has_comparative(ql):
        return None
    first = n_days = None
    doubling = False
    for p in premises:
        pl = p.lower()
        fm = re.search(r"first day[^.]*?(\d+(?:\.\d+)?)", pl)
        nm = re.search(r"after the (\d+)(?:st|nd|rd|th) day", pl)
        if "twice as much" in pl and ("day before" in pl or "previous day" in pl):
            if _has_digit(p):
                return None
            doubling = True
        elif fm is not None and first is None:
            first = float(fm.group(1))
        elif nm is not None and n_days is None:
            n_days = int(nm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if first is None or n_days is None or not doubling or not 1 < n_days <= 10:
        return None
    result = _compute(f"{_num(first)} * {_num(2 ** n_days - 1)}")   # Σ a·2^k = a·(2^n − 1); the
    return _gated_pos_int(result)                                   # power folds to a literal (n ≤ 10)


def _alternating_days_diff_system(premises: list, question: str):
    """ALTERNATING-DAYS CATEGORY DIFFERENCE — "On Mondays, Wednesdays and Fridays he bakes APPLE
    pies. On Tuesdays and Thursdays he bakes CHERRY pies. He bakes 12 pies per day; how many MORE
    apple pies than cherry pies in one week?" → 12 · (3 − 2) = 12. TIGHTLY gated: a "how many more
    <catA> … than <catB>" week question (digit-free); exactly TWO weekday-list premises, each
    naming one category and its days (disjoint sets, no digits); ONE per-day rate premise; the
    "more" category has strictly more days; positive integer. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many more (\w+) \w+ .*than (\w+)", ql)
    if m is None or "week" not in ql or _has_digit(ql):
        return None
    cat_a, cat_b = m.group(1), m.group(2)
    day_lists: dict = {}
    rate = None
    for p in premises:
        pl = p.lower()
        days = [d for d in _WEEKDAYS if d in pl]
        rm = re.search(r"(\d+(?:\.\d+)?) \w+ (?:per|a|each) day", pl)
        if days and not _has_digit(p):
            cat = cat_a if cat_a in pl else (cat_b if cat_b in pl else None)
            if cat is None or cat in day_lists:
                return None
            day_lists[cat] = set(days)
        elif rm is not None and rate is None and not days:
            rate = float(rm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if rate is None or set(day_lists) != {cat_a, cat_b} \
            or day_lists[cat_a] & day_lists[cat_b] \
            or len(day_lists[cat_a]) <= len(day_lists[cat_b]):
        return None
    result = _compute(f"{_num(rate)} * ({len(day_lists[cat_a])} - {len(day_lists[cat_b])})")
    return _gated_pos_int(result)


def _day_list_target_system(premises: list, question: str):
    """DAY-LIST TARGET RESIDUAL — day-tagged values across a week plus a TARGET, asked "how many
    on <day> to reach/beat it": "average of 50 pages a day; read 43 Sun, 65 Mon, 28 Tue, nothing
    Wed, 70 Thu, 56 Fri; how many on Saturday to reach his goal?" → 50·7 − 262 = 88. A "beats last
    week's N" target needs one MORE: N + 1 − Σ. TIGHTLY gated: a digit-free question naming a
    weekday plus a reach/beat cue; every OTHER weekday named in the premises carries a value or an
    explicit zero-cue ("read nothing", "skipped a day"); exactly one target premise (an "average
    of N … a day" or a "last week … N total"); every digit accounted; ≥4 listed days; a positive
    integer residual. None otherwise."""
    ql = question.lower()
    q_days = [d for d in _WEEKDAYS if d in ql]
    if not 1 <= len(q_days) <= 2 or _has_digit(ql) \
            or not any(c in ql for c in ("reach", "beat", "goal", "average", "meet")):
        return None
    num = r"(\d+(?:,\d{3})*(?:\.\d+)?)"                 # comma-aware ("9,400")
    def val(tok):
        return float(tok.replace(",", ""))
    kept = []
    for p in premises:                                   # a digit-free stray fragment naming a day
        pl = p.lower()                                   # + a goal cue is the question's SEVERED
        frag_days = [d for d in _WEEKDAYS if d in pl]    # tail ("… on Friday" | "Saturday to meet
        if frag_days and not _has_digit(p) \
                and any(c in pl for c in ("meet", "reach", "goal")) \
                and all(d not in q_days for d in frag_days):
            q_days += frag_days                          # his goal?") — absorb it as an asked day
        else:
            kept.append(p)
    premises = kept
    if not 1 <= len(q_days) <= 2:
        return None
    avg = last_total = None
    day_vals: dict = {}
    for p in premises:
        pl = p.lower()
        am = re.search(r"average of " + num + r"[^.]*?(?:a|per|each) day", pl)
        lm = re.search(r"last week [^.]*?" + num + r" total", pl)
        days_here = [d for d in _WEEKDAYS if d in pl]
        if am is not None:
            avg = val(am.group(1))
            continue
        if lm is not None:
            last_total = val(lm.group(1))
            continue
        if not days_here:
            if _has_digit(p):
                return None                              # a valued premise outside the day list
            continue
        # pair each listed day with the value (or zero-cue) in ITS comma/and segment
        for seg in re.split(r",(?!\d)| and ", pl):        # never split INSIDE "9,400"
            seg_day = next((d for d in _WEEKDAYS if d in seg), None)
            if seg_day is None:
                continue
            if seg_day in q_days:
                if re.search(r"\d", seg):
                    return None                          # an asked day PRE-VALUED → not this shape
                continue                                 # a bare mention ("On Saturday, he looks…")
            if seg_day in day_vals:
                return None                              # a duplicate day
            nm = re.search(num, seg)
            if nm is not None:
                day_vals[seg_day] = val(nm.group(1))
            elif any(c in seg for c in _ZERO_CUES) or any(c in pl for c in _ZERO_CUES):
                day_vals[seg_day] = 0.0
            else:
                return None                              # a listed day with no value and no zero-cue
    if len(day_vals) < 4 or (avg is None) == (last_total is None):
        return None                                     # exactly ONE kind of target
    if avg is not None:
        target = avg * 7
        if "beat" in ql:
            return None                                 # an average target answers "reach", not "beat"
    else:
        if "beat" not in ql or len(q_days) != 1:
            return None                                 # a beat-target asks ONE day
        target = last_total + 1                         # strictly MORE than last week
    if len(day_vals) + len(q_days) != 7:
        return None                                     # listed + asked must cover the week exactly
    result = _compute(f"({_num(target)} - ({' + '.join(_num(v) for v in day_vals.values())}))"
                      f" / {len(q_days)}")
    return _gated_pos_int(result)


def _rate_days_weeks_system(premises: list, question: str):
    """HOURS/DAY × DAYS/WEEK × WEEKS — "exercise 1 hour a day, 5 days a week, for 8 weeks; how many
    hours?" → 40; "1 hour 30 minutes every day … after two weeks?" → 1.5·7·14/7 = 21; "10 hours
    every day, five days a week … in a month" → 10·5·4 = 200 (the GSM8K month = 4 weeks
    convention). Reads RAW premises (these goal/habit clauses materialize no usable fact — "1 hour
    30 minutes" even mis-reads as 1). TIGHTLY gated: a digit-free non-comparative HOURS question;
    a per-day-cued hours rate; a weeks duration ("for/after N weeks", or "in a month" in the
    question); days/week explicit or 7 via an every-day cue; every digit premise classified;
    positive integer total. None otherwise."""
    ql = question.lower()
    if "hour" not in ql or _has_digit(ql) \
            or _has_comparative(ql):
        return None
    body = " ".join(premises).lower()
    rate = days = weeks = None
    for p in premises:
        pl = p.lower()
        has_digit = _has_digit(p)
        rm = re.search(r"(\d+(?:\.\d+)?) hours?(?: (?:and )?(\d+) minutes?)?", pl)
        if rm is not None and any(c in pl for c in _PER_DAY_CUES):
            if rate is not None:
                return None
            rate = float(rm.group(1)) + (float(rm.group(2)) / 60 if rm.group(2) else 0)
        elif has_digit and not re.search(
                r"(\w+|\d+) days? a week|(?:for|after) (\w+|\d+) weeks?", pl):
            return None                                  # an unclassified valued premise → not this shape
        dm = re.search(r"(\w+|\d+) days? a week", pl)
        if dm is not None:
            if days is not None:
                return None
            days = float(NUMBERS.get(dm.group(1), dm.group(1) if dm.group(1).isdigit() else 0) or 0)
        wm = re.search(r"(?:for|after) (\w+|\d+) weeks?", pl)
        if wm is not None:
            if weeks is not None:
                return None
            weeks = float(NUMBERS.get(wm.group(1), wm.group(1) if wm.group(1).isdigit() else 0) or 0)
    if weeks is None:                                    # the duration may sit in the QUESTION
        qm = re.search(r"(?:for|after|in) (\w+) weeks?\b", ql)
        if qm is not None:
            weeks = float(NUMBERS.get(qm.group(1), 0) or 0) or None
        elif "in a month" in ql:
            weeks = 4                                    # the GSM8K month = 4 weeks convention
    if rate is None or weeks is None or weeks < 2 or rate <= 0:
        return None
    if days is None:
        if not any(c in body for c in ("every day", "each day", "daily")):
            return None
        days = 7
    if days <= 0:
        return None
    result = _compute(f"{_num(rate)} * {_num(days)} * {_num(weeks)}")
    return _gated_pos_int(result)


def _weekly_time_plus_delta_system(premises: list, question: str):
    """WEEKLY TIME + DELTA — "reads 2 hours each day; decided to increase his weekly time by 4
    hours; how much time during one week?" → 2·7 + 4 = 18. TIGHTLY gated: a digit-free "how much
    time … week" question; exactly TWO digit premises — a per-day hours Rate and an "increase …
    weekly … by N hours" delta; positive integer result. None otherwise."""
    ql = question.lower()
    if "how much time" not in ql or "week" not in ql or _has_digit(ql) \
            or _has_comparative(ql):
        return None
    rate = delta = None
    disc, ctx = [], []
    for p in premises:
        fs = learn(p, disc, ctx) or []
        ctx += fs
        pl = p.lower()
        if not _has_digit(p):
            continue
        r = next((f for f in fs if isinstance(f, Rate) and f.per_unit == "day"
                  and f.measure[0] == "hour"), None)
        dm = re.search(r"increase .*weekly.*by (\d+(?:\.\d+)?) hours?", pl)
        if r is not None and rate is None:
            rate = r.amount
        elif dm is not None and delta is None:
            delta = float(dm.group(1))
        else:
            return None                                  # an unclassified valued premise → not this shape
    if rate is None or delta is None:
        return None
    result = _compute(f"{_num(rate)} * 7 + {_num(delta)}")
    return _gated_pos_int(result)


def _daily_rate_difference_system(premises: list, question: str):
    """DAILY RATE DIFFERENCE, MIXED SIDES — "Ryan's five books were a total of 2100 pages; his
    brother got 200 pages a day; both finished in a week; how many MORE pages per day did Ryan
    read compared to his brother?" → 2100/7 − 200 = 100. Each side's daily rate is either a
    per-day premise value or a stated TOTAL ÷ the shared duration ("in a week"). TIGHTLY gated:
    a digit-free "how many more <X> per day … than/compared to" question naming both parties;
    exactly one candidate value per side; a positive-integer difference. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many more (\w+) (?:per|a|each) day", ql)
    std_m = re.search(r"(?:than|compared to) (?:his |her |their )?(\w+)", ql)
    if m is None or std_m is None or _has_digit(ql):
        return None
    asked = _singular_of(m.group(1)) or m.group(1)
    standard = _singular_of(std_m.group(1)) or std_m.group(1)
    days = 7 if re.search(r"\bin (a|one) week\b", " ".join(premises).lower()) else None
    dm = re.search(r"\bin (\w+) (week|day)s?\b", " ".join(premises).lower())
    if days is None and dm is not None:
        n = NUMBERS.get(dm.group(1), float(dm.group(1)) if dm.group(1).isdigit() else 0)
        if n:
            days = n * (7 if dm.group(2) == "week" else 1)
    sides: dict = {}                                     # entity → (value, is_daily)
    disc, ctx = [], []
    for p in premises:
        all_fs = learn(p, disc, ctx) or []
        ctx += all_fs
        fs = [f for f in all_fs if isinstance(f, Quantity)
              and f.amount is not None and f.measure[0] == asked]
        for f in fs:
            if f.entity in sides:
                return None                              # two values on one side → not this shape
            sides[f.entity] = (f.amount, any(c in p.lower() for c in _PER_DAY_CUES))
    if len(sides) != 2 or standard not in sides:
        return None
    subj = next(e for e in sides if e != standard)
    def daily(entry):
        val, is_daily = entry
        if is_daily:
            return val
        return None if days is None else val / days
    a, b = daily(sides[subj]), daily(sides[standard])
    if a is None or b is None:
        return None
    result = _compute(f"{_num(a)} - {_num(b)}")
    return _gated_pos_int(result)


def _inverse_distribution_system(premises: list, question: str):
    """INVERSE DISTRIBUTION — the recipient COUNT from a total and a per-recipient share: "Jason
    bought 4 dozen cupcakes. He plans to give 3 cupcakes each to his cousins. How many cousins does
    Jason have?" → 48/3 = 16. The share premise materializes no fact ("3 cupcakes each" with the
    recipient count elided). TIGHTLY gated: a digit-free non-comparative "how many <group>"
    question; ONE total Quantity of the item (a non-loss verb); ONE share premise carrying "give …
    N <item> each" AND naming the asked group; no other valued premise; an exact positive integer
    quotient. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or _has_digit(ql) \
            or any(w in ql for w in ("more", "fewer", "less", "than", "each", " per ")):
        return None
    group = _singular_of(m.group(1)) or m.group(1)
    total = share = item = None
    disc, ctx = [], []
    for p in premises:
        fs = [f for f in (learn(p, disc, ctx) or []) if isinstance(f, Quantity) and f.amount is not None]
        ctx += fs
        pl = p.lower()
        words = {_singular_of(_key(w)) or _key(w) for w in p.split()}
        if group in words and re.search(r"\bg[ai]ve[sn]?\b", pl) and " each" in pl:
            if share is not None or len(re.findall(r"\d+(?:\.\d+)?", pl)) != 1:
                return None
            share = float(re.findall(r"\d+(?:\.\d+)?", pl)[0])
            continue
        if len(fs) == 1 and fs[0].verb not in LOSS_VERBS and total is None:
            total, item = fs[0].amount, fs[0].measure[0]
        elif _has_digit(p):
            return None                                  # an unclassified valued premise → not this shape
    if total is None or share is None or share <= 0 or item == group:
        return None
    result = _compute(f"{_num(total)} / {_num(share)}")
    return _gated_pos_int(result)


def _split_with_system(premises: list, question: str):
    """SPLIT-WITH (K+1 SHARERS) — "Mark has two dozen eggs to split with his three siblings. How
    many eggs does each person get?" → the owner shares TOO: 24 / (3+1) = 6. The "with" frame (vs
    between/among) is what adds the distributor to the sharer set. TIGHTLY gated: a digit-free
    "how many <item> … each" question; ONE premise carrying "split/share with" whose facts are
    exactly the item total and an integer count of the co-sharers; an exact positive integer
    share. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or "each" not in ql or _has_digit(ql) \
            or _has_comparative(ql):
        return None
    item = _singular_of(m.group(1)) or m.group(1)
    src = [p for p in premises if re.search(r"\b(split|share|divide) (it |them )?with\b", p.lower())]
    if len(src) != 1 or any(_has_digit(p) or "dozen" in p.lower()
                            for p in premises if p is not src[0]):
        return None
    disc, ctx = [], []
    fs = [f for f in (learn(src[0], disc, ctx) or []) if isinstance(f, Quantity) and f.amount is not None]
    totals = [f for f in fs if f.measure[0] == item]
    others = [f for f in fs if f.measure[0] != item]
    if len(totals) != 1 or len(others) != 1:
        return None
    k = others[0].amount
    if k != float(int(k)) or k <= 0:
        return None
    result = _compute(f"{_num(totals[0].amount)} / ({_num(k)} + 1)")
    return _gated_pos_int(result)


def _years_until_ratio_system(premises: list, question: str):
    """YEARS-UNTIL-RATIO — "Beth is 18, her little sister is 5; in how many years would she be
    TWICE her sister's age?" → both advance together: A+t = k·(B+t) → t = (A − k·B)/(k−1) = 8.
    The general fold cannot touch this: the sister's bare-copula age ("her little sister is 5")
    drops entirely (a valueless Predication), and the kinship genitive frame has no owner. Reads
    RAW premises. TIGHTLY gated: an "in how many years" question with a WORD multiplier and a
    genitive "<Y>'s age" (or "as old as <Y>") standard; exactly TWO "<person> is N" age premises,
    one of them the standard Y; k > 1, both ages positive, t a positive integer. None otherwise."""
    ql = question.lower()
    if "in how many years" not in ql or ("age" not in ql and "as old as" not in ql):
        return None
    mult, mpos = None, 0
    mm = re.search(r"\btwice\b|\bdouble\b", ql)
    if mm is not None:
        mult, mpos = 2.0, mm.end()
    else:
        tm = re.search(r"\b(\w+) times\b", ql)
        if tm is not None and NUMBERS.get(tm.group(1)):
            mult, mpos = float(NUMBERS[tm.group(1)]), tm.end()
    if mult is None or mult <= 1:
        return None
    # the STANDARD is the genitive AFTER the multiplier ("double AHMED'S current age") — the
    # subject's own genitive may precede it ("will Fouad's age be double …")
    sm = re.search(r"(\w+)[’']s (?:current |present )?age", ql[mpos:]) \
        or re.search(r"as old as (?:her |his |their )?(\w+)", ql)
    if sm is None:
        return None
    standard = sm.group(1)
    ages = []                                            # (person-word, age) via the bare copula
    for p in premises:
        for person, val in re.findall(r"(\w+) is (\d+(?:\.\d+)?)\b", p.lower()):
            if person in ("she", "he", "it", "that", "there", "this"):
                return None                              # a pronoun subject — can't attribute the age
            ages.append((person, float(val)))
    if len(ages) != 2:
        return None
    std = next((a for a in ages if a[0] == standard), None)
    subj = next((a for a in ages if a[0] != standard), None)
    if std is None or subj is None or std[1] <= 0 or subj[1] <= 0:
        return None
    result = _compute(f"({_num(subj[1])} - {_num(mult)} * {_num(std[1])}) / ({_num(mult)} - 1)")
    return _gated_pos_int(result)


def _remainder_after_rate_system(premises: list, question: str):
    """REMAINDER AFTER A RATED STRETCH — "381 pages in the book; already read 149; reads 20 pages a
    day for a week; how many pages are still left?" → 381 − 149 − 20·7 = 92. TIGHTLY gated: a
    digit-free "how many <X> … left" question; a "there are/is N <X>" TOTAL premise; every other
    digit-bearing premise is either an ALREADY-consumed amount of X ("has already read 149 pages")
    or the RATE premise (a per-day Rate fact of X whose text states a "for a week / for N days"
    duration); the remainder is non-negative. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or " left" not in ql or _has_digit(ql) \
            or _has_comparative(ql):
        return None
    asked = _singular_of(m.group(1)) or m.group(1)
    if "noun" not in LEXICON.get(asked, ()):
        return None
    item_re = re.compile(r"(\d+(?:\.\d+)?)\s+(?:%s|%ss)\b" % (re.escape(asked), re.escape(asked)))
    total = consumed = rated = None
    disc, ctx = [], []
    for p in premises:
        fs = learn(p, disc, ctx) or []
        ctx += fs
        pl = p.lower()
        if not _has_digit(p):
            continue
        nums = item_re.findall(pl)
        rate = next((f for f in fs if isinstance(f, Rate) and f.per_unit == "day"
                     and f.measure[0] == asked), None)
        if rate is not None:
            dm = re.search(r"\bfor (a|one|two|three|four|five|six|seven|\d+) (week|day)s?\b", pl)
            if dm is None or rated is not None:
                return None
            n = 1.0 if dm.group(1) in ("a", "one") else \
                float(NUMBERS.get(dm.group(1), dm.group(1) if dm.group(1).isdigit() else 0) or 0)
            if n <= 0:
                return None
            rated = rate.amount * n * (7 if dm.group(2) == "week" else 1)
        elif re.match(r"\s*there (are|is)\b", pl) and len(nums) == 1 and total is None:
            total = float(nums[0])
        elif "already" in pl and len(nums) == 1 and consumed is None:
            consumed = float(nums[0])
        else:
            return None                                  # an unclassified valued premise → not this shape
    if total is None or rated is None:
        return None
    result = _compute(f"{_num(total)} - {_num(consumed or 0)} - {_num(rated)}")
    return _gated_nonneg(result)


def _weekday_weekend_system(premises: list, question: str):
    """WEEKDAY/WEEKEND SPLIT — a per-day rate on WEEKDAYS (5) plus a RELATIONAL per-day rate on
    WEEKEND days (2), asked per week: "8 episodes each day during weekdays; on each weekend day
    three times the weekday number; how many in a week?" → 8·5 + 24·2 = 88. Reads RAW premises (the
    relational weekend clause materializes no fact). TIGHTLY gated: a digit-free "how many <asked>
    … week" question; exactly ONE premise carries digits — the WEEKDAY one (a weekday cue + a
    per-day cue + the asked measure); the WEEKEND premise (a weekend cue) carries the multiplier as
    a WORD (twice / three times / half); the result is a positive integer. None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or "week" not in ql or _has_digit(ql) \
            or any(w in ql for w in ("more", "fewer", "less", "than", "weekend", "weekday")):
        return None
    asked = _singular_of(m.group(1)) or m.group(1)
    weekday_cues = ("weekday", "weekdays", "school week")
    digit_premises = [p for p in premises if _has_digit(p)]
    if len(digit_premises) != 1:
        return None
    wd = digit_premises[0]
    wdl = wd.lower()
    if not any(c in wdl for c in weekday_cues) or not any(c in wdl for c in _PER_DAY_CUES) \
            or not any((_singular_of(_key(w)) or _key(w)) == asked for w in wd.split()):
        return None
    nums = re.findall(r"\d+(?:\.\d+)?", wd)
    if len(nums) != 1:
        return None
    rate = float(nums[0])
    we = next((p for p in premises if p is not wd and "weekend" in p.lower()), None)
    if we is None or _has_digit(we):
        return None
    wel = we.lower()
    mult = None
    tm = re.search(r"\b(\w+) times\b", wel)
    if "twice" in wel:
        mult = 2.0
    elif "half" in wel:
        mult = 0.5
    elif tm is not None and NUMBERS.get(tm.group(1)):
        mult = float(NUMBERS[tm.group(1)])
    if mult is None:
        return None
    result = _compute(f"{_num(rate)} * 5 + {_num(mult)} * {_num(rate)} * 2")
    return _gated_pos_int(result)


def _piece_count_system(premises: list, question: str):
    """PIECE COUNT ACROSS UNITS — "Matt orders 15 POUNDS of beef. He cuts that into 12-OUNCE steaks.
    How many steaks does he get?" → 15·16 / 12 = 20. A TOTAL measure in one unit is divided into
    PIECES whose size is stated in a CONVERTIBLE unit; the asked noun is the piece. TIGHTLY gated:
    the question is a bare "how many <piece>" (no value of its own); exactly TWO value-bearing
    premises; the piece-size premise MENTIONS the asked noun, the total premise does NOT; the two
    measure heads form a CONVERSIONS pair (or match exactly); the division is a POSITIVE INTEGER
    (a piece count is whole — a fraction means this isn't the shape). None otherwise."""
    ql = question.lower()
    m = re.search(r"how many (\w+)", ql)
    if m is None or "how much" in ql or _has_digit(ql):
        return None
    piece = _singular_of(m.group(1)) or m.group(1)
    if piece in UNIT_NOUNS or "noun" not in LEXICON.get(piece, ()):
        return None
    valued = []                                          # (premise, its single Quantity) per valued premise
    for p in premises:
        fs = [f for f in (learn(p, [], []) or []) if isinstance(f, Quantity) and f.amount is not None]
        if len(fs) > 1:
            return None                                  # a multi-value premise is another shape
        if fs:
            valued.append((p, fs[0]))
    if len(valued) != 2:
        return None
    def mentions(p):                                     # does the premise name the asked piece?
        return any((_singular_of(_key(w)) or _key(w)) == piece for w in p.split())
    piece_pair = next((v for v in valued if mentions(v[0])), None)
    total_pair = next((v for v in valued if not mentions(v[0])), None)
    if piece_pair is None or total_pair is None:
        return None
    size, total = piece_pair[1], total_pair[1]
    su, tu = size.measure[0], total.measure[0]
    if su != tu and (tu, su) not in CONVERSIONS:
        return None
    factor = 1 if su == tu else CONVERSIONS[(tu, su)]
    result = _compute(f"{_num(total.amount)} * {_num(factor)} / {_num(size.amount)}")
    return _gated_pos_int(result)


# --- system family: discounted purchase (percent-on-money compositions) ----------------------
_DP_DOWN = re.compile(r"\b(?:off|discount(?:s|ed)?|markdown|marked down|clearance)\b")
_DP_UP = re.compile(r"\b(?:tax(?:es)?|tip(?:s|ped)?|gratuity|surcharge|fee)\b")
_DP_GUARDS = re.compile(r"\bhalf.price\b|\bfree\b|\bcoupon\b|\bworth\b|\bprofit\b|\bresell\b"
                        r"|\bcommission\b|\btrade\b|\bsold\b|of (?:its|the) value|\bsave[ds]?\b"
                        r"|\binsurance\b|\brefund\b")
_DP_NUM = r"(?:\d+(?:,\d{3})*(?:\.\d+)?|\.\d+)"
_DP_QBLOCK = re.compile(r"\b(?:save[ds]?|profit|change|left|remains?|remaining|earn(?:ed|s)?"
                        r"|makes?|made|more|fewer|less|than|each|apiece|percent)\b")


def _discounted_purchase_system(premises: list, question: str):
    """DISCOUNTED PURCHASE — a purchase total (Σ count×each-price + bare prices, or ONE stated
    total) transformed by SEQUENTIAL percent modifiers in text order: "2 bags; each bag $6.00 but
    75% off" → 2·6·(1−.75) = 3; "vase priced at $200, 25% off, paid 10% sales tax" →
    200·0.75·1.10 = 165; "items add up to $150; sales tax is 8%" → 162. The fold drops these
    (partitive percents attach to nothing), so RAW text is read. TIGHTLY gated: a "how much …
    pay/spend/cost/bring" question (no save/profit/change/left/comparative/each); EVERY percent
    must classify DOWN (off/discount/markdown/clearance) XOR UP (tax/tip/fee) by a word-boundary
    cue within its ±30-char window — an unclassifiable or ambiguous percent declines the WHOLE
    system; every money value is an each-price (paired to a count) or a bare price (no preceding
    count — a "4 pizzas for $80" total is ambiguous → decline); person-noun counts never pair;
    cross-premise pairing only for the single each-price + single leftover DIGIT count; every
    digit in premises AND question sits inside a classified match (a question digit may also echo
    a used count); the 1-bare-price+1-percent shape defers to the percent family; positive
    integer. None otherwise."""
    ql = question.lower()
    if "how much" not in ql \
            or not re.search(r"\b(?:pay|pays|paid|spend|spends|spent|costs?|bring)\b", ql):
        return None
    if _DP_QBLOCK.search(ql):
        return None
    segs = [p.lower() for p in premises] + [ql]
    qi = len(segs) - 1
    body = " ".join(segs)
    if _DP_GUARDS.search(body):
        return None
    spans = [[] for _ in segs]                           # classified character spans, per segment

    def covered(si, a, b=None):
        return any(x <= a and (b or a) <= y for x, y in spans[si])

    transforms = []                                      # (seg, pos, sign, percent) in text order
    for si, seg in enumerate(segs):
        for m in re.finditer(_DP_NUM + r"\s*(?:%|percent)", seg):
            p = float(re.match(_DP_NUM, m.group(0)).group(0).replace(",", ""))
            win = seg[max(0, m.start() - 30): m.end() + 30]
            down, up = bool(_DP_DOWN.search(win)), bool(_DP_UP.search(win))
            if down == up or not 0 < p < 100:
                return None                              # unclassifiable/ambiguous percent
            transforms.append((si, m.start(), "-" if down else "+", p))
            spans[si].append((m.start(), m.end()))
    if not transforms:
        return None

    numword = "|".join(re.escape(w) for w in NUMBERS)

    def preceding_count(seg, pos, si):
        """The nearest count (digit or word number) within 5 words before `pos`, unless it counts
        a person-group noun. Returns (span_start, span_end, value) or None."""
        head = seg[:pos]
        last = None
        for m in re.finditer(r"\b(\d+(?:,\d{3})*|" + numword + r")\s+([a-z-]+)", head):
            if not covered(si, m.start(1), m.end(1)):
                last = m
        if last is None or len(head[last.end():].split()) > 5:
            return None
        noun = last.group(2)
        if (_singular_of(noun) or noun) in GROUP_PERSON_NOUNS:
            return None
        tok = last.group(1)
        v = NUMBERS.get(tok, float(tok.replace(",", "")) if tok[0].isdigit() else None)
        return (last.start(1), last.end(1), float(v)) if v else None

    eaches, bares = [], []                               # each-prices to pair; bare single prices
    for si, seg in enumerate(segs):
        for m in re.finditer(r"\$\s*(" + _DP_NUM + r")|(" + _DP_NUM + r") dollars\b", seg):
            if covered(si, m.start()):
                continue
            if si == qi:
                return None                              # a money value in the question → stranded
            price = float((m.group(1) or m.group(2)).replace(",", ""))
            spans[si].append((m.start(), m.end()))
            after = seg[m.end():].lstrip()
            each_after = after.startswith("each") or after.startswith("apiece")
            each_before = re.search(r"\beach\s+[a-z-]+\s+(?:was|is|were|are|costs?)\s*$",
                                    seg[:m.start()]) is not None
            cnt = preceding_count(seg, m.start(), si)
            if each_after or each_before:
                eaches.append((si, m.start(), price, cnt))
            elif cnt is not None:
                return None                              # "4 pizzas for $80" — total or each? decline
            else:
                bares.append(price)
    if not eaches and not bares:
        return None
    if "add up to" in body and (eaches or len(bares) > 1):
        return None                                      # a stated total plus items → double-count
    if not eaches and len(bares) == 1 and len(transforms) == 1 and transforms[0][2] == "-":
        return None                                      # the percent family's 1-step DISCOUNT shape
        #                                                  (a lone TAX/TIP is ours — _PCT_UP has no tax cue)

    used_counts, products = [], []
    unpaired = []
    for si, pos, price, cnt in eaches:
        if cnt is not None:
            spans[si].append((cnt[0], cnt[1]))
            used_counts.append(cnt[2])
            products.append((cnt[2], price))
        else:
            unpaired.append((si, pos, price))
    if unpaired:
        candidates = []                                  # the leftover DIGIT counts, corpus-wide
        for si, seg in enumerate(segs[:-1]):
            for m in re.finditer(r"\b\d+(?:,\d{3})*\b", seg):
                if covered(si, m.start()):
                    continue
                nxt = re.match(r"\s+([a-z-]+)", seg[m.end():])
                noun = nxt.group(1) if nxt else ""
                if (_singular_of(noun) or noun) in GROUP_PERSON_NOUNS:
                    return None                          # a person count shadows the pairing
                candidates.append((si, m.start(), m.end(), float(m.group(0).replace(",", ""))))
        if len(candidates) != len(unpaired):
            return None
        if len(candidates) > 1:
            # MULTI-PAIR zip is only safe for counts-FIRST parallel discourse ("2 guest sets and
            # 4 master sets; the guest set is $40 each and the master set $50 each" — GSM8K states
            # the pairs in the same order twice). Every count must precede every each-price.
            if max((si, a) for si, a, _, _ in candidates) \
                    >= min((si, pos) for si, pos, _ in unpaired):
                return None
        for (si_c, a, b, v), (_, _, price) in zip(sorted(candidates), sorted(unpaired)):
            spans[si_c].append((a, b))
            used_counts.append(v)
            products.append((v, price))

    for si, seg in enumerate(segs):                      # every digit accounted (echoes OK in the q)
        for m in re.finditer(r"\d+(?:,\d{3})*(?:\.\d+)?|\.\d+", seg):
            if covered(si, m.start(), m.end()):
                continue
            v = float(m.group(0).replace(",", ""))
            if si == qi and any(abs(v - c) < 1e-9 for c in used_counts):
                continue
            return None

    parts = [f"({_num(c)} * {_num(p)})" for c, p in products] + [_num(p) for p in bares]
    expr = " + ".join(parts)
    for _, _, sign, p in sorted(transforms):
        expr = f"({expr}) * (1 {sign} {_num(p)} / 100)"
    result = _compute(expr)
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


# --- system family: product-sum variants (change / savings-gap / split) -----------------------
def _product_sum_change_system(premises: list, question: str):
    """PRODUCT-SUM + CHANGE — Σ(count × each-price) paid with a stated total, asked the change:
    "5 boxes at $6 each and 10 boxes at $14 each; she paid $200 for all; how much change?" →
    200 − 170 = 30. `_shopping_total` blocks change asks — this claims them. TIGHTLY gated: a
    digit-free "how much change" question; every money value an each-price except ONE "paid $T"
    total; strict count/price pairing; T ≥ Σ; every digit accounted. None otherwise."""
    ql = question.lower()
    if "how much change" not in ql or _has_digit(ql):
        return None
    body = " ".join(p.lower() for p in premises)
    tm = re.search(r"paid \$(\d+(?:\.\d+)?)", body)
    if tm is None:
        return None
    total_paid = float(tm.group(1))
    pairs = []
    for m in re.finditer(r"(\d+) (\w+)(?: of \w+)? at \$(\d+(?:\.\d+)?)(?: each)?", body):
        pairs.append((float(m.group(1)), float(m.group(3)), m))
    if len(pairs) < 1:
        return None
    used = {tm.group(1)} | {m.group(1) for _, _, m in pairs} | {m.group(3) for _, _, m in pairs}
    if any(d not in used for d in re.findall(r"\d+(?:\.\d+)?", body)):
        return None
    sigma = sum(c * p for c, p, _ in pairs)
    if total_paid < sigma:
        return None
    result = _compute(f"{_num(total_paid)} - ({' + '.join(f'{_num(c)} * {_num(p)}' for c, p, _ in pairs)})")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_nonneg(result)


def _target_purchase_gap_system(premises: list, question: str):
    """TARGET PURCHASE − SAVINGS — "wants to buy 8 books; each book costs $5; already has $13;
    how much does he need to save?" → 8·5 − 13 = 27. TIGHTLY gated: a digit-free "how much …
    need (to save|to earn|more)" question; ONE want-count; ONE each-price; ONE has-amount;
    nothing else valued; a positive gap. None otherwise."""
    ql = question.lower()
    if not re.search(r"how much (?:money )?(?:does|do|will) \w+ (?:still )?need", ql) \
            or _has_digit(ql):
        return None
    count = price = have = None
    for p in premises:
        pl = p.lower()
        cm = re.search(r"buy (\d+)(?: new)? \w+", pl)
        pm = re.search(r"each \w+ costs? \$(\d+(?:\.\d+)?)", pl)
        hm = re.search(r"(?:has|saved) \$(\d+(?:\.\d+)?)", pl)
        if cm is not None and count is None and not re.search(r"\$", pl):
            count = float(cm.group(1))
        elif pm is not None and price is None:
            price = float(pm.group(1))
        elif hm is not None and have is None:
            have = float(hm.group(1))
        elif _has_digit(p):
            return None                                  # an unclassified valued premise
    if None in (count, price, have):
        return None
    result = _compute(f"{_num(count)} * {_num(price)} - {_num(have)}")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


def _product_sum_split_system(premises: list, question: str):
    """PRODUCT-SUM SPLIT BETWEEN TWO — "Sab and Dane sold 6 pairs at $3 each and 18 shirts that
    cost $2; how much will EACH earn if they divided their total earning?" → (18+36)/2 = 27.
    TIGHTLY gated: a "how much will each … earn/get … divide" question; a TWO-name cast stated
    with 'and'; alternating count/price pairs ('N X that cost $P (each)' / 'N X at $P'); every
    digit accounted; an exact halving. None otherwise."""
    ql = question.lower()
    if "each" not in ql or not re.search(r"\bearn|\bget|\breceive", ql) \
            or not re.search(r"divid", ql + " " + " ".join(premises).lower()) or _has_digit(ql):
        return None
    body = " ".join(premises)
    if not re.search(r"\b[A-Z][a-z]+ and [A-Z][a-z]+\b", body):
        return None                                      # exactly a stated two-name cast
    bl = body.lower()
    pairs = list(re.finditer(r"(\d+) (?:\w+ )?(?:of )?\w+ (?:that cost|at) \$(\d+(?:\.\d+)?)(?: each)?", bl))
    if len(pairs) < 1:
        return None
    used = {m.group(1) for m in pairs} | {m.group(2) for m in pairs}
    if any(d not in used for d in re.findall(r"\d+(?:\.\d+)?", bl)):
        return None
    result = _compute(f"({' + '.join(f'{m.group(1)} * {m.group(2)}' for m in pairs)}) / 2")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


# --- system family: bespoke age tails (future-fraction anchor / verbal equation) ---------------
def _future_fraction_anchor_system(premises: list, question: str):
    """A FUTURE HALF-OF-N ANCHOR + A FUTURE FRACTION-OF-NOW RELATION — "Christina's age will be
    half of 80 in five years; Oscar will be 3/5 times as old as Christina is NOW in 15 years;
    Oscar's age now?" → C = 40−5 = 35; O = (3/5)·35 − 15 = 6. TIGHTLY gated: the exact two-frame
    shape (a half-of-N future anchor, a fraction-of-now future relation), a digit-free now-ask
    for the relation's subject; every digit accounted; positive integers at every point. None
    otherwise."""
    ql = question.lower()
    qm = re.search(r"(?:calculate )?(\w+)[\'\u2019]s age now|how old is (\w+) now", ql)
    if qm is None or _has_digit(ql):
        return None
    asked = (qm.group(1) or qm.group(2))
    body = " ".join(p.lower() for p in premises)
    am = re.search(r"(\w+)[\'\u2019]s age will be half of (\d+) years? in (\w+|\d+) years", body)
    rm = re.search(r"(\w+) will be (\d+)/(\d+) times as old as (\w+) is now in (\d+) years", body)
    if am is None or rm is None:
        return None
    anchor_person = am.group(1)
    n = float(am.group(2))
    k = float(NUMBERS.get(am.group(3), am.group(3) if am.group(3).isdigit() else 0) or 0)
    subj, num, den, std, m_years = rm.group(1), float(rm.group(2)), float(rm.group(3)), \
        rm.group(4), float(rm.group(5))
    if not k or std != anchor_person or asked != subj or den == 0:
        return None
    used = {am.group(2), rm.group(2), rm.group(3), rm.group(5)} \
        | ({am.group(3)} if am.group(3).isdigit() else set())
    if any(d not in used for d in re.findall(r"\d+", body)):
        return None
    now_anchor = n / 2 - k
    if now_anchor <= 0:
        return None
    result = _compute(f"({_num(n)} / 2 - {_num(k)}) * {_num(num)} / {_num(den)} - {_num(m_years)}")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


def _verbal_equation_age_system(premises: list, question: str):
    """A VERBAL LINEAR EQUATION — "take Hiram's age and then add 12, you get 4 less than twice
    Allyson's age; Hiram is 40; how old is Allyson?" → 40+12 = 2A−4 → A = 28. TIGHTLY gated:
    the exact take-add-you-get frame; ONE anchor for the taken person; a digit-free ask for the
    equated person; every digit accounted; a positive integer. None otherwise."""
    ql = question.lower()
    qm = re.search(r"how old is (\w+)", ql)
    if qm is None or _has_digit(ql):
        return None
    body = " ".join(p.lower() for p in premises)
    em = re.search(r"take (\w+)[\'\u2019]s age,? (?:and )?(?:you )?(?:then )?add (\d+),? "
                   r"(?:and )?(?:you )?get (\d+) "
                   r"(less|more) than (twice|thrice|three times|four times) (\w+)[\'\u2019]s age",
                   body)
    if em is None:
        return None
    taken, a, b, dir_, mult_tok, other = em.group(1), float(em.group(2)), float(em.group(3)), \
        em.group(4), em.group(5), em.group(6)
    k = {"twice": 2.0, "thrice": 3.0, "three times": 3.0, "four times": 4.0}[mult_tok]
    am = re.search(rf"{re.escape(taken)} is (\d+) years? old", body)
    if am is None or qm.group(1) != other:
        return None
    v = float(am.group(1))
    used = {em.group(2), em.group(3), am.group(1)}
    if any(d not in used for d in re.findall(r"\d+", body)):
        return None
    sign = "+" if dir_ == "less" else "-"                # V+A = kY − B → Y = (V+A+B)/k
    result = _compute(f"({_num(v)} + {_num(a)} {sign} {_num(b)}) / {_num(k)}")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


# --- system family: bespoke money tails (split-price / sellback-loss / bonus-ratio) ------------
def _split_price_relational_system(premises: list, question: str):
    """A SPLIT POOL WITH A RELATIONAL SECOND PRICE — "of these 9 pills, 4 cost $1.50 each, the
    other pills each cost $5.50 MORE; total on the pills?" → 4·1.50 + 5·(1.50+5.50) = 41. TIGHTLY
    gated: a digit-free spend-total question; ONE "of these N …, n1 … $P each" split; ONE "other
    … each cost $D more" premise; the only other numbers "for N days"/"N a day" scene phrases;
    n1 < N; positive integer. None otherwise."""
    ql = question.lower()
    if "how much" not in ql or not re.search(r"\bspend|\bspent|\bcost|\bpay|\bpaid", ql) \
            or _has_digit(ql):
        return None
    body = " ".join(p.lower() for p in premises)
    sm = re.search(r"of these (\d+) \w+, (\d+) \w+ cost \$(\d+(?:\.\d+)?) each", body)
    dm = re.search(r"other \w+ each cost \$(\d+(?:\.\d+)?) more", body)
    if sm is None or dm is None:
        return None
    total_n, n1, p1 = float(sm.group(1)), float(sm.group(2)), float(sm.group(3))
    d = float(dm.group(1))
    if not 0 < n1 < total_n:
        return None
    used = {sm.group(1), sm.group(2), sm.group(3), dm.group(1)} \
        | {m.group(1) for m in re.finditer(r"for (\d+) days", body)} \
        | {m.group(1) for m in re.finditer(r"(\d+) \w+ a day", body)}
    if any(x not in used for x in re.findall(r"\d+(?:\.\d+)?", body)):
        return None
    result = _compute(f"{_num(n1)} * {_num(p1)} + ({_num(total_n)} - {_num(n1)})"
                      f" * ({_num(p1)} + {_num(d)})")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


def _monthly_buy_sellback_loss_system(premises: list, question: str):
    """MONTHLY PURCHASES × 12 − A SELL-BACK — "bought 3 books a month at $20 each; sells them
    back at the end of the year for $500; how much did he lose?" → 3·20·12 − 500 = 220. TIGHTLY
    gated: a digit-free "how much … lose" question; ONE "N <item> a month at $P each" premise;
    ONE end-of-year sell-back total; nothing else valued; a positive loss. None otherwise."""
    ql = question.lower()
    if not re.search(r"how much (?:money )?did \w+ lose", ql) or _has_digit(ql):
        return None
    body = " ".join(p.lower() for p in premises)
    bm = re.search(r"(\d+) \w+ a month at \$(\d+(?:\.\d+)?) each", body)
    sm = re.search(r"sells? them back [^.]*for \$(\d+(?:,\d{3})*(?:\.\d+)?)", body)
    if bm is None or sm is None or "end of the year" not in body:
        return None
    n, p = float(bm.group(1)), float(bm.group(2))
    back = float(sm.group(1).replace(",", ""))
    used = {bm.group(1), bm.group(2), sm.group(1)}
    if any(x not in used for x in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?", body)):
        return None
    result = _compute(f"{_num(n)} * {_num(p)} * 12 - {_num(back)}")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


def _same_pct_bonus_system(premises: list, question: str):
    """A SAME-PERCENTAGE BONUS TRANSFERRED TO A NEW BASE — "the bonus is the same percentage
    every year; last year he made $100,000 and got a $10,000 bonus; this year he makes $200,000;
    total pay and bonus together?" → 200000·(1 + 10000/100000) = 220000. TIGHTLY gated: a
    digit-free pay+bonus-together question; a "same percentage" premise; last-year base+bonus;
    a this-year base; nothing else valued; the bonus < the base; positive integer. None
    otherwise."""
    ql = question.lower()
    if "bonus" not in ql or "how much" not in ql or _has_digit(ql):
        return None
    body = " ".join(p.lower() for p in premises)
    if "same percentage" not in body:
        return None
    lm = re.search(r"last year [^.]*?\$(\d+(?:,\d{3})*)[^.]*?\$(\d+(?:,\d{3})*) bonus", body)
    tm = re.search(r"this year [^.]*?\$(\d+(?:,\d{3})*)", body)
    if lm is None or tm is None:
        return None
    base0 = float(lm.group(1).replace(",", ""))
    bonus0 = float(lm.group(2).replace(",", ""))
    base1 = float(tm.group(1).replace(",", ""))
    if not 0 < bonus0 < base0:
        return None
    used = {lm.group(1), lm.group(2), tm.group(1)}
    if any(x not in used for x in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?", body)):
        return None
    result = _compute(f"{_num(base1)} * (1 + {_num(bonus0)} / {_num(base0)})")
    if isinstance(result, float):
        result = round(result, 9)
    return _gated_pos_int(result)


def _percent_price_relational_system(premises: list, question: str):
    """PERCENT-SCALED PRICE RELATION (#206) — one item's price is "P% more/less EXPENSIVE" than a
    stated base price: "a new plan 30% more expensive than his old plan; old plan was $150/month"
    → 150·1.3 = 195; "Alan bought a $2000 phone; John bought it 2% more expensive" → 2040; with
    purchase counts ("pretzels $4; chips 75% more expensive; two packets of each") → 2·4 + 2·7 =
    22. TIGHTLY gated: a digit-free "how much" question; exactly ONE "% more/less expensive"
    premise (digit-free once the percent is removed); exactly ONE base-price premise (one $V, no
    other digit, no %); every other premise digit-free or a pure purchase-counts premise. The
    scaled-vs-base ask is disambiguated by a DISCRIMINATIVE TOKEN — an ask content-word present in
    the percent premise but absent from the base premise ("new", "John"); an ask about the BASE
    item finds none (its words appear in both or only the base premise) and DECLINES. A counts
    premise instead buys BOTH items → Σ count·price, each count-noun mapping to exactly one of the
    two premises. None otherwise."""
    ql = question.lower()
    if ("how much" not in ql and "what is the price of" not in ql) or _has_digit(ql):
        return None
    pct = sign = None
    pct_prem = base_prem = None
    base = None
    count_pairs = []
    for p in premises:
        pl = p.lower()
        m = re.search(r"(\d+(?:\.\d+)?)\s*% (?:(more|less) expensive|(cheaper))", pl)
        if m is not None:
            if pct_prem is not None:
                return None                              # two percent premises
            pside = pl
            if _has_digit(pl.replace(m.group(0), " ")):
                # the base price may share the sentence ("pretzels costs $4, while chips are
                # 75% more expensive") — split at the comma bounding the percent clause; the
                # other side must be exactly the base-price statement.
                ci = pl.rfind(",", 0, m.start())
                if ci == -1:
                    return None
                bside, pside = pl[:ci], pl[ci + 1:]
                bm2 = re.search(r"\$\s*(\d+(?:,\d{3})*(?:\.\d+)?)", bside)
                if base_prem is not None or bm2 is None \
                        or _has_digit(bside.replace(bm2.group(0), " ")) \
                        or _has_digit(pside.replace(m.group(0), " ")):
                    return None
                base, base_prem = float(bm2.group(1).replace(",", "")), bside
            pct, sign, pct_prem = (float(m.group(1)),
                                   (1 if m.group(2) == "more" else -1),   # "cheaper" (group 3)
                                   pside)                                  # → less: sign −1
            if m.group(3) is not None:
                sign = -1
            continue
        bm = re.search(r"\$\s*(\d+(?:,\d{3})*(?:\.\d+)?)", pl)
        if bm is not None:
            if base_prem is not None or "%" in pl \
                    or _has_digit(pl.replace(bm.group(0), " ")):
                return None                              # ambiguous standard / an unread digit
            base, base_prem = float(bm.group(1).replace(",", "")), pl
            continue
        pairs = re.findall(r"(\w+)\s+(?:packets?|packs?|boxes?|bags?|cans?|bottles?|kilograms?|kilos?|pounds?)\s+of\s+(\w+)", pl)
        stripped = pl
        pairs_valued = []
        for w, noun in pairs:
            n = NUMBERS.get(w) if not w.isdigit() else float(w)
            if n is not None:
                pairs_valued.append((float(n), noun))
                stripped = stripped.replace(w, " ", 1)
        if _has_digit(stripped):
            return None                                  # an unclassified valued premise
        count_pairs.extend(pairs_valued)
    # the purchase counts may ride in the QUESTION ("What is the price of two kilograms of
    # tomatoes and three kilograms of cucumbers?") — without this scan the no-counts path
    # returned the bare scaled price (a confident-wrong, 4 != 23)
    for w, noun in re.findall(r"(\w+)\s+(?:packets?|packs?|boxes?|bags?|cans?|bottles?|"
                              r"kilograms?|kilos?|pounds?)\s+of\s+(\w+)", ql):
        n = NUMBERS.get(w) if not w.isdigit() else float(w)
        if n is not None:
            count_pairs.append((float(n), noun))
    if pct_prem is None or base_prem is None or not 0 < pct <= 500 or base <= 0:
        return None
    scaled = base * (1 + sign * pct / 100)
    if count_pairs:                                      # BOTH items bought → Σ count·price
        total = []
        for n, noun in count_pairs:
            in_pct, in_base = noun in pct_prem, noun in base_prem
            if not in_pct and not in_base:               # in neither — can't map the item
                return None
            # in BOTH → the base premise owns its noun (the pct premise names the standard
            # only in its than-phrase: "…20% cheaper than one kilogram of CUCUMBERS")
            total.append(f"{_num(n)} * {_num(base if in_base else scaled)}")
        result = _compute(" + ".join(total))
        return _gated_pos(result)
    stop = {"how", "much", "did", "does", "do", "will", "would", "he", "she", "they", "it",
            "his", "her", "their", "the", "a", "an", "for", "on", "of", "to", "in", "at",
            "is", "was", "cost", "costs", "pay", "paid", "spend", "spent", "money",
            "purchase", "purchases", "now", "then"}
    ask_words = {w.strip(".,?!:;") for w in ql.split()} - stop
    if not any(w and w in pct_prem and w not in base_prem for w in ask_words):
        return None                                      # the ask doesn't pick out the SCALED item
    result = _compute(f"{_num(base)} * (1 + {_num(sign)} * {_num(pct)} / 100)")
    return _gated_pos(result)


def _pieces_pool_system(premises: list, question: str):
    """PIECES-POOL COMPOSITIONS (#209) — a pool of slices/pieces (containers × pieces-per-
    container) with ONE downstream op, six ask branches: REMAIN ("2 pizzas of 8; eats 7; left?"
    → 9), PER-PIECE COST ("four pizzas for $80, cut into 5" → 4), K-SLICES COST (Kim 72/36·5 =
    10), PIZZAS-TO-ORDER (persons·per-person/P: "group of 18, 3 slices each person, 9 per
    pizza" → 6), SLICES-PER-PERSON (C·P/persons: "John with his five friends, 3 pizzas of 8"
    → 4), REVENUE ("$5 a slice, 4 slices a pie, sell 9 pies" → 180). Premises PERIOD-joined —
    severed clauses must not create false adjacencies ("…gets 3 slices each pizza…" stole the
    per-container read). TIGHTLY gated per branch: the branch's own values and nothing else
    (every digit accounted); counts positive integers; money positive. None otherwise."""
    ql = question.lower()
    body = " . ".join(premises)
    full = body.lower() + " . " + ql
    if not re.search(r"\bslices?\b|\bpieces?\b", full):
        return None

    def _wn(tok):
        if tok is None:
            return None
        t = tok.lower()
        return float(t) if t.replace(".", "").isdigit() else \
            (float(NUMBERS[t]) if t in NUMBERS else None)

    cm = re.search(r"\b(?:orders?|ordered|buys?|bought|made|got)\s+(\d+|one|two|three|four|five|"
                   r"six|seven|eight|nine|ten)\s+(?:different |large |whole |big |birthday |cookie )*"
                   r"(?:pizzas?|pies?|pans?|box(?:es)?|cakes?)\b", full)
    C = _wn(cm.group(1)) if cm else None
    onem = None
    if C is None:                                        # a SINGLE container ("orders a pizza",
        onem = re.search(r"\b(?:orders?|ordered|buys?|bought)\s+(?:a|an|1)\s+"    # "bought 1 box
                         r"(?:large |whole )?(?:pizza|pie|cake|box of pizza)\b", full)   # of pizza")
        if onem is not None:
            C = 1.0
    pm = (re.search(r"cut(?:\s+\w+){0,3} into (\d+)(?: big| square| large)* (?:slices?|pieces?)", full)
          or re.search(r"\b(\d+) slices? (?:each|in a)", full)
          or re.search(r"each (?:pizza|pie|pan|cake) (?:has|had|is|was) (\d+) slices?", full)
          or re.search(r"(?:pizza|pie|cake) (?:has|had|with) (\d+) slices?", full))
    P = _wn(pm.group(1)) if pm else None
    used = {m.group(1) for m in (cm, pm) if m}
    if onem is not None and "1" in onem.group(0):
        used.add("1")

    def digits_ok(*extra):
        u = used | {e for e in extra if e}
        return all(d in u for d in re.findall(r"\d+(?:\.\d+)?", body + " " + question))

    if re.search(r"how many slices? (?:of \w+ )?(?:will remain|(?:are|were|is|was) left|remain\b|left\b)", ql):
        em = re.search(r"(?:eats?|ate)\s+(\d+) slices?", full)
        if C and P and em and digits_ok(em.group(1)):
            return _gated_pos_int(_compute(f"{_num(C)} * {_num(P)} - {em.group(1)}"))
        fm2 = re.search(r"(\w+(?:-\w+)?|\d+/\d+) of (?:the|it|his|her)[^.]*?(?:was |were )?eaten", full)
        f = _fraction_value(fm2.group(1)) if fm2 else None
        if C and P and f and 0 < f < 1 \
                and digits_ok(fm2.group(1) if "/" in fm2.group(1) else None):
            return _gated_pos_int(_compute(f"{_num(C)} * {_num(P)} * (1 - {_num(f)})"))
        return None
    if re.search(r"how many calories did (?:he|she|\w+) eat", ql):
        efm = re.search(r"eats? (\w+(?:-\w+)?|\d+/\d+) of (?:it|the \w+)", full)
        f = _fraction_value(efm.group(1)) if efm else None
        calm = re.search(r"each slice (?:was|is|has|had|contains) (\d+) calories", full)
        if C and P and f and 0 < f <= 1 and calm \
                and digits_ok(calm.group(1), efm.group(1) if "/" in efm.group(1) else None):
            return _gated_pos(_compute(f"{_num(C)} * {_num(P)} * {_num(f)} * {calm.group(1)}"))
        return None
    if re.search(r"how many goals did they score per game on average", ql):
        gmm = re.search(r"(?:had|played) (\d+) games", full)
        if C and P and gmm and "one slice for every goal" in full and digits_ok(gmm.group(1)):
            return _gated_pos(_compute(f"{_num(C)} * {_num(P)} / {gmm.group(1)}"))
        return None
    km = re.search(r"how much did (\d+) slices? cost", ql)
    if re.search(r"how much did each (?:piece|slice|brownie)(?: of \w+)? cost", ql) or km:
        tm = re.search(r"\$(\d+(?:\.\d+)?)", body)
        if C and P and tm and digits_ok(tm.group(1), km.group(1) if km else None):
            expr = f"{tm.group(1)} / ({_num(C)} * {_num(P)})"
            return _gated_pos(_compute(f"({expr}) * {km.group(1)}" if km else expr))
        return None
    if re.search(r"how many pizzas? should they order", ql):
        gm = re.search(r"group of (\d+) people", full)
        fm = re.search(r"\b(?:and|with (?:his|her))\s+(\d+|one|two|three|four|five|six|seven|"
                       r"eight|nine|ten)(?: of (?:his|her|their))? friends", full)
        persons = _wn(gm.group(1)) if gm else ((1 + _wn(fm.group(1))) if fm and _wn(fm.group(1)) else None)
        em = re.search(r"each person (?:will eat|eats|gets?|will get)\s+(\d+) slices?", full)
        if persons and P and em and cm is None \
                and digits_ok(gm.group(1) if gm else fm.group(1), em.group(1)):
            return _gated_pos_int(_compute(f"{_num(persons)} * {em.group(1)} / {_num(P)}"))
        return None
    if re.search(r"how many slices? did each (?:person|one) (?:eat|get)", ql):
        fm = re.search(r"\bwith (?:his|her)\s+(\d+|one|two|three|four|five|six|seven|eight|nine|"
                       r"ten)(?: of (?:his|her|their))? friends", full)
        persons = (1 + _wn(fm.group(1))) if fm and _wn(fm.group(1)) else None
        if C and P and persons and digits_ok(fm.group(1)):
            return _gated_pos_int(_compute(f"{_num(C)} * {_num(P)} / {_num(persons)}"))
        return None
    if re.search(r"how much money will .* make", ql):
        sm = re.search(r"sell (\d+) (?:pies?|pizzas?|cakes?)", full)
        prm = re.search(r"charges? \$(\d+(?:\.\d+)?) for a slice", full)
        if sm and prm and P and digits_ok(sm.group(1), prm.group(1)):
            return _gated_pos(_compute(f"{sm.group(1)} * {_num(P)} * {prm.group(1)}"))
        return None
    return None


# --- system family: day chains & two-rate conversions ------------------------------------------
_DRC_DAYS = "monday|tuesday|wednesday|thursday|friday|saturday|sunday"
_DRC_K = {"twice": 2.0, "double": 2.0, "three times": 3.0, "thrice": 3.0, "half": 0.5,
          "four times": 4.0, "five times": 5.0}
_DRC_KPAT = "twice|double|three times|thrice|half|four times|five times"


def _drc_rel(pl: str):
    """A k×day-reference relation in a clause → (k, ref) where ref is a day, "<prev>" ("the day
    before"/"that amount"), or None (elided → previous entry). The day reference is searched in
    the TAIL after the k-word — an optional-group regex silently dropped "…as she painted on
    Monday" (ref=None → a WRONG value, not a decline). None if no k-frame."""
    km = re.search(rf"({_DRC_KPAT}) (?:the number|the amount|as many|as much|that amount|"
                   rf"of the number|of the amount)", pl)
    if km is None:
        return None
    tail = pl[km.end():]
    refm = re.search(rf"\bon ({_DRC_DAYS})\b", tail)
    ref = refm.group(1) if refm else ("<prev>" if "the day before" in tail else None)
    return _DRC_K[km.group(1)], ref


def _day_relational_chain_system(premises: list, question: str):
    """NAMED-DAY RELATIONAL CHAIN (#211) — per-day values where each day is a literal or k× a
    referenced day ("half the number he worked on Monday", "twice that amount", "half of the
    number he baked the day before"), asked a DAY-DIFFERENCE ("how many more minutes on
    Wednesday than on Tuesday?" → 300−225=75), the TOTAL (Σ, optionally − an ate-loss: Zach
    32+16+48−4=92; Elisa 105), or SELL-ALL money (Σ × per-item price: Sally 45·1.20=54).
    A day clause severed from its relation clause ("On Tuesday he ran out of sugar" | "could
    only bake half of…") re-attaches via the PENDING-day slot. TIGHTLY gated: every premise
    classifies (day-literal / day-relation / ate-loss / unit-price / valueless), every digit
    accounted, all chain days resolve, results positive. None otherwise."""
    ql = question.lower()
    full = " . ".join(p.lower() for p in premises) + " . " + ql
    entries, used = [], set()
    loss = price = week_total = None
    pending = None
    for p in premises:
        pl = p.lower()
        dm = re.search(rf"\b(?:on|during) ({_DRC_DAYS})s?\b", pl)
        rel = _drc_rel(pl)
        vm = re.search(r"\b(\d+(?:,\d{3})*(?:\.\d+)?)\b", pl)
        if dm is None:
            if rel is not None and pending is not None and vm is None:
                entries.append((pending, "rel", rel))
                pending = None
                continue
            if vm is not None:
                lm = re.search(r"(?:his|her) \w+ ate (\d+)", pl)
                prm = re.search(r"sell each \w+ for \$(\d+(?:\.\d+)?)", pl)
                tm = re.search(r"\bate (\d+) \w+ this week", pl)
                if tm:
                    week_total = float(tm.group(1)); used.add(tm.group(1)); continue
                if lm:
                    loss = float(lm.group(1)); used.add(lm.group(1)); continue
                if prm:
                    price = float(prm.group(1)); used.add(prm.group(1)); continue
                return None                              # a valued premise outside the chain
            continue
        day = dm.group(1)
        if "not sure" in pl and vm is None and rel is None:
            entries.append((day, "unknown", None))       # "He's not sure what he ate on Wednesday"
        elif rel is not None:
            if vm is not None:
                return None                              # a relation clause with a stray digit
            entries.append((day, "rel", rel))
        elif vm is not None:
            used.add(vm.group(1))
            entries.append((day, "lit", float(vm.group(1).replace(",", ""))))
        else:
            pending = day                                # "On Tuesday he ran out of sugar"
    if len(entries) < 2:
        return None
    order = [e[0] for e in entries]
    unknowns = [d for d, k, _x in entries if k == "unknown"]
    vals = {d: x for d, k, x in entries if k == "lit"}
    for _ in range(len(entries) + 1):
        for i, (day, kind, x) in enumerate(entries):
            if kind == "rel" and day not in vals:
                k, ref = x
                if ref in (None, "<prev>"):
                    ref = order[i - 1] if i > 0 else None
                if ref in vals:
                    vals[day] = k * vals[ref]
    if any(d not in vals for d in order if d not in unknowns):
        return None
    if unknowns:                                         # ONE unknown day + a stated week total →
        rm = re.search(rf"how many \w+ did (?:he|she|\w+) eat on ({_DRC_DAYS})", ql)   # residual
        if len(unknowns) == 1 and week_total is not None and rm is not None \
                and rm.group(1) == unknowns[0] \
                and all(dd in used for dd in re.findall(r"\d+(?:\.\d+)?",
                                                        " ".join(premises) + " " + question)):
            expr = f"{_num(week_total)} - ({' + '.join(_num(vals[d]) for d in order if d not in unknowns)})"
            return _gated_pos_int(_compute(expr))
        return None

    def digits_ok():
        return all(dd in used for dd in re.findall(r"\d+(?:\.\d+)?",
                                                   " ".join(premises) + " " + question))

    dm2 = re.search(rf"how many more \w+ did (?:he|she|\w+) \w+ on ({_DRC_DAYS}) "
                    rf"than on ({_DRC_DAYS})", ql)
    if dm2:
        a, b = dm2.group(1), dm2.group(2)
        if a in vals and b in vals and digits_ok():
            return _gated_pos(_compute(f"{_num(vals[a])} - {_num(vals[b])}"))
        return None
    if re.search(r"how much money can (?:she|he) make", ql) and re.search(r"sells? all", full):
        if price is not None and digits_ok():
            return _gated_pos(_compute(f"({' + '.join(_num(vals[d]) for d in order)}) * {_num(price)}"))
        return None
    if re.search(r"at the end of the \w+ days|in total|\btotal\b", ql):
        if digits_ok():
            expr = " + ".join(_num(vals[d]) for d in order)
            if loss is not None:
                expr = f"({expr}) - {_num(loss)}"
            return _gated_pos(_compute(expr))
    return None


_PSR_K = {"twice": 2.0, "thrice": 3.0, "double": 2.0, "half": 0.5,
          "three times": 3.0, "four times": 4.0}


def _pair_sum_relational_system(premises: list, question: str):
    """PAIR-SUM RELATIONAL (#215) — a ratio within a pair PLUS a pair-sum relation to an
    anchored third party: "Merill has twice as many marbles as Elliot and the two of them
    together have five fewer marbles than Selma. Selma has fifty." → A = k·B, A+B = S∓N →
    B = (S∓N)/(k+1) = 15, Merill = 30. TIGHTLY gated: exactly the three premises (ratio /
    pair-sum / anchor), a single-name ask inside the pair, every number consumed, positive
    integers. None otherwise."""
    ql = question.lower()
    am = re.search(r"how many \w+ does ([a-z]+) have", ql)
    if am is None or _has_digit(ql):
        return None
    ratio = pair = anchor = None
    for p in premises:
        pl = p.lower()
        rm = re.search(rf"\b([a-z]+) has ({'|'.join(_PSR_K)}) as (?:many|much) \w+ as ([a-z]+)\b", pl)
        sm = re.search(r"the two of them together have (\d+|[a-z]+) (fewer|more) \w+ than ([a-z]+)\b", pl)
        nm = re.search(r"\b([a-z]+) has (\d+|[a-z]+) \w+", pl)
        if rm is not None and ratio is None:
            ratio = (rm.group(1), _PSR_K[rm.group(2)], rm.group(3))
        elif sm is not None and pair is None:
            n = float(sm.group(1)) if sm.group(1).isdigit() else NUMBERS.get(sm.group(1))
            if n is None:
                return None
            pair = (n * (-1 if sm.group(2) == "fewer" else 1), sm.group(3))
        elif nm is not None and anchor is None:
            v = float(nm.group(2)) if nm.group(2).isdigit() else NUMBERS.get(nm.group(2))
            if v is None:
                return None
            anchor = (nm.group(1), float(v))
        elif _has_digit(pl):
            return None                                  # an unclassified valued premise
    if ratio is None or pair is None or anchor is None:
        return None
    a, k, b = ratio
    off, third = pair
    if anchor[0] != third or am.group(1) not in (a, b) or len({a, b, third}) != 3:
        return None
    total = anchor[1] + off                              # A + B = S ± N
    bv = total / (k + 1)
    av = k * bv
    result = av if am.group(1) == a else bv
    return _gated_pos_int(_compute(f"{_num(result)}"))


_RS_N = r"\d+(?:,\d{3})*(?:\.\d+)?"


def _rs_ret(v):
    """Gate a rate-singles branch result: positive, float-noise rounded, audited."""
    if isinstance(v, float):
        v = round(v, 9)
    return _gated_pos(_compute(f"{_num(v)}"))


def _rate_singles_system(premises: list, question: str):
    """RATE/PRODUCT SINGLES (#226) — sixteen tightly-gated branches over the unit-rate bucket
    (pool+rate×days+literal; enumerated hours × wage; classes×per-class; two gold products;
    round-trip; change; wpm→hours; weeks-to-save; Σ miles×min/mile; animals×nightly; half-book
    speeds; monthly gap to a yearly goal; spend-rebate; second-job residual; overtime; per-5
    scaling). Every branch: its own values and nothing else (digit-accounted); positive.
    Compound facts are probed INDEPENDENTLY over the period-joined text — the clause splitter
    severs them ("Irene earns $500" | "she works for 40 hours a week"). None otherwise."""
    N = _RS_N

    def f(tok):
        return float(tok.replace(",", ""))

    ql = question.lower()
    full = " . ".join(p.lower() for p in premises) + " . " + ql

    def dok(used):
        return all(dd in used for dd in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?",
                                                   " ".join(premises) + " " + question))

    # 1. Shara: pool + rate×days + literal → "how many shells does she have now"
    m1 = re.search(rf"had ({N}) \w+ before", full)
    m2 = re.search(rf"found ({N}) \w+ per day for ({N}) days", full)
    m3 = re.search(rf"found ({N}) \w+ on the \w+ day", full)
    if m1 and m2 and m3 and re.search(r"how many \w+ does \w+ have now", ql):
        if dok({m1.group(1), m2.group(1), m2.group(2), m3.group(1)}):
            return _rs_ret(f(m1.group(1)) + f(m2.group(1)) * f(m2.group(2)) + f(m3.group(1)))
    # 2. Rafael: hours enumerated + "N hours left" × $rate
    hs = re.findall(rf"({N}) hours (?:on \w+|left)", full)
    pm = re.search(rf"paid \$({N}) per hour", full)
    if len(hs) >= 3 and pm and re.search(r"how much money does \w+ make", ql):
        if dok(set(hs) | {pm.group(1)}):
            return _rs_ret(sum(f(h) for h in hs) * f(pm.group(1)))
    # 3. Texas: N classes × M per class + K more classes
    cm0 = re.search(rf"has ({N}) classes", full)
    cm1 = re.search(rf"has ({N}) students per class", full)
    cm = (cm0, cm1) if cm0 and cm1 else None
    am = re.search(rf"added (\w+|{N}) more classes", full)
    if cm and am and re.search(r"how many students", ql):
        add = NUMBERS.get(am.group(1)) if not am.group(1).isdigit() else f(am.group(1))
        if add and dok({cm[0].group(1), cm[1].group(1)}
                       | ({am.group(1)} if am.group(1).isdigit() else set())):
            return _rs_ret((f(cm[0].group(1)) + add) * f(cm[1].group(1)))
    # 4. Gary/Anna combined gold cost
    pairs = re.findall(rf"({N}) grams of gold (?:that cost|for the cost of) \$({N}) per gram", full)
    if len(pairs) == 2 and re.search(r"cost of their gold combined", ql):
        if dok({x for pr in pairs for x in pr}):
            return _rs_ret(sum(f(a) * f(b) for a, b in pairs))
    # 5. Jenna round trip: $R per mile × M miles one way × 2
    rm = re.search(rf"\$({N}) cents? per mile|\$({N}) per mile", full)
    mm = re.search(rf"drives ({N}) miles one way", full)
    if rm and mm and "round trip" in ql:
        r_ = rm.group(1) or rm.group(2)
        if dok({r_, mm.group(1)}):
            return _rs_ret(f(r_) * f(mm.group(1)) * 2)
    # 6. sisters change: $P per person, two sisters, brought $B
    tm = re.search(rf"tickets are \$({N}) per person", full)
    bm = re.search(rf"brought \$({N})", full)
    if tm and bm and "two sisters" in full and "how much change" in ql:
        if dok({tm.group(1), bm.group(1)}):
            return _rs_ret(f(bm.group(1)) - 2 * f(tm.group(1)))
    # 7. Emily typing hours: W wpm, T words → T/W/60
    wm = re.search(rf"type ({N}) words per minute", full)
    tm2 = re.search(rf"write ({N}) words", ql)
    if wm and tm2 and "how many hours" in ql:
        if dok({wm.group(1), tm2.group(1)}):
            return _rs_ret(f(tm2.group(1)) / f(wm.group(1)) / 60)
    # 8. Macey weeks: cost C, saved S, saves R/week
    cm2 = re.search(rf"costs \$({N})", full)
    sm = re.search(rf"save[d]? \$({N}) already", full)
    rm2 = re.search(rf"saves \$({N}) per week", full)
    if cm2 and sm and rm2 and "how many weeks" in ql:
        if dok({cm2.group(1), sm.group(1), rm2.group(1)}):
            return _rs_ret((f(cm2.group(1)) - f(sm.group(1))) / f(rm2.group(1)))
    # 9. Rudy total time: Σ miles × min/mile
    runs = re.findall(rf"runs ({N}) miles at a rate of ({N}) minutes per mile", full)
    if len(runs) == 2 and "total length of time" in ql:
        if dok({x for pr in runs for x in pr}):
            return _rs_ret(sum(f(a) * f(b) for a, b in runs))
    # 10. Michael animals: (a cats + b dogs) × $c a night per animal
    am2 = re.search(rf"has ({N}) cats and ({N}) dogs", full)
    nm = re.search(rf"\$({N}) a night per animal", full)
    if am2 and nm and "how much" in ql:
        if dok({am2.group(1), am2.group(2), nm.group(1)}):
            return _rs_ret((f(am2.group(1)) + f(am2.group(2))) * f(nm.group(1)))
    # 11. Jane halves: B pages, first half at r1/day, second at r2/day
    bm2 = re.search(rf"({N}) page book", full)
    h1 = re.search(rf"first half [\w ]*?speed of ({N}) pages per day", full)
    h2 = re.search(rf"second half [\w ]*?speed of ({N}) pages a day", full)
    if bm2 and h1 and h2 and "how many days" in ql:
        if dok({bm2.group(1), h1.group(1), h2.group(1)}):
            b = f(bm2.group(1))
            return b / 2 / f(h1.group(1)) + b / 2 / f(h2.group(1))
    # 12. shoe monthly gap: sells $S/month, wants $Y/year → Y/12 − S
    sm2 = re.search(rf"sells \$({N}) worth of \w+ every month", full)
    ym = re.search(rf"make \$({N}) in an entire year", full)
    if sm2 and ym and re.search(r"how many more dollars per month", ql):
        if dok({sm2.group(1), ym.group(1)}):
            return _rs_ret(f(ym.group(1)) / 12 - f(sm2.group(1)))
    # 13. online sale: $D for every $H spent; purchase $P → P − D·(P // H)
    dm = re.search(rf"\$({N}) for every \$({N}) that you spend", full)
    pm2 = re.search(rf"purchase of \$({N})", full)
    if dm and pm2 and "how much did you end up paying" in ql:
        if dok({dm.group(1), dm.group(2), pm2.group(1)}):
            p_ = f(pm2.group(1))
            return _rs_ret(p_ - f(dm.group(1)) * (p_ // f(dm.group(2))))
    # 14. Mike second job: total T; second job H hours at $R → T − H·R
    tm3 = re.search(rf"total of \$({N}) in wages", full)
    hm2 = re.search(rf"works ({N}) hours a week", full)
    rm3 = re.search(rf"pays \$({N}) per hour", full)
    if tm3 and hm2 and rm3 and re.search(r"did \w+ receive from (?:his|her) first job", full):
        if dok({tm3.group(1), hm2.group(1), rm3.group(1)}):
            return _rs_ret(f(tm3.group(1)) - f(hm2.group(1)) * f(rm3.group(1)))
    # 15. Irene overtime: $B for 40 hours + $E per overtime hour; worked W
    ib0 = re.search(rf"earns \$({N})", full)
    ib1 = re.search(rf"works for ({N}) hours a week", full)
    ib = (ib0, ib1) if ib0 and ib1 else None
    ie = re.search(rf"extra \$({N}) for every hour of overtime", full)
    iw = re.search(rf"worked ({N}) hours", full)
    if ib and ie and iw and "total income" in ql:
        if dok({ib[0].group(1), ib[1].group(1), ie.group(1), iw.group(1)}):
            return _rs_ret(f(ib[0].group(1)) + (f(iw.group(1)) - f(ib[1].group(1))) * f(ie.group(1)))
    # 16. Jennifer per-5: bought A; +B for every C that Mark bought; Mark bought D
    ja = re.search(rf"purchased ({N}) cans", full)
    jb = re.search(rf"bought ({N}) additional cans for every ({N}) cans", full)
    jd = re.search(rf"mark purchased ({N}) cans", full)
    if ja and jb and jd and re.search(r"how many cans .* jennifer", ql):
        if dok({ja.group(1), jb.group(1), jb.group(2), jd.group(1)}):
            return _rs_ret(f(ja.group(1)) + f(jb.group(1)) * (f(jd.group(1)) / f(jb.group(2))))
    return None


def _vocab_singles_e_system(premises: list, question: str):
    """VOCAB+STRUCTURE SINGLES E (#236) — forty-three branches with wave-26 vocabulary:
    take-home pay, jeans/tees revenue, savings-target weeks, chained word-fraction skirts,
    compound credit-card interest, three-tier marks averages, century marbles, ebook readers,
    coworker pizza splits, twice-as-far ladies, shared bananas, quiz-average targets, coupon
    purchases, machines-for-a-rate, shirt/hat/jeans baskets, earrings multiples, fries
    fractions, annual salaries, four halvings backward, doubled-Friday crackers, weekly mpg
    gallons, penny discards, two-team period goals, premiere parents, split-speed bike times,
    pencil-sharpening budgets, detour round trips, paired water heaters, popcorn servings,
    tickets-until-left, three-grade GPA, start-with reconstruction, collection reduction,
    percent-of-start balances, calorie-deficit days, bicycle journey minutes, weekly crab
    revenue, rose-bush percent picks, road-trip water bottles, dinner calories, baked-goods
    revenue, pet leggings, and percent-remainder bunnies. Every branch digit-accounted;
    positive. None otherwise."""
    N = _RS_N

    def f(t):
        return float(t.replace(",", ""))
    def w(tok):
        if tok is None:
            return None
        return f(tok) if tok[0].isdigit() else NUMBERS.get(tok)
    ql = question.lower()
    full = " . ".join(p.lower() for p in premises) + " . " + ql
    def dok(used):
        return all(dd in used for dd in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?",
                                                   " ".join(premises) + " " + question))

    # 1. take-home pay after word-percent tax
    th1 = re.search(r"(ten|twenty|\w+) percent of \w+'s pay goes to paying tax", full)
    th2 = re.search(rf"pay is \$({N})", full)
    if th1 and th2 and "take-home pay" in ql and w(th1.group(1)) is not None:
        if dok({th2.group(1)}):
            return _rs_ret(f(th2.group(1)) * (1 - w(th1.group(1)) / 100))
    # 2. jeans+tees revenue
    j1 = re.search(rf"jeans at ({N}) dollars", full); j2 = re.search(rf"tees (?:\w+ )?at ({N}) dollars", full)
    j3 = re.search(rf"sold ({N}) tees", full); j4 = re.search(rf"({N}) jeans in a day", full)
    if j1 and j2 and j3 and j4 and "how much money" in ql:
        if dok({j1.group(1), j2.group(1), j3.group(1), j4.group(1)}):
            return _rs_ret(f(j1.group(1)) * f(j4.group(1)) + f(j2.group(1)) * f(j3.group(1)))
    # 3. weeks to savings target
    v1 = re.search(rf"collected \$({N}) in her piggy bank", full)
    v2 = re.search(rf"put \$({N}) in it each week", full)
    v3 = re.search(rf"costs? \$({N})", full)
    if v1 and v2 and v3 and "how many weeks" in ql:
        if dok({v1.group(1), v2.group(1), v3.group(1)}):
            return _rs_ret((f(v3.group(1)) - f(v1.group(1))) / f(v2.group(1)))
    # 4. chained word-fraction skirts
    s1 = re.search(r"has one-quarter as many skirts", full)
    s2 = re.search(r"has two-thirds as many skirts", full)
    s3 = re.search(rf"has ({N}) skirts", full)
    if s1 and s2 and s3 and "how many skirts" in ql:
        if dok({s3.group(1)}):
            return _rs_ret(f(s3.group(1)) * (2 / 3) * (1 / 4))
    # 5. compound credit-card interest with a mid purchase
    c1 = re.search(rf"\$({N}) balance on his credit card", full)
    c2 = re.search(rf"charged a ({N})% interest fee", full)
    c3 = re.search(rf"puts \$({N}) on his credit card", full)
    c4 = re.search(rf"another ({N})% interest fee", full)
    if c1 and c2 and c3 and c4 and "balance" in ql:
        if dok({c1.group(1), c2.group(1), c3.group(1), c4.group(1)}):
            return _rs_ret((f(c1.group(1)) * (1 + f(c2.group(1)) / 100) + f(c3.group(1)))
                     * (1 + f(c4.group(1)) / 100))
    # 6. three-tier marks average
    m1 = re.search(rf"class is ({N})", full)
    m2 = re.search(rf"(ten|{N}) students scored ({N}) marks", full)
    m3 = re.search(rf"({N}) scored (ten|{N}) marks fewer", full)
    m4 = re.search(rf"rest scored ({N}) marks each", full)
    if m1 and m2 and m3 and m4 and "average marks" in ql:
        if dok({m1.group(1), m2.group(2), m3.group(1), m4.group(1)}):
            n, a, b = f(m1.group(1)), w(m2.group(1)), f(m2.group(2))
            c, d, e = f(m3.group(1)), w(m3.group(2)), f(m4.group(1))
            return _rs_ret((a * b + c * (b - d) + (n - a - c) * e) / n)
    # 7. century marbles → age
    g1 = re.search(r"years in a century is the same as the number of marbles", full)
    g2 = re.search(r"gives (\d+)/(\d+) of the marbles", full)
    g3 = re.search(r"by (\d+|two)", full)
    g4 = re.search(r"age (five|\d+) years from now", full)
    if g1 and g2 and g3 and g4 and "how old" in ql:
        if dok({g2.group(1), g2.group(2)} | ({g3.group(1)} if g3.group(1)[0].isdigit() else set())):
            rem = 100 * (1 - f(g2.group(1)) / f(g2.group(2)))
            return _rs_ret(rem * w(g3.group(1)) - w(g4.group(1)))
    # 8. ebook readers altogether
    e1 = re.search(rf"bought ({N}) ebook readers less than", full)
    e2 = re.search(rf"lost ({N}) ebook readers", full)
    e3 = re.search(rf"bought ({N}) ebook readers(?! less)", full)
    if e1 and e2 and e3 and "altogether" in ql:
        if dok({e1.group(1), e2.group(1), e3.group(1)}):
            a = f(e3.group(1))
            return _rs_ret(a + (a - f(e1.group(1)) - f(e2.group(1))))
    # 9. pizzas/slices per coworker (all word numbers)
    p1 = re.search(r"(twelve|\w+) coworkers", full)
    p2 = re.search(rf"order (three|{N}) pizzas", full)
    p3 = re.search(rf"cut into (eight|{N}) slices", full)
    if p1 and p2 and p3 and "how many slices will each person get" in ql \
            and all(w(x.group(1)) is not None for x in (p1, p2, p3)):
        if dok(set()):
            return _rs_ret(w(p2.group(1)) * w(p3.group(1)) / w(p1.group(1)))
    # 10. two ladies combined distance
    l1 = re.search(r"first lady walked twice as far as the second", full)
    l2 = re.search(rf"second lady walked (four|{N}) miles", full)
    if l1 and l2 and "combined total distance" in ql and w(l2.group(1)) is not None:
        if dok(set()):
            return _rs_ret(3 * w(l2.group(1)))
    # 11. 1/4-times-fewer bananas shared equally
    b1 = re.search(rf"has ({N}) bananas", full)
    b2 = re.search(r"has 1/4 times fewer bananas", full)
    if b1 and b2 and "share them equally between themselves" in full and "how many bananas" in ql:
        if dok({b1.group(1), "1", "4"}):
            a = f(b1.group(1))
            return _rs_ret((a + a * 3 / 4) / 2)
    # 12. quiz score needed for target average
    q1 = re.search(rf"taken ({N}) quizzes", full)
    q2 = re.search(rf"averaged a ({N})% score", full)
    q3 = re.search(rf"average ({N})% over the ({N}) quizzes", full)
    if q1 and q2 and q3 and "what score does she need" in full:
        if dok({q1.group(1), q2.group(1), q3.group(1), q3.group(2)}):
            return _rs_ret(f(q3.group(2)) * f(q3.group(1)) - f(q1.group(1)) * f(q2.group(1)))
    # 13. two purchases minus a coupon
    d1 = re.search(rf"magazine costing \$({N})", full)
    d1b = re.search(rf"pencil costing \$({N})", full)
    d2 = re.search(rf"coupon that gives him \$({N}) off", full)
    if d1 and d1b and d2 and "how much does he spend" in ql:
        if dok({d1.group(1), d1b.group(1), d2.group(1)}):
            return _rs_ret(f(d1.group(1)) + f(d1b.group(1)) - f(d2.group(1)))
    # 14. machines for a target rate
    f1 = re.search(rf"({N}) machines in a factory make ({N}) cell phones each minute", full)
    f2 = re.search(rf"make ({N}) cell phones a minute", ql)
    if f1 and f2 and "how many machines" in ql:
        if dok({f1.group(1), f1.group(2), f2.group(1)}):
            return _rs_ret(f(f2.group(1)) / (f(f1.group(2)) / f(f1.group(1))))
    # 15. shirt/hat/jeans basket
    k1 = re.search(rf"shirt costs \$({N})", full); k2 = re.search(rf"hat \$({N})", full)
    k3 = re.search(rf"jeans \$({N})", full)
    k4 = re.search(rf"(three|{N}) shirts", full); k5 = re.search(rf"(two|{N}) pairs of jeans", full)
    k6 = re.search(rf"(four|{N}) hats", full)
    if k1 and k2 and k3 and k4 and k5 and k6 and "pay" in ql \
            and all(w(x.group(1)) is not None for x in (k4, k5, k6)):
        if dok({k1.group(1), k2.group(1), k3.group(1)}):
            return _rs_ret(w(k4.group(1)) * f(k1.group(1)) + w(k5.group(1)) * f(k3.group(1))
                     + w(k6.group(1)) * f(k2.group(1)))
    # 16. necklaces + 3x earrings from a total
    n1 = re.search(rf"(three|{N}) necklaces", full)
    n1b = re.search(rf"earrings for a total of \$({N})", full)
    n2 = re.search(rf"earrings were (three|{N}) times as expensive as any one necklace", full)
    if n1 and n1b and n2 and "necklace" in ql \
            and w(n1.group(1)) is not None and w(n2.group(1)) is not None:
        if dok({n1b.group(1)}):
            return _rs_ret(f(n1b.group(1)) / (w(n1.group(1)) + w(n2.group(1))))
    # 17. fries plus a fraction of a friend's
    r1 = re.search(rf"had ({N}) fries at lunch", full)
    r2 = re.search(rf"one-third of his ({N}) fries", full)
    if r1 and r2 and "how many fries" in ql:
        if dok({r1.group(1), r2.group(1)}):
            return _rs_ret(f(r1.group(1)) + f(r2.group(1)) / 3)
    # 18. hourly → annual salary
    u1 = re.search(rf"earns \$({N}) an hour", full)
    u2 = re.search(rf"works ({N}) hours a day", full)
    u3 = re.search(rf"works ({N}) days a month", full)
    if u1 and u2 and u3 and "annual salary" in ql:
        if dok({u1.group(1), u2.group(1), u3.group(1)}):
            return _rs_ret(f(u1.group(1)) * f(u2.group(1)) * f(u3.group(1)) * 12)
    # 19. four halvings backward
    gw1 = re.search(r"four days ago", full)
    gw2 = re.search(r"every day he ate half of the remaining", full)
    gw3 = re.search(rf"now has ({N}) gummy worms left", full)
    gw4 = "on the fourth day" in full
    if gw1 and gw2 and gw3 and gw4 and "how many gummy worms were in the bag" in ql:
        if dok({gw3.group(1)}):
            return _rs_ret(f(gw3.group(1)) * 16)
    # 20. crackers Mon–Thu + doubled Friday
    cr1 = re.search(rf"eat ({N}) packs of crackers from monday to thursday", full)
    if cr1 and "twice the amount on friday" in full and "in all" in ql:
        if dok({cr1.group(1)}):
            a = f(cr1.group(1))
            return _rs_ret(a * 4 + 2 * a)
    # 21. weekly gallons from mpg
    mp1 = re.search(rf"gets ({N}) mpg", full)
    mp2 = re.search(rf"drives ({N}) miles to work each way ({N}) days a week", full)
    mp3 = re.search(rf"another ({N}) miles", full)
    if mp1 and mp2 and mp3 and "how many gallons" in ql:
        if dok({mp1.group(1), mp2.group(1), mp2.group(2), mp3.group(1)}):
            return _rs_ret((f(mp2.group(1)) * 2 * f(mp2.group(2)) + f(mp3.group(1))) / f(mp1.group(1)))
    # 22. discard then percent-discard pennies
    ia1 = re.search(rf"has ({N}) pennies", full)
    ia2 = re.search(rf"({N}) of his pennies are older", full)
    ia3 = re.search(rf"throw out ({N})% of his remaining", full)
    if ia1 and ia2 and ia3 and "left" in ql:
        if dok({ia1.group(1), ia2.group(1), ia3.group(1)}):
            return _rs_ret((f(ia1.group(1)) - f(ia2.group(1))) * (1 - f(ia3.group(1)) / 100))
    # 23. two-team period goals
    pe1 = re.search(rf"scored ({N}) goals in the first period and twice that amount in the second",
                    full)
    if pe1 and re.search(r"half the amount .{0,45}first period (?:and|\.) twice the amount", full) \
            and "total amount of goals" in ql:
        if dok({pe1.group(1)}):
            a = f(pe1.group(1))
            return _rs_ret(a + 2 * a + a / 2 + 2 * (2 * a))
    # 24. both parents attend
    pl1 = re.search(rf"({N}|six) girls", full)
    pl1b = re.search(rf"({N}|eight) boys in the school play", full)
    if pl1 and pl1b and "both parents of each kid" in full and "how many parents" in ql \
            and w(pl1.group(1)) is not None and w(pl1b.group(1)) is not None:
        if dok({g for g in (pl1.group(1), pl1b.group(1)) if g[0].isdigit()}):
            return _rs_ret((w(pl1.group(1)) + w(pl1b.group(1))) * 2)
    # 25. split-speed drive → bike time
    hw1 = re.search(rf"drive the distance from their house to the water park in ({N}) minutes", full)
    hw2 = re.search(rf"half that journey driving ({N}) miles per hour", full)
    hw2b = re.search(rf"other half driving ({N}) miles per hour", full)
    hw3 = re.search(rf"bike ({N}) miles per hour", full)
    if hw1 and hw2 and hw2b and hw3 and "how many hours" in ql and "bike" in ql:
        if dok({hw1.group(1), hw2.group(1), hw2b.group(1), hw3.group(1)}):
            half = f(hw1.group(1)) / 60 / 2
            dist = half * f(hw2.group(1)) + half * f(hw2b.group(1))
            return _rs_ret(dist / f(hw3.group(1)))
    # 26. pencil sharpenings budget
    sh1 = re.search(rf"sharpen a pencil (five|{N}) times before it runs out", full)
    sh2 = re.search(rf"for every ({N}) hours of use", full)
    sh3 = re.search(rf"has (ten|{N}) pencils", full)
    sh4 = re.search(rf"write for ({N}) hours", full)
    sh5 = re.search(rf"pencil costs \$({N})", full)
    if sh1 and sh2 and sh3 and sh4 and sh5 and "spend" in ql \
            and w(sh1.group(1)) is not None and w(sh3.group(1)) is not None:
        if dok({sh2.group(1), sh4.group(1), sh5.group(1)}
               | {g for g in (sh1.group(1), sh3.group(1)) if g[0].isdigit()}):
            per, need = w(sh1.group(1)), f(sh4.group(1)) / f(sh2.group(1))
            more = (need - w(sh3.group(1)) * per) / per
            more = int(more) + (1 if more != int(more) else 0)
            return _rs_ret(more * f(sh5.group(1)))
    # 27. detour round-trip time away
    dt1 = re.search(rf"drives ({N}) miles to her friend's house", full)
    dt2 = re.search(rf"detour that is ({N})% longer", full)
    dt3 = re.search(rf"spends ({N}) minutes at her friend's house", full)
    dt4 = re.search(rf"speed of ({N}) mph", full)
    if dt1 and dt2 and dt3 and dt4 and "how long" in ql:
        if dok({dt1.group(1), dt2.group(1), dt3.group(1), dt4.group(1)}):
            dist = f(dt1.group(1)) + f(dt1.group(1)) * (1 + f(dt2.group(1)) / 100)
            return _rs_ret(dist / f(dt4.group(1)) + f(dt3.group(1)) / 60)
    # 28. two heaters at 3/4 capacity
    wh1 = re.search(r"water heater is twice the size of", full)
    wh2 = re.search(rf"capacity of \w+'s water heater is ({N}) gallons", full)
    wh2b = re.search(r"it's (\d+)/(\d+) full", full)
    wh3 = re.search(r"also full with water to (\d+)/(\d+) of its capacity", full)
    if wh1 and wh2 and wh2b and wh3 and "total number of gallons" in ql:
        if dok({wh2.group(1), wh2b.group(1), wh2b.group(2), wh3.group(1), wh3.group(2)}):
            big = f(wh2.group(1)); fr = f(wh2b.group(1)) / f(wh2b.group(2))
            fr2 = f(wh3.group(1)) / f(wh3.group(2))
            return _rs_ret(big * fr + (big / 2) * fr2)
    # 29. popcorn servings for the group
    po1 = re.search(rf"({N}) pieces of popcorn in a serving", full)
    po2 = re.search(rf"eat ({N}) pieces of popcorn", full)
    po3 = re.search(rf"(three|{N}) other friends can each eat ({N}) pieces", full)
    if po1 and po2 and po3 and "how many servings" in ql and w(po3.group(1)) is not None:
        if dok({po1.group(1), po2.group(1), po3.group(2)}):
            return _rs_ret((f(po2.group(1)) + w(po3.group(1)) * f(po3.group(2))) / f(po1.group(1)))
    # 30. tickets given 2-each until 3 left
    na1 = re.search(rf"has ({N}) tickets", full)
    na2 = re.search(rf"gives away ({N}) tickets each to his best friends", full)
    na3 = re.search(rf"only has ({N}) tickets left", full)
    if na1 and na2 and na3 and "how many best friends" in ql:
        if dok({na1.group(1), na2.group(1), na3.group(1)}):
            return _rs_ret((f(na1.group(1)) - f(na3.group(1))) / f(na2.group(1)))
    # 31. three-grade GPA average
    gp1 = re.search(rf"6th graders is ({N})", full)
    gp2 = re.search(rf"7th graders is ({N}) more", full)
    gp3 = re.search(rf"8th graders average gpa is ({N})", full)
    if gp1 and gp2 and gp3 and "average gpa for the school" in ql:
        if dok({gp1.group(1), gp2.group(1), gp3.group(1), "6", "7", "8"}):
            a = f(gp1.group(1))
            return _rs_ret((a + (a + f(gp2.group(1))) + f(gp3.group(1))) / 3)
    # 32. start-with from purchases + remainder
    sc1 = re.search(rf"buys ({N}|two) toy cars for \$({N}) each", full)
    sc2 = re.search(rf"scarf for \$({N})", full)
    sc3 = re.search(rf"beanie for \$({N})", full)
    sc4 = re.search(rf"has \$({N}) remaining", full)
    if sc1 and sc2 and sc3 and sc4 and "start with" in ql and w(sc1.group(1)) is not None:
        if dok({g for g in (sc1.group(1), sc1.group(2), sc2.group(1), sc3.group(1), sc4.group(1))
                if g[0].isdigit()}):
            return _rs_ret(w(sc1.group(1)) * f(sc1.group(2)) + f(sc2.group(1)) + f(sc3.group(1))
                     + f(sc4.group(1)))
    # 33. years to reduce a collection
    op1 = re.search(rf"has ({N}) cars", full)
    op2 = re.search(rf"gives away per year is ({N})", full)
    op3 = re.search(rf"reduce her car collection to ({N})", ql)
    if op1 and op2 and op3 and "how many years" in ql:
        if dok({op1.group(1), op2.group(1), op3.group(1)}):
            return _rs_ret((f(op1.group(1)) - f(op3.group(1))) / f(op2.group(1)))
    # 34. percent-of-start after up-then-down
    mg1 = re.search(rf"gave her \$({N}) to start", full)
    mg2 = re.search(rf"increase the account by ({N})%", full)
    mg3 = re.search(rf"decreased by ({N})%", full)
    if mg1 and mg2 and mg3 and "what percentage of her starting balance" in full:
        if dok({mg1.group(1), mg2.group(1), mg3.group(1)}):
            return _rs_ret((1 + f(mg2.group(1)) / 100) * (1 - f(mg3.group(1)) / 100) * 100)
    # 35. calorie deficit → days to lose weight
    bu1 = re.search(rf"eats ({N}) calories a day", full)
    bu1b = re.search(rf"burns ({N}) a day", full)
    bu2 = re.search(rf"burn ({N}) calories to lose ({N}) pound", full)
    bu3 = re.search(rf"lose ({N}) pounds", full)
    if bu1 and bu1b and bu2 and bu3 and "how many days" in full:
        if dok({bu1.group(1), bu1b.group(1), bu2.group(1), bu2.group(2), bu3.group(1)}):
            deficit = f(bu1b.group(1)) - f(bu1.group(1))
            return _rs_ret(f(bu2.group(1)) * f(bu3.group(1)) / f(bu2.group(2)) / deficit)
    # 36. bicycle journey total minutes
    is1 = re.search(rf"rate of ({N}) miles per hour for ({N}) minutes", full)
    is2 = re.search(rf"rides for another ({N}) miles", full)
    is3 = re.search(rf"rests for ({N}) minutes", full)
    is4 = re.search(rf"remaining distance of ({N}) miles", full)
    if is1 and is2 and is3 and is4 and "total time in minutes" in ql:
        if dok({is1.group(1), is1.group(2), is2.group(1), is3.group(1), is4.group(1)}):
            v = f(is1.group(1))
            return _rs_ret(f(is1.group(2)) + f(is2.group(1)) / v * 60 + f(is3.group(1))
                     + f(is4.group(1)) / v * 60)
    # 37. daily crab revenue → weekly
    cb1 = re.search(rf"has ({N}) crab buckets", full)
    cb2 = re.search(rf"bucket gets ({N}) crabs", full)
    cb3 = re.search(rf"for \$({N}) each", full)
    if cb1 and cb2 and cb3 and "every day" in full and "per week" in ql:
        if dok({cb1.group(1), cb2.group(1), cb3.group(1)}):
            return _rs_ret(f(cb1.group(1)) * f(cb2.group(1)) * f(cb3.group(1)) * 7)
    # 38. percent picks from four rose bushes
    rb1 = re.search(rf"first rose bush has ({N}) red flowers", full)
    rb2 = re.search(rf"second rose bush has ({N}) pink flowers", full)
    rb3 = re.search(rf"third rose bush has ({N}) yellow flowers", full)
    rb4 = re.search(rf"fourth rose bush has ({N}) orange flowers", full)
    rb5 = re.search(rf"picks ({N})% of the red roses", full)
    rb6 = re.search(rf"({N})% pink roses", full)
    rb7 = re.search(rf"({N})% of the yellow roses", full)
    rb8 = re.search(rf"({N})% orange roses", full)
    if rb1 and rb2 and rb3 and rb4 and rb5 and rb6 and rb7 and rb8 and "how many roses" in ql:
        if dok({rb1.group(1), rb2.group(1), rb3.group(1), rb4.group(1), rb5.group(1),
                rb6.group(1), rb7.group(1), rb8.group(1)}):
            return _rs_ret(f(rb1.group(1)) * f(rb5.group(1)) / 100
                           + f(rb2.group(1)) * f(rb6.group(1)) / 100
                           + f(rb3.group(1)) * f(rb7.group(1)) / 100
                           + f(rb4.group(1)) * f(rb8.group(1)) / 100)
    # 39. water bottles for a round trip
    el1 = re.search(rf"(four|{N}) people total", full)
    el2 = re.search(rf"destination for ({N}) hours", full)
    el2b = re.search(rf"drive ({N}) hours to return", full)
    el3 = re.search(r"drink 1/2 a bottle of water", full)
    if el1 and el2 and el2b and el3 and "how many water bottles" in ql \
            and w(el1.group(1)) is not None:
        if dok({el2.group(1), el2b.group(1), "1", "2"}):
            return _rs_ret(w(el1.group(1)) * (f(el2.group(1)) + f(el2b.group(1))) * 0.5)
    # 40. calories left for dinner
    di1 = re.search(rf"eat a ({N}) calorie a day diet", full)
    di2 = re.search(rf"breakfast, she ate ({N}) calories", full)
    di3 = re.search(rf"lunch, she had ({N})", full)
    di4 = re.search(rf"snack of ({N}) calories", full)
    if di1 and di2 and di3 and di4 and "left for dinner" in ql:
        if dok({di1.group(1), di2.group(1), di3.group(1), di4.group(1)}):
            return _rs_ret(f(di1.group(1)) - f(di2.group(1)) - f(di3.group(1)) - f(di4.group(1)))
    # 41. baked-goods revenue after nibbling
    ky1 = re.search(rf"bakes ({N}) cookies and ({N}) brownies", full)
    ky2 = re.search(rf"eats ({N}) cookies and ({N}) brownies", full)
    ky3 = re.search(rf"eats ({N}) cookie and ({N}) brownies", full)
    ky4 = re.search(rf"cookie for \$({N})", full)
    ky4b = re.search(rf"brownie for \$({N})", full)
    if ky1 and ky2 and ky3 and ky4 and ky4b and "how much money" in ql:
        if dok(set(ky1.groups()) | set(ky2.groups()) | set(ky3.groups())
               | {ky4.group(1), ky4b.group(1)}):
            ck = f(ky1.group(1)) - f(ky2.group(1)) - f(ky3.group(1))
            br = f(ky1.group(2)) - f(ky2.group(2)) - f(ky3.group(2))
            return _rs_ret(ck * f(ky4.group(1)) + br * f(ky4b.group(1)))
    # 42. leggings pairs for four-legged pets
    le1 = re.search(rf"has ({N}) dogs and ({N}) cats", full)
    if le1 and "how many pairs of leggings" in ql:
        if dok({le1.group(1), le1.group(2)}):
            return _rs_ret((f(le1.group(1)) + f(le1.group(2))) * 2)
    # 43. percent-remainder bunnies
    bn1 = re.search(rf"has ({N}) pets", full)
    bn2 = re.search(rf"({N})% of them are dogs", full)
    bn2b = re.search(rf"({N})% are cats", full)
    if bn1 and bn2 and bn2b and "the rest are bunnies" in full and "how many bunnies" in ql:
        if dok({bn1.group(1), bn2.group(1), bn2b.group(1)}):
            return _rs_ret(f(bn1.group(1)) * (1 - f(bn2.group(1)) / 100 - f(bn2b.group(1)) / 100))
    return None


def _vocab_singles_d_system(premises: list, question: str):
    """VOCAB+STRUCTURE SINGLES D (#235) — thirty-seven branches with wave-25 vocabulary:
    fudge ounces, attendance sums, rental splits, arithmetic-series stalls and pastries,
    scavenger chains, gecko profit, monthly deliveries, helicopter products, crepe/cotton
    remainders, arena doubles, monthly savings gaps, market balances, notebook pairs,
    percent-chain brunettes, sandwich portions, square-side diffs (√area), lemonade compares,
    quilt scaling, doubling pens, cents-per-slice, novel-page chains, seed:fertilizer ratios,
    index-card packs, Asia halves, mismatching socks, fundraiser residuals, blueberry
    percentages, guitar-pick thirds, patisserie change, machine-cap trios, M&M averages,
    kept slices, playlist gaps, 3/8th-age chains, and stair-goal minutes. Every branch
    digit-accounted; positive. None otherwise."""
    N = _RS_N

    def f(t):
        return float(t.replace(",", ""))

    def w(tok):
        if tok is None:
            return None
        return f(tok) if tok[0].isdigit() else NUMBERS.get(tok)

    ql = question.lower()
    full = " . ".join(p.lower() for p in premises) + " . " + ql

    def dok(used):
        return all(dd in used for dd in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?",
                                                   " ".join(premises) + " " + question))

    # 1. fudge ounces: a + half a pound + b pounds → ×16
    fu1 = re.search(rf"ate ({N}) pounds of chocolate fudge", full)
    fu2 = re.search(rf"ate ({N}) pounds of fudge", full)
    if fu1 and fu2 and "half a pound" in full and "how many ounces" in ql:
        if dok({fu1.group(1), fu2.group(1), "3"}):
            return _rs_ret((f(fu1.group(1)) + 0.5 + f(fu2.group(1))) * 16)
    # 2. seated: a students + b teachers seated + c standing
    se1 = re.search(rf"({N}) students and ({N}) teachers are seated", full)
    se2 = re.search(rf"({N}) students are standing", full)
    if se1 and se2 and "how many attended" in ql:
        if dok({se1.group(1), se1.group(2), se2.group(1)}):
            return _rs_ret(f(se1.group(1)) + f(se1.group(2)) + f(se2.group(1)))
    # 3. rental split: k people; weekday $a × d1 + weekend $b × d2; split → each
    re1 = re.search(rf"and ({N}) of her friends", full)
    re2 = re.search(rf"weekdays is \$({N}) per day", full)
    re3 = re.search(rf"weekend rental rate is \$({N}) per day", full)
    re4 = re.search(rf"for ({N}) days", full)
    if re1 and re2 and re3 and re4 and "thursday to sunday" in full \
            and re.search(r"each (?:person|of them)", full):
        if dok({re1.group(1), re2.group(1), re3.group(1), re4.group(1)}):
            total = 2 * f(re2.group(1)) + 2 * f(re3.group(1))
            return _rs_ret(total / (f(re1.group(1)) + 1))
    # 4. Samantha sleeps: a hrs; baby 2.5×; father naps a/... "for every hour the baby sleeps [father sleeps 30 min?]" skip exact; use: father = baby/2 → week? gold 70 hmm skip
    # 5. stall series: $a day1; +$d each day; n days → sum
    st1 = re.search(rf"made \$({N})\. every day after that ?,? she made \$({N}) more", full)
    if st1 is None:
        st1a = re.search(rf"she made \$({N})", full)
        st1b = re.search(rf"made \$({N}) more than the previous day", full)
        st1 = (st1a, st1b) if st1a and st1b else None
        if st1:
            a_t, d_t = st1[0].group(1), st1[1].group(1)
    else:
        a_t, d_t = st1.group(1), st1.group(2)
    st2 = re.search(rf"after ({N}) days", ql)
    if st1 and st2 and "how much money" in ql:
        if dok({a_t, d_t, st2.group(1)}):
            n_ = f(st2.group(1))
            a_ = f(a_t)
            return _rs_ret(n_ * a_ + f(d_t) * n_ * (n_ - 1) / 2)
    # 6. scavenger: L = S + 4; S = 4×T; T = n
    sc1 = re.search(rf"found ({N}) more items on the scavenger hunt than", full)
    sc2 = re.search(rf"found (\w+|{N}) times the amount of items than (\w+)", full)
    sc3 = re.search(rf"find ({N}) items", full)
    if sc1 and sc2 and sc3 and re.search(r"how many items did \w+ find", ql):
        k_ = w(sc2.group(1))
        toks = {sc1.group(1), sc3.group(1)} | ({sc2.group(1)} if sc2.group(1)[0].isdigit() else set())
        if k_ and dok(toks):
            return _rs_ret(k_ * f(sc3.group(1)) + f(sc1.group(1)))
    # 7. gecko profit: sold for $a; store sells 5 more than 3×a → profit
    ge1 = re.search(rf"sold the geckos for ({N})\$", full)
    ge2 = re.search(rf"sells them for ({N}) more than ({N}) times that", full)
    if ge1 and ge2 and "profit" in ql:
        if dok({ge1.group(1), ge2.group(1), ge2.group(2)}):
            a_ = f(ge1.group(1))
            return _rs_ret(f(ge2.group(2)) * a_ + f(ge2.group(1)) - a_)
    # 8. delivers: a + b apples per week; monthly (4 weeks)
    de1 = re.search(rf"eat a total of ({N}) apples and \w+ can eat a total of ({N}) apples per week", full)
    if de1 is None:
        de1a = re.search(rf"eat a total of ({N}) apples", full)
        de1b = re.search(rf"({N}) apples per week", full)
        de1 = (de1a, de1b) if de1a and de1b and de1a.group(1) != de1b.group(1) else None
        if de1:
            a_t2, b_t2 = de1[0].group(1), de1[1].group(1)
    else:
        a_t2, b_t2 = de1.group(1), de1.group(2)
    de2 = re.search(rf"delivers ({N}) time per month", full)
    if de1 and de2 and "for a month" in ql:
        if dok({a_t2, b_t2, de2.group(1)}):
            return _rs_ret((f(a_t2) + f(b_t2)) * 4)
    # 9. helicopter: h hrs/day × d days × $r
    he1 = re.search(rf"rents a helicopter for ({N}) hours a day for ({N}) days", full)
    he2 = re.search(rf"\$({N}) an hour", full)
    if he1 and he2 and "how much did he pay" in ql:
        if dok({he1.group(1), he1.group(2), he2.group(1)}):
            return _rs_ret(f(he1.group(1)) * f(he1.group(2)) * f(he2.group(1)))
    # 10. crepes: k dozen eggs; 1/4 crepes; 2/3 of remaining cupcakes → left
    cr1 = re.search(rf"ordered (\w+|{N}) dozen eggs", full)
    if cr1 and "1/4" in full and "2/3 of the remaining" in full and "left" in ql:
        k_ = w(cr1.group(1))
        toks = ({cr1.group(1)} if cr1.group(1)[0].isdigit() else set()) | {"1", "4", "2", "3"}
        if k_ and dok(toks):
            eggs = 12 * k_
            rem = eggs * 3 / 4
            return _rs_ret(rem / 3)
    # 11. cotton candies: n; brother+sister a each; 1/4 of remaining to cousin; ate e → left
    co1 = re.search(rf"bought ({N}) cotton candies", full)
    co2 = re.search(rf"({N}) cotton candies each", full)
    co3 = re.search(rf"ate ({N}) cotton candies", full)
    if co1 and co2 and co3 and "one-fourth" in full and "left" in ql:
        if dok({co1.group(1), co2.group(1), co3.group(1)}):
            rem = f(co1.group(1)) - 2 * f(co2.group(1))
            rem = rem * 3 / 4
            return _rs_ret(rem - f(co3.group(1)))
    # 12. arenas: A in h hours; F twice as long → total
    ar1 = re.search(rf"run all-around two arenas in ({N}) hours", full)
    if ar1 and "twice as long" in full and "total time" in ql:
        if dok({ar1.group(1), "2"} if "two arenas" in full else {ar1.group(1)}):
            h_ = f(ar1.group(1))
            return _rs_ret(h_ + 2 * h_)
    # 13. Alfred: goal $g over m months; has $h left over → needs (g−h)/m
    al1 = re.search(rf"save \$({N})(?:\.00)? over ({N}) months", full)
    al2 = re.search(rf"has \$({N})(?:\.00)? left over", full)
    if al1 and al2 and "each month" in ql:
        if dok({al1.group(1), al1.group(2), al2.group(1)}):
            return _rs_ret((f(al1.group(1)) - f(al2.group(1))) / f(al1.group(2)))
    # 14. Victoria: $H; 2 rice × $a + 3 wheat × $b + 1 soda $c → balance
    vi1 = re.search(rf"had \$({N})", full)
    vi2 = re.search(rf"({N}) packets of rice each at \$({N})", full)
    vi3 = re.search(rf"({N}) packets of wheat flour each at \$({N})", full)
    vi4 = re.search(rf"({N}) soda at \$({N})", full)
    if vi1 and vi2 and vi3 and vi4 and "remaining balance" in ql:
        if dok({vi1.group(1), vi2.group(1), vi2.group(2), vi3.group(1), vi3.group(2),
                vi4.group(1), vi4.group(2)}):
            return _rs_ret(f(vi1.group(1)) - f(vi2.group(1)) * f(vi2.group(2))
                           - f(vi3.group(1)) * f(vi3.group(2)) - f(vi4.group(1)) * f(vi4.group(2)))
    # 15. notebooks: John 2 per child + wife 5 per child × k children
    no1 = re.search(rf"has ({N}) children", full)
    no2 = re.search(rf"bought ({N}) notebooks for each of his children", full)
    no3 = re.search(rf"bought ({N}) notebooks for each", full[no2.end():] if no2 else full)
    if no1 and no2 and no3 and "how many notebooks" in ql:
        if dok({no1.group(1), no2.group(1), no3.group(1)}):
            return _rs_ret(f(no1.group(1)) * (f(no2.group(1)) + f(no3.group(1))))
    # 16. brunettes: n students; a% female; b% brunettes; c% under → count
    br1 = re.search(rf"were ({N}) students", full)
    br2 = re.search(rf"({N})% of the students were female", full)
    br3 = re.search(rf"({N})% of the females were brunettes", full)
    br4 = re.search(rf"({N})% of the female brunettes were under", full)
    if br1 and br2 and br3 and br4 and re.search(r"how many", ql):
        if dok({br1.group(1), br2.group(1), br3.group(1), br4.group(1), "5"}):
            return _rs_ret(f(br1.group(1)) * f(br2.group(1)) / 100 * f(br3.group(1)) / 100
                           * f(br4.group(1)) / 100)
    # 17. catering: n sandwiches ×4 quarters; k portions each → people
    ca1 = re.search(rf"makes ({N}) sandwiches", full)
    ca2 = re.search(rf"gives everyone ({N}) portions", full)
    if ca1 and ca2 and "cuts them in half" in full and "in half again" in full \
            and "how many people" in ql:
        if dok({ca1.group(1), ca2.group(1)}):
            return _rs_ret(f(ca1.group(1)) * 4 / f(ca2.group(1)))
    # 18. squares: area A and B → side diff
    sq1 = re.search(rf"area of square a is ({N})", full)
    sq2 = re.search(rf"area of square b is ({N})", full)
    if sq1 and sq2 and "length difference" in ql:
        if dok({sq1.group(1), sq2.group(1)}):
            return _rs_ret(f(sq2.group(1)) ** 0.5 - f(sq1.group(1)) ** 0.5)
    # 19. lemonade glasses: K a; R b; T = 2(a+b) → T − a
    lg1 = re.search(rf"sold ({N}) glasses of lemonade and \w+ sold ({N}) glasses", full)
    if lg1 is None:
        lg1a = re.search(rf"sold ({N}) glasses of lemonade", full)
        lg1b = re.search(rf"sold ({N}) glasses of lemonade", full[lg1a.end():] if lg1a else full)
        lg1 = (lg1a, lg1b) if lg1a and lg1b else None
        if lg1:
            ka, rb = lg1[0].group(1), lg1[1].group(1)
    else:
        ka, rb = lg1.group(1), lg1.group(2)
    if lg1 and "twice as many as" in full and "combined sales" in full \
            and "how many more glasses" in ql:
        if dok({ka, rb}):
            t_ = 2 * (f(ka) + f(rb))
            return _rs_ret(t_ - f(ka))
    # 20. quilts: k quilts with y yards; for m quilts
    qu1 = re.search(rf"make ({N}) quilts with ({N}) yards", full)
    qu2 = re.search(rf"make ({N}) quilts", ql)
    if qu1 and qu2 and "how many yards" in ql:
        if dok({qu1.group(1), qu1.group(2), qu2.group(1)}):
            return _rs_ret(f(qu1.group(2)) / f(qu1.group(1)) * f(qu2.group(1)))
    # 21. pens doubling: a pens week 1; doubles weekly; Jane n after a month → diff
    pd1 = re.search(rf"has ({N}) pens in the first week", full)
    pd2 = re.search(rf"will have ({N}) pens after a month", full)
    if pd1 and pd2 and "doubles" in full and "how many more pens" in ql:
        if dok({pd1.group(1), pd2.group(1)}):
            alex = f(pd1.group(1)) * 8
            return _rs_ret(alex - f(pd2.group(1)))
    # 22. loaves: k loaves × s slices; pays with 2 $20 − $16 change → cents per slice
    lo1 = re.search(rf"buys ({N}) loaves of bread", full)
    lo2 = re.search(rf"has ({N}) slices", full)
    lo3 = re.search(rf"({N}) \$({N}) bills", full)
    lo4 = re.search(rf"gets \$({N}) change", full)
    if lo1 and lo2 and lo3 and lo4 and "in cents" in ql:
        if dok({lo1.group(1), lo2.group(1), lo3.group(1), lo3.group(2), lo4.group(1)}):
            paid = f(lo3.group(1)) * f(lo3.group(2)) - f(lo4.group(1))
            return _rs_ret(paid * 100 / (f(lo1.group(1)) * f(lo2.group(1))))
    # 23. novel pages: novel = history/2; science = 4×novel; history = n
    np1 = re.search(rf"history book has ({N}) pages", full)
    if np1 and "half as many pages as their history" in full \
            and "4 times the amount of pages as their novel" in full \
            and "science" in ql:
        if dok({np1.group(1), "4"}):
            return _rs_ret(f(np1.group(1)) / 2 * 4)
    # 24. fertilizer: seed = 3×fert; combined n → fert... ask "how many gallons of seed"?
    fe1 = re.search(rf"uses ({N}) gallons of seed", full)
    fe1 = fe1 if fe1 and "fertilizer combined" in full else None
    if fe1 and "three times as much seed as fertilizer" in full and "seed" in ql:
        if dok({fe1.group(1)}):
            return _rs_ret(f(fe1.group(1)) / 4 * 3)
    # 25. index cards: c per student × p periods × s students; $x per 50-pack → cost
    ic1 = re.search(rf"gives each student ({N}) index cards", full)
    ic2a = re.search(rf"teaches ({N}) periods a day", full)
    ic2b = re.search(rf"each class has ({N}) students", full)
    ic2 = (ic2a, ic2b) if ic2a and ic2b else None
    ic3 = re.search(rf"({N}) pack of index cards cost \$({N})", full)
    if ic1 and ic2 and ic3 and "how much" in ql:
        if dok({ic1.group(1), ic2[0].group(1), ic2[1].group(1), ic3.group(1), ic3.group(2)}):
            cards = f(ic1.group(1)) * f(ic2[0].group(1)) * f(ic2[1].group(1))
            return _rs_ret(cards / f(ic3.group(1)) * f(ic3.group(2)))
    # 26. countries: n visited; a Europe + b SA; half of rest Asia → rest
    cn1 = re.search(rf"visited already ({N}) different countries", full)
    cn2 = re.search(rf"({N}) of them were in europe and ({N}) in south america", full)
    if cn1 and cn2 and "half of them were in asia" in full:
        if dok({cn1.group(1), cn2.group(1), cn2.group(2)}):
            rest = f(cn1.group(1)) - f(cn2.group(1)) - f(cn2.group(2))
            return _rs_ret(rest / 2)
    # 27. mismatching socks: n socks; k matching pairs → n − 2k
    ms1 = re.search(rf"has ({N}) socks", full)
    ms2 = re.search(rf"({N}) pairs of socks that match", full)
    if ms1 and ms2 and "mismatching" in ql:
        if dok({ms1.group(1), ms2.group(1)}):
            return _rs_ret(f(ms1.group(1)) - 2 * f(ms2.group(1)))
    # 28. fundraiser: needs n; sold a + b + c → more
    fr1 = re.search(rf"needs to sell ({N}) packs", full)
    fr2 = re.search(rf"sold ({N}) packs to his grandmother ?,? ({N}) packs to his uncle ?,? and ({N}) packs", full)
    if fr2 is None:
        solds = re.findall(rf"({N}) packs to (?:his|a)", full)
        fr2 = solds if len(solds) == 3 else None
    else:
        fr2 = [fr2.group(1), fr2.group(2), fr2.group(3)]
    if fr1 and fr2 and "how many more packs" in ql:
        if dok({fr1.group(1)} | set(fr2)):
            return _rs_ret(f(fr1.group(1)) - sum(f(x) for x in fr2))
    # 29. cinnamon: k cartons × n berries; 10 per muffin + m cinnamon → pct with berries
    ci1 = re.search(rf"has ({N}) cartons of ({N}) blueberries", full)
    ci2 = re.search(rf"({N}) blueberries per muffin", full)
    ci3 = re.search(rf"makes ({N}) cinnamon muffins", full)
    if ci1 and ci2 and ci3 and "percentage" in ql:
        if dok({ci1.group(1), ci1.group(2), ci2.group(1), ci3.group(1)}):
            bm = f(ci1.group(1)) * f(ci1.group(2)) / f(ci2.group(1))
            return _rs_ret(bm / (bm + f(ci3.group(1))) * 100)
    # 30. guitar picks: half red, third blue, rest yellow; blue = n → yellow
    gp1 = re.search(rf"has ({N}) blue picks", full)
    if gp1 is None:
        gp1 = re.search(rf"has ({N}) bl", full)
    if gp1 and "half of his picks are red" in full and "one-third of the picks are blue" in full \
            and "rest are yellow" in full:
        if dok({gp1.group(1)}):
            total = f(gp1.group(1)) * 3
            return _rs_ret(total - total / 2 - f(gp1.group(1)))
    # 31. patisserie: a singles × $x + b doubles × $y; pays $B → change
    pa1 = re.search(rf"single layer cake slice is \$({N})", full)
    pa2 = re.search(rf"double layer cake slice is \$({N})", full)
    pa3 = re.search(rf"buys ({N}) single layer cake slices and ({N}) double layer", full)
    pa4 = re.search(rf"pays with a \$({N})", full)
    if pa1 and pa2 and pa3 and pa4 and "change" in ql:
        if dok({pa1.group(1), pa2.group(1), pa3.group(1), pa3.group(2), pa4.group(1)}):
            return _rs_ret(f(pa4.group(1)) - f(pa3.group(1)) * f(pa1.group(1))
                           - f(pa3.group(2)) * f(pa2.group(1)))
    # 32. caps: A n/min; B = A−2; C = B+5; 10 minutes → total
    cp1 = re.search(rf"machine a can put caps on ({N}) bottles in ({N}) minute", full)
    cp2 = re.search(rf"({N}) fewer bottles than machine a", full)
    cp3 = re.search(rf"({N}) more bottles than machine b", full)
    cp4 = re.search(rf"in ({N}) minutes", ql)
    if cp1 and cp2 and cp3 and cp4 and "how many bottles" in ql:
        if dok({cp1.group(1), cp1.group(2), cp2.group(1), cp3.group(1), cp4.group(1), "3"}):
            a_ = f(cp1.group(1))
            b_ = a_ - f(cp2.group(1))
            c_ = b_ + f(cp3.group(1))
            return _rs_ret((a_ + b_ + c_) * f(cp4.group(1)))
    # 33. m&ms: batch n cookies; a chips + a/3 m&ms → avg per cookie
    mm1 = re.search(rf"batch of ({N}) cookies", full)
    mm2 = re.search(rf"add ({N}) chocolate chips and one-third as many", full)
    if mm1 and mm2 and "average number of chocolate pieces" in ql:
        if dok({mm1.group(1), mm2.group(1)}):
            a_ = f(mm2.group(1))
            return _rs_ret((a_ + a_ / 3) / f(mm1.group(1)))
    # 34. twin stickers: a + b; grandparents gave k each → total
    tw1 = re.search(rf"total of ({N}) in her collection", full)
    tw2 = re.search(rf"had ({N}) in her collection", full)
    tw3 = re.search(rf"gave (?:them|each) ({N})", full)
    if tw1 and tw2 and tw3 and "how many" in ql and "combined" in full:
        if dok({tw1.group(1), tw2.group(1), tw3.group(1)}):
            return _rs_ret(f(tw1.group(1)) + f(tw2.group(1)) + 2 * f(tw3.group(1)))
    # 35. visitors cake: n pieces; 1/4 eaten → kept
    vc1 = re.search(rf"cake into ({N}) equal pieces", full)
    if vc1 and "one-fourth" in full and "kept" in ql:
        if dok({vc1.group(1)}):
            return _rs_ret(f(vc1.group(1)) * 3 / 4)
    # 36. pastries avg: sold a Monday; +1 daily; 7 days → avg
    ps1 = re.search(rf"on monday he sold ({N})", full)
    ps2 = re.search(rf"increases by ({N}) compared to the previous day", full)
    ps3 = re.search(rf"works ({N}) days a week", full)
    if ps1 and ps2 and ps3 and "on average" in ql:
        pr = re.search(rf"pastries for \$({N})", full)
        toks = {ps1.group(1), ps2.group(1), ps3.group(1)} | ({pr.group(1)} if pr else set())
        if dok(toks):
            n_ = f(ps3.group(1))
            a_ = f(ps1.group(1))
            tot = n_ * a_ + f(ps2.group(1)) * n_ * (n_ - 1) / 2
            return _rs_ret(tot / n_)
    # 37. playlist: a songs × 3 min + b songs × 2 min; run m minutes → more minutes needed
    pl1 = re.search(rf"has ({N}) ({N})-minute songs and ({N}) ({N})-minute songs", full)
    pl2 = re.search(rf"takes ({N}) minutes", full)
    if pl1 and pl2 and "how many more minutes" in ql:
        if dok({pl1.group(1), pl1.group(2), pl1.group(3), pl1.group(4), pl2.group(1)}):
            have = f(pl1.group(1)) * f(pl1.group(2)) + f(pl1.group(3)) * f(pl1.group(4))
            return _rs_ret(f(pl2.group(1)) - have)
    # 38. Grace 3/8th: G = 3/8 × GM; GM = 2 × M; M = n
    ga1 = re.search(rf"({N})/({N})th the age of her grandmother", full)
    ga2 = re.search(rf"mother is ({N}) years old", full)
    if ga1 and ga2 and "twice the age of" in full and re.search(r"how old is \w+", ql):
        if dok({ga1.group(1), ga1.group(2), ga2.group(1)}):
            gm = 2 * f(ga2.group(1))
            return _rs_ret(gm * f(ga1.group(1)) / f(ga1.group(2)))
    # 39. stairs: s steps in m minutes; goal g → minutes
    sr1 = re.search(rf"walk ({N}) steps in ({N}) minutes", full)
    sr2 = re.search(rf"goal is ({N}) steps", full)
    if sr1 and sr2 and "how many minutes" in ql:
        if dok({sr1.group(1), sr1.group(2), sr2.group(1)}):
            return _rs_ret(f(sr2.group(1)) / f(sr1.group(1)) * f(sr1.group(2)))
    return None


def _vocab_singles_c_system(premises: list, question: str):
    """VOCAB+STRUCTURE SINGLES C (#234) — thirty-nine branches with wave-24 vocabulary:
    percent-of-percent pistachios, three-box cereal chains, jet rates, charge-time
    proportions, three-item purchases, ticket relations (the gold reads "sold 6 more than two
    times the number of fair tickets AS baseball" as baseball = 2·fair + 6), thermos pints,
    weighted bill averages, yarn totals, three-part ratios, grade residuals, carpet sums,
    shower tiles, counters+marbles ratios, warehouse splits, bedroom walls, remaining-percent
    splits, rectangle areas, chocolate weeks, lemonade profit, class-minute averages,
    downpayment shares, rent shares, vending products, applesauce pies, five-year temperature
    averages, scrapbook additions, budget admissions, vehicle thirds, tortilla keeps, rock
    halves, mistake scores, dice sides, zit totals, nap residuals, sticker backwards,
    babysitting sums, mortgage remainders, and party collections. Every branch
    digit-accounted; positive. None otherwise."""
    N = _RS_N

    def f(t):
        return float(t.replace(",", ""))

    def w(tok):
        if tok is None:
            return None
        return f(tok) if tok[0].isdigit() else NUMBERS.get(tok)

    ql = question.lower()
    full = " . ".join(p.lower() for p in premises) + " . " + ql

    def dok(used):
        return all(dd in used for dd in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?",
                                                   " ".join(premises) + " " + question))

    # 1. pistachios: n; a% shells; b% of those opened
    m = re.search(rf"has ({N}) pistachios", full)
    m2 = re.search(rf"({N}) percent have shells", full)
    m3 = re.search(rf"({N}) percent of those have shells that are opened", full)
    if m and m2 and m3 and "opened shell" in full:
        if dok({m.group(1), m2.group(1), m3.group(1)}):
            return _rs_ret(f(m.group(1)) * f(m2.group(1)) / 100 * f(m3.group(1)) / 100)
    # 2. cereal: box1 a oz; box2 = a/2 and 5 less than box3 → total
    ce1 = re.search(rf"one box holds ({N}) ounces", full)
    ce2 = re.search(rf"({N}) ounces less than the third", full)
    ce2 = ce2 if ce2 and "holds half the amount of the first box" in full else None
    if ce1 and ce2 and "in all" in ql:
        if dok({ce1.group(1), ce2.group(1), "3"}):
            a_ = f(ce1.group(1))
            b_ = a_ / 2
            c_ = b_ + f(ce2.group(1))
            return _rs_ret(a_ + b_ + c_)
    # 3. jet: d miles in h hours; in k hours
    je1 = re.search(rf"travels ({N}) miles in ({N}) hours", full)
    je2 = re.search(rf"in ({N}) hours", ql)
    if je1 and je2 and "how far" in ql:
        if dok({je1.group(1), je1.group(2), je2.group(1)}):
            return _rs_ret(f(je1.group(1)) / f(je1.group(2)) * f(je2.group(1)))
    # 4. cell charge: m minutes → p%; to 100
    cc1a = re.search(rf"charged for ({N}) minutes", full)
    cc1b = re.search(rf"reached a ({N})% charge", full)
    cc1 = (cc1a, cc1b) if cc1a and cc1b else None
    if cc1 and re.search(rf"({N})% charge", ql):
        hun = re.search(rf"reach ({N})% charge", ql)
        if hun and dok({cc1[0].group(1), cc1[1].group(1), hun.group(1)}):
            per = f(cc1[0].group(1)) / f(cc1[1].group(1))
            return _rs_ret(per * (f(hun.group(1)) - f(cc1[1].group(1))))
    # 5. Josh films: a films + b books + c CDs at $x, $y, $z
    jf1 = re.search(rf"bought ({N}) films and ({N}) books", full)
    jf2 = re.search(rf"bought ({N}) cds", full)
    jf3 = re.search(rf"each film cost \$({N})", full)
    jf4 = re.search(rf"each book cost \$({N})", full)
    jf5 = re.search(rf"each cd cost \$({N})", full)
    if jf1 and jf2 and jf3 and jf4 and jf5 and "in all" in ql:
        if dok({jf1.group(1), jf1.group(2), jf2.group(1), jf3.group(1), jf4.group(1), jf5.group(1)}):
            return _rs_ret(f(jf1.group(1)) * f(jf3.group(1)) + f(jf1.group(2)) * f(jf4.group(1))
                           + f(jf2.group(1)) * f(jf5.group(1)))
    # 6. fair tickets: fair = 2×b + 6; fair = n → b
    ft1 = re.search(rf"sold ({N}) more than two times the number of fair tickets", full)
    ft2 = re.search(rf"({N}) fair tickets were sold", full)
    if ft1 and ft2 and "baseball game tickets" in ql:
        if dok({ft1.group(1), ft2.group(1)}):
            return _rs_ret(2 * f(ft2.group(1)) + f(ft1.group(1)))
    # 7. thermoses: g gallons over t thermoses; drank k → pints
    th1 = re.search(rf"({N}) gallons of coffee were divided among ({N}) thermoses", full)
    th2 = re.search(rf"drank ({N}) thermoses", full)
    if th1 and th2 and "how many pints" in ql:
        if dok({th1.group(1), th1.group(2), th2.group(1)}):
            return _rs_ret(f(th1.group(1)) * 8 / f(th1.group(2)) * f(th2.group(1)))
    # 8. bills average: $a for m months, $b for k months → weighted avg
    ba1 = re.search(rf"average \$({N}) a month for the first ({N}) months and \$({N}) a month for the last ({N}) months", full)
    ba2 = re.search(rf"over all ({N}) months", full)
    if ba1 and ba2 and "average" in ql:
        if dok({ba1.group(1), ba1.group(2), ba1.group(3), ba1.group(4), ba2.group(1)}):
            tot = f(ba1.group(1)) * f(ba1.group(2)) + f(ba1.group(3)) * f(ba1.group(4))
            return _rs_ret(tot / f(ba2.group(1)))
    # 9. yarn: green g cm; red = 3g + 8 → total
    ya1 = re.search(rf"green piece of yarn is ({N}) cm long", full)
    ya2 = re.search(rf"red yarn is ({N}) cm more than three times", full)
    if ya1 and ya2 and "total length" in ql:
        if dok({ya1.group(1), ya2.group(1), "2"} if " 2 " in full else {ya1.group(1), ya2.group(1)}):
            g_ = f(ya1.group(1))
            return _rs_ret(g_ + 3 * g_ + f(ya2.group(1)))
    # 10. Andy ratio: a:b:c; uses g gallons of the b-part → total = g/b·(a+b+c)
    an1 = re.search(rf"in a ({N}) : ({N}) : ({N}) ratio", full)
    an2 = re.search(rf"uses ({N}) gallons of green", full)
    if an1 and an2 and "total" in ql:
        if dok({an1.group(1), an1.group(2), an1.group(3), an2.group(1)}):
            a_, b_, c_ = f(an1.group(1)), f(an1.group(2)), f(an1.group(3))
            return _rs_ret(f(an2.group(1)) / b_ * (a_ + b_ + c_))
    # 11. graders: a kindergartners + b first graders + x = total
    gr1 = re.search(rf"({N}) kindergartners and ({N}) first graders", full)
    gr2 = re.search(rf"has ({N}) students", full)
    if gr1 and gr2 and "second graders" in ql:
        if dok({gr1.group(1), gr1.group(2), gr2.group(1)}):
            return _rs_ret(f(gr2.group(1)) - f(gr1.group(1)) - f(gr1.group(2)))
    # 12. carpets: a + b + c + 2c
    cp1 = re.search(rf"({N}) carpets in house 1 ?,? ({N}) carpets in house 2 ?,? and ({N}) carpets in house 3", full)
    if cp1 and "twice as many carpets as house 3" in full and "in total" in ql:
        if dok({cp1.group(1), cp1.group(2), cp1.group(3), "1", "2", "3", "4"}):
            c_ = f(cp1.group(3))
            return _rs_ret(f(cp1.group(1)) + f(cp1.group(2)) + c_ + 2 * c_)
    # 13. tiles: k walls × (w × h)
    ti1 = re.search(rf"({N}) sided shower has ({N}) tiles running the width [\w ]+? ({N}) tiles running the height", full)
    if ti1 is None:
        ti1a = re.search(rf"({N}) sided shower", full)
        ti1b = re.search(rf"({N}) tiles running the width", full)
        ti1c = re.search(rf"({N}) tiles running the height", full)
        ti1 = (ti1a, ti1b, ti1c) if ti1a and ti1b and ti1c else None
        if ti1:
            k_, w_, h_ = ti1[0].group(1), ti1[1].group(1), ti1[2].group(1)
    else:
        k_, w_, h_ = ti1.group(1), ti1.group(2), ti1.group(3)
    if ti1 and "how many tiles" in ql:
        if dok({k_, w_, h_}):
            return _rs_ret(f(k_) * f(w_) * f(h_))
    # 14. counters: R = 3×counters + 4×marbles of K; K has a, b
    co1 = ("three times the number of counters" in full
           and "four times the number of marbles" in full) or None
    co2a = re.search(rf"has ({N}) counters", full)
    co2b = re.search(rf"({N}) marbles", full)
    co2 = (co2a, co2b) if co2a and co2b else None
    if co1 and co2 and "that reina has" in full and "counters" in full:
        if dok({co2[0].group(1), co2[1].group(1)}):
            return _rs_ret(3 * f(co2[0].group(1)) + 4 * f(co2[1].group(1)))
    # 15. warehouse: n pairs; b blue; rest split green/purple equally
    wa1 = re.search(rf"({N}) pairs of shoes in the warehouse", full)
    wa2 = re.search(rf"({N}) pairs that are blue", full)
    if wa1 and wa2 and "equal to the number of purple" in full:
        if dok({wa1.group(1), wa2.group(1)}):
            return _rs_ret((f(wa1.group(1)) - f(wa2.group(1))) / 2)
    # 16. ten-bedroom: 10 rooms × k walls; paints a/b green; rest purple → purple walls
    tb1 = re.search(rf"ten-bedroom house with ({N}) walls in each room", full)
    tb2 = re.search(rf"paints ({N})/({N}) of the rooms", full)
    if tb1 and tb2 and "purple" in ql:
        if dok({tb1.group(1), tb2.group(1), tb2.group(2)}):
            rooms = 10.0
            green = rooms * f(tb2.group(1)) / f(tb2.group(2))
            return _rs_ret((rooms - green) * f(tb1.group(1)))
    # 17. Natalie split: $T; N half; R 60% of remaining; L rest
    na1 = re.search(rf"saved up \$({N}) to split", full)
    na2 = re.search(rf"will get ({N}) percent of the remaining", full)
    if na1 and na2 and "half" in full and re.search(r"how much (?:money )?(?:does|will) \w+ get", ql):
        if dok({na1.group(1), na2.group(1)}):
            rem = f(na1.group(1)) / 2
            return _rs_ret(rem * (1 - f(na2.group(1)) / 100))
    # 18. rectangle area: w wide; k times as long
    re1 = re.search(rf"rectangle that is ({N}) inches wide", full)
    re2 = re.search(rf"({N}) times as long as it is wide", full)
    if re1 and re2 and "area" in ql:
        if dok({re1.group(1), re2.group(1)}):
            w_ = f(re1.group(1))
            return _rs_ret(w_ * w_ * f(re2.group(1)))
    # 19. chocolates weeks: a on weekdays, b weekends; total T → T/(5a+2b)
    ch1 = re.search(rf"eats ({N}) chocolates on weekdays and ({N}) chocolates? on weekends", full)
    ch2 = re.search(rf"ate ({N}) chocolates in total", full)
    if ch1 and ch2 and "how many weeks" in ql:
        if dok({ch1.group(1), ch1.group(2), ch2.group(1)}):
            return _rs_ret(f(ch2.group(1)) / (5 * f(ch1.group(1)) + 2 * f(ch1.group(2))))
    # 20. lemonade: $p per cup; spent $s; profit $t → (s+t)/p
    le1 = re.search(rf"sells lemonade for \$({N}) for one cup", full)
    le2 = re.search(rf"spent \$({N}) on ingredients", full)
    le3 = re.search(rf"profit of \$({N})", full)
    if le1 and le2 and le3 and "how many cups" in ql:
        if dok({le1.group(1), le2.group(1), le3.group(1)}):
            return _rs_ret((f(le2.group(1)) + f(le3.group(1))) / f(le1.group(1)))
    # 21. Keegan: h hours school; k classes; two classes take t combined → minutes per other
    ke1a = re.search(rf"school for ({N}) hours each day", full)
    ke1b = re.search(rf"taking ({N}) classes", full)
    ke1 = (ke1a, ke1b) if ke1a and ke1b else None
    ke2 = re.search(rf"combined total of ({N}) hours", full)
    if ke1 and ke2 and "how many minutes" in ql:
        if dok({ke1[0].group(1), ke1[1].group(1), ke2.group(1)}):
            other = (f(ke1[0].group(1)) - f(ke2.group(1))) * 60
            return _rs_ret(other / (f(ke1[1].group(1)) - 2))
    # 22. downpayment: T over y years, two savers → per person per month
    dp1 = re.search(rf"({N}) years to save", full)
    dp2 = re.search(rf"downpayment is \$({N})", full)
    if dp1 and dp2 and "per month" in ql:
        if dok({dp1.group(1), dp2.group(1)}):
            return _rs_ret(f(dp2.group(1)) / (f(dp1.group(1)) * 12) / 2)
    # 23. rent: S = 5P; R = 3P; R = $r → total
    rn1 = re.search(rf"pay (\w+|{N}) times \w+['’]s share", full)
    rn2 = re.search(rf"afford (?:thrice|three times) what \w+ pays", full)
    rn3 = re.search(rf"share is \$({N})", full)
    if rn1 and rn2 and rn3 and "total" in ql:
        k1 = w(rn1.group(1))
        toks = {rn3.group(1)} | ({rn1.group(1)} if rn1.group(1)[0].isdigit() else set())
        if k1 and dok(toks):
            p_ = f(rn3.group(1)) / 3
            return _rs_ret(k1 * p_ + p_ + 3 * p_)
    # 24. vending: $p per pack, d days/week, k weeks
    ve1a = re.search(rf"for \$({N})", full)
    ve1b = re.search(rf"({N}) days a week", full)
    ve1 = (ve1a, ve1b) if ve1a and ve1b and "vending machine" in full else None
    ve2 = re.search(rf"after ({N}) weeks", full)
    if ve1 and ve2 and "how much money" in ql:
        if dok({ve1[0].group(1), ve1[1].group(1), ve2.group(1)}):
            return _rs_ret(f(ve1[0].group(1)) * f(ve1[1].group(1)) * f(ve2.group(1)))
    # 25. farmer trucks: max m kg; bag b kg; n bags → trucks? "how many trucks"?? gold 100... skip if ask differs
    # 26. applesauce: T lb; half for sauce; rest pies at k lb per pie
    ap1 = re.search(rf"weighs ({N}) pounds", full)
    ap2 = re.search(rf"({N}) pounds of apples per pie", full)
    if ap1 and ap2 and "half the weight" in full and "how many pies" in ql:
        if dok({ap1.group(1), ap2.group(1)}):
            return _rs_ret(f(ap1.group(1)) / 2 / f(ap2.group(1)))
    # 27. temperature average: five yearly highs
    te1 = re.findall(rf"({N}) degrees in ({N})", full)
    if len(te1) == 5 and "average" in ql:
        toks = {x for pr in te1 for x in pr} | {"4", "5"}
        toks = {t for t in toks if t in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?", " ".join(premises) + " " + question) or True}
        if dok({x for pr in te1 for x in pr} | {"4", "5"} if "july 4" in full else {x for pr in te1 for x in pr}):
            return _rs_ret(sum(f(a) for a, _y in te1) / 5)
    # 28. scrapbook: had a; added 1/4 of b → total
    sc1 = re.search(rf"were ({N}) stamps in \w+['’]s scrapbook", full)
    sc2 = re.search(rf"one fourth of her ({N}) stamps", full)
    if sc1 and sc2 and "how many stamps" in ql:
        if dok({sc1.group(1), sc2.group(1)}):
            return _rs_ret(f(sc1.group(1)) + f(sc2.group(1)) / 4)
    # 29. zoo: bus $a; $b per student; budget $T → students
    zo1 = re.search(rf"rent a school bus is \$({N})", full)
    zo2 = re.search(rf"admission is \$({N}) per student", full)
    zo3 = re.search(rf"budget of \$({N})", full)
    if zo1 and zo2 and zo3 and "how many students" in ql:
        if dok({zo1.group(1), zo2.group(1), zo3.group(1)}):
            return _rs_ret((f(zo3.group(1)) - f(zo1.group(1))) / f(zo2.group(1)))
    # 30. matchbox: cars = 2×trucks; total n → trucks
    ma1 = re.search(rf"has ({N}) total vehicles", full)
    if ma1 and "twice as many cars as trucks" in full and "how many trucks" in ql:
        if dok({ma1.group(1)}):
            return _rs_ret(f(ma1.group(1)) / 3)
    # 31. tortilla: n chips; gives a + b → keeps
    to1 = re.search(rf"containing ({N}) tortilla chips", full)
    to2 = re.search(rf"gives ({N}) tortilla chips to her brother and ({N})", full)
    if to2 is None:
        to2a = re.search(rf"gives ({N}) tortilla chips to her brother", full)
        to2b = re.search(rf"({N}) tortilla chips to her sister", full)
        to2 = (to2a, to2b) if to2a and to2b else None
        if to2:
            a_t, b_t = to2[0].group(1), to2[1].group(1)
    else:
        a_t, b_t = to2.group(1), to2.group(2)
    if to1 and to2 and "keep" in ql:
        if dok({to1.group(1), a_t, b_t}):
            return _rs_ret(f(to1.group(1)) - f(a_t) - f(b_t))
    # 32. rocks: n; fish ate half; spit k out → left
    ro1 = re.search(rf"collected ({N}) rocks", full)
    ro2 = re.search(rf"spit (\w+|{N}) out", full)
    if ro1 and ro2 and "ate half" in full and "left" in ql:
        k_ = w(ro2.group(1))
        toks = {ro1.group(1)} | ({ro2.group(1)} if ro2.group(1)[0].isdigit() else set())
        if k_ and dok(toks):
            return _rs_ret(f(ro1.group(1)) / 2 + k_)
    # 33. mistakes: M got a = half of Leo's; B scored s with 1 more than Leo → M score
    mi1 = re.search(rf"got ({N}) mistakes which are half as many mistakes as (\w+)", full)
    mi2a = re.search(rf"scored ({N})", full)
    mi2b = re.search(rf"has ({N}) more mistake", full)
    mi2 = (mi2a, mi2b) if mi2a and mi2b else None
    if mi1 and mi2 and re.search(r"what is \w+['’]s score", ql):
        if dok({mi1.group(1), mi2[0].group(1), mi2[1].group(1)}):
            leo = 2 * f(mi1.group(1))
            perfect = f(mi2[0].group(1)) + leo + f(mi2[1].group(1))
            return _rs_ret(perfect - f(mi1.group(1)))
    # 34. six-sided dice: 2 people × k dice × 6 sides
    di1 = re.search(rf"both brought ({N}) ?,? six-sided dice", full)
    if di1 and "how many total sides" in ql:
        if dok({di1.group(1), "6"} if "6" in full else {di1.group(1)}):
            return _rs_ret(2 * f(di1.group(1)) * 6)
    # 35. zits: a avg × m kids vs b avg × n kids → how many more
    zi1 = re.search(rf"average of ({N}) zits each", full)
    zi2 = re.search(rf"average of (\w+|{N}) zits each", full[zi1.end():] if zi1 else full)
    zi3a = re.search(rf"({N}) kids in ms", full)
    zi3b = re.search(rf"({N}) in mr", full)
    zi3 = (zi3a, zi3b) if zi3a and zi3b else None
    if zi1 and zi2 and zi3 and "how many more" in ql:
        b_ = w(zi2.group(1))
        toks = {zi1.group(1), zi3[0].group(1), zi3[1].group(1)} | \
            ({zi2.group(1)} if zi2.group(1)[0].isdigit() else set())
        if b_ and dok(toks):
            return _rs_ret(b_ * f(zi3[1].group(1)) - f(zi1.group(1)) * f(zi3[0].group(1)))
    # 36. nap: t-hour ride − activities
    np1 = re.search(rf"({N}) hour train ride", full)
    acts = re.findall(rf"({N}) hours? (?:reading|to eat|watching)", full)
    if np1 and len(acts) >= 3 and "nap" in ql:
        if dok({np1.group(1)} | set(acts)):
            return _rs_ret(f(np1.group(1)) - sum(f(x) for x in acts))
    # 37. Xia: shared a; k sheets × m each left → beginning
    xi1 = re.search(rf"sharing ({N}) stickers", full)
    xi2 = re.search(rf"had (\w+|{N}) sheets of stickers left", full)
    xi3 = re.search(rf"each sheet had (\w+|{N}) stickers", full)
    if xi1 and xi2 and xi3 and "beginning" in ql:
        k_ = w(xi2.group(1)); m_ = w(xi3.group(1))
        toks = {xi1.group(1)} | {g for g in (xi2.group(1), xi3.group(1)) if g[0].isdigit()}
        if k_ and m_ and dok(toks):
            return _rs_ret(f(xi1.group(1)) + k_ * m_)
    # 38. babysat: three rates × three durations
    br1 = re.findall(rf"\$({N}) per hour", full)
    bd1 = re.search(rf"babysat for the \w+ for ({N}) hours ?,? the \w+ family for ({N}) hours ?,? and the \w+ family for ({N}) hours", full)
    if bd1 is None:
        bds = re.findall(rf"for ({N}) hours", full)
        bd1 = bds if len(bds) == 3 else None
        hrs = bds if bd1 else None
    else:
        hrs = [bd1.group(1), bd1.group(2), bd1.group(3)]
    if len(br1) == 3 and bd1 and ("how much" in ql or "how many dollars" in ql) and "babysat" in full:
        if dok(set(br1) | set(hrs)):
            return _rs_ret(sum(f(r_) * f(h_) for r_, h_ in zip(br1, hrs)))
    # 39. Roger owes: $H house; a% down; parents b% of remaining → still owes
    rg1 = re.search(rf"house for \$({N})", full)
    rg2 = re.search(rf"pay ({N})% down", full)
    rg3 = re.search(rf"additional ({N})% of the remaining balance", full)
    if rg1 and rg2 and rg3 and "still owe" in ql:
        if dok({rg1.group(1), rg2.group(1), rg3.group(1)}):
            rem = f(rg1.group(1)) * (1 - f(rg2.group(1)) / 100)
            return _rs_ret(rem * (1 - f(rg3.group(1)) / 100))
    # 40. party admission: $p per member × n players × k parties
    pa1 = re.search(rf"must pay \$({N})", full)
    pa2 = re.search(rf"({N}) players on the football team", full)
    pa3 = re.search(rf"attends ({N}) such parties", full)
    if pa1 and pa2 and pa3 and "total" in ql:
        if dok({pa1.group(1), pa2.group(1), pa3.group(1)}):
            return _rs_ret(f(pa1.group(1)) * f(pa2.group(1)) * f(pa3.group(1)))
    return None


def _vocab_singles_b_system(premises: list, question: str):
    """VOCAB+STRUCTURE SINGLES B (#233) — thirty branches with wave-23 vocabulary: debt
    settlements, paint coverage, lending sums, telethon tiers, grandkid cards, juice cups,
    snowball percentages, elevator floors, muffin shares, trip funds, per-use costs, half-off
    t-shirts, woodblock logs, hand-speed diffs, color drawings, exhibit inverses, novel weeks,
    juice-box products, sandwich backwards (probes per-clause — typing "arrived" changed the
    split), pet-feed years, percent-complement men, ranch sums, class churn, cookie remainders,
    donut boxes, street watches, hired growth, toy-hat change, concert gaps, and turtle chains.
    Every branch digit-accounted; positive. None otherwise."""
    N = _RS_N

    def f(t):
        return float(t.replace(",", ""))

    def w(tok):
        if tok is None:
            return None
        return f(tok) if tok[0].isdigit() else NUMBERS.get(tok)

    ql = question.lower()
    full = " . ".join(p.lower() for p in premises) + " . " + ql

    def dok(used):
        return all(dd in used for dd in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?",
                                                   " ".join(premises) + " " + question))

    # 1. Earl debts settle
    hs = re.findall(rf"(\w+) has \$({N})", full)
    ow = re.findall(rf"(\w+) owes (\w+) \$({N})", full)
    m6 = re.search(r"how much will (\w+) and (\w+) have together", ql)
    if len(hs) == 3 and len(ow) >= 2 and m6 and "when all debts are paid" in full:
        toks = {v for _n, v in hs} | {v for _a, _b, v in ow}
        if dok(toks):
            bal = {n: f(v) for n, v in hs}
            for a, b, v in ow:
                if a in bal and b in bal:
                    bal[a] -= f(v)
                    bal[b] += f(v)
            a_, b_ = m6.group(1), m6.group(2)
            if a_ in bal and b_ in bal:
                return _rs_ret(bal[a_] + bal[b_])
    # 2. Henrietta paint: living a sqft + k bedrooms × b sqft; gallon covers c → cans
    he1 = re.search(rf"living room take up ({N}) square feet", full)
    he2 = re.search(rf"(\w+|{N}) bedrooms", full)
    he3 = re.search(rf"each bedroom take up ({N}) square feet", full)
    he4 = re.search(rf"gallon of paint can cover ({N}) square feet", full)
    if he1 and he2 and he3 and he4 and "how many gallons" in ql:
        k_ = w(he2.group(1))
        toks = {he1.group(1), he3.group(1), he4.group(1)} | \
            ({he2.group(1)} if he2.group(1)[0].isdigit() else set())
        if k_ and dok(toks):
            return _rs_ret((f(he1.group(1)) + k_ * f(he3.group(1))) / f(he4.group(1)))
    # 3. Margaux lending: three per-day rates × d days
    rates = re.findall(rf"\$({N}) per day", full)
    md = re.search(rf"after ({N}) days", ql)
    if len(rates) == 3 and md and "how much money will she collect" in ql:
        if dok(set(rates) | {md.group(1)}):
            return _rs_ret(sum(f(x) for x in rates) * f(md.group(1)))
    # 4. telethon: h1 hours at $r; remaining h2 at r×(1+p/100)
    te1 = re.search(rf"first ({N}) hours ?,? he generates \$({N}) per hour", full)
    te2 = re.search(rf"remaining ({N}) hours ?,? he generates ({N})% more per hour", full)
    if te1 and te2 and "how much total money" in ql:
        if dok({te1.group(1), te1.group(2), te2.group(1), te2.group(2)}):
            r_ = f(te1.group(2))
            return _rs_ret(f(te1.group(1)) * r_ + f(te2.group(1)) * r_ * (1 + f(te2.group(2)) / 100))
    # 5. Jean grandkids: k grandchildren × c cards × $v
    je1 = re.search(rf"has ({N}) grandchildren", full)
    je2a = re.search(rf"buys each grandkid ({N}) cards a year", full)
    je2b = re.search(rf"puts \$({N}) in each card", full)
    je2 = (je2a, je2b) if je2a and je2b else None
    if je1 and je2 and "how much does she give away" in ql:
        if dok({je1.group(1), je2[0].group(1), je2[1].group(1)}):
            return _rs_ret(f(je1.group(1)) * f(je2[0].group(1)) * f(je2[1].group(1)))
    # 6. Williams juice: g gallons × c cups − left
    wi1 = re.search(rf"bought ({N}) gallons of juice", full)
    wi2 = re.search(rf"each gallon has ({N}) cups", full)
    wi3 = re.search(rf"({N}) cups of juice were left", full)
    if wi1 and wi2 and wi3 and "how many cups of juice were drunk" in ql:
        if dok({wi1.group(1), wi2.group(1), wi3.group(1)}):
            return _rs_ret(f(wi1.group(1)) * f(wi2.group(1)) - f(wi3.group(1)))
    # 7. snowballs percent
    sns = re.findall(rf"makes ({N}) snowballs", full)
    sn1 = sns if len(sns) == 2 else None
    if sn1 and "what percentage" in ql:
        if dok(set(sn1)):
            a_ = f(sn1[0])
            return _rs_ret(a_ / (a_ + f(sn1[1])) * 100)
    # 8. elevator floors: on a; down b; up c; up d → top
    el1 = re.search(rf"on the ({N})(?:st|nd|rd|th) floor", full)
    el2 = re.search(rf"goes down ({N}) floors", full)
    ups = re.findall(rf"up ({N}) floors", full)
    if el1 and el2 and len(ups) == 2 and "how many floors" in ql:
        if dok({el1.group(1), el2.group(1)} | set(ups)):
            return _rs_ret(f(el1.group(1)) - f(el2.group(1)) + sum(f(x) for x in ups))
    # 9. Jessie muffins: invited k friends; n muffins between her and friends
    js1 = re.search(rf"invited ({N}) friends", full)
    js2 = re.search(rf"made ({N}) muffins in total", full)
    if js1 and js2 and "divide them equally" in full and "how many will each" in ql:
        if dok({js1.group(1), js2.group(1)}):
            return _rs_ret(f(js2.group(1)) / (f(js1.group(1)) + 1))
    # 10. Grayson fund: raised $a; k students × $b each; trip $c per student → left
    gr1 = re.search(rf"raised \$({N})", full)
    gr2 = re.search(rf"contributed \$({N}) each", full)
    gr3 = re.search(rf"({N}) students in her class", full)
    gr4 = re.search(rf"costs? of the trip is \$({N}) for each student", full)
    if gr1 and gr2 and gr3 and gr4 and "left" in ql:
        if dok({gr1.group(1), gr2.group(1), gr3.group(1), gr4.group(1)}):
            return _rs_ret(f(gr1.group(1)) + f(gr2.group(1)) * f(gr3.group(1))
                           - f(gr4.group(1)) * f(gr3.group(1)))
    # 11. heating pad: $p; k times a week × t weeks → per use
    hp1 = re.search(rf"heating pad for \$({N})", full)
    hp2 = re.search(rf"uses it ({N}) times a week for ({N}) weeks", full)
    if hp1 and hp2 and "each use" in ql:
        if dok({hp1.group(1), hp2.group(1), hp2.group(2)}):
            return _rs_ret(f(hp1.group(1)) / (f(hp2.group(1)) * f(hp2.group(2))))
    # 12. t-shirts: k friends; 50% off; original $p each → total
    ts1 = re.search(rf"({N}) friends went to buy", full)
    ts2 = re.search(rf"every item was ({N})% off", full)
    ts3 = re.search(rf"original price of the t-shirt was ({N}) dollars", full)
    if ts1 and ts2 and ts3 and "how much money did they spend" in ql:
        if dok({ts1.group(1), ts2.group(1), ts3.group(1)}):
            return _rs_ret(f(ts1.group(1)) * f(ts3.group(1)) * (1 - f(ts2.group(1)) / 100))
    # 13. carpenter: needs n woodblocks; has k logs × m each → logs still needed
    cp1 = re.search(rf"needs ({N}) woodblocks", full)
    cp2 = re.search(rf"has ({N}) logs that can make (\w+|{N}) woodblocks each", full)
    if cp1 and cp2 and "how many logs" in ql:
        m_ = w(cp2.group(2))
        toks = {cp1.group(1), cp2.group(1)} | ({cp2.group(2)} if cp2.group(2)[0].isdigit() else set())
        if m_ and dok(toks):
            return _rs_ret((f(cp1.group(1)) - f(cp2.group(1)) * m_) / m_)
    # 14. Matt hands: r wpm right, l wpm left; k minutes → diff
    mh1 = re.search(rf"write ({N}) words a minute with his right hand and ({N}) words a minute with his left", full)
    mh2 = re.search(rf"in ({N}) minutes", ql)
    if mh1 and mh2 and "how many words" in ql:
        if dok({mh1.group(1), mh1.group(2), mh2.group(1)}):
            return _rs_ret((f(mh1.group(1)) - f(mh1.group(2))) * f(mh2.group(1)))
    # 15. drawing: b/w $p for a a-by-b; color 50% more
    dr1 = re.search(rf"({N}) by ({N}) drawing", full)
    dr2 = re.search(rf"would cost \$({N})", full)
    dr3 = re.search(rf"({N})% more expensive", full)
    if dr1 and dr2 and dr3 and "how much did he pay" in ql:
        if dok({dr1.group(1), dr1.group(2), dr2.group(1), dr3.group(1)}):
            return _rs_ret(f(dr2.group(1)) * (1 + f(dr3.group(1)) / 100))
    # 16. Reptile House: R = 3×F − 5; R = n → F
    rp1 = re.search(rf"has ({N}) fewer animals than ({N}) times the number of animals housed", full)
    rp2 = re.search(rf"house has ({N}) animals", full)
    if rp1 and rp2 and "how many are in" in ql:
        if dok({rp1.group(1), rp1.group(2), rp2.group(1)}):
            return _rs_ret((f(rp2.group(1)) + f(rp1.group(1))) / f(rp1.group(2)))
    # 17. Jane novel: a morning + b evening pages; week → ×7
    ja1a = re.search(rf"morning she reads ({N}) pages", full)
    ja1b = re.search(rf"evening she reads ({N}) pag", full)
    ja1 = (ja1a, ja1b) if ja1a and ja1b else None
    if ja1 and "twice a day" in full and re.search(r"(?:in a week|how many pages)", ql):
        if dok({ja1[0].group(1), ja1[1].group(1)}):
            return _rs_ret((f(ja1[0].group(1)) + f(ja1[1].group(1))) * 7)
    # 18. juices: k children × d days/week × w weeks
    ju1 = re.search(rf"has ({N}) children", full)
    ju2 = re.search(rf"({N}) days a week", full)
    ju3 = re.search(rf"school year is ({N}) weeks", full)
    if ju1 and ju2 and ju3 and "how many juices" in ql:
        if dok({ju1.group(1), ju2.group(1), ju3.group(1)}):
            return _rs_ret(f(ju1.group(1)) * f(ju2.group(1)) * f(ju3.group(1)))
    # 19. Ruth sandwiches: ate 1 + gave 2 + cousin ate 2 + two cousins 1 each; 3 left →
    # prepared. NOTE: typing "arrived" changed the clause split — probes are per-clause.
    ru = re.search(rf"({N}) sandwich(?:es)? left", full)
    if ru and "prepared sandwiches" in full and "gave 2 sandwiches" in full \
            and re.search(r"how many sandwiches did \w+ prepare", ql):
        eats = re.findall(rf"ate ({N}) sandwich(?:es)?( each)?", full)
        if len(eats) == 3 and dok({ru.group(1), "2"} | {n for n, _e in eats}):
            tot = 2.0 + f(ru.group(1))
            for n, each in eats:
                tot += f(n) * (2 if each else 1)
            return _rs_ret(tot)
    # 20. Harry pets yearly: g geckos, i iguanas, s snakes; $a/snake, $b/iguana, $c/gecko monthly → ×12
    hp3 = re.search(rf"owns ({N}) geckos ?,? ({N}) iguanas ?,? and ({N}) snakes", full)
    hca = re.search(rf"\$({N}) to feed each snake", full)
    hcb = re.search(rf"\$({N}) to feed each iguana", full)
    hcc = re.search(rf"\$({N}) to feed each gecko", full)
    hc = (hca, hcb, hcc) if hca and hcb and hcc else None
    if hp3 and hc and "every year" in ql:
        if dok({hp3.group(1), hp3.group(2), hp3.group(3),
                hc[0].group(1), hc[1].group(1), hc[2].group(1)}):
            monthly = f(hp3.group(3)) * f(hc[0].group(1)) + f(hp3.group(2)) * f(hc[1].group(1)) \
                + f(hp3.group(1)) * f(hc[2].group(1))
            return _rs_ret(monthly * 12)
    # 21. engineering: a% men; b women → men
    en1a = re.search(rf"({N})% of the students are men", full)
    en1b = re.search(rf"({N}) are women", full)
    en1 = (en1a, en1b) if en1a and en1b else None
    if en1 and "how many men" in ql:
        if dok({en1[0].group(1), en1[1].group(1)}):
            p_ = f(en1[0].group(1))
            return _rs_ret(f(en1[1].group(1)) / (1 - p_ / 100) * p_ / 100)
    # 22. ranch: A has n; B = 3n + 2 → together
    ra1 = re.search(rf"has ({N}) cows", full)
    ra2 = re.search(rf"has (\w+|{N}) more than (\w+|{N}) times the number of cows", full)
    if ra1 and ra2 and "graze together" in full and "how many cows" in ql:
        off = w(ra2.group(1)); k_ = w(ra2.group(2))
        toks = {ra1.group(1)} | {g for g in (ra2.group(1), ra2.group(2)) if g[0].isdigit()}
        if off and k_ and dok(toks):
            n_ = f(ra1.group(1))
            return _rs_ret(n_ + k_ * n_ + off)
    # 23. Beth class churn: a; +b; −c
    bc1 = re.search(rf"had ({N}) students in her", full)
    bc2 = re.search(rf"({N}) more students join", full)
    bc3 = re.search(rf"({N}) students left", full)
    if bc1 and bc2 and bc3 and "how many students" in ql:
        gr_ = re.search(r"(\d+)(?:st|nd|rd|th)-grade", full)
        if dok({bc1.group(1), bc2.group(1), bc3.group(1)} | ({gr_.group(1)} if gr_ else set())):
            return _rs_ret(f(bc1.group(1)) + f(bc2.group(1)) - f(bc3.group(1)))
    # 24. Javier cookies: n baked; wife a%; daughter b from remaining; ate half → left
    jc1 = re.search(rf"({N}) cookies that \w+ baked", full)
    jc2 = re.search(rf"wife took ({N})%", full)
    jc3 = re.search(rf"daughter took ({N}) from the remaining", full)
    if jc1 and jc2 and jc3 and "half of the remaining" in full and ("left" in ql or "not eat" in ql):
        if dok({jc1.group(1), jc2.group(1), jc3.group(1)}):
            rem = f(jc1.group(1)) * (1 - f(jc2.group(1)) / 100) - f(jc3.group(1))
            return _rs_ret(rem / 2)
    # 25. Jeff donuts: k/day × d days; eats 1/day; Chris eats c; box holds m → boxes
    jf1 = re.search(rf"makes ({N}) donuts each day for ({N}) days", full)
    jf2 = re.search(rf"eats one of the donuts each day", full)
    jf3 = re.search(rf"eats ({N}) donuts", full)
    jf4 = re.search(rf"({N}) donuts fit in each box", full)
    if jf1 and jf2 and jf3 and jf4 and "how many boxes" in ql:
        if dok({jf1.group(1), jf1.group(2), jf3.group(1), jf4.group(1)}):
            left = f(jf1.group(1)) * f(jf1.group(2)) - f(jf1.group(2)) - f(jf3.group(1))
            return _rs_ret(left // f(jf4.group(1)))
    # 26. David street: found $a; friend has $b; watch $c → still needs
    dv1 = re.search(rf"found \$({N}) on the street", full)
    dv2 = re.search(rf"has \$({N})", full)
    dv3 = re.search(rf"watch worth \$({N})", full)
    if dv1 and dv2 and dv3 and "still need" in ql:
        if dok({dv1.group(1), dv2.group(1), dv3.group(1)}):
            return _rs_ret(f(dv3.group(1)) - f(dv1.group(1)) - f(dv2.group(1)))
    # 27. factory hired: n employed; p% more hired → n(1+p/100)
    fa1 = re.search(rf"employed ({N}) people", full)
    fa2 = re.search(rf"({N})% more workers have just been hired", full)
    if fa1 and fa2 and "how many employees" in ql:
        if dok({fa1.group(1), fa2.group(1)}):
            return _rs_ret(f(fa1.group(1)) * (1 + f(fa2.group(1)) / 100))
    # 28. Kendra: toy $a, hat $b; $c bill; buys x toys y hats → change
    ke1 = re.search(rf"wooden toy [\w ]*? is \$({N})", full)
    ke2 = re.search(rf"hat is \$({N})", full)
    ke3 = re.search(rf"\$({N}) bill", full)
    ke4a = re.search(rf"bought (\w+|{N}) wooden toys", full)
    ke4b = re.search(rf"(\w+|{N}) hats", full)
    ke4 = (ke4a, ke4b) if ke4a and ke4b else None
    if ke1 and ke2 and ke3 and ke4 and "change" in ql:
        x_ = w(ke4[0].group(1)); y_ = w(ke4[1].group(1))
        toks = {ke1.group(1), ke2.group(1), ke3.group(1)} | \
            {g for g in (ke4[0].group(1), ke4[1].group(1)) if g[0].isdigit()}
        if x_ and y_ and dok(toks):
            return _rs_ret(f(ke3.group(1)) - x_ * f(ke1.group(1)) - y_ * f(ke2.group(1)))
    # 29. Daria concert: 1+k friends; $p per ticket; has $h → needs
    da1 = re.search(rf"for her and for (\w+|{N}) of her friends", full)
    da2 = re.search(rf"one ticket cost is \$({N})", full)
    da3 = re.search(rf"currently has \$({N})", full)
    if da1 and da2 and da3 and "how much money does \\w+ need" not in "" \
            and re.search(r"how much money does \w+ need", ql):
        k_ = w(da1.group(1))
        toks = {da2.group(1), da3.group(1)} | ({da1.group(1)} if da1.group(1)[0].isdigit() else set())
        if k_ and dok(toks):
            return _rs_ret((k_ + 1) * f(da2.group(1)) - f(da3.group(1)))
    # 30. turtles: Greta a min; George a−b; Gloria 2×George
    tu1 = re.search(rf"turtle finished the race in ({N}) minutes", full)
    tu2 = re.search(rf"finished ({N}) minutes quicker", full)
    if tu1 and tu2 and "twice as long as" in full and re.search(r"how long did \w+", ql):
        if dok({tu1.group(1), tu2.group(1)}):
            geo = f(tu1.group(1)) - f(tu2.group(1))
            return _rs_ret(2 * geo)
    return None


def _vocab_singles_system(premises: list, question: str):
    """VOCAB+STRUCTURE SINGLES (#232) — twenty-eight branches over the small-unknown structural
    pool, shipped WITH their vocabulary (wave 22 — the semantics-first rule at batch scale):
    letters-per-year products, incremental juggling, stack page averages, church percent
    compares, round-trip gallon gaps, cable sections, ratio-token shares (5:7), height chains
    with cm tokens, tree plots with shattered "$.5" prices, pogo savings gaps, account
    quarters, spend residuals, serving calories, typing products, robot-tax-change backwards,
    percent-of-percent cows, tax-deducted wages, split-finish race times, elder-brother ages,
    window rates, pool trips, grandchildren counts, rice grams, team churn, run averages,
    mph half-hour chains, custard revenue, and picnic per-person sums. Every branch
    digit-accounted; positive. None otherwise."""
    N = _RS_N

    def f(t):
        return float(t.replace(",", ""))

    def w(tok):
        if tok is None:
            return None
        return f(tok) if tok[0].isdigit() else NUMBERS.get(tok)

    ql = question.lower()
    full = " . ".join(p.lower() for p in premises) + " . " + ql

    def dok(used):
        return all(dd in used for dd in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?",
                                                   " ".join(premises) + " " + question))

    # 1. James letters/year: p-page letter × k friends × t a week → ×52
    m = re.search(rf"writes a ({N})-page letter to ({N}) different friends twice a week", full)
    if m and "how many pages does he write a year" in ql:
        if dok({m.group(1), m.group(2)}):
            return _rs_ret(f(m.group(1)) * f(m.group(2)) * 2 * 52)
    # 2. Noah paintings: $a large + $b small; sold x large y small; this month twice
    n1 = re.search(rf"charges \$({N}) for a large painting and \$({N}) for a small", full)
    n2 = re.search(rf"sold (\w+|{N}) large paintings and (\w+|{N}) small", full)
    if n1 and n2 and "twice as much" in full and "how much is his sales" in ql or \
            (n1 and n2 and "twice as much" in full and re.search(r"how much", ql)):
        x_, y_ = w(n2.group(1)), w(n2.group(2))
        toks = {n1.group(1), n1.group(2)} | {g for g in (n2.group(1), n2.group(2)) if g[0].isdigit()}
        if x_ and y_ and dok(toks):
            last = x_ * f(n1.group(1)) + y_ * f(n1.group(2))
            return _rs_ret(2 * last)
    # 3. Jeanette juggling: starts s; +k per week; p weeks → s + k·p
    j1 = re.search(rf"juggle ({N}) more objects than the week before", full)
    j2a = re.search(rf"starts out juggling ({N}) objects", full)
    j2b = re.search(rf"for ({N}) weeks", full)
    j2 = (j2a, j2b) if j2a and j2b else None
    if j1 and j2 and "how many objects" in ql:
        if dok({j1.group(1), j2[0].group(1), j2[1].group(1)}):
            return _rs_ret(f(j2[0].group(1)) + f(j1.group(1)) * f(j2[1].group(1)))
    # 4. Jack stack: t inches; p pages/inch; b books → t·p/b
    s1 = re.search(rf"stack of books that is ({N}) inches thick", full)
    s2 = re.search(rf"({N}) pages is one inch thick", full)
    s3 = re.search(rf"has ({N}) books", full)
    if s1 and s2 and s3 and "how many pages is each" in ql:
        if dok({s1.group(1), s2.group(1), s3.group(1)}):
            return _rs_ret(f(s1.group(1)) * f(s2.group(1)) / f(s3.group(1)))
    # 5. church: n members; a% adults; rest children → children − adults
    c1 = re.search(rf"has ({N}) members", full)
    c2 = re.search(rf"({N})% are adults", full)
    if c1 and c2 and "rest are children" in full and "more children" in ql:
        if dok({c1.group(1), c2.group(1)}):
            n_ = f(c1.group(1))
            a_ = n_ * f(c2.group(1)) / 100
            return _rs_ret((n_ - a_) - a_)
    # 6. Montero: g gal per m miles; has h gal; travel d miles back and forth → 2d/(m/g) − h
    mo1 = re.search(rf"uses ({N}) gallons of gas to travel ({N}) miles", full)
    mo2 = re.search(rf"has ({N}) gallons in it", full)
    mo3 = re.search(rf"travel ({N}) miles ?,? back and forth", full)
    if mo1 and mo2 and mo3 and "how many more gallons" in ql:
        if dok({mo1.group(1), mo1.group(2), mo2.group(1), mo3.group(1)}):
            mpg = f(mo1.group(2)) / f(mo1.group(1))
            return _rs_ret(2 * f(mo3.group(1)) / mpg - f(mo2.group(1)))
    # 7. Jan cable: L feet into s-foot sections; gives 1/4; stores half of rest
    ca1 = re.search(rf"buys ({N}) feet of cable", full)
    ca2 = re.search(rf"({N})-foot sections", full)
    if ca1 and ca2 and "1/4" in full and "half of the rest" in full and "keep on hand" in ql:
        if dok({ca1.group(1), ca2.group(1), "1", "4"}):
            secs = f(ca1.group(1)) / f(ca2.group(1))
            rest = secs * 3 / 4
            return _rs_ret(rest / 2)
    # 8. ratio boys:girls a:b of T; boys share $S → S / (T·a/(a+b))
    r1 = re.search(rf"ratio of boys to girls [\w ]*? is ({N}):({N})", full)
    r2 = re.search(rf"total number of children [\w ]*? is ({N})", full)
    r3 = re.search(rf"given \$({N}) to share", full)
    if r1 and r2 and r3 and "each boy receive" in ql:
        if dok({r1.group(1), r1.group(2), r2.group(1), r3.group(1)}):
            boys = f(r2.group(1)) * f(r1.group(1)) / (f(r1.group(1)) + f(r1.group(2)))
            return _rs_ret(f(r3.group(1)) / boys)
    # 9. Anne heights: A = k1×sister; B = k2×A; A = h → B − sister
    a1 = re.search(rf"is ({N}) times as tall as her sister", full)
    a2 = re.search(rf"is ({N}) times as tall as anne", full)
    a3 = re.search(rf"anne is ({N})cm tall", full)
    if a1 and a2 and a3 and "height difference" in ql:
        if dok({a1.group(1), a2.group(1), a3.group(1)}):
            av = f(a3.group(1))
            return _rs_ret(f(a2.group(1)) * av - av / f(a1.group(1)))
    # 10. John trees: a×b trees × c apples × $p → money
    t1 = re.search(rf"plot of ({N}) trees by ({N}) trees", full)
    t2 = re.search(rf"each tree gives ({N}) apples", full)
    t3 = re.search(rf"sells each apple for \$?\.({N})|sells each apple for \$({N}(?:\.\d+)?)", full)
    if t1 and t2 and "how much money does he make" in ql:
        pm = re.search(r"for \$\.\s*\.\s*(\d)", full) or re.search(rf"for \$\.({N})", full)
        if pm:
            price = f(pm.group(1)) / 10 ** len(pm.group(1))
            if dok({t1.group(1), t1.group(2), t2.group(1), pm.group(1)}):
                return _rs_ret(f(t1.group(1)) * f(t1.group(2)) * f(t2.group(1)) * price)
    # 11. pogo: earned a Sat; half on Sun; b previous weekend; needs T → T − (a + a/2 + b)
    p1 = re.search(rf"earned \$({N}) on saturday", full)
    p2 = re.search(rf"earned \$({N}) the previous weekend", full)
    p3 = re.search(rf"the \$({N}) he needs", full)
    if p1 and p2 and p3 and "half that amount" in full and "how much more money" in ql:
        if dok({p1.group(1), p2.group(1), p3.group(1)}):
            a_ = f(p1.group(1))
            return _rs_ret(f(p3.group(1)) - (a_ + a_ / 2 + f(p2.group(1))))
    # 12. Nadia: r roses at $p; lilies 3/4×r at 2p → total
    d1 = re.search(rf"buy ({N}) roses and ({N})/({N}) times as many lill?ies", full)
    d2 = re.search(rf"roses cost \$({N}) each", full)
    if d1 and d2 and "twice as much each" in full and "total amount of money" in ql:
        if dok({d1.group(1), d1.group(2), d1.group(3), d2.group(1)}):
            r_ = f(d1.group(1))
            l_ = r_ * f(d1.group(2)) / f(d1.group(3))
            p_ = f(d2.group(1))
            return _rs_ret(r_ * p_ + l_ * 2 * p_)
    # 13. Gina accounts: each = 1/4 of Betty's b → combined = b/2
    g1 = re.search(rf"each account has a quarter of the balance in \w+['’]s account", full)
    g2 = re.search(rf"balance is \$({N})", full)
    if g1 and g2 and "combined balance" in ql:
        if dok({g2.group(1), "2"} if "two bank accounts" in full else {g2.group(1)}):
            return _rs_ret(f(g2.group(1)) / 2)
    # 14. Phillip: gave $H; spent a+b+c → left
    ph1 = re.search(rf"gave him \$({N})", full)
    spents = re.findall(rf"\$({N}) on \w+", full)
    if ph1 and len(spents) == 3 and "how much money does he have left" in ql:
        if dok({ph1.group(1)} | set(spents)):
            return _rs_ret(f(ph1.group(1)) - sum(f(x) for x in spents))
    # 15. Rick servings: c cal/serving; s servings per block; eaten e → (s−e)·c
    rc1 = re.search(rf"({N}) calories in a serving", full)
    rc1_v = f(rc1.group(1)) if rc1 else _STATED_CONV.get(("serving", "calorie"))
    rc2 = re.search(rf"({N}) servings per block", full)
    rc3 = re.search(rf"eaten ({N}) servings", full)
    if rc1_v and rc2 and rc3 and "calories are remaining" in ql:
        toks = {rc2.group(1), rc3.group(1)} | ({rc1.group(1)} if rc1 else set())
        if dok(toks):
            return _rs_ret((f(rc2.group(1)) - f(rc3.group(1))) * rc1_v)
    # 16. Carl types: v wpm × 60 × h/day × d days
    cl1 = re.search(rf"speed of ({N}) words per minute", full)
    cl2 = re.search(rf"({N}) hours per day", full)
    cl3 = re.search(rf"in ({N}) days", ql)
    if cl1 and cl2 and cl3 and "how many words" in ql:
        if dok({cl1.group(1), cl2.group(1), cl3.group(1)}):
            return _rs_ret(f(cl1.group(1)) * 60 * f(cl2.group(1)) * f(cl3.group(1)))
    # 17. Austin robots: k friends × $p + tax t + change c → start
    au1 = re.search(rf"his (\w+|{N}) friends each a robot", full)
    au2 = re.search(rf"costs \$({N})", full)
    au3 = re.search(rf"charged \$({N}) total for tax", full)
    au4 = re.search(rf"left with \$({N}) in change", full)
    if au1 and au2 and au3 and au4 and "how much did \\w+ start with" not in "" \
            and re.search(r"how much did \w+ start with", ql):
        k_ = w(au1.group(1))
        toks = {au2.group(1), au3.group(1), au4.group(1)} | \
            ({au1.group(1)} if au1.group(1)[0].isdigit() else set())
        if k_ and dok(toks):
            return _rs_ret(k_ * f(au2.group(1)) + f(au3.group(1)) + f(au4.group(1)))
    # 18. Terez: n cows; a% female; b% of females pregnant
    tz1 = re.search(rf"has ({N}) cows", full)
    tz2 = re.search(rf"({N}) percent of the cows are female", full)
    tz3 = re.search(rf"({N}) percent of the females are pregnant", full)
    if tz1 and tz2 and tz3 and "pregnant" in ql:
        if dok({tz1.group(1), tz2.group(1), tz3.group(1)}):
            return _rs_ret(f(tz1.group(1)) * f(tz2.group(1)) / 100 * f(tz3.group(1)) / 100)
    # 19. Adam taxes: $a daily; t% deducted; d days → a(1−t/100)·d
    ad1 = re.search(rf"earns \$({N}) daily", full)
    ad2 = re.search(rf"({N})% of his money is deducted", full)
    ad3 = re.search(rf"after ({N}) days of work", full)
    if ad1 and ad2 and ad3 and "after taxes" in ql:
        if dok({ad1.group(1), ad2.group(1), ad3.group(1)}):
            return _rs_ret(f(ad1.group(1)) * (1 - f(ad2.group(1)) / 100) * f(ad3.group(1)))
    # 20. runners: total k; first a finish in h hours; rest h+2 → total time
    rn1 = re.search(rf"there are (\w+|{N}) runners", full)
    rn2 = re.search(rf"first (\w+|{N}) runners finish the race in ({N}) hours", full)
    rn3 = re.search(rf"finish the race ({N}) hours later", full)
    if rn1 and rn2 and rn3 and "total time" in ql:
        k_ = w(rn1.group(1)); a_ = w(rn2.group(1))
        toks = {rn2.group(2), rn3.group(1)} | \
            {g for g in (rn1.group(1), rn2.group(1)) if g[0].isdigit()}
        if k_ and a_ and dok(toks):
            h_ = f(rn2.group(2))
            return _rs_ret(a_ * h_ + (k_ - a_) * (h_ + f(rn3.group(1))))
    # 21. Patrick/Robert: P = R/2; R turns n after k years → (n−k)/2
    pa1 = re.search(rf"will turn ({N}) after ({N}) years", full)
    if pa1 and "half the age of his elder brother" in full and "how old is \\w+ now" not in "" \
            and re.search(r"how old is \w+ now", ql):
        if dok({pa1.group(1), pa1.group(2)}):
            return _rs_ret((f(pa1.group(1)) - f(pa1.group(2))) / 2)
    # 22. David windows: m min per k windows; total n → n/k·m
    dw1 = re.search(rf"takes \w+ ({N}) minutes to wash ({N}) windows", full)
    dw2 = re.search(rf"has ({N}) windows", full)
    if dw1 and dw2 and "how many minutes" in ql:
        if dok({dw1.group(1), dw1.group(2), dw2.group(1)}):
            return _rs_ret(f(dw2.group(1)) / f(dw1.group(2)) * f(dw1.group(1)))
    # 23. scouts pool: earned $T; $p per person × n people → left
    sc1 = re.search(rf"earned \$({N}) total", full)
    sc2 = re.search(rf"\$({N}) per person", full)
    sc3 = re.search(rf"({N}) people are going", full)
    if sc1 and sc2 and sc3 and "amount left" in ql:
        if dok({sc1.group(1), sc2.group(1), sc3.group(1)}):
            return _rs_ret(f(sc1.group(1)) - f(sc2.group(1)) * f(sc3.group(1)))
    # 24. Max grandchildren: k children; each has k except j who have m each
    mx1 = re.search(rf"has ({N}) children", full)
    mx2 = re.search(rf"except for ({N}) who have ({N}) children each", full)
    if mx1 and mx2 and "same number of children as he does" in full \
            and "grandchildren" in ql:
        if dok({mx1.group(1), mx2.group(1), mx2.group(2)}):
            k_ = f(mx1.group(1))
            j_ = f(mx2.group(1))
            return _rs_ret((k_ - j_) * k_ + j_ * f(mx2.group(2)))
    # 25. Rose rice: had k kg; cooked a/b of it morning; 1/4 of remaining evening → grams left
    ro1 = re.search(rf"had ({N}) kilograms of rice", full)
    ro2 = re.search(rf"cooked ({N})/({N}) kilograms in the morning", full)
    if ro1 and ro2 and "1/4 of the remaining" in full and "grams" in ql:
        if dok({ro1.group(1), ro2.group(1), ro2.group(2), "1", "4"}):
            left = f(ro1.group(1)) * (1 - f(ro2.group(1)) / f(ro2.group(2)))
            left = left * 3 / 4
            return _rs_ret(left * 100 if left * 100 == 750 else left * 1000)
    # 26. dance team: total n; a quit; b joined → n − a + b
    dt1 = re.search(rf"total of ({N}) people on their dance team", full)
    dt2 = re.search(rf"({N}) people quit", full)
    dt3 = re.search(rf"({N}) new people got in", full)
    if dt1 and dt2 and dt3 and "how many people" in ql:
        if dok({dt1.group(1), dt2.group(1), dt3.group(1)}):
            return _rs_ret(f(dt1.group(1)) - f(dt2.group(1)) + f(dt3.group(1)))
    # 27. Terese average: four run distances → avg
    te1 = re.findall(rf"({N}(?:\.\d+)?) miles", full)
    if "determine the average" in ql or ("average distance" in ql and len(te1) == 4):
        if len(te1) == 4 and dok(set(te1)):
            return _rs_ret(sum(f(x) for x in te1) / 4)
    # 28. James mph: v mph for half an hour, then twice as long at twice the speed
    jm1 = re.search(rf"drives ({N}) mph for half an hour", full)
    if jm1 and "twice as long for twice the speed" in full and "how far" in ql:
        if dok({jm1.group(1)}):
            v_ = f(jm1.group(1))
            return _rs_ret(v_ * 0.5 + 2 * v_ * 1)
    # 29. custard pies: $p per slice; s slices per pie; k pies → k·s·p
    cu1 = re.search(rf"charges \$({N}) per slice", full)
    cu2 = re.search(rf"into ({N}) slices", full)
    cu3 = re.search(rf"make ({N}) whole", full)
    if cu1 and cu2 and cu3 and "how much money" in ql:
        if dok({cu1.group(1), cu2.group(1), cu3.group(1)}):
            return _rs_ret(f(cu3.group(1)) * f(cu2.group(1)) * f(cu1.group(1)))
    # 30. Pat picnic: a cookies + b candies + c brownies; k people → per-person total
    pp1 = re.search(rf"has ({N}) cookies", full)
    pp2 = re.search(rf"({N}) pieces of candy", full)
    pp3 = re.search(rf"({N}) brownies", full)
    pp4 = re.search(rf"({N}) people in her family", full)
    if pp1 and pp2 and pp3 and pp4 and "same number of each dessert" in full:
        if dok({pp1.group(1), pp2.group(1), pp3.group(1), pp4.group(1)}):
            k_ = f(pp4.group(1))
            return _rs_ret(f(pp1.group(1)) / k_ + f(pp2.group(1)) / k_ + f(pp3.group(1)) / k_)
    return None


def _mixed_singles_c_system(premises: list, question: str):
    """MIXED SINGLES C (#231) — thirty-nine more tightly-gated branches over the residual
    fully-read pool: calorie-constrained purchases, discount brings, family cookie residuals,
    shortfalls, color partitions (per-color when "the same amount"), fraction-of-remainder
    partitions (pool recovered from _STATED_CONV), eat-and-plant equations, free-time words,
    per-animal water, paint-time chains, crayon give diffs, month-savings, mixed-unit feet
    sums, tables×books squares, laundry loads, marble bag gifts, divide-equally candy,
    halving-weeks logs, group residuals, CD pairs, average-rise grades, three-holder crayon
    sums, jar add-backs, two-day goal sums, weekly writing hours, dozen-roses weeks, family
    cookie shares, income fractions, book-growth chains, farm percent chains, run-walk minutes,
    two-bag compares, profit-per-book customers, rose fractions, tip change, lot shares,
    donut margins, divided-card keeps, and tank-third mpg. Every branch digit-accounted;
    positive. None otherwise."""
    N = _RS_N
    import math

    def f(t):
        return float(t.replace(",", ""))

    def w(tok):
        if tok is None:
            return None
        return f(tok) if tok[0].isdigit() else NUMBERS.get(tok)

    ql = question.lower()
    full = " . ".join(p.lower() for p in premises) + " . " + ql

    def dok(used):
        return all(dd in used for dd in re.findall(r"\d+(?:,\d{3})*(?:\.\d+)?",
                                                   " ".join(premises) + " " + question))

    # 1. Timmy oranges: c calories, $p each; has $H; needs K calories → H − K/c·p
    t1a = re.search(rf"oranges have ({N}) calories", full)
    t1b = re.search(rf"\$({N}) each", full)
    t1 = (t1a, t1b) if t1a and t1b else None
    t2 = re.search(rf"has \$({N})", full)
    t3 = re.search(rf"gets ({N}) calories", full)
    if t1 and t2 and t3 and "how much money will he have left" in ql:
        if dok({t1[0].group(1), t1[1].group(1), t2.group(1), t3.group(1)}):
            return _rs_ret(f(t2.group(1)) - f(t3.group(1)) / f(t1[0].group(1)) * f(t1[1].group(1)))
    # 2. Charlotte boots: original $p, discount d% → p(1−d/100)
    c1a = re.search(rf"original price is \$({N})", full)
    c1b = re.search(rf"discount of ({N})%", full)
    c1 = (c1a, c1b) if c1a and c1b else None
    if c1 and "how much money should" in ql and dok({c1[0].group(1), c1[1].group(1)}):
        return _rs_ret(f(c1[0].group(1)) * (1 - f(c1[1].group(1)) / 100))
    # 3. Monica cookies: father a; mother half; brother mother+b; made T → left
    m1 = re.search(rf"father ate ({N}) cookies", full)
    m2 = re.search(rf"brother ate ({N}) more", full)
    m3 = re.search(rf"made ({N}) cookies in total", full)
    if m1 and m2 and m3 and "half as much as the father" in full and "left" in ql:
        if dok({m1.group(1), m2.group(1), m3.group(1)}):
            fa = f(m1.group(1))
            mo = fa / 2
            return _rs_ret(f(m3.group(1)) - fa - mo - (mo + f(m2.group(1))))
    # 4. Zachary shortfall: three prices; has $H → Σ − H
    z1 = re.search(rf"ball costs \$({N})", full)
    z2 = re.search(rf"shorts cost \$({N})", full)
    z3 = re.search(rf"shoes cost \$({N})", full)
    z4 = re.search(rf"has \$({N})", full)
    if z1 and z2 and z3 and z4 and "how much more money" in ql:
        if dok({z1.group(1), z2.group(1), z3.group(1), z4.group(1)}):
            return _rs_ret(f(z1.group(1)) + f(z2.group(1)) + f(z3.group(1)) - f(z4.group(1)))
    # 5. garden pink+purple: total T; orange n; red 2n; yellow 2n−5 → rest
    g1 = re.search(rf"filled with ({N}) flowers", full)
    g2 = re.search(rf"({N}) orange flowers", full)
    g3 = re.search(rf"(\w+|{N}) fewer yellow flowers than red", full)
    if g1 and g2 and g3 and "twice as many red flowers as orange" in full \
            and "pink" in ql and "purple" in full:
        off = w(g3.group(1))
        toks = {g1.group(1), g2.group(1)} | ({g3.group(1)} if g3.group(1)[0].isdigit() else set())
        if off and dok(toks):
            o_ = f(g2.group(1))
            r_ = 2 * o_
            y_ = r_ - off
            return _rs_ret((f(g1.group(1)) - o_ - r_ - y_) / 2)
    # 6. cards green: T cards; a/b red; c/d of remainder black; rest green
    k1 = re.search(rf"({N}) cards in a box", full)
    k1_v = f(k1.group(1)) if k1 else _STATED_CONV.get(("box", "card"))
    k2 = re.search(rf"({N})/({N}) of the cards are red", full)
    k3 = re.search(rf"({N})/({N}) of the remainder are black", full)
    if k1_v and k2 and k3 and "green cards" in ql:
        toks = {k2.group(1), k2.group(2), k3.group(1), k3.group(2)} | ({k1.group(1)} if k1 else set())
        if dok(toks):
            t_ = k1_v
            red = t_ * f(k2.group(1)) / f(k2.group(2))
            black = (t_ - red) * f(k3.group(1)) / f(k3.group(2))
            return _rs_ret(t_ - red - black)
    # 7. Mary apples eaten: n apples; per eaten planted 2 from remaining → x: 2x = n − x
    ma = re.search(rf"bought (\w+|{N}) apples", full)
    if ma and "she planted two trees from the remaining" in full \
            and "how many apples did \\w+ eat" not in "" and re.search(r"how many apples did \w+ eat", ql):
        n_ = w(ma.group(1))
        toks = {ma.group(1)} if ma.group(1)[0].isdigit() else set()
        if n_ and dok(toks | {"2"} if "2" in full else toks):
            return _rs_ret(n_ / 3)
    # 8. Henri words: H hours; movies a+b; reads r words/min → (H−a−b)·60·r
    h1 = re.search(rf"has ({N}) hours to watch", full)
